/* browser back/forward support: portal pages become history entries */
let _navGuard=false;
function navPush(appId,page){
  if(_navGuard) return;
  try{
    if(!history.state||!history.state.mvs) history.replaceState({mvs:1,app:appId,pg:page},'');
    else history.pushState({mvs:1,app:appId,pg:page},'');
  }catch(e){}
}
function navPushView(v){ if(_navGuard) return; try{ history.pushState({mvs:1,app:'student-app',pg:'tests',view:v},''); }catch(e){} }
window.addEventListener('popstate',e=>{
  const st=e.state; if(!st||!st.mvs||!st.app) return;
  _navGuard=true;
  try{ navTo(st.app,st.pg); }finally{ _navGuard=false; }
});
function navTo(appId,page){
  let target=null;
  document.querySelectorAll('#'+appId+' .nav-item').forEach(n=>{ if((n.getAttribute('onclick')||'').includes("'"+page+"'")) target=n; });
  if(appId==='teacher-app') tPage(page,target);
  else if(appId==='student-app') sPage(page,target);
  else aPage(page,target);
}
// ripple effect on all buttons
document.addEventListener('click',e=>{
  const b=e.target.closest('.btn'); if(!b) return;
  const r=document.createElement('span'); r.className='ripple';
  const d=Math.max(b.clientWidth,b.clientHeight); const rect=b.getBoundingClientRect();
  r.style.width=r.style.height=d+'px';
  r.style.left=(e.clientX-rect.left-d/2)+'px'; r.style.top=(e.clientY-rect.top-d/2)+'px';
  b.appendChild(r); setTimeout(()=>r.remove(),600);
});
// client-side image compression (resize + quality) -> returns File/Blob; PDFs pass through
async function compressIfImage(file,maxDim=1800,quality=0.72){
  if(!file || !file.type || !file.type.startsWith('image/')) return file;
  try{
    const img=await new Promise((res,rej)=>{ const i=new Image(); i.onload=()=>res(i); i.onerror=rej; i.src=URL.createObjectURL(file); });
    let {width:w,height:h}=img;
    if(w>maxDim||h>maxDim){ const s=maxDim/Math.max(w,h); w=Math.round(w*s); h=Math.round(h*s); }
    const cv=document.createElement('canvas'); cv.width=w; cv.height=h;
    cv.getContext('2d').drawImage(img,0,0,w,h);
    const blob=await new Promise(res=>cv.toBlob(res,'image/jpeg',quality));
    URL.revokeObjectURL(img.src);
    if(blob && blob.size<file.size) return new File([blob],(file.name||'image').replace(/\.\w+$/,'')+'.jpg',{type:'image/jpeg'});
    return file;
  }catch(e){ return file; }
}
const MAXB=20*1024*1024;
// Compress a big PDF by rasterising pages (handles photo/scan-heavy PDFs)
async function compressPdf(file,statusCb,target){
  const TARGET=target||MAXB;
  if(!window.pdfjsLib || !window.jspdf) return file;
  try{ window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js'; }catch(e){}
  const buf=await file.arrayBuffer();
  const pdf=await window.pdfjsLib.getDocument({data:buf}).promise;
  let last=null;
  const tries=[[1.5,0.7],[1.2,0.6],[1.0,0.52],[0.85,0.45],[0.7,0.4]];
  for(let ti=0;ti<tries.length;ti++){
    const [scale,q]=tries[ti];
    const {jsPDF}=window.jspdf; let doc=null;
    for(let p=1;p<=pdf.numPages;p++){
      const page=await pdf.getPage(p);
      const vp=page.getViewport({scale});
      const cv=document.createElement('canvas'); cv.width=Math.ceil(vp.width); cv.height=Math.ceil(vp.height);
      await page.render({canvasContext:cv.getContext('2d'),viewport:vp}).promise;
      const img=cv.toDataURL('image/jpeg',q);
      const w=cv.width,h=cv.height;
      if(p===1) doc=new jsPDF({orientation:w>h?'l':'p',unit:'px',format:[w,h]});
      else doc.addPage([w,h], w>h?'l':'p');
      doc.addImage(img,'JPEG',0,0,w,h);
      statusCb&&statusCb(`Compressing the PDF... (page ${p}/${pdf.numPages}, pass ${ti+1})`);
    }
    const blob=doc.output('blob'); last=blob;
    if(blob.size<=TARGET) return new File([blob],(file.name||'file.pdf'),{type:'application/pdf'});
  }
  return last?new File([last],(file.name||'file.pdf'),{type:'application/pdf'}):file;
}
// One entry point: compress images + oversized PDFs to fit 20MB. Returns {file, ok, msg}
async function smartCompress(file,statusCb){
  if(!file) return {file,ok:false};
  if(file.type && file.type.startsWith('image/')){
    statusCb&&statusCb('Compressing the image...');
    let f=await compressIfImage(file);
    let q=0.6;
    while(f.size>MAXB && q>=0.3){ f=await compressIfImage(file,1500,q); q-=0.15; }
    return {file:f, ok:f.size<=MAXB};
  }
  if(file.type==='application/pdf' && file.size>MAXB){
    statusCb&&statusCb('Compressing the PDF, please wait...');
    try{ const f=await compressPdf(file,statusCb); return {file:f, ok:f.size<=MAXB, compressed:true}; }
    catch(e){ return {file, ok:false}; }
  }
  return {file, ok:file.size<=MAXB};
}
// ---------- v107: smart PDF pick — auto-compress with live % progress in the dropzone ----------
function _dzProgEl(dzId){
  const z=document.getElementById(dzId); if(!z) return null;
  let p=document.getElementById(dzId+'-prog');
  if(!p){
    p=document.createElement('div'); p.className='dz-prog'; p.id=dzId+'-prog';
    p.innerHTML='<div class="dz-prog-bar"><span></span></div><div class="dz-prog-t">Preparing\u2026</div>';
    z.appendChild(p);
  }
  p.style.display='block'; return p;
}
function _dzProgSet(dzId,pct,msg){
  const p=document.getElementById(dzId+'-prog')||_dzProgEl(dzId); if(!p) return;
  const bar=p.querySelector('.dz-prog-bar span'); if(bar) bar.style.width=Math.max(3,Math.min(100,pct||3))+'%';
  const t=p.querySelector('.dz-prog-t'); if(t) t.textContent=msg||('Compressing the PDF\u2026 '+Math.round(pct||0)+'%');
}
function _dzProgDone(dzId,msg){
  const p=document.getElementById(dzId+'-prog'); if(!p) return;
  const bar=p.querySelector('.dz-prog-bar span'); if(bar) bar.style.width='100%';
  const t=p.querySelector('.dz-prog-t'); if(t) t.textContent=msg||'Done';
  setTimeout(()=>{ p.style.display='none'; const b2=p.querySelector('.dz-prog-bar span'); if(b2)b2.style.width='0'; },1200);
}
function _fmtMB(x){ const v=(x||0)/1048576; return (v>=10?Math.round(v):Math.round(v*10)/10)+'MB'; }
// Teacher picks a big PDF -> never an error: compress automatically, show % progress, then accept.
async function _smartPdfPick(f,dzId,onDone){
  if(!f) return;
  if(!(f.type==='application/pdf'||/\.pdf$/i.test(f.name||''))){ toast('Only PDF files can be uploaded here.',true); return; }
  if(f.size<=MAXB){ onDone(f); return; }
  const orig=f.size;
  _dzProgSet(dzId,3,'Large PDF ('+_fmtMB(orig)+') \u2014 compressing automatically\u2026');
  try{
    const r=await smartCompress(f,(m)=>{
      const mm=/page (\d+)\/(\d+)(?:, pass (\d+))?/.exec(m||'');
      if(mm){
        const pct=Math.round(+mm[1]/+mm[2]*100);
        _dzProgSet(dzId,pct,'Compressing the PDF\u2026 '+pct+'%'+(+mm[3]>1?' (pass '+mm[3]+')':''));
      }
    });
    if(!r.ok||!r.file||r.file.size>MAXB){
      _dzProgDone(dzId,'Still too large');
      toast('This PDF is still too large even after compression. Please try a shorter or clearer scan.',true);
      return;
    }
    _dzProgDone(dzId,'Compressed: '+_fmtMB(orig)+' \u2192 '+_fmtMB(r.file.size));
    toast('Large PDF compressed automatically ('+_fmtMB(orig)+' \u2192 '+_fmtMB(r.file.size)+').');
    onDone(r.file);
  }catch(e){
    _dzProgDone(dzId,'Could not compress');
    toast('Could not process this PDF. Please try another file.',true);
  }
}
