function _premiumLogin(portal){
  try{
    _ensureAuth2Css();
    var scr=document.getElementById('login-screen'); if(!scr) return;
    var box=document.querySelector('#login-screen .login-box'); if(!box) return;
    // Sabhi login sub-forms se "\u2190 Back" link hata do (teeno portals) — Vicky ne bola.
    try{ box.querySelectorAll('p[onclick]').forEach(function(pp){ if(/goHome/.test(pp.getAttribute('onclick')||'')) pp.style.display='none'; }); }catch(e){}
    // purane gold-square version ke elements (agar hon) hata do
    var oldB=document.getElementById('mvs-auth-brand'); if(oldB) oldB.remove();
    var oldS=document.getElementById('mvs-auth-switch'); if(oldS) oldS.remove();
    scr.style.background='';                       // inline hata do — class handle karti hai
    scr.classList.remove('auth-light','auth-console','role-teacher','role-admin');
    var isStudent=(portal==='student');
    // Teacher aur Admin ko alag pehchan: alag color + icon + badge.
    var roleUI={teacher:{title:'Teacher Console',icon:'users',badge:'Faculty Access'},
                admin:{title:'Admin Console',icon:'shield',badge:'Administrator'},
                production:{title:'Production Console',icon:'shield',badge:'Production Manager'},
                editor:{title:'Editor Workspace',icon:'users',badge:'Editor Access'},
                youtuber:{title:'Creator Studio',icon:'users',badge:'Content Creator'},
                graphics:{title:'Graphics Workspace',icon:'users',badge:'Graphics Access'}};
    if(isStudent){ scr.classList.add('auth-light'); }
    else { scr.classList.add('auth-console'); scr.classList.add(portal==='admin'?'role-admin':'role-teacher'); }
    var rc=roleUI[portal];
    var title=isStudent?'Student Portal':(rc?rc.title:'Console');
    // brand: ASLI MVS logo + title (+ teacher/admin role badge)
    var brand=document.getElementById('mvs-auth2-brand');
    if(!brand){ brand=document.createElement('div'); brand.id='mvs-auth2-brand'; brand.className='a2-brand'; box.insertBefore(brand, box.firstChild); }
    brand.style.display='';
    var badgeHtml=(isStudent||!rc)?'':('<div class="a2-role-badge">'+(typeof ic==='function'?ic(rc.icon):'')+'<span>'+rc.badge+'</span></div>');
    brand.innerHTML='<div class="a2-logo">'+_mvsLogoImg(62)+'</div><div class="a2-title">'+title+'</div>'+badgeHtml;
    // switcher: STUDENT par nahi (clean); teacher/admin par baaki portals
    var sw=document.getElementById('mvs-auth2-switch');
    if(isStudent){ if(sw) sw.style.display='none'; return; }
    if(!sw){ sw=document.createElement('div'); sw.id='mvs-auth2-switch'; sw.className='a2-switch'; box.appendChild(sw); }
    sw.style.display='';
    var others=['student','teacher','admin'].filter(function(x){return x!==portal;});
    sw.innerHTML='<span>Switch portal</span><div class="a2-switch-row">'+
      others.map(function(x){return '<button type="button" class="a2-pill" onclick="goLogin(\''+x+'\')">'+(_AUTH_META[x]?_AUTH_META[x].tag:x)+'</button>';}).join('')+'</div>';
  }catch(e){}
}

// ========================================================
//  CONFIG — Aapka live backend URL (same-origin primary, taaki ISP-block ka asar na ho)
// ========================================================
// app.mvsfoundation.in KHUD API bhi serve karta hai (confirmed). Isliye API ko USI domain se call
// karte hain jahan se page khula — wo hamesha reachable hai (page usi se aaya to API bhi aayega),
// to kisi student ke ISP/DNS ne Railway domain block kiya ho to bhi login/logo chalta rahega.
// Railway aur api.mvsfoundation.in sirf FALLBACK hain (agar kabhi same-origin fail ho).
const API_DEFAULT = "https://mvs-foundation-api-production-0553.up.railway.app";
const _API_BASES = [];
try{ if(/^https/i.test(location.origin||'')) _API_BASES.push(location.origin); }catch(e){}
if(_API_BASES.indexOf(API_DEFAULT)<0) _API_BASES.push(API_DEFAULT);
if(_API_BASES.indexOf("https://api.mvsfoundation.in")<0) _API_BASES.push("https://api.mvsfoundation.in");
let API = _API_BASES[0];
// Note: same-origin hamesha reachable + API serve karta hai, isliye wahi primary rehta hai.
// _apiSetBase runtime par sirf tab base badalta hai jab same-origin kabhi fail ho (safety net).
function _apiSetBase(b){
  if(!b || b===API) return;
  API=b;
  try{ localStorage.setItem('mvs_api_base', b); }catch(e){}
  try{ _refreshLogos(); }catch(e){}
  try{ _setFavicon(); }catch(e){}
}
function _refreshLogos(){
  try{
    document.querySelectorAll('img[src*="/api/student/logo"]').forEach(function(im){
      im.onerror=function(){ try{ _logoFallback(im); }catch(e){} };
      im.src=_logoSrc()+'?t='+Date.now();
    });
  }catch(e){}
}

let TOKEN = null, ROLE = null, NAME = null, CURRENT_PORTAL = null;
let countdownTimer = null;

// ========================================================
//  API HELPER
// ========================================================
// v113: in-memory GET cache (30s) — section switches network ke bina instant khulte hain.
// Koi bhi successful POST/PATCH/DELETE poora cache clear kar deta hai, to data kabhi
// stale nahi rehta. Login/logout pe bhi clear hota hai.
const _apiCache={};
const _API_TTL=60000;
const _API_NOCACHE=/notifications|heartbeat|\/photo|\/image|\/voice|\/file|\/download|\/pdf|\/content|\/badge|video-tasks\/my|video-tasks\b|production\/tasks|production\/dashboard|(editor|graphics|youtuber)\/(tasks|videos|dashboard)|\/collab/i;
let _curLoader=null;        // current page ka loader — background refresh aane par isse re-render
let _swrT=null;
function _swrRerender(){
  if(_swrT) return;
  _swrT=setTimeout(function(){
    _swrT=null;
    // v170: agar user abhi kisi input/textarea me type kar raha hai (ya select khula hai),
    // to background refresh ka re-render MAT karo — warna text aur focus dono udd jaate hain.
    // Thodi der baad phir try karega; type khatam hote hi normal refresh ho jaayega.
    try{
      var ae=document.activeElement;
      if(ae && /^(INPUT|TEXTAREA|SELECT)$/.test(ae.tagName||'') && ae.type!=='checkbox' && ae.type!=='radio' && ae.type!=='button'){
        _swrT=setTimeout(function(){ _swrT=null; _swrRerender(); }, 800);
        return;
      }
    }catch(e){}
    try{ if(typeof _curLoader==='function') _curLoader(); }catch(e){}
  }, 140);
}
function _apiBust(){ for(const k in _apiCache){ if(_apiCache[k]) _apiCache[k].t=0; } }  // delete nahi — stale mark (SWR: turant stale + bg refresh)
async function _apiRefreshBg(path,_ck){
  try{
    const opts={method:'GET',headers:{'Content-Type':'application/json'}};
    if(TOKEN) opts.headers['Authorization']='Bearer '+TOKEN;
    if(window._payoutToken) opts.headers['X-Payout-Token']=window._payoutToken;
    const res=await fetch(API+path,opts); if(!res.ok) return;
    const d=await res.json();
    try{ const s=JSON.stringify(d);
      if(s.length<1572864){
        const old=_apiCache[_ck];
        const changed=!old||JSON.stringify(old.d)!==s;   // data BADLA tabhi re-render (warna view disturb nahi)
        _apiCache[_ck]={t:Date.now(),d:d};
        if(changed) _swrRerender();
      }
    }catch(e){}
  }catch(e){}
}
function _preloadAdmin(){
  // Login ke baad SAARE sections ka data background me cache kar lo — taaki click karte hi
  // 0ms me khule (api() cached turant deta hai, fresh bg me aa jaata hai).
  try{
    const m=(new Date()).toISOString().slice(0,7);
    const urls=[
      '/api/admin/dashboard','/api/admin/portal-overview','/api/admin/teachers',
      '/api/admin/video-tasks',
      '/api/admin/doubts?status=pending','/api/admin/doubts-overview',
      '/api/admin/timetable-all','/api/admin/materials-tree','/api/admin/live-users',
      '/api/admin/student-filter-counts?source=&session=&medium=&cls=',
      '/api/admin/students-paged?q=&source=&cls=&session=&medium=&batch=&subject=&page=1&page_size=10'
    ];
    let i=0;
    (function next(){
      if(i>=urls.length) return;
      const u=urls[i++];
      api(u).catch(function(){}).finally(function(){ setTimeout(next, 120); });
    })();
  }catch(e){}
}
async function api(path, method='GET', body=null) {
  const opts = { method, headers: { 'Content-Type':'application/json' } };
  if (TOKEN) opts.headers['Authorization'] = 'Bearer ' + TOKEN;
  if (window._payoutToken) opts.headers['X-Payout-Token'] = window._payoutToken;
  if (body) opts.body = JSON.stringify(body);
  const _ck=method+' '+path;
  if(method==='GET'&&!_API_NOCACHE.test(path)){
    const hit=_apiCache[_ck];
    if(hit){
      // stale ho to bhi TURANT cached do (0ms) — stale hone par background me refresh + re-render
      if((Date.now()-hit.t)>=_API_TTL && !hit._bg){ hit._bg=1; _apiRefreshBg(path,_ck).finally(()=>{ if(_apiCache[_ck]) _apiCache[_ck]._bg=0; }); }
      return hit.d;
    }
  }
  // network fail (Failed to fetch) pe 2 baar aur retry — backend cold-start/restart sambhal jaata hai.
  // v113: badi bodies (PDF base64 uploads) ko retry MAT karo — server pehli baar me save kar
  // chuka ho sakta hai; dobara bhejne se duplicate banta hai aur screen "Saving..." pe atakti thi.
  // Network resilience: Railway backend cold-start me 30-60s le sakta hai (so jaata hai to
  // pehli request use jagati hai). Isliye network-fail par GENTLE backoff ke saath kai baar
  // retry karte hain — student ko scary error ke bajaye backend apne aap ready hone tak wait
  // ho jata hai. Sacchi offline state me turant (bina 30s hang) friendly message. Badi uploads
  // sirf 1 baar (duplicate save se bachne ke liye).
  // Network resilience: (1) Railway cold-start me 30-60s -> gentle backoff se retry. (2) Agar
  // student ke ISP ne primary domain block kar diya ho to baaki reachable bases apne aap try
  // hote hain aur jo chale wahi yaad rakh liya jaata hai. Badi uploads sirf 1 try (duplicate se
  // bachao). Note: fetch sirf NETWORK fail (connect na ho) par throw hota hai — 4xx/5xx nahi —
  // isliye dusra base sirf tab try hota hai jab sach me domain reachable hi nahi.
  const _bigBody=(opts.body&&opts.body.length>524288);
  const _delays=_bigBody?[]:[1200,2000,3000,5000,8000,8000];
  const _tryBases=[API].concat(_API_BASES.filter(function(b){ return b!==API; }));
  let res=null,_wasOffline=false,_usedBase=API;
  for(let bi=0; bi<_tryBases.length && !res && !_wasOffline; bi++){
    const base=_tryBases[bi];
    const delays=(bi===0)?_delays:[1500];   // primary: poora backoff; fallback base: quick single retry
    for(let attempt=0; attempt<=delays.length; attempt++){
      try{ res=await fetch(base+path, opts); _usedBase=base; break; }
      catch(e){
        res=null;
        if(typeof navigator!=='undefined' && navigator.onLine===false){ _wasOffline=true; break; }
        if(attempt<delays.length) await new Promise(r=>setTimeout(r, delays[attempt]));
      }
    }
  }
  if(res && _usedBase!==API) _apiSetBase(_usedBase);
  if(!res){
    if(_wasOffline) throw new Error('You appear to be offline. Please check your internet — the page will update on its own once you are back online.');
    throw new Error('The server is just waking up. Please wait a few seconds and tap the button again — it will work.');
  }
  let data;
  try { data = await res.json(); } catch { data = null; }
  if (!res.ok) {
 const msg = (data && data.detail) ? data.detail : ('Error ' + res.status);
 const err = new Error(msg); err.status = res.status; throw err;
  }
  if(typeof _auth401!=='undefined') _auth401=0;   // koi bhi success -> 401-streak reset
  if(method==='GET'){
    if(!_API_NOCACHE.test(path)){ try{ if(JSON.stringify(data).length<1572864) _apiCache[_ck]={t:Date.now(),d:data}; }catch(e){} }
  } else _apiBust();
  return data;
}

// ========================================================
//  BULLETPROOF CONNECTIVITY — cold-start warm-up + silent auto-refresh
//  Students ko kabhi manually refresh na karna pade, aur "server not reachable" panic khatam.
// ========================================================
// Railway backend so jaata hai. Login screen dikhte hi (aur reconnect par) backend ko background
// me jaga do — taaki student jab tak phone type kare, server ready ho jaaye. Success (koi bhi HTTP
// response) tak silently retry; kabhi bhi UI par error nahi.
let _warmDone=false, _warmT=null, _warmN=0;
// Backend warm-up + safety net. Pehle CURRENT base (aam taur par same-origin) ko jagao. Wo reachable
// ho to bas — kabhi kisi aur base par switch nahi (working same-origin ko badalna nahi). Sirf agar
// current base sach me reachable na ho, tabhi fallbacks me se jo pehla chale use adopt karo.
function _warmBackend(){
  if(_warmDone) return;
  try{ if(_warmT) clearTimeout(_warmT); }catch(e){}
  fetch(API+'/api/student/logo',{cache:'no-store',mode:'no-cors'})
    .then(function(){ _warmDone=true; _warmN=0; })
    .catch(function(){ _warmTryFallbacks(); });
}
function _warmTryFallbacks(){
  var others=_API_BASES.filter(function(b){ return b!==API; });
  var pending=others.length;
  if(!pending){ _warmRetryLater(); return; }
  others.forEach(function(base){
    fetch(base+'/api/student/logo',{cache:'no-store',mode:'no-cors'})
      .then(function(){ pending--; if(!_warmDone){ _warmDone=true; _warmN=0; _apiSetBase(base); } })
      .catch(function(){ pending--; if(!_warmDone && pending<=0) _warmRetryLater(); });
  });
}
function _warmRetryLater(){
  if(_warmDone) return;
  _warmN++; if(_warmN<20){ _warmT=setTimeout(_warmBackend, 3500); }   // koi base abhi reachable nahi -> dobara
}
// Current page ka data chupchaap fresh karo (spinner/flicker ke bina). _apiBust sab cache stale
// mark karta hai; _swrRerender typing-safe re-render karta hai jo background me naya data laata hai
// aur badla ho to hi dobara render karta hai. Isse student ko update apne aap milta rehta hai.
let _lastAutoRefresh=0;
function _autoRefreshNow(force){
  try{
    if(document.visibilityState!=='visible') return;
    if(typeof navigator!=='undefined' && navigator.onLine===false) return;
    const now=Date.now();
    if(!force && (now-_lastAutoRefresh)<8000) return;   // throttle — flood na ho
    _lastAutoRefresh=now;
    try{ _apiBust(); }catch(e){}
    try{ _swrRerender(); }catch(e){}
  }catch(e){}
}
// Tab wapas focus me aane par: turant fresh data + backend jagao.
document.addEventListener('visibilitychange', function(){
  if(document.visibilityState==='visible'){ _warmBackend(); _autoRefreshNow(true); }
});
// Internet wapas aane par: re-warm + fresh data + session ping.
window.addEventListener('online', function(){
  _warmDone=false; _warmN=0; _warmBackend();
  _autoRefreshNow(true);
  try{ _pingNow(true); }catch(e){}
});
// Halka periodic auto-refresh — koi bhi portal khula ho to har 60s me chupchaap fresh data.
setInterval(function(){ if(TOKEN) _autoRefreshNow(false); }, 60000);
// "Saving..." pe dead nahi dikhti; percent chalta rehta hai.
function _xhrJson(url,payload,onProgress){
  return new Promise((resolve,reject)=>{
    const xhr=new XMLHttpRequest(); xhr.open('POST',API+url);
    if(TOKEN) xhr.setRequestHeader('Authorization','Bearer '+TOKEN);
    xhr.setRequestHeader('Content-Type','application/json');
    if(xhr.upload) xhr.upload.onprogress=e=>{ if(e.lengthComputable&&onProgress) onProgress(Math.round(e.loaded/e.total*100)); };
    xhr.onload=()=>{ let j=null; try{ j=JSON.parse(xhr.responseText); }catch(e){}
      if(xhr.status>=200&&xhr.status<300){ _apiBust(); resolve(j||{}); }
      else{ const er=new Error((j&&j.detail)||('Error '+xhr.status)); er.status=xhr.status; reject(er); } };
    xhr.onerror=()=>reject(new Error('Could not reach the server — with a large file the upload may still have completed, so please check once before trying again.'));
    xhr.send(JSON.stringify(payload));
  });
}

