function fmtDur(s){ s=Math.max(0,s|0); const m=Math.floor(s/60), h=Math.floor(m/60); if(h>0) return h+'h '+(m%60)+'m'; if(m>0) return m+'m '+(s%60)+'s'; return s+'s'; }
