/* notification type -> us section ka page jahan redirect hona hai */
const NOTIF_GO={
  student:{new_material:'materials',new_notes:'materials',questionbank:'qbank',test_reminder:'tests',exam_result:'tests',marks:'tests',
    doubt_resolved:'doubts',new_doubt:'doubts',doubt:'doubts',timetable:'timetable',new_class:'timetable',class:'timetable',
    reschedule_approved:'timetable',reschedule_rejected:'timetable',class_rescheduled:'timetable',dpp:'dpp',new_dpp:'dpp',dpp_checked:'dpp',
    result:'resultcard',predicted:'resultcard',warning:'dashboard'},
  teacher:{class_request:'timetable',class_approved:'timetable',class_rejected:'timetable',new_class:'timetable',timetable:'timetable',
    reschedule_approved:'timetable',reschedule_rejected:'timetable',reschedule_request:'timetable',leave:'attendance',
    doubt:'doubts',new_doubt:'doubts',admin_message:'notifications',admin_broadcast:'notifications',broadcast:'notifications',
    video_task:'vtasks',video_proposal:'vtasks',new_video_proposal:'vtasks',video_submitted:'vtasks',
    payout:'payout',attendance:'attendance',dpp:'dpp',test:'tests',warning:'dashboard'},
  admin:{class_request:'approvals',teacher_to_admin:'reports',app_review:'approvals',new_class:'timetable',timetable:'timetable',
    reschedule_request:'approvals',class_rescheduled:'timetable',leave:'attendance',
    video_task:'vtasks',video_proposal:'vtasks',new_video_proposal:'vtasks',video_submitted:'vtasks',
    doubt:'doubts',new_doubt:'doubts',doubt_resolved:'doubts',teacher_message:'reports',payout:'payouts',attendance:'attendance',warning:'dashboard'}
};
/* Fallback: agar exact type map me na ho, to type ke keywords se sahi section dhoondo —
   isse har notification click sahi jagah le jaata hai (dashboard pe atak nahi jaata). */
function _notifResolvePage(role,type,fbPage){
  const exact=(NOTIF_GO[role]||{})[type||''];
  if(exact) return exact;
  const t=(type||'').toLowerCase();
  const has=w=>t.indexOf(w)>=0;
  let g='';
  if(has('complaint')) g='complaints';
  else if(has('feedback')) g='feedback';
  else if(has('doubt')) g='doubts';
  else if(has('video')||has('task')||has('reshoot')||has('proposal')) g='vtasks';
  else if(has('reschedule')||has('class')||has('timetable')||has('slot')) g='timetable';
  else if(has('payout')||has('salary')||has('incentive')) g=(role==='admin'?'payouts':'payout');
  else if(has('attend')||has('leave')||has('punch')) g='attendance';
  else if(has('test')||has('exam')||has('marks')||has('result')) g=(role==='admin'?'tests':(role==='teacher'?'tests':'tests'));
  else if(has('dpp')) g='dpp';
  else if(has('material')||has('note')||has('qbank')||has('syllabus')) g=(role==='student'?'materials':'qbank');
  else if(has('approval')||has('request')) g=(role==='admin'?'approvals':'timetable');
  else if(has('message')||has('broadcast')) g=(role==='admin'?'reports':'notifications');
  // admin ke case me section-access check — na ho to fallback page
  if(g && role==='admin'){ try{ if(!adminAllowed(g)) g=''; }catch(e){} }
  return g||fbPage||'';
}
function _notifAvHtml(n,fb){
  if(!n.image_url) return '';
  return `<div class="notif-av" data-nimg="${esc(n.image_url)}">${esc(initials(fb||'MVS'))}<span class="mvs-b">M</span></div>`;
}
async function _notifImgs(root){
  if(!root) return;
  for(const el of [...root.querySelectorAll('[data-nimg]')]){
    const u=el.getAttribute('data-nimg'); if(!u) continue;
    try{
      const r=await fetch(API+u,{headers:{Authorization:'Bearer '+TOKEN}});
      if(r.ok){ el.style.backgroundImage=`url(${URL.createObjectURL(await r.blob())})`;
        el.textContent=''; const b=document.createElement('span'); b.className='mvs-b'; b.textContent='M'; el.appendChild(b); }
    }catch(e){}
  }
  // full-size attached image preview (admin notification)
  for(const el of [...root.querySelectorAll('[data-nimg-full]')]){
    const u=el.getAttribute('data-nimg-full'); if(!u) continue;
    try{
      const r=await fetch(API+u,{headers:{Authorization:'Bearer '+TOKEN}});
      if(r.ok){ el.src=URL.createObjectURL(await r.blob()); el.style.display='block'; }
    }catch(e){}
  }
}
async function notifGo(role,nid,type,fbPage){
  // NAVIGATE PEHLE (read-call ka intezaar nahi) — warna slow/failed read navigation ko rok deta tha.
  const page=_notifResolvePage(role,type,fbPage);
  closeModal();
  if(page){
    const navTo=(role==='teacher')?tPage:(role==='admin')?aPage:sPage;
    try{ navTo(page,null); }catch(e){}
    // navbar me active item bhi sahi dikhe
    const appId=role==='teacher'?'teacher-app':role==='admin'?'admin-app':'student-app';
    document.querySelectorAll('#'+appId+' .nav-item').forEach(el=>{
      el.classList.remove('active');
      if((el.getAttribute('onclick')||'').includes("'"+page+"'")) el.classList.add('active');
    });
  }
  // read + badge background me (fire-and-forget)
  if(nid){ try{ api(notifEp(role,'/notifications/'+nid+'/read'),'PATCH').catch(function(){}); }catch(e){} }
  try{ refreshNotifBadge(role); }catch(e){}
}
async function openNotifPanel(role){
  let list;
  try{ list=await fetchNotifs(role); }catch(e){ if(e&&e.status===401){ _sessionExpired(); return; } list=[]; }
  const fbPage=role==='admin'?'dashboard':'notifications';
  const html=list.length?list.map(n=>{
    const hasLink=!!n.link;
    const click=hasLink?`notifLinkOpen('${role}',${n.id},'${encodeURIComponent(n.link)}','${esc(n.notif_type||'')}','${fbPage}')`:`notifGo('${role}',${n.id},'${esc(n.notif_type||'')}','${fbPage}')`;
    const unread=!n.is_read;
    const hint=hasLink?` <span style="font-size:.68rem;color:var(--primary);font-weight:800">Open Link &#8250;</span>`:' <span style="font-size:.68rem;color:var(--primary);font-weight:800">&#8250;</span>';
    const isBroadcast=(n.notif_type==='admin_broadcast');
    const av=(isBroadcast&&n.image_url)?'':_notifAvHtml(n,'MVS');
    const imgPrev=(isBroadcast&&n.image_url)?`<img data-nimg-full="${esc(n.image_url)}" alt="" style="width:100%;max-height:220px;object-fit:cover;border-radius:10px;margin-top:8px;display:none;background:var(--border)">`:'';
    const dot=unread?`<span style="width:9px;height:9px;border-radius:50%;background:var(--primary);flex:0 0 9px;margin-top:6px;box-shadow:0 0 0 3px var(--primary-50)"></span>`:'';
    const inner=`<div class="ni-title" style="font-weight:${unread?'800':'600'}">${esc(n.title)}${hint}</div><div class="ni-msg"${unread?' style="color:var(--text);font-weight:500"':''}>${esc(n.message)}</div>${imgPrev}<div class="ni-time"> ${fmtNice(n.created_at)}</div>`;
    const itStyle=`cursor:pointer;${unread?'border-left:3px solid var(--primary);background:linear-gradient(90deg,var(--primary-50),transparent 70%)':''}`;
    return `<div class="notif-item ${unread?'unread':''}" data-go="1" style="${itStyle}" onclick="${click}" title="${hasLink?'Tap to open the link':'Tap to open this section'}"><div class="notif-row" style="display:flex;gap:10px;align-items:flex-start">${dot}${av}<div style="min-width:0;flex:1">${inner}</div></div></div>`;
  }).join(''):'<div class="empty-state"><div class="empty-icon"></div><p>No notifications yet</p></div>';
  showModal(' Notifications',html,`<button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
  _notifImgs(document.getElementById('modal-body'));
  // SMART: panel khulte hi sab read -> badge/count clear, bell blink band, dobara na dikhe
  // jab tak koi naya notification na aaye. (Items is view me highlighted rehte hain jisse
  // pata chale kaunse naye the.)
  if(list.some(n=>!n.is_read)){
    api(notifEp(role,'/notifications/read-all'),'PATCH').catch(()=>{});
    list.forEach(n=>n.is_read=true);
    _lastUnread[role]=0;
    const b=document.getElementById((role==='teacher'?'t':role==='admin'?'a':'s')+'-notif-badge');
    if(b) b.style.display='none';
    _setBellUnread(role,false);
    const np=document.getElementById('notif-pop'); if(np) np.remove();
  }
}
function _setBellUnread(role,on){
  const b=document.getElementById((role==='teacher'?'t':role==='admin'?'a':'s')+'-notif-badge');
  const w=b&&b.closest('.bell-wrap'); if(w) w.classList.toggle('has-unread',!!on);
}
async function notifLinkOpen(role,id,encLink,ntype,fbPage){
  try{ await api(notifEp(role,'/notifications/'+id+'/read'),'PATCH'); }catch(e){}
  const link=decodeURIComponent(encLink||'');
  try{ refreshNotifBadge(role); }catch(e){}
  // Real URL -> open in a new tab
  if(/^https?:\/\//i.test(link)){ if(link) window.open(link,'_blank','noopener'); openNotifPanel(role); return; }
  // Support deep links -> open the exact record INSIDE the portal
  if(link.indexOf('/support/')===0){
    closeModal();
    var _appId=role==='admin'?'admin-app':'student-app';
    var _navTo=(role==='admin')?aPage:sPage;
    if(link.indexOf('/support/feedback')===0){
      try{ _navTo('feedback',null); }catch(e){}
      _supActivateNav(_appId,'feedback'); return;
    }
    var _m=link.match(/\/support\/complaint\/(\d+)/);
    try{ _navTo('complaints',null); }catch(e){}
    _supActivateNav(_appId,'complaints');
    if(_m){ var _cid=parseInt(_m[1],10); setTimeout(function(){ try{ (role==='admin')?amcCmpOpen(_cid):scOpenDetail(_cid); }catch(e){} }, 420); }
    return;
  }
  // Numeric task id -> navigate INSIDE the app to that task and highlight it
  const tid=parseInt(link,10);
  if(tid && (''+tid)===link.trim()){
    closeModal();
    const page=_notifResolvePage(role,ntype||'video_task',fbPage||'vtasks');
    if(page){
      const navTo=(role==='teacher')?tPage:(role==='admin')?aPage:sPage;
      try{ navTo(page,null); }catch(e){}
      const appId=role==='teacher'?'teacher-app':role==='admin'?'admin-app':'student-app';
      document.querySelectorAll('#'+appId+' .nav-item').forEach(el=>{ el.classList.remove('active'); if((el.getAttribute('onclick')||'').includes("'"+page+"'")) el.classList.add('active'); });
    }
    setTimeout(()=>_focusTaskCard(tid),650);
    return;
  }
  if(link) window.open(link,'_blank','noopener');
  openNotifPanel(role);
}
function _focusTaskCard(tid){
  // find the task card by any known data-attribute and scroll+flash it
  let el=document.querySelector('[data-tid-card="'+tid+'"]')
      || document.querySelector('.vt-card [id="tvt-link-'+tid+'"]')
      || document.querySelector('[data-vt-cd="'+tid+'"]');
  if(el && !el.classList.contains('vt-card')){ const c=el.closest('.vt-card'); if(c) el=c; }
  if(!el){
    // retry once after lists finish loading
    setTimeout(()=>{ let e2=document.querySelector('[data-tid-card="'+tid+'"]'); if(e2){ e2.scrollIntoView({behavior:'smooth',block:'center'}); _flashCard(e2); } },900);
    return;
  }
  el.scrollIntoView({behavior:'smooth',block:'center'}); _flashCard(el);
}
function _flashCard(el){
  try{ el.style.transition='box-shadow .3s'; const prev=el.style.boxShadow; el.style.boxShadow='0 0 0 3px var(--primary)'; setTimeout(()=>{ el.style.boxShadow=prev||''; },1600); }catch(e){}
}
async function markAllRead(role){
  let list;
  try{ list=await fetchNotifs(role); }catch(e){ if(e&&e.status===401){ _sessionExpired(); return; } list=[]; }
  for(const n of list.filter(x=>!x.is_read)){ try{ await api(notifEp(role,'/notifications/'+n.id+'/read'),'PATCH'); }catch(e){} }
  closeModal(); refreshNotifBadge(role); _lastUnread[role]=0; var _np=document.getElementById('notif-pop'); if(_np)_np.remove(); toast('All marked as read.');
}
let _notifInt=null, _lastUnread={};
function showNotifPop(role,unread){
  const appId=role==='teacher'?'teacher-app':role==='admin'?'admin-app':'student-app';
  const main=document.querySelector('#'+appId+' .main'); if(!main) return;
  const old=document.getElementById('notif-pop'); if(old) old.remove();
  if(!unread.length) return;
  const latest=unread[0];
  const banner=`<div class="notif-pop" id="notif-pop"><div class="np-dot"></div><div class="np-body"><div class="np-title">${unread.length} new notification${unread.length>1?'s':''}</div><div class="np-msg">${esc(latest.title)}</div></div><button class="btn btn-primary btn-sm" onclick="openNotifPanel('${role}')">View</button><span class="np-close" onclick="document.getElementById('notif-pop').remove()">✕</span></div>`;
  const tb=main.querySelector('.topbar');
  if(tb) tb.insertAdjacentHTML('afterend',banner); else main.insertAdjacentHTML('afterbegin',banner);
}
async function notifPopupOnOpen(role){
  const list=await refreshNotifBadge(role);
  const unread=list.filter(n=>!n.is_read);
  _lastUnread[role]=unread.length;
  showNotifPop(role,unread);
  startNotifPolling(role);
}
async function pollNotifs(role){
  if(document.hidden) return;   // v167: backgrounded tab poll na kare -> server load kam
  let list;
  try{ list=await fetchNotifs(role); }catch(e){ if(e&&e.status===401){ _sessionExpired(); return; } throw e; }
  const unread=list.filter(n=>!n.is_read);
  const badge=document.getElementById((role==='teacher'?'t':role==='admin'?'a':'s')+'-notif-badge');
  if(badge){ badge.style.display=unread.length?'flex':'none'; badge.textContent=unread.length; }
  _setBellUnread(role,unread.length>0);
  const prev=_lastUnread[role]||0;
  if(unread.length>prev){ showNotifPop(role,unread); }
  _lastUnread[role]=unread.length;
  if(role==='admin') _avtBadgePoll();   // v115: Task Manager badge bhi saath refresh
}
function _sessionExpired(){
  if(window._sessDead) return; window._sessDead=true;
  stopNotifPolling(); stopStudentHeartbeat(); stopAdminLivePoll();
  toast('Your session has expired — please log in again.', true);
  setTimeout(()=>{ window._sessDead=false; goHome(); }, 1600);
}
function startNotifPolling(role){ stopNotifPolling(); pollNotifs(role).catch(()=>{}); _notifInt=setInterval(()=>pollNotifs(role).catch(e=>{ if(e&&e.status===401) _authFail(); }),45000); }
function stopNotifPolling(){ if(_notifInt){ clearInterval(_notifInt); _notifInt=null; } }
// ===== SEND NOTIFICATIONS (admin + teacher) =====
// ===== v93: notify modals — recipient clarity + live student counts =====
async function openAdminNotify(){
  if(!adminAllowed('notify')){ toast('You do not have access to this section.',true); return; }
  showModal('Send Notification','<div class="spinner"></div>','');
  let c={all:0,teachers:0,students:0,subjects:[],classes:[]};
  try{ c=await api('/api/admin/notify-targets'); }catch(e){}
  window._anCounts=c; window._anImg=null; window._anSubsByClass=c.subjects_by_class||{}; window._anAllSubs=c.subjects||[];
  const subOpts=['<option value="">All subjects</option>'].concat((c.subjects||[]).map(s=>`<option value="${esc(s)}">${esc(s)}</option>`)).join('');
  const clsOpts=['<option value="">All classes</option>'].concat((c.classes||[]).map(cl=>`<option value="${esc(cl)}">Class ${esc(cl)}</option>`)).join('');
  showModal('Send Notification',
   `<div class="form-group"><label>Send To</label>
      <select class="form-control" id="an-target" onchange="anScope()">
        <option value="all">Everyone — Teachers + Students (${c.all})</option>
        <option value="teachers">Teachers Only (${c.teachers})</option>
        <option value="students">Students Only (${c.students})</option>
      </select></div>
    <div id="an-filters" class="ex-grid2" style="display:none">
      <div><label class="ex-lbl">Class (optional)</label><select class="form-control" id="an-class" onchange="anClassChange()">${clsOpts}</select></div>
      <div><label class="ex-lbl">Subject (optional)</label><select class="form-control" id="an-subject" onchange="anScope()">${subOpts}</select></div>
    </div>
    <div id="an-scope" style="margin:6px 0 12px"></div>
    <div class="form-group"><label>Title</label><input class="form-control" id="an-title" placeholder="e.g. Holiday Notice"></div>
    <div class="form-group"><label>Message</label><textarea class="form-control" id="an-msg" rows="4" placeholder="Write your message..."></textarea></div>
    <div class="form-group"><label>Attach Link <span style="color:var(--text-muted);font-weight:400">(optional — tapping the notification opens it)</span></label><input class="form-control" id="an-link" placeholder="https://..."></div>
    <div class="form-group"><label>Attach Image <span style="color:var(--text-muted);font-weight:400">(optional)</span></label>
      <input type="file" accept="image/*" id="an-imgfile" style="display:none" onchange="anPickImg(this)">
      <div id="an-imgbox"><button class="btn btn-ghost btn-sm" onclick="document.getElementById('an-imgfile').click()">${ic('upload')} Choose image</button></div>
    </div>`,
   `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="submitAdminNotify()">${ic('bell')} Send Notification</button>`);
  anScope();
}
function anClassChange(){
  const cl=val('an-class');
  const sel=document.getElementById('an-subject');
  if(sel){
    const byCls=window._anSubsByClass||{};
    const subs=cl?(byCls[cl]||[]):(window._anAllSubs||[]);
    const cur=sel.value;
    sel.innerHTML=['<option value="">All subjects</option>'].concat(subs.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`)).join('');
    // agar pehle chuna subject nayi class me nahi hai to reset
    if(cur && subs.indexOf(cur)>=0) sel.value=cur; else sel.value='';
  }
  anScope();
}
function anScope(){
  const c=window._anCounts||{all:0,teachers:0,students:0};
  const t=document.getElementById('an-target'); const box=document.getElementById('an-scope'); const filt=document.getElementById('an-filters');
  if(!t||!box) return;
  const v=t.value;
  if(filt) filt.style.display=(v==='students')?'grid':'none';
  let label,n,star='';
  if(v==='teachers'){ label='Teachers Only'; n=c.teachers; }
  else if(v==='students'){
    label='Students'; n=c.students;
    const cl=val('an-class'), sub=val('an-subject');
    if(cl||sub){ label='Students'+(cl?' · Class '+cl:'')+(sub?' · '+sub:''); star='*'; }
  } else { label='Everyone — Teachers + Students'; n=c.all; }
  box.innerHTML=`<div style="display:flex;align-items:center;gap:14px;background:linear-gradient(135deg,var(--primary-50),#fff);border:1px solid var(--border);border-radius:14px;padding:12px 16px">
    <div style="font-size:1.7rem;font-weight:800;color:var(--primary);line-height:1">${n}${star}</div>
    <div style="font-size:.84rem"><b>${esc(label)}</b><br><span style="color:var(--text-muted);font-size:.74rem">${star?'Reaches the matching subset of these '+n+' students.':'This notification will reach '+n+' user'+(n===1?'':'s')+'.'}</span></div>
  </div>`;
}
async function anPickImg(inp){
  const f=inp.files&&inp.files[0]; if(!f) return;
  try{
    let file=f;
    if(typeof smartCompress==='function'){ try{ const r=await smartCompress(f,()=>{}); if(r&&r.ok&&r.file) file=r.file; }catch(e){} }
    const b64=await new Promise((res,rej)=>{ const rd=new FileReader(); rd.onload=()=>res(rd.result); rd.onerror=rej; rd.readAsDataURL(file); });
    window._anImg=b64;
    const box=document.getElementById('an-imgbox');
    if(box) box.innerHTML=`<div style="display:flex;align-items:center;gap:10px"><img src="${b64}" style="width:72px;height:72px;object-fit:cover;border-radius:10px;border:1px solid var(--border)"><button class="btn btn-ghost btn-sm" onclick="anClearImg()">${ic('trash')} Remove</button></div>`;
  }catch(e){ toast('Could not load image',true); }
}
function anClearImg(){
  window._anImg=null;
  const box=document.getElementById('an-imgbox');
  if(box) box.innerHTML=`<button class="btn btn-ghost btn-sm" onclick="document.getElementById('an-imgfile').click()">${ic('upload')} Choose image</button>`;
}
async function submitAdminNotify(){
  const title=val('an-title'), message=document.getElementById('an-msg').value.trim(), target=val('an-target');
  if(!title||!message){ toast('Title and message are required.',true); return; }
  const body={title,message,target};
  if(target==='students'){ body.class_name=val('an-class')||''; body.subject=val('an-subject')||''; }
  const link=val('an-link'); if(link) body.link=link;
  if(window._anImg) body.image_b64=window._anImg;
  const btns=document.querySelectorAll('.modal-footer .btn'); btns.forEach(b=>b.disabled=true);
  try{ const r=await api('/api/admin/notify','POST',body); closeModal(); toast(r.message); }
  catch(e){ toast(e.message,true); btns.forEach(b=>b.disabled=false); }
}
async function openTeacherNotify(){
  showModal(' Notify Students','<div class="spinner"></div>','');
  let tg={subjects:[],all_count:0,scoped:false};
  try{ tg=await api('/api/teacher/notify-targets'); }catch(e){}
  window._tnTargets=tg;
  const opts=[`<option value="">All My Students (${tg.all_count})</option>`]
    .concat((tg.subjects||[]).map(s=>{
      const clsTxt=(s.class&&s.class!=='?')?` (Class ${s.class})`:'';
      return `<option value="${esc(s.key||s.name)}">${esc(s.name)}${clsTxt} (${s.count})</option>`;
    })).join('');
  showModal(' Notify Students',
 `<div class="form-group"><label>Send To</label><select class="form-control" id="tn-target" onchange="tnScope()">${opts}</select></div><div class="ntf-scope" id="tn-scope"></div><div class="form-group"><label>Title</label><input class="form-control" id="tn-title" placeholder="e.g. Today's class timing"></div><div class="form-group"><label>Message</label><textarea class="form-control" id="tn-msg" rows="4" placeholder="Write your message..."></textarea></div>`,
 `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="submitTeacherNotify()">Send</button>`);
  tnScope();
}
function tnScope(){
  const tg=window._tnTargets||{subjects:[],all_count:0};
  const t=document.getElementById('tn-target'); const box=document.getElementById('tn-scope');
  if(!t||!box) return;
  const v=t.value; let label='All My Students', n=tg.all_count;
  if(v){ const s=(tg.subjects||[]).find(x=>(x.key||x.name)===v); if(s){ const clsTxt=(s.class&&s.class!=='?')?' (Class '+s.class+')':''; label=s.name+clsTxt+' Students'; n=s.count; } else { label=v+' Students'; n=0; } }
  box.innerHTML=`<div class="ns-n">${n}</div><div class="ns-t"><b>${esc(label)}</b><br>This notification will reach ${n} student${n===1?'':'s'}.</div>`;
}
async function submitTeacherNotify(){
  const title=val('tn-title'), message=document.getElementById('tn-msg').value.trim(), subject=val('tn-target');
  if(!title||!message){ toast('Title and message are required.',true); return; }
  try{ const r=await api('/api/teacher/notify','POST',{title,message,subject}); closeModal(); toast(r.message); }catch(e){ toast(e.message,true); }
}
