function trkCompare(tid){
  const me=_trkMe, other=(_trkBoard||[]).find(r=>r.teacher_id===tid);
  if(!me||!other) return;
  if(other.teacher_id===me.teacher_id){
    showModal('That\'s you!',`<p style="font-size:.88rem">You are at <b>Rank #${me.rank}</b> with a score of <b>${me.score}/100</b>. Tap another teacher to see what it takes to catch them.</p>`,`<button class="btn btn-primary btn-sm" onclick="closeModal()">OK</button>`);
    return;
  }
  const diff=Math.round((other.score-me.score)*10)/10;
  const ahead=diff>0;
  const mm=(me.metrics||{}), om=(other.metrics||{});
  const MET=[['dpp_cov','DPP coverage','pct'],['test_cov','test coverage','pct'],['lectures','on-time classes','pct'],['doubts','doubts resolved','pct'],['attendance','present days','count'],['tasks','on-time tasks','pct']];
  const gaps=MET.map(([k,lbl,ty])=>({k,lbl,ty,ov:(om[k]||0),mv:(mm[k]||0)}));
  gaps.forEach(g=>g.gap=g.ov-g.mv);
  const _sfx=g=>g.ty==='pct'?'%':'';
  const gapRows=gaps.map(g=>{
    const max=Math.max(1,g.ov,g.mv);
    return `<div class="trk-cmp-row"><span class="trk-cmp-lbl">${g.lbl[0].toUpperCase()+g.lbl.slice(1)}</span>
      <div class="trk-cmp-bars"><div class="trk-cmp-bar them" style="width:${Math.round(g.ov/max*100)}%"></div><div class="trk-cmp-bar me" style="width:${Math.round(g.mv/max*100)}%"></div></div>
      <span class="trk-cmp-val">${g.ov}${_sfx(g)} vs ${g.mv}${_sfx(g)}</span></div>`;
  }).join('');
  let suggest='';
  if(ahead){
    const TIP={dpp_cov:'Give a DPP in more of your syllabus chapters',test_cov:'Set a test in more of your chapters',lectures:'Complete your classes on their scheduled day',doubts:'Resolve any pending student doubts',attendance:'Mark present on more working days',tasks:'Deliver production tasks on time (propose your own for a bonus)'};
    const steps=gaps.filter(g=>g.gap>0).sort((a,b)=>b.gap-a.gap).slice(0,4).map(g=>`<li>${TIP[g.k]||g.lbl} — you're ${Math.round(g.gap)}${_sfx(g)} behind</li>`).join('');
    suggest=`<div class="trk-sugg"><b>&#128161; How to reach Rank #${other.rank}:</b><ul>${steps||'<li>You are already level on activity — consistency will tip the score.</li>'}</ul>
      <div class="trk-sugg-note">Close these and your score can climb to about <b>${other.score}</b> — right at Rank #${other.rank}.</div></div>`;
  }else{
    suggest=`<div class="trk-sugg"><b>&#127881; You are ahead!</b><div class="trk-sugg-note">You lead ${esc(other.name)} by <b>${Math.abs(diff)} points</b>. Keep your coverage, on-time classes and attendance steady to hold the position.</div></div>`;
  }
  showModal(`${esc(other.name)} — Rank #${other.rank}`,
    `<div class="trk-cmp-head"><div class="trk-cmp-cell"><div class="trk-cmp-score">${me.score}</div><div class="trk-cmp-who">You &middot; Rank #${me.rank}</div></div>
     <div class="trk-cmp-diff ${ahead?'behind':'ahead'}">${ahead?`${diff} pts behind`:`${Math.abs(diff)} pts ahead`}</div>
     <div class="trk-cmp-cell"><div class="trk-cmp-score">${other.score}</div><div class="trk-cmp-who">${esc(other.name)} &middot; Rank #${other.rank}</div></div></div>
     <div class="trk-cmp-legend"><span><i class="dot them"></i>${esc(other.name)}</span><span><i class="dot me"></i>You</span></div>
     ${gapRows}${suggest}`,
    `<button class="btn btn-primary btn-sm" onclick="closeModal()">Close</button>`);
}
async function loadTeacherToday(wrapId){
  const wrap=document.getElementById(wrapId||'t-today-wrap'); if(!wrap) return;
  try{
 const cls=await api('/api/teacher/today-classes');
 window._tClasses=cls; // v123: Submit Report modal (openClassReport) isi list se class prefill karta hai
 if(cls.length===0){ wrap.innerHTML='<div class="empty-state"><div class="empty-icon"></div><p>No classes today.</p></div>'; return; }
 const now=istNow();
 wrap.innerHTML=cls.map(e=>{
 const dt=parseClassDT(e.date,e.time);
 const over=dt && now>new Date(dt.getTime()+0);
 const isEvent=e.type==='event';
 const bareTopic=!isEvent && /^part\s*\d+$/i.test((e.part||'').trim());
 const ch=encodeURIComponent(e.chapter||''); const sub=encodeURIComponent(e.subject); const cln=encodeURIComponent(e.class_name||'');
 // status / actions
 let right='';
 if(bareTopic){
 right=`<span class="tstatus" style="background:rgba(239,68,68,.15);color:var(--danger)"> Topic Pending</span><button class="btn btn-ghost btn-sm" onclick="openEditTopic(${e.id},'${encodeURIComponent(e.part||'')}')"> Add Topic</button>`;
 } else if(isEvent){
 right=`<span class="tchip">${esc(e.time||'')}</span>`;
 } else if(e.notes && e.completed){
 right=`<span class="tstatus done"> Lecture Done · Material Done</span>`;
 } else {
 // v168: Submit Report ab SIRF class ka time nikalne ke BAAD dikhta hai (over=true).
 // Class se pehle (Upcoming) report ka button nahi aayega — sirf "Upcoming" chip.
 let _b='';
 if(!e.completed && (over || !dt)) _b+=`<button class="btn btn-success btn-sm" onclick="openClassReport(${e.id})"> Submit Report</button>`;
 if(!e.notes && (over || !dt)) _b+=`<button class="btn btn-primary btn-sm" onclick="openUploadHub({type:'notes',chapter:decodeURIComponent('${ch}'),subject:decodeURIComponent('${sub}'),class_name:decodeURIComponent('${cln}')})"> Upload Notes</button>`;
 if(over){
 _b+=`<span class="tstatus" style="background:rgba(245,158,11,.15);color:var(--warning)">${!e.completed?'Report Pending':'Material Pending'}</span>`;
 } else {
 _b+=`<span class="tstatus upcoming">Upcoming</span>`;
 }
 right=_b;
 }
 const redStyle=bareTopic?'border-color:var(--danger);background:rgba(239,68,68,.04)':'';
 return `<div class="today-row" style="${redStyle}"><div><div class="tr-sub">${isEvent?'':''} ${esc(e.subject)}</div><div class="tr-topic">${esc(e.part||e.chapter||'')}</div></div><div class="tmeta">${e.date?`<span class="tchip date"> ${fmtNice(e.date)}</span>`:''}${e.day?`<span class="tchip">${esc(e.day)}</span>`:''}${e.time?`<span class="tchip"> ${esc(e.time)}</span>`:''}${right}</div></div>`;
 }).join('');
  }catch(e){ wrap.innerHTML=errHtml(e); }
}

function statusTag(s){ if(s==='done')return '<span class="tag tag-done">Done</span>'; if(s==='rescheduled')return '<span class="tag tag-reschedule">Rescheduled</span>'; return '<span class="tag tag-pending">Pending</span>'; }

let _ttEntries=[]; let _ttActiveSub='';
let _rcChapters={};   // 'subject||class' -> [chapters] from the existing timetable
let _rcClasses={};    // subject -> [class_names]
async function openRequestClass(){
  let subs=[]; _rcChapters={}; _rcClasses={}; window._rcEntries=[];
  try{
    const es=await api('/api/teacher/my-timetable');
    window._rcEntries=es;
    subs=[...new Set(es.map(e=>e.subject))];
    es.forEach(e=>{
      const cls=(e.class_name||'').trim();
      if(cls){ (_rcClasses[e.subject]=_rcClasses[e.subject]||[]); if(!_rcClasses[e.subject].includes(cls)) _rcClasses[e.subject].push(cls); }
      if(e.type!=='event'&&e.chapter){ const k=e.subject+'||'+cls; (_rcChapters[k]=_rcChapters[k]||[]); if(!_rcChapters[k].includes(e.chapter)) _rcChapters[k].push(e.chapter); }
    });
  }catch(e){}
  if(subs.length===0){ try{ const p=await api('/api/teacher/profile'); subs=p.subjects||[]; }catch(e){} }
  const today=new Date().toISOString().slice(0,10);
  showModal('Add Extra Class',
    `<div class="alert alert-info" style="font-size:.78rem">Missed class ya absent day ki compensation — extra class <b>alag slot / alag timing</b> is added. Other classes stay in place, <b>no auto-shifting</b> hoti.</div>
    <div class="ex-grid2">
       <div><label class="ex-lbl">Subject</label><select class="form-control" id="rc-sub" onchange="rcFillCls();rcFillCh()">${subs.map(s=>`<option>${esc(s)}</option>`).join('')}</select></div>
       <div><label class="ex-lbl">Class</label><select class="form-control" id="rc-cls" onchange="rcFillCh()"></select></div>
     </div>
     <div style="margin-top:10px"><label class="ex-lbl">Chapter <span style="font-weight:600;color:var(--text-muted)">(selected class ke chapters)</span></label><select class="form-control" id="rc-ch" onchange="rcChSel()"></select></div>
     <div id="rc-newch" style="display:none;margin-top:10px"><label class="ex-lbl">New chapter / topic name</label><input class="form-control" id="rc-newch-in" placeholder="e.g. Chapter 12 \u2014 Thermodynamics"></div>
     <label class="ex-lbl" style="margin-top:10px">Part / Note <span style="font-weight:600;color:var(--text-muted)">(optional)</span></label>
     <input class="form-control" id="rc-topic" placeholder="e.g. Part 3 / Extra doubt class">
     <div class="ex-grid2" style="margin-top:10px">
       <div><label class="ex-lbl">Date</label><input type="date" class="form-control" id="rc-date" min="${today}" value="${today}"></div>
       <div><label class="ex-lbl">Time <span style="font-weight:600;color:var(--text-muted)">(regular slot se alag)</span></label><input type="time" class="form-control" id="rc-time" value="17:00"></div>
     </div>
     <div id="rc-status"></div>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" id="rc-btn" onclick="submitRequestClass()">Send for Approval</button>`);
  rcFillCls(); rcFillCh();
}
function rcFillCls(){
  const sel=document.getElementById('rc-cls'); if(!sel) return;
  const list=(_rcClasses[val('rc-sub')]||[]).slice().sort((a,b)=>{const na=parseInt((a.match(/\d+/)||['999'])[0])||999,nb=parseInt((b.match(/\d+/)||['999'])[0])||999;return na-nb||a.localeCompare(b);});
  sel.innerHTML=list.map(c=>`<option>${esc(c)}</option>`).join('')+(list.length?'':'<option value="">All classes</option>');
}
function rcFillCh(){
  const sel=document.getElementById('rc-ch'); if(!sel) return;
  const sub=val('rc-sub'), cls=(document.getElementById('rc-cls')||{}).value||'';
  let list=_rcChapters[sub+'||'+cls]||[];
  if(!list.length){  // fallback: is subject ke saare chapters (class info nahi mili to)
    const seen={}; list=[];
    Object.keys(_rcChapters).forEach(k=>{ if(k.indexOf(sub+'||')===0) _rcChapters[k].forEach(c=>{ if(!seen[c]){ seen[c]=1; list.push(c); } }); });
  }
  sel.innerHTML=list.map(c=>`<option>${esc(c)}</option>`).join('')+'<option value="__new">\u2795 New chapter / topic\u2026</option>';
  rcChSel();
}
function rcChSel(){
  const nw=document.getElementById('rc-newch');
  if(nw) nw.style.display=(val('rc-ch')==='__new')?'block':'none';
}
async function submitRequestClass(){
  const subject=val('rc-sub'), date=val('rc-date');
  const t=val('rc-time');
  const time=t?new Date('2000-01-01T'+t).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',hour12:true}).toLowerCase():'';
  const chSel=val('rc-ch');
  const chapter=(chSel&&chSel!=='__new')?chSel:(val('rc-newch-in')||val('rc-topic')||'Extra Class');
  const topic=val('rc-topic');
  if(!subject||!date||!time){ toast('Subject, date and time are required.',true); return; }
  if(chSel==='__new'&&!val('rc-newch-in')){ toast('Please enter the new chapter/topic name.',true); return; }
  // Same date + same time pe pehle se class hai to rok do — extra class alag slot pe honi chahiye
  const sameTm=(window._rcEntries||[]).find(e=>e.date===date&&e.time&&e.status!=='pending'&&((e.time||'').toLowerCase().replace(/\s/g,'')===time.replace(/\s/g,'')));
  if(sameTm){ document.getElementById('rc-status').innerHTML=`<div class="alert alert-danger">Is date/time pe aapki <b>${esc(sameTm.subject)}</b> class already exists (${esc(sameTm.time)}). Choose a different time for the extra class.</div>`; return; }
  const btn=document.getElementById('rc-btn'); btn.disabled=true; btn.textContent='Sending...';
  try{
    const r=await api('/api/teacher/extra-class','POST',{subject,topic,date,time,chapter,class_name:(document.getElementById('rc-cls')||{}).value||''});
    document.getElementById('rc-status').innerHTML=`<div class="alert alert-success">${esc(r.message)}</div>`;
    toast('Request sent to the admin.'); btn.textContent='Sent'; btn.setAttribute('onclick','closeModal()'); btn.disabled=false;
  }catch(e){ document.getElementById('rc-status').innerHTML=`<div class="alert alert-danger">${esc(e.message)}</div>`; btn.disabled=false; btn.textContent='Send for Approval'; }
}
// ===== TEACHER: MY STUDENTS (subject-wise counts) =====
// ===== AVATARS / PHOTOS =====
// v165 cross-user photo leak fix. The "own photo" endpoints (/api/{role}/my-photo)
// use the SAME URL for every user (the server resolves the user from the token). After
// the R2 migration these return a 302 redirect to the user's photo, and the browser was
// caching that redirect against the shared URL — so the next user who logged in on the
// same tab saw the previous user's photo. We defeat this with a per-login nonce appended
// to every "my-photo" fetch, and by purging all photo caches + avatar DOM on each login.
function _selfPhoto(role){
  const n=window._sessNonce||'';
  return '/api/'+(role==='teacher'?'teacher':role==='admin'?'admin':'student')+'/my-photo'+(n?('?v='+n):'');
}
function _freshSessionPhotos(){
  window._sessNonce=Date.now();
  try{ for(var _u in _imgBlobCache){ try{ URL.revokeObjectURL(_imgBlobCache[_u]); }catch(_){} delete _imgBlobCache[_u]; } }catch(e){}
  try{ window._photoUrls={}; }catch(e){}
  try{ if(window._myPhotoUrl){ URL.revokeObjectURL(window._myPhotoUrl); } }catch(e){}
  window._myPhotoUrl=null;
  try{
    document.querySelectorAll('.avatar,.topbar-avatar,#t-avatar,#t-topavatar,#s-avatar,#s-topavatar,#a-avatar,#tprof-ava').forEach(function(a){
      var im=a.querySelector&&a.querySelector('img'); if(im) im.remove();
      a.style.backgroundImage=''; a.classList.remove('has-photo');
    });
  }catch(e){}
}
async function loadTopAvatar(role){
  const elId=role==='teacher'?'t-topavatar':'s-topavatar';
  const sideId=role==='teacher'?'t-avatar':'s-avatar';
  const url=_selfPhoto(role);
  const el=document.getElementById(elId);
  if(el) el.textContent=initials(NAME);
  try{
    const r=await fetch(API+url,{headers:{Authorization:'Bearer '+TOKEN}});
    if(r.ok){ const u=URL.createObjectURL(await r.blob()); window._myPhotoUrl=u;
      if(el){ el.style.backgroundImage=`url(${u})`; el.textContent=''; }
      const sb=document.getElementById(sideId); if(sb){ sb.style.backgroundImage=`url(${u})`; sb.textContent=''; }
    } else if(role==='student' && !window._photoPrompted){
      window._photoPrompted=true;
      setTimeout(()=>toast('Set your profile photo — click the avatar at the top.'),1500);
    }
  }catch(e){}
}
