const _pc={img:null,scale:1,min:1,x:0,y:0,drag:false,sx:0,sy:0,size:300,onDone:null};
function photoCropperHTML(inputId){
  return `<div id="pc-pick">
      <div class="file-drop" onclick="document.getElementById('${inputId}').click()"
           ondragover="event.preventDefault();this.classList.add('drag')"
           ondragleave="this.classList.remove('drag')"
           ondrop="pcDrop(event,this)">
        <div class="fd-icon">${ic('upload')}</div>
        <div style="font-size:.85rem">Photo here \u2014 <strong>drag &amp; drop</strong> or <strong>click</strong> to upload</div>
      </div>
      <input type="file" id="${inputId}" accept="image/*" style="display:none">
    </div>
    <div id="pc-editor" style="display:none">
      <div class="pc-stage"><canvas id="pc-canvas" width="300" height="300"></canvas><div class="pc-mask"></div></div>
      <div class="pc-ctrl">
        <span class="pc-lbl">Zoom</span>
        <input type="range" id="pc-zoom" min="1" max="3" step="0.01" value="1" oninput="pcZoom(this.value)">
        <button class="btn btn-ghost btn-sm" onclick="pcReset()">Reset</button>
        <button class="btn btn-ghost btn-sm" onclick="pcChange('${inputId}')">Change photo</button>
      </div>
      <p class="pc-hint">Drag the photo to reposition \u00b7 use the slider to zoom \u00b7 only the circle will be saved</p>
    </div>`;
}
function pcInit(inputId){
  const inp=document.getElementById(inputId);
  inp.addEventListener('change',()=>{ if(inp.files&&inp.files[0]) pcLoad(inp.files[0]); });
}
function pcDrop(e,el){
  e.preventDefault(); el.classList.remove('drag');
  const f=e.dataTransfer&&e.dataTransfer.files&&e.dataTransfer.files[0];
  if(f&&f.size>0) pcLoad(f);
  else toast('Could not read that image. If you dragged it from a website, save it to your device first.',true);
}
function pcLoad(file){
  if(!file||!(file.type||'').startsWith('image/')){ toast('Please choose an image file.',true); return; }
  const img=new Image();
  img.onload=()=>{
    _pc.img=img;
    const S=_pc.size;
    _pc.min=Math.max(S/img.width,S/img.height);
    _pc.scale=_pc.min; _pc.x=0; _pc.y=0;
    const z=document.getElementById('pc-zoom'); z.min=_pc.min; z.max=_pc.min*3; z.step=(_pc.min*2)/100; z.value=_pc.min;
    document.getElementById('pc-pick').style.display='none';
    document.getElementById('pc-editor').style.display='block';
    pcBind(); pcDraw();
  };
  img.onerror=()=>toast('This image could not be read. Try another file.',true);
  img.src=URL.createObjectURL(file);
}
function pcClamp(){
  const S=_pc.size, w=_pc.img.width*_pc.scale, h=_pc.img.height*_pc.scale;
  const mx=Math.max(0,(w-S)/2), my=Math.max(0,(h-S)/2);
  _pc.x=Math.max(-mx,Math.min(mx,_pc.x)); _pc.y=Math.max(-my,Math.min(my,_pc.y));
}
function pcDraw(){
  const c=document.getElementById('pc-canvas'); if(!c||!_pc.img) return;
  const ctx=c.getContext('2d'), S=_pc.size;
  ctx.clearRect(0,0,S,S);
  pcClamp();
  const w=_pc.img.width*_pc.scale, h=_pc.img.height*_pc.scale;
  // sirf circle ke andar hi photo — ek hi circle dikhta hai
  ctx.save();
  ctx.beginPath(); ctx.arc(S/2,S/2,S/2,0,Math.PI*2); ctx.closePath(); ctx.clip();
  ctx.fillStyle='#f0ebd8'; ctx.fillRect(0,0,S,S);
  ctx.drawImage(_pc.img,(S-w)/2+_pc.x,(S-h)/2+_pc.y,w,h);
  ctx.restore();
}
function pcZoom(v){ _pc.scale=parseFloat(v); pcDraw(); }
function pcReset(){ _pc.scale=_pc.min; _pc.x=0; _pc.y=0; document.getElementById('pc-zoom').value=_pc.min; pcDraw(); }
function pcChange(inputId){
  document.getElementById('pc-editor').style.display='none';
  document.getElementById('pc-pick').style.display='block';
  const inp=document.getElementById(inputId); if(inp) inp.value='';
  _pc.img=null;
}
function pcBind(){
  const c=document.getElementById('pc-canvas'); if(!c||c.dataset.bound) return; c.dataset.bound='1';
  const down=e=>{ _pc.drag=true; const p=e.touches?e.touches[0]:e; _pc.sx=p.clientX-_pc.x; _pc.sy=p.clientY-_pc.y; };
  const move=e=>{ if(!_pc.drag) return; const p=e.touches?e.touches[0]:e; _pc.x=p.clientX-_pc.sx; _pc.y=p.clientY-_pc.sy; pcDraw(); if(e.cancelable) e.preventDefault(); };
  const up=()=>{ _pc.drag=false; };
  c.addEventListener('mousedown',down); window.addEventListener('mousemove',move); window.addEventListener('mouseup',up);
  c.addEventListener('touchstart',down,{passive:true}); c.addEventListener('touchmove',move,{passive:false}); c.addEventListener('touchend',up);
}
function pcBlob(){
  return new Promise((res,rej)=>{
    if(!_pc.img) return rej(new Error('Please choose a photo first.'));
    const S=512, out=document.createElement('canvas'); out.width=S; out.height=S;
    const ctx=out.getContext('2d');
    const k=S/_pc.size, w=_pc.img.width*_pc.scale*k, h=_pc.img.height*_pc.scale*k;
    ctx.fillStyle='#fff'; ctx.fillRect(0,0,S,S);
    ctx.drawImage(_pc.img,(S-w)/2+_pc.x*k,(S-h)/2+_pc.y*k,w,h);
    out.toBlob(b=>b?res(new File([b],'photo.jpg',{type:'image/jpeg'})):rej(new Error('Crop failed')),'image/jpeg',0.85);
  });
}
function openSetStudentPhoto(){
  showModal('Profile Photo',
    `<div class="form-group">${photoCropperHTML('sp-file')}</div><div id="sp-status"></div>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" id="sp-btn" onclick="submitStudentPhoto()">Save Photo</button>`);
  pcInit('sp-file');
}
async function submitStudentPhoto(){
  const btn=document.getElementById('sp-btn'); btn.disabled=true; btn.textContent='Uploading...';
  let f;
  try{ f=await pcBlob(); }catch(e){ toast(e.message,true); btn.disabled=false; btn.textContent='Save Photo'; return; }
  const fd=new FormData(); fd.append('file',f);
  try{
    const r=await fetch(API+'/api/student/photo',{method:'POST',headers:{Authorization:'Bearer '+TOKEN},body:fd});
    if(!r.ok) throw new Error('Upload fail'); 
    toast('Profile photo updated.'); closeModal(); loadTopAvatar('student');
    if(document.getElementById('s-page-profile')&&document.getElementById('s-page-profile').classList.contains('active')) loadSProfile();
  }catch(e){ document.getElementById('sp-status').innerHTML=`<div class="alert alert-danger">${esc(e.message)}</div>`; btn.disabled=false; btn.textContent='Save Photo'; }
}
function viewKytPhoto(key,title){
  const u=(window._photoUrls||{})[key];
  if(!u) return;
  const ov=document.createElement('div'); ov.className='pv-overlay';
  ov.innerHTML=`<button class="pv-close" aria-label="Close">\u2715</button><div class="pv-box"><img src="${u}" alt=""><div class="pv-cap">${esc(title||'')}</div></div>`;
  ov.addEventListener('click',()=>ov.remove());
  document.body.appendChild(ov);
  requestAnimationFrame(()=>ov.classList.add('show'));
}
