let _lecTT=[];          // timetable entries for optional linking
let _lecFiles={pdf:null};

async function loadTLectures(){
  const el=document.getElementById('t-lectures-content');
  softSpin(el);
  try{
    const lecs=await api('/api/teacher/lectures');
    let html=`<div class="sm-head" style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap"><div><h2>Lecture Reports</h2><p>Publish a report after teaching in the MVC App. Students mark it done from their portal.</p></div><button class="btn btn-primary btn-sm" onclick="openLectureForm()">${ic('upload')} New Lecture Report</button></div>`;
    if(!lecs.length){ html+=`<div class="card"><div class="card-body"><div class="empty-state"><div class="empty-icon"></div><p>No lecture reports yet. Create one so students can mark it done.</p></div></div></div>`; }
    else{
      html+=lecs.map(l=>{
         const files=[]; if(l.has_pdf) files.push('Notes'); if(l.has_dpp) files.push('DPP');
        return `<div class="lec-card"><div class="lec-head"><div><div class="lec-title">${esc(l.title)}</div><div class="lec-meta">${esc(l.subject)}${l.chapter?' \u00b7 '+esc(l.chapter):''} \u00b7 ${esc(l.date)}${files.length?' \u00b7 '+files.join(' + '):''}</div></div><button class="btn btn-danger btn-sm" onclick="deleteLecture(${l.id})">${ic('trash')}</button></div><div class="lec-body"><b>${l.verified}</b> student${l.verified===1?'':'s'} marked done</div></div>`;
      }).join('');
    }
    el.innerHTML=html;
  }catch(e){ el.innerHTML=errHtml(e); }
}

async function deleteLecture(id){
  if(!confirm('Remove this lecture report? Students will no longer see it.')) return;
  try{ await api('/api/teacher/lecture/'+id,'DELETE'); toast('Lecture removed'); loadTLectures(); }
  catch(e){ toast(e.message,true); }
}

