    if(!ln.includes('$')) return ln;
    let n=(ln.match(/\$/g)||[]).length;
    if(n%2===1){ const li=ln.lastIndexOf('$'); ln=ln.slice(0,li)+ln.slice(li+1); }
    return ln;
