  s=s.replace(/\\(sqrt)\s*\{((?:[^{}]|\{[^{}]*\})*)\}/g,(m)=>stash(m,false));
  s=s.replace(/\\text\s*\{((?:[^{}]|\{[^{}]*\})*)\}/g,(m)=>stash(m,false));
  s=s.replace(/\\(times|div|cdot|circ|pm|mp|approx|neq|leq|le|geq|ge|implies|Rightarrow|rightarrow|infty|alpha|beta|gamma|delta|eta|theta|lambda|mu|pi|sigma|phi|omega|degree|therefore|because|%)(?![a-zA-Z])/g,(m)=>stash(m,false));
