function renderMath(el){
  if(!el||!window.katex) return;
  // guard: bahut lamba text (student ka pathological doubt) math-render ko slow kar sakta hai -> skip
  try{ if((el.textContent||'').length>8000) return; }catch(e){}
  try{
    const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT,null);
    const nodes=[]; let n;
    while(n=walker.nextNode()){ if(n.nodeValue&&n.nodeValue.length<=4000&&/[$\\]|[_^][A-Za-z0-9{]|\)\s*\/\s*\(/.test(n.nodeValue)&&!(n.parentNode&&n.parentNode.closest&&n.parentNode.closest('.katex'))) nodes.push(n); }
    nodes.forEach(node=>{
      const parts=spBareMath(node.nodeValue).split(/([$][$][^$]*[$][$]|[$][^$]+[$])/g);
      if(parts.length<=1) return;
      const frag=document.createDocumentFragment();
      parts.forEach(part=>{
        if(/^[$][$][^$]*[$][$]$/.test(part)){ const s=document.createElement('div'); s.className='math-block'; _kRender(s,part.slice(2,-2),true,part); frag.appendChild(s); }
        else if(/^[$][^$]+[$]$/.test(part)){
          const inner=part.slice(1,-1);
          // Match-the-following jaisi tables ko apni line par block me dikhao -
          // inline rehne par wo question ke text se chipak jati thi
          const blk=/\\begin\{(array|matrix|[bpvBV]matrix|aligned|cases)\}/.test(inner);
          const s=document.createElement(blk?'div':'span');
          if(blk) s.className='math-block';
          _kRender(s,inner,blk,part);
          frag.appendChild(s);
        }
        else if(part){ frag.appendChild(document.createTextNode(part)); }
      });
      node.parentNode.replaceChild(frag,node);
    });
  }catch(e){}
}
function insertTex(snip){ const t=_lastField; if(!t){ toast('Tip: click inside a question or answer box first, then tap a tool.',true); return; } const s=t.selectionStart||0,e=t.selectionEnd||0; t.value=t.value.slice(0,s)+snip+t.value.slice(e); const p=s+snip.length; t.selectionStart=t.selectionEnd=p; t.focus(); t.dispatchEvent(new Event('input',{bubbles:true})); }
