function _hasTxt(v){ return !!(v&&String(v).trim()); }
function _qTransState(q){
  // 'none' = Hindi bilkul nahi, 'part' = kuch fields baaki, 'done' = sab translate ho chuke
  if(!q) return 'none';
  const pairs=[[q.q,q.q_hi],[q.expl,q.expl_hi],[q.model,q.model_hi]];
  if(Array.isArray(q.opts)) q.opts.forEach((o,j)=>pairs.push([o,(q.opts_hi||[])[j]]));
  let need=0, have=0;
  pairs.forEach(([en,hi])=>{ if(_hasTxt(en)){ need++; if(_hasTxt(hi)) have++; } });
  if(!need||!have) return have?'part':'none';
  return have>=need?'done':'part';
}
