function _qDraftKey(){ return 'mvs_qdraft_'+(window._dppMode?'dpp':'test')+'_'+(_examType||'x'); }
function _qCount(qs){
  return (qs||[]).filter(function(q){ return q && ((q.q||'').trim()||(q.model||'').trim()||q.image_b64
    ||q.model_answer_image||(q.opts||[]).some(function(o){return (o||'').trim();})||(q.expl||'').trim()); }).length;
}
function _saveQDraft(){
  try{
    if(window._editExamId||window._dppEditId) return;              // edit mode -> draft nahi
    if(!document.getElementById('ex-qs')) return;                  // panel band -> skip
    if(_qCount(_examQs)<1) return;                                 // koi content nahi -> skip
    var form={sub:val('ex-sub'),cls:val('ex-cls-test'),dur:val('ex-dur'),medium:val('ex-medium'),
              sched:val('ex-sched'),title:val('ex-title'),ch:val('ex-ch')};
    try{ localStorage.setItem(_qDraftKey(),JSON.stringify({ts:Date.now(),dpp:!!window._dppMode,type:_examType,qs:_examQs,form:form})); }
    catch(e){
      // quota (bade images) -> images hata ke text/structure bacha lo (kam se kam mehnat na jaye)
      var light=(_examQs||[]).map(function(q){var c=Object.assign({},q);delete c.image_b64;delete c.alt_image_b64;delete c.model_answer_image;return c;});
      try{ localStorage.setItem(_qDraftKey(),JSON.stringify({ts:Date.now(),dpp:!!window._dppMode,type:_examType,qs:light,form:form,noimg:true})); }catch(e2){}
    }
  }catch(e){}
}
function _clearQDraft(){ try{ localStorage.removeItem(_qDraftKey()); }catch(e){} }
function _restoreQDraft(dr){
  try{
    _examQs=(dr.qs&&dr.qs.length)?dr.qs:[]; if(!_examQs.length) addExamQ();
    var f=dr.form||{};
    var set=function(id,v){ var el=document.getElementById(id); if(el&&v!=null) el.value=v; };
    if(f.sub){ var s=document.getElementById('ex-sub'); if(s){ if(![].slice.call(s.options).some(function(o){return o.text===f.sub;})){ var op=document.createElement('option'); op.text=f.sub; s.add(op);} s.value=f.sub; } }
    set('ex-title',f.title); set('ex-ch',f.ch); set('ex-dur',f.dur); set('ex-sched',f.sched);
    if(f.medium){ set('ex-medium',f.medium); _examMedium=f.medium; }
    try{ _examFillTestCls(false); }catch(e){}
    if(f.cls){ var c=document.getElementById('ex-cls-test'); if(c){ if(![].slice.call(c.options).some(function(o){return o.text===f.cls;})){ var op2=document.createElement('option'); op2.text=f.cls; c.add(op2);} c.value=f.cls; } }
    renderExamQs();
    var b=document.getElementById('qdraft-banner'); if(b) b.remove();
    toast('Draft restored \u2014 '+_qCount(_examQs)+' question(s)');
  }catch(e){}
}
function _resetAllQ(){
  if(!confirm('Remove all questions and start over? This cannot be undone.')) return;
  _examQs=[]; addExamQ(); renderExamQs(); _clearQDraft();
  var b=document.getElementById('qdraft-banner'); if(b) b.remove();
}
function _maybeShowQDraft(){
  try{
    var raw=localStorage.getItem(_qDraftKey()); if(!raw) return;
    var dr=JSON.parse(raw); var n=_qCount(dr.qs); if(n<1) return;
    var cont=document.getElementById('ex-qs'); if(!cont) return;
    var when=new Date(dr.ts||Date.now()).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',hour12:true});
    var bn=document.createElement('div'); bn.id='qdraft-banner'; bn.className='alert alert-info';
    bn.style.cssText='display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:10px';
    bn.innerHTML='<div style="flex:1;min-width:200px;line-height:1.5">An unsaved '+(window._dppMode?'DPP':'test')+' draft was found &mdash; <b>'+n+' question'+(n>1?'s':'')+'</b> <span style="opacity:.75">('+esc(when)+')</span>'+(dr.noimg?'<br><small style="opacity:.75">Images will not be restored.</small>':'')+'</div>'
      +'<span style="display:flex;gap:10px;flex:none">'
      +'<button id="qdraft-cont" style="white-space:nowrap;background:#b8941f;color:#fff;border:none;padding:9px 20px;border-radius:9px;font-weight:700;font-size:.86rem;cursor:pointer">Continue</button>'
      +'<button id="qdraft-new" style="white-space:nowrap;background:#fff;color:#5a4a20;border:1px solid #ddc98f;padding:9px 20px;border-radius:9px;font-weight:600;font-size:.86rem;cursor:pointer">Start fresh</button>'
      +'</span>';
    cont.parentNode.insertBefore(bn,cont);
    document.getElementById('qdraft-cont').onclick=function(){ _restoreQDraft(dr); };
    document.getElementById('qdraft-new').onclick=function(){ _clearQDraft(); bn.remove(); };
  }catch(e){}
}
function renderExamQs(){
  const el=document.getElementById('ex-qs'); if(!el) return;
  const biling=(_examMedium==='Bilingual');
  el.innerHTML=_examQs.map((q,i)=>{
    const isHi=biling&&q._tab==='hi';
    const head=`<div class="ex-qhead"><span class="ex-qnum">Question ${i+1}</span><div class="ex-qhead-actions"><button type="button" class="btn btn-sm ex-ocr" title="Upload a screenshot of the question — AI reads it into text (best for PYQ integrals/fractions where copy-paste breaks)" onclick="document.getElementById('ex-ocrf-${i}').click()">Screenshot to Text</button><input type="file" id="ex-ocrf-${i}" accept="image/*" style="display:none" onchange="ocrFillQuestion(this,${i})">${_examQs.length>1?`<button class="btn btn-danger btn-sm" onclick="removeExamQ(${i})">${ic('trash')}</button>`:''}</div></div>`;
    const _ts=_qTransState(q);
    const _tsLbl=_ts==='done'?'Hindi Added':(_ts==='part'?'Finish Hindi':'Translate to Hindi');
    const _tsTitle=_ts==='done'?'Hindi is filled for this question. Click to translate anything still empty.'
      :(_ts==='part'?'Some Hindi fields are still empty. Click to fill them.'
      :'Translate this question to Hindi');
    const tabs=biling?`<div class="ex-lang-tabs"><button type="button" class="ex-lang-tab ${q._tab!=='hi'?'active':''}" onclick="setExamTab(${i},'en')">English</button><button type="button" class="ex-lang-tab ${q._tab==='hi'?'active':''}" onclick="setExamTab(${i},'hi')">\u0939\u093f\u0902\u0926\u0940</button><button type="button" class="ex-lang-tab ex-tr tr-${_ts}" title="${_tsTitle}" onclick="examTranslate(${i},this)">${_tsLbl}</button></div>`:'';
    const autoHint='';
    const sp=(_examType==='mcq'&&!isHi)?_mcqSmartPasteBox(i):'';
    const qval=isHi?(q.q_hi||''):(q.q||'');
    const qbind=isHi?`_examQs[${i}].q_hi=this.value`:`_examQs[${i}].q=this.value`;
    const qImg=isHi?'':`<div id="ex-imgsec-${i}">${_qImgSection(i)}</div>`;
    const qId=`exq-${i}`;
    const qsec=`<div class="ex-sec ex-sec-q"><div class="ex-sec-lbl">Question${isHi?' \u00b7 Hindi':''}</div>${_rtBar(qId,isHi?null:i)}<textarea id="${qId}" class="form-control" rows="2" placeholder="${isHi?'\u092a\u094d\u0930\u0936\u094d\u0928 \u0939\u093f\u0902\u0926\u0940 \u092e\u0947\u0902 (\u0935\u093f\u0915\u0932\u094d\u092a\u093f\u0915)':'Type the question here \u2014 maths & reactions supported'}" onfocus="_lastField=this" oninput="${qbind};examPrev(this,'pv-q-${i}')${isHi?'':`;_syncImgSecLive(${i},this.value)`}">${esc(qval)}</textarea><div class="ex-prev" id="pv-q-${i}"></div>${autoHint}${qImg}</div>`;
    let mid;
    if(_examType==='mcq'){
      let opts;
      if(isHi){
        const oh=q.opts_hi||['','','',''];
        opts=oh.map((o,j)=>`<div class="ex-opt"><span class="ex-opt-letter">${String.fromCharCode(65+j)}</span><input class="form-control" id="oxh-${i}-${j}" placeholder="\u0935\u093f\u0915\u0932\u094d\u092a ${j+1} (\u0939\u093f\u0902\u0926\u0940)" value="${esc(o||'')}" onfocus="_lastField=this" oninput="_examQs[${i}].opts_hi[${j}]=this.value;examOptPrev(this,'pv-oh-${i}-${j}')"><div class="ex-prev ex-prev-o" id="pv-oh-${i}-${j}" style="display:none"></div></div>`).join('');
      } else {
        opts=q.opts.map((o,j)=>`<div class="ex-opt"><input type="radio" name="exc-${i}" ${q.correct===j?'checked':''} onclick="_examQs[${i}].correct=${j}" title="Mark as the correct answer"><input class="form-control" id="exo-${i}-${j}" placeholder="Option ${j+1}" value="${esc(o)}" onfocus="_lastField=this" oninput="_examQs[${i}].opts[${j}]=this.value;examOptPrev(this,'pv-o-${i}-${j}')"><div class="ex-prev ex-prev-o" id="pv-o-${i}-${j}" style="display:none"></div></div>`).join('');
      }
      const marks=isHi?'':`<div class="ex-marks"><label>Marks</label><input type="number" class="form-control" style="width:80px" value="${q.marks}" oninput="_examQs[${i}].marks=this.value"></div>`;
      const eval_=isHi?(q.expl_hi||''):(q.expl||'');
      const ebind=isHi?`_examQs[${i}].expl_hi=this.value`:`_examQs[${i}].expl=this.value`;
      const eId=`exe-${i}`;
      const expl=`<div class="ex-sec ex-sec-a"><div class="ex-sec-lbl">Explanation${isHi?' \u00b7 Hindi':''}</div>${_rtBar(eId)}<textarea id="${eId}" class="form-control" rows="2" placeholder="${isHi?'\u0938\u0939\u0940 \u0909\u0924\u094d\u0924\u0930 \u0915\u0940 \u0935\u094d\u092f\u093e\u0916\u094d\u092f\u093e (\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915)':'Why is this the correct answer? Students see this after submitting.'}" onfocus="_lastField=this" oninput="${ebind};examPrev(this,'pv-e-${i}')">${esc(eval_)}</textarea><div class="ex-prev" id="pv-e-${i}"></div></div>`;
      mid=`<div class="ex-sec ex-sec-o"><div class="ex-sec-lbl">Options${isHi?' \u00b7 Hindi':''}</div><div class="ex-opts">${opts}</div>${autoHint}${marks}</div>${expl}`;
    } else {
      const aval=isHi?(q.model_hi||''):(q.model||'');
      const abind=isHi?`_examQs[${i}].model_hi=this.value`:`_examQs[${i}].model=this.value`;
      const aImg=isHi?'':(_ansImgZone(i)+`<input type="file" id="ex-aimgf-${i}" accept="image/*" style="display:none" onchange="examAnsImgFile(this,${i})">`);
      const marks=isHi||window._dppMode?'':`<div class="ex-marks"><label>Max Marks</label><input type="number" class="form-control" style="width:80px" value="${q.marks}" oninput="_examQs[${i}].marks=this.value"></div>`;
      const aId=`exa-${i}`;
      mid=`<div class="ex-sec ex-sec-a"><div class="ex-sec-lbl">Model Answer${isHi?' \u00b7 Hindi':''}</div>${_rtBar(aId)}${isHi?'':`<div style="margin:2px 0 6px"><button type="button" class="btn btn-sm ex-ocr" title="Upload/paste a screenshot of the answer — AI reads it into text" onclick="document.getElementById('ex-aocrf-${i}').click()">Screenshot to Text</button><input type="file" id="ex-aocrf-${i}" accept="image/*" style="display:none" onchange="ocrFillAnswer(this,${i})"></div>`}<textarea id="${aId}" class="form-control" rows="2" placeholder="${isHi?'\u0906\u0926\u0930\u094d\u0936 \u0909\u0924\u094d\u0924\u0930 \u0939\u093f\u0902\u0926\u0940 \u092e\u0947\u0902 (\u0935\u093f\u0915\u0932\u094d\u092a\u093f\u0915)':'Type the ideal/model answer here'}" onfocus="_lastField=this" oninput="${abind};examPrev(this,'pv-a-${i}')">${esc(aval)}</textarea><div class="ex-prev" id="pv-a-${i}"></div>${autoHint}${aImg}${marks}</div>`;
    }
    return `<div class="ex-qcard">${head}${tabs}${sp}${qsec}${mid}</div>`;
  }).join('');
  _examQs.forEach((q,i)=>{
    const isHi=(_examMedium==='Bilingual')&&q._tab==='hi';
    const pq=document.getElementById('pv-q-'+i); if(pq){pq.innerHTML=_fmtRich(isHi?(q.q_hi||''):(q.q||''));renderMath(pq);}
    const pa=document.getElementById('pv-a-'+i); if(pa){pa.innerHTML=_fmtRich(isHi?(q.model_hi||''):(q.model||''));renderMath(pa);}
    const pe=document.getElementById('pv-e-'+i); if(pe){pe.innerHTML=_fmtRich(isHi?(q.expl_hi||''):(q.expl||''));renderMath(pe);}
    // v124: khuli hui options ke previews bhi bharo (edit mode / re-render pe)
    const _ol=isHi?(q.opts_hi||[]):(q.opts||[]);
    _ol.forEach((ov,j)=>{ const ip=document.getElementById((isHi?'oxh-':'exo-')+i+'-'+j); if(ip) examOptPrev(ip,(isHi?'pv-oh-':'pv-o-')+i+'-'+j); });
  });
  // Header ke "Translate All" pe kitne question abhi Hindi me baaki hain
  const trAll=document.getElementById('ex-tr-all');
  if(trAll){
    if(_examMedium!=='Bilingual'){ trAll.textContent='Translate All to Hindi'; trAll.classList.remove('tr-done'); }
    else{
      const pend=_examQs.filter(q=>_qTransState(q)!=='done').length;
      trAll.textContent=pend?('Translate All to Hindi ('+pend+' pending)'):'All Questions Translated';
      trAll.classList.toggle('tr-done',!pend);
    }
  }
}

