/* admin: one-click cleanup of deleted teachers' leftover content */
async function orphanCleanup(){
  try{
    toast('Checking old data\u2026');
    const s=await api('/api/admin/orphan-data/summary');
    const c=s.counts||{}, total=s.total||0;
    if(!total){ toast('Everything is clean — no leftover data found.'); return; }
    const rows=[['tests',c.tests,'Tests (paper + questions + submissions)'],['lectures',c.lectures,'Lecture records'],['timetables',c.timetables,'Timetable entries'],['dpp_submissions',c.dpp_submissions,'Orphan DPP submissions'],['test_submissions',c.test_submissions,'Orphan test submissions']]
      .filter(r=>r[1]>0)
      .map(r=>`<div style="display:flex;justify-content:space-between;padding:7px 2px;border-bottom:1px dashed var(--border);font-size:.84rem"><span>${r[2]}</span><b style="color:#dc2626">${r[1]}</b></div>`).join('');
    showModal('Clear Leftover Data?',
    `<div class="ws-empty"><div class="big" style="color:#dc2626">${ic('trash')}</div>
     <p><b>Leftover data from deleted teachers was found:</b></p></div>
     <div style="text-align:left;max-width:400px;margin:0 auto">${rows}</div>
     <small style="display:block;margin-top:12px;color:var(--text-muted)">Everything will be removed in one click — from the student portal as well. Active teachers' data will remain completely safe. This action cannot be undone.</small>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-danger" onclick="orphanCleanupGo()">${ic('trash')} Yes, Clear Everything</button>`);
  }catch(e){ toast('Check failed: '+e.message,true); }
}
async function orphanCleanupGo(){
  closeModal(); toast('Cleaning\u2026');
  try{
    const r=await api('/api/admin/orphan-data/cleanup','POST');
    toast('Done — '+(r.total||0)+' leftover items deleted.');
    loadATests();
  }catch(e){ toast('Cleanup failed: '+e.message,true); }
}
async function loadATests(){
  const el=document.getElementById('a-tests-content'); if(!el)return;
  softSpin(el);
  try{
    const rows=await api('/api/admin/exams');
    window._aTestsRows=rows||[];
    if(window._aTestSub===undefined) window._aTestSub='';   // pehle sirf cards; koi auto-select nahi
    if(window._aTestClass===undefined) window._aTestClass='all';
    _renderATests();
  }catch(e){
    el.innerHTML=`<div class="card"><div class="card-body"><div class="ws-empty"><div class="big">${ic('clipboard')}</div><p><b>The Tests Tracker needs one small backend endpoint</b></p><small>Once <code>GET /api/admin/exams</code> is added, all tests with submission tracking appear here, subject-wise.<br>Ready-made code: <b>mvs_backend_exam_update.py</b> — paste it at the end of admin_routes.py and redeploy.</small></div></div></div>`;
  }
}
function aTestSubPick(s){ window._aTestSub=(window._aTestSub===s?'':s); _renderATests(); }
function _renderATests(){
  const el=document.getElementById('a-tests-content'); if(!el)return;
  const allRows=window._aTestsRows||[];
  const cls=window._aTestClass||'all';
  const _cd=cn=>{ const m=String(cn||'').match(/(10|12)/); return m?m[1]:''; };   // "Class 10" -> "10"
  // class filter: "" (sabhi classes waala test) har filter me dikhta hai
  const rows=cls==='all'?allRows:allRows.filter(e=>{ const d=_cd(e.class_name); return d===''||d===cls; });
  const sel=window._aTestSub||'';
  const bySub={};
  rows.forEach(e=>{ const s=e.subject||'General'; (bySub[s]=bySub[s]||[]).push(e); });
  const subs=Object.keys(bySub).sort();
  const _stat=l=>({t:l.length,s:l.reduce((a,e)=>a+(e.attempts||0),0),g:l.reduce((a,e)=>a+(e.graded||0),0)});
  const selList=sel===''?[]:(sel==='all'?rows:(bySub[sel]||[]));
  const st=_stat(sel===''?rows:selList);
  const _testRow=e=>{
    const sch=spSchedOf(e);
    return `<div class="today-row"><div><div class="tr-sub">${esc(e.title||'')}</div><div class="tr-topic">${esc(e.teacher_name||'')}${spCleanCh(e.chapter)?' \u00b7 '+esc(spCleanCh(e.chapter)):''} \u00b7 ${e.questions||0} Qs \u00b7 ${e.total_marks||0} marks \u00b7 ${e.duration_min?e.duration_min+' min':'No time limit'}${sch?' \u00b7 '+spSchedFmt(sch):''}</div></div><div class="tmeta"><span class="tstatus">${e.attempts||0} submitted</span><span class="tstatus ${(e.graded||0)>0?'done':''}">${e.graded||0} evaluated</span><span class="tstatus" style="color:#b45309">${Math.max(0,(e.attempts||0)-(e.graded||0))} pending</span>${(e.graded||0)>0?`<button class="btn btn-ghost btn-sm" title="Class ranking of this test" onclick="openExamRanking(${e.id},'admin')">${ic('chart')} Ranking</button>`:''}</div></div>`;
  };
  const _sec=(sub,list)=>`<div class="card"><div class="card-header"><h3>${esc(sub)}</h3><span class="tx-pill nv">${list.length} test${list.length>1?'s':''}</span></div><div class="card-body">${list.map(_testRow).join('')}</div></div>`;
  const clsPill=(v,lbl)=>`<button class="btn ${cls===v?'btn-primary':'btn-ghost'} btn-sm" onclick="aTestClassPick('${v}')">${lbl}</button>`;
  el.innerHTML=`<div class="sm-head" style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap"><div><h2 style="margin:0">Tests Tracker</h2><div style="font-size:.74rem;color:var(--text-muted);margin-top:3px">Subject-wise all tests · live submission tracking</div></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-danger btn-sm" onclick="orphanCleanup()">${ic('trash')} Clean Old Data</button><button class="btn btn-ghost btn-sm" onclick="loadATests()">${ic('refresh')} Refresh</button></div></div>`
    +`<div style="display:flex;gap:8px;flex-wrap:wrap;margin:2px 0 14px;align-items:center"><span style="font-size:.74rem;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.05em">Class</span>${clsPill('all','All Classes')}${clsPill('10','Class 10')}${clsPill('12','Class 12')}</div>`
    +`<div class="tx-stats">`
    +`<div class="tx-stat"><b style="color:#c2410c">${st.t}</b><span>Total tests</span></div>`
    +`<div class="tx-stat"><b>${st.s}</b><span>Submissions</span></div>`
    +`<div class="tx-stat"><b style="color:#b45309">${Math.max(0,st.s-st.g)}</b><span>Pending evaluation</span></div>`
    +`<div class="tx-stat"><b style="color:#047857">${st.g}</b><span>Evaluated</span></div></div>`
    +(rows.length? `<div class="dps-grid">`
      +`<div class="dps-card ${sel==='all'?'open':''}" onclick="aTestSubPick('all')"><div class="dps-name">All Subjects</div><div class="dps-count">${rows.length} test${rows.length===1?'':'s'} \u00b7 ${_stat(rows).s} submissions</div><div class="dps-tick">${sel==='all'?'\u25b2':'\u25bc'}</div></div>`
      +subs.map((s,i)=>{const l=bySub[s];const ss=_stat(l);return `<div class="dps-card ${sel===s?'open':''}" onclick="aTestSubPickIdx(${i})"><div class="dps-name">${esc(s)}</div><div class="dps-count">${l.length} test${l.length>1?'s':''} \u00b7 ${ss.s} submission${ss.s===1?'':'s'}</div><div class="dps-tick">${sel===s?'\u25b2':'\u25bc'}</div></div>`;}).join('')
      +`</div>`
      +(sel===''
        ? `<div class="card"><div class="card-body ws-empty"><p style="margin:0;color:var(--text-muted)">Select a subject above to see its tests.</p></div></div>`
        : (sel==='all'? subs.map(sub=>_sec(sub,bySub[sub])).join('') : _sec(sel,selList)))
      : `<div class="tx-empty"><div class="ic">${ic('clipboard')}</div><b>No tests${cls==='all'?'':' for Class '+cls}</b><p>Tests from teachers will appear here, subject-wise.</p></div>`);
}
function aTestClassPick(c){ window._aTestClass=c; window._aTestSub=''; _renderATests(); }
function aTestSubPickIdx(i){
  const rows=window._aTestsRows||[];
  const subs=[...new Set(rows.map(e=>e.subject||'General'))].sort();
  aTestSubPick(subs[i]||'all');
}

// ===== ADMIN DPP TRACKER — Tests Tracker jaisa. Nav item + page JS se inject (HTML file
// chhue bina). Data /api/admin/dpp-rankings se (subject, class, submissions sab isme hai). =====
function initAdminDppTracker(){
  var app=document.getElementById('admin-app'); if(!app) return;
  var nav=app.querySelector('.sidebar-nav');
  if(nav && !nav.querySelector('[onclick*="dpptracker"]')){
    var items=[].slice.call(nav.querySelectorAll('.nav-item'));
    var testsItem=items.filter(function(n){return (n.getAttribute('onclick')||'').indexOf("'tests'")>=0;})[0];
    var d=document.createElement('div'); d.className='nav-item'; d.setAttribute('onclick',"aPage('dpptracker',this)");
    d.innerHTML=ic('upload')+'<span>DPP Tracker</span>';
    if(testsItem){ testsItem.parentNode.insertBefore(d, testsItem.nextSibling); } else { nav.appendChild(d); }
  }
  var main=app.querySelector('.main');
  if(main && !document.getElementById('a-page-dpptracker')){
    var pg=document.createElement('div'); pg.className='page'; pg.id='a-page-dpptracker';
    pg.innerHTML='<div id="a-dpptracker-content"><div class="spinner"></div></div>';
    main.appendChild(pg);
  }
}
async function loadADppTracker(){
  const el=document.getElementById('a-dpptracker-content'); if(!el) return;
  softSpin(el);
  try{
    const d=await api('/api/admin/dpp-rankings');
    window._aDppTrRows=(d&&d.packs)||(Array.isArray(d)?d:[]);
    if(window._aDppTrSub===undefined) window._aDppTrSub='';
    if(window._aDppTrClass===undefined) window._aDppTrClass='all';
    _renderADppTracker();
  }catch(e){ el.innerHTML=errHtml(e); }
}
function _dppTrFiltered(){
  const all=window._aDppTrRows||[]; const cls=window._aDppTrClass||'all';
  const cd=cn=>{const m=String(cn||'').match(/(10|12)/);return m?m[1]:'';};
  return cls==='all'?all:all.filter(e=>{const dd=cd(e.class_name);return dd===''||dd===cls;});
}
function aDppTrClassPick(c){ window._aDppTrClass=c; window._aDppTrSub=''; _renderADppTracker(); }
function aDppTrSubPick(s){ window._aDppTrSub=(window._aDppTrSub===s?'':s); _renderADppTracker(); }
function aDppTrSubPickIdx(i){ const subs=[...new Set(_dppTrFiltered().map(e=>e.subject||'General'))].sort(); aDppTrSubPick(subs[i]||'all'); }
function _renderADppTracker(){
  const el=document.getElementById('a-dpptracker-content'); if(!el) return;
  const cls=window._aDppTrClass||'all';
  const rows=_dppTrFiltered();
  const sel=window._aDppTrSub||'';
  const bySub={}; rows.forEach(e=>{const s=e.subject||'General';(bySub[s]=bySub[s]||[]).push(e);});
  const subs=Object.keys(bySub).sort();
  const _stat=l=>({t:l.length,s:l.reduce((a,e)=>a+(e.submitted||0),0),c:l.reduce((a,e)=>a+(e.checked||0),0)});
  const selList=sel===''?[]:(sel==='all'?rows:(bySub[sel]||[]));
  const st=_stat(sel===''?rows:selList);
  const _pend=e=>(e.pending!=null?e.pending:Math.max(0,(e.submitted||0)-(e.checked||0)));
  const _row=e=>`<div class="today-row"><div><div class="tr-sub">${esc(e.title||'DPP')}</div><div class="tr-topic">${esc(e.teacher||'')}${e.chapter?' \u00b7 '+esc(e.chapter):''}${e.part?' \u00b7 Part: '+esc(e.part):''}${e.class_name?' \u00b7 '+esc(e.class_name):''}${e.created_at?' \u00b7 '+esc(e.created_at):''}</div></div><div class="tmeta"><span class="tstatus">${e.submitted||0} submitted</span><span class="tstatus ${(e.checked||0)>0?'done':''}">${e.checked||0} checked</span><span class="tstatus" style="color:#b45309">${_pend(e)} pending</span>${(e.submitted||0)>0?`<button class="btn btn-ghost btn-sm" title="DPP ranking" onclick="openDppRanking(${e.id},'admin')">${ic('chart')} Ranking</button>`:''}</div></div>`;
  const _sec=(sub,list)=>`<div class="card"><div class="card-header"><h3>${esc(sub)}</h3><span class="tx-pill nv">${list.length} DPP${list.length>1?'s':''}</span></div><div class="card-body">${list.map(_row).join('')}</div></div>`;
  const clsPill=(v,lbl)=>`<button class="btn ${cls===v?'btn-primary':'btn-ghost'} btn-sm" onclick="aDppTrClassPick('${v}')">${lbl}</button>`;
  const totS=_stat(rows);
  el.innerHTML=`<div class="sm-head" style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap"><div><h2 style="margin:0">DPP Tracker</h2><div style="font-size:.74rem;color:var(--text-muted);margin-top:3px">Subject-wise all DPPs · live submission tracking</div></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-ghost btn-sm" onclick="loadADppTracker()">${ic('refresh')} Refresh</button></div></div>`
    +`<div style="display:flex;gap:8px;flex-wrap:wrap;margin:2px 0 14px;align-items:center"><span style="font-size:.74rem;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.05em">Class</span>${clsPill('all','All Classes')}${clsPill('10','Class 10')}${clsPill('12','Class 12')}</div>`
    +`<div class="tx-stats">`
    +`<div class="tx-stat"><b style="color:#c2410c">${st.t}</b><span>Total DPPs</span></div>`
    +`<div class="tx-stat"><b>${st.s}</b><span>Submissions</span></div>`
    +`<div class="tx-stat"><b style="color:#b45309">${Math.max(0,st.s-st.c)}</b><span>Pending check</span></div>`
    +`<div class="tx-stat"><b style="color:#047857">${st.c}</b><span>Checked</span></div></div>`
    +(rows.length? `<div class="dps-grid">`
      +`<div class="dps-card ${sel==='all'?'open':''}" onclick="aDppTrSubPick('all')"><div class="dps-name">All Subjects</div><div class="dps-count">${rows.length} DPP${rows.length===1?'':'s'} \u00b7 ${totS.s} submissions</div><div class="dps-tick">${sel==='all'?'\u25b2':'\u25bc'}</div></div>`
      +subs.map((s,i)=>{const l=bySub[s];const ss=_stat(l);return `<div class="dps-card ${sel===s?'open':''}" onclick="aDppTrSubPickIdx(${i})"><div class="dps-name">${esc(s)}</div><div class="dps-count">${l.length} DPP${l.length>1?'s':''} \u00b7 ${ss.s} submission${ss.s===1?'':'s'}</div><div class="dps-tick">${sel===s?'\u25b2':'\u25bc'}</div></div>`;}).join('')
      +`</div>`
      +(sel===''
        ? `<div class="card"><div class="card-body ws-empty"><p style="margin:0;color:var(--text-muted)">Select a subject above to see its DPPs.</p></div></div>`
        : (sel==='all'? subs.map(sub=>_sec(sub,bySub[sub])).join('') : _sec(sel,selList)))
      : `<div class="tx-empty"><div class="ic">${ic('clipboard')}</div><b>No DPPs${cls==='all'?'':' for Class '+cls}</b><p>DPPs from teachers will appear here, subject-wise.</p></div>`);
}

// ===================== ADMIN — YOUTUBER TASKS (apna alag section) =====================
// Teacher Task Manager se bilkul alag. Existing production engine (/api/production/*,
// creator_type=youtuber) se chalta hai — youtuber panel se seedha connected. HTML file
// chhue bina nav + page JS se inject (DPP Tracker jaisa pattern).
(function(){ try{ if(document.getElementById('yt-adm-css')) return; var st=document.createElement('style'); st.id='yt-adm-css';
  st.textContent=[
    '.yt-scope .yt-hero{background:linear-gradient(135deg,#2a1d02,#4a3608);color:#fff;border-radius:18px;padding:20px 22px;display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-bottom:16px}',
    '.yt-scope .yt-hero h3{margin:0;font-size:1.25rem;font-weight:800}',
    '.yt-scope .yt-hero p{margin:3px 0 0;font-size:.8rem;opacity:.82}',
    '.yt-scope .yt-hero .vt-sp{flex:1}',
    '.yt-scope .ytc-thumb{width:104px;min-width:104px;height:66px;border-radius:11px;background:#efe8d6 center/cover no-repeat;display:flex;align-items:center;justify-content:center;color:#b89a55}',
    'body.dark .yt-scope .ytc-thumb{background:#241b09;color:#7c6a38}',
    '.yt-scope .ytc-thumb img{width:100%;height:100%;object-fit:cover;border-radius:11px}',
    '.yt-scope .ytc-meta{display:flex;gap:12px;flex-wrap:wrap;align-items:center;font-size:.74rem;color:var(--text-muted);margin-top:7px}',
    '.yt-scope .ytc-meta svg{width:13px;height:13px;vertical-align:-2px}',
    '.yt-scope .ytc-dl.over{color:#dc2626;font-weight:700}',
    '.yt-scope .ytc-next{margin-top:6px;font-size:.72rem;color:#8a6d10;font-weight:600}',
    '.yt-scope .yt-empty{text-align:center;padding:40px 16px;color:var(--text-muted)}',
    '.yt-scope .yt-empty .big{font-size:2rem;opacity:.5}'
  ].join('\n'); document.head.appendChild(st); }catch(e){} })();

function initAdminYtTasks(){
  var app=document.getElementById('admin-app'); if(!app) return;
  var nav=app.querySelector('.sidebar-nav');
  if(nav && !nav.querySelector('[onclick*="ytasks"]')){
    var items=[].slice.call(nav.querySelectorAll('.nav-item'));
    var anchor=items.filter(function(n){return (n.getAttribute('onclick')||'').indexOf("'vtasks'")>=0;})[0]
            || items.filter(function(n){return (n.getAttribute('onclick')||'').indexOf("'urgent'")>=0;})[0];
    var d=document.createElement('div'); d.className='nav-item'; d.setAttribute('onclick',"aPage('ytasks',this)");
    d.innerHTML=ic('play')+'<span>YouTuber Tasks</span>';
    if(anchor){ anchor.parentNode.insertBefore(d, anchor.nextSibling); } else { nav.appendChild(d); }
  }
  var main=app.querySelector('.main');
  if(main && !document.getElementById('a-page-ytasks')){
    var pg=document.createElement('div'); pg.className='page'; pg.id='a-page-ytasks';
    pg.innerHTML='<div id="a-ytasks-content" class="yt-scope"><div class="spinner"></div></div>';
    main.appendChild(pg);
  }
}

var _YT_DONE=['uploaded','completed'];
var _YT_PROD=['approved','editor_assigned','editing_soon','editing','editing_paused','editing_done','qc_pending','qc_approved','qc_changes','ready_for_youtube'];
var _YT_REVIEW=['creator_submitted','pm_review'];
function _ytBucket(t){ var lc=t.lifecycle||''; if(_YT_DONE.indexOf(lc)>=0)return'done'; if(_YT_PROD.indexOf(lc)>=0)return'prod'; if(_YT_REVIEW.indexOf(lc)>=0)return'review'; return 'assigned'; }
function _ytOverdue(t){ return !!(t.deadline_flag&&t.deadline_flag.kind==='overdue')&&_YT_DONE.indexOf(t.lifecycle||'')<0; }
function _ytNum(n){ try{ return (n||0).toLocaleString(); }catch(e){ return String(n||0); } }
function _ytUrl(u){ u=String(u||''); return /^(https?:|data:)/i.test(u)?u.replace(/"/g,'%22'):''; }

window._ytF={q:'',creator:'',channel:'',video_type:'',bucket:''};

async function loadAYtTasks(hostId){
  if(hostId) window._ytHost=hostId;
  var HOST=window._ytHost||'a-ytasks-content';
  var el=document.getElementById(HOST); if(!el) return;
  el.classList.add('yt-scope');
  softSpin(el);
  try{
    var res=await Promise.all([
      api('/api/production/tasks?creator_type=youtuber&size=200'),
      api('/api/production/channels').catch(function(){return{channels:[]};}),
      api('/api/production/video-types').catch(function(){return{types:[]};}),
      api('/api/production/people?role=youtuber').catch(function(){return{youtubers:[]};})
    ]);
    window._ytTasks=(res[0]&&res[0].tasks)||[];
    window._ytChannels=(res[1]&&res[1].channels)||[];
    window._ytTypes=(res[2]&&res[2].types)||[];
    window._ytPeople=(((res[3]&&res[3].youtubers)||[]).map(function(y){return {profile_id:y.id, name:y.name};}));
    _renderAYtTasks();
  }catch(e){ el.innerHTML=errHtml(e); }
}

function _renderAYtTasks(){
  var el=document.getElementById(window._ytHost||'a-ytasks-content'); if(!el) return;
  el.classList.add('yt-scope');
  var all=window._ytTasks||[], f=window._ytF;
  var total=all.length,done=0,prod=0,review=0,assigned=0,overdue=0;
  all.forEach(function(t){ var b=_ytBucket(t); if(b==='done')done++;else if(b==='prod')prod++;else if(b==='review')review++;else assigned++; if(_ytOverdue(t))overdue++; });
  function stat(l,n,color,icn,bucket){ return '<div class="vt-stat'+(bucket?' vt-stat-click':'')+'"'+(bucket?' data-ytb="'+bucket+'" onclick="_ytBucketFilter(\''+bucket+'\')"':'')+'><div class="vs-ic" style="background:'+color+'1f;color:'+color+'">'+ic(icn)+'</div><div><div class="vs-n" style="color:'+color+'">'+n+'</div><div class="vs-l">'+l+'</div></div></div>'; }
  var byType={}; all.forEach(function(t){ var k=(t.video_type||'').trim()||'Uncategorized'; byType[k]=(byType[k]||0)+1; });
  var creators=[]; all.forEach(function(t){ var c=(t.creator_name||'').trim(); if(c&&creators.indexOf(c)<0)creators.push(c); }); creators.sort();
  var cOpt='<option value="">All YouTubers</option>'+creators.map(function(c){return '<option value="'+esc(c)+'"'+(f.creator===c?' selected':'')+'>'+esc(c)+'</option>';}).join('');
  var chOpt='<option value="">All Channels</option>'+(window._ytChannels||[]).map(function(c){return '<option value="'+esc(c.name)+'"'+(f.channel===c.name?' selected':'')+'>'+esc(c.name)+'</option>';}).join('');
  var tyOpt='<option value="">All Types</option>'+(window._ytTypes||[]).map(function(c){return '<option value="'+esc(c.name)+'"'+(f.video_type===c.name?' selected':'')+'>'+esc(c.name)+'</option>';}).join('');
  var _serTasks=all.filter(function(t){ return (t.series_name||'').trim(); });
  var _soloTasks=all.filter(function(t){ return !(t.series_name||'').trim(); });
  var cards=_soloTasks.map(_ytCard).join('');
  el.innerHTML=''
    +'<div class="yt-hero"><div><h3>'+ic('play')+' YouTuber Task Manager</h3><p>Assign videos & projects to your YouTubers, track the full production pipeline, and publish — separate from the teacher Task Manager.</p></div><div class="vt-sp"></div>'
      +'<div style="display:flex;gap:10px;flex-wrap:wrap"><button class="btn btn-ghost btn-sm" onclick="openYtChannels()">'+ic('play')+' Channels ('+(window._ytChannels||[]).length+')</button>'
      +'<button class="btn btn-ghost btn-sm" onclick="openYtTypes()">'+ic('edit')+' Video Types ('+(window._ytTypes||[]).length+')</button>'
      +'<button class="btn btn-ghost btn-sm" onclick="loadAYtTasks()">'+ic('refresh')+' Refresh</button>'
      +'<button class="btn btn-gold btn-sm" onclick="openYtAssign()">'+ic('clipboard')+' Assign Work</button>'
      +'<button class="btn btn-gold btn-sm" onclick="openYtSeries()">'+ic('folder')+' Assign Series</button>'
      +'<button class="btn btn-ghost btn-sm" onclick="openYtTargets()">'+ic('target')+' Targets</button></div></div>'
    +'<div class="vt-cards"></div>';
  // build stat row cleanly
  var statRow=''
    +stat('Total Assigned',total,'#8a6d10','clipboard','all')
    +stat('To Shoot',assigned,'#0891b2','clock','assigned')
    +stat('Approval Pending',review,'#c99a2e','bell','review')
    +stat('In Production',prod,'#7c4fc0','play','prod')
    +stat('Published',done,'#059669','check','done')
    +stat('Overdue',overdue,'#dc2626','alert','over');
  el.querySelector('.vt-cards').innerHTML=statRow;
  // type chips
  var typeKeys=Object.keys(byType);
  var typeHtml = typeKeys.length ? '<div class="card" style="margin-bottom:16px"><div class="card-body" style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;padding:12px 16px"><span style="font-size:.68rem;font-weight:800;color:var(--text-muted);text-transform:uppercase;letter-spacing:.06em">'+ic('chart')+' Type-wise</span>'+typeKeys.map(function(k){return '<span class="vt-type" style="cursor:pointer" onclick="_ytTypeFilter(\''+esc(String(k).replace(/'/g,''))+'\')">'+esc(k)+' · '+byType[k]+'</span>';}).join('')+'</div></div>' : '';
  var filters='<div class="vt-filters">'
    +'<input class="vt-filt-search yt-search" type="search" placeholder="Search — title, youtuber, channel, subject, ref…" value="'+esc(f.q||'')+'" oninput="window._ytF.q=this.value.trim().toLowerCase();_ytClientFilter()">'
    +'<span class="vt-filt-lbl">'+ic('help')+' Filter</span>'
    +'<select class="vt-filt-sel" onchange="window._ytF.creator=this.value;_ytClientFilter()">'+cOpt+'</select>'
    +'<select class="vt-filt-sel" onchange="window._ytF.channel=this.value;_ytClientFilter()">'+chOpt+'</select>'
    +'<select class="vt-filt-sel" onchange="window._ytF.video_type=this.value;_ytClientFilter()">'+tyOpt+'</select>'
    +'<button class="vt-filt-clear" onclick="_ytClearFilters()" title="Clear all filters">× Clear</button>'
    +'<div style="flex:1"></div>'
    +'<button class="btn btn-ghost btn-sm" onclick="ytDownloadReport()">'+ic('download')+' Download Report</button>'
    +'</div>';
  var grid='<div class="vt-grid yt-grid">'+(cards||'<div class="yt-empty"><div class="big">'+ic('clipboard')+'</div><p><b>No YouTuber tasks yet</b></p><small>Tap “Assign Work” to give a video or project to a YouTuber.</small></div>')+'</div>';
  el.insertAdjacentHTML('beforeend', typeHtml+_ytRankStrip(all)+_ytSeriesSection(_serTasks)+filters+grid);
  if(f.q||f.creator||f.channel||f.video_type||f.bucket) _ytClientFilter();
}

function _ytCard(t){
  var b=_ytBucket(t), over=_ytOverdue(t), lc=t.lifecycle||'';
  var pc={done:'#059669',prod:'#7c4fc0',review:'#c99a2e',assigned:'#0891b2'}[b];
  var timg=_ytUrl(t.thumbnail);
  var thumb='<div class="ytc-thumb">'+(timg?'<img src="'+timg+'" onerror="this.style.display=\'none\'">':ic('play'))+'</div>';
  var chips='';
  if(t.channel_name) chips+='<span class="vt-pill assigned">'+esc(t.channel_name)+'</span>';
  if(t.video_type) chips+='<span class="vt-type">'+esc(t.video_type)+'</span>';
  if(t.streaming) chips+='<span class="vt-pill '+(t.streaming==='live'?'delayed':'assigned')+'">'+(t.streaming==='live'?'Live':'Recorded')+'</span>';
  if(t.priority==='urgent') chips+='<span class="vt-pill delayed">URGENT</span>';
  var dl = t.deadline?'<span class="ytc-dl'+(over?' over':'')+'">'+ic('clock')+' '+esc(t.deadline)+(over?' · overdue':'')+'</span>':'';
  var acts='<button class="btn btn-ghost btn-sm" onclick="openYtDetail('+t.id+')">'+ic('eye')+' Details</button>';
  if(t.youtube_url) acts+='<a class="btn btn-ghost btn-sm" href="'+_ytUrl(t.youtube_url)+'" target="_blank" rel="noopener">'+ic('play')+' YouTube</a>';
  if(t.submitted_link) acts+='<a class="btn btn-ghost btn-sm" href="'+_ytUrl(t.submitted_link)+'" target="_blank" rel="noopener">'+ic('eye')+' Submission</a>';
  if(_YT_REVIEW.indexOf(lc)>=0){
    acts+='<button class="btn btn-primary btn-sm" onclick="ytApprove('+t.id+')">'+ic('check')+' Approve</button>'
      +'<button class="btn btn-ghost btn-sm" onclick="ytReview('+t.id+',\'changes\')">Changes</button>'
      +'<button class="btn btn-ghost btn-sm" onclick="ytReview('+t.id+',\'reshoot\')">Reshoot</button>'
      +'<button class="btn btn-ghost btn-sm" onclick="ytReview('+t.id+',\'reject\')">Reject</button>';
  } else if(lc==='ready_for_youtube'){
    acts+='<button class="btn btn-gold btn-sm" onclick="ytPublish('+t.id+')">'+ic('play')+' Add YouTube Link</button>';
  }
  var searchTxt=((t.title||'')+' '+(t.creator_name||'')+' '+(t.channel_name||'')+' '+(t.subject||'')+' '+(t.video_type||'')+' '+(t.ref_code||'')).toLowerCase();
  return '<div class="vt-card" data-ytbucket="'+b+'" data-over="'+(over?1:0)+'" data-creator="'+esc(t.creator_name||'')+'" data-channel="'+esc(t.channel_name||'')+'" data-vt="'+esc(t.video_type||'')+'" data-txt="'+esc(searchTxt)+'">'
    +thumb
    +'<div class="vt-body">'
      +'<div class="vt-title">'+esc(t.title||'Untitled')+' <span class="vt-pill" style="background:'+pc+'1f;color:'+pc+'">'+esc(t.lifecycle_label||b)+'</span></div>'
      +(chips?'<div class="vt-chips">'+chips+'</div>':'')
      +'<div class="ytc-meta"><span>'+ic('user')+' '+esc(t.creator_name||'—')+'</span>'+(t.editor_name?'<span>'+ic('edit')+' '+esc(t.editor_name)+'</span>':'')+dl+(t.yt_views!=null?'<span>'+ic('chart')+' '+_ytNum(t.yt_views)+' views</span>':'')+(t.ref_code?'<span style="opacity:.6">'+esc(t.ref_code)+'</span>':'')+'</div>'
      +(t.next_action?'<div class="ytc-next">'+ic('clock')+' '+esc(t.next_action)+'</div>':'')
      +(acts?'<div class="vt-foot" style="margin-top:9px;display:flex;gap:8px;flex-wrap:wrap">'+acts+'</div>':'')
    +'</div></div>';
}

function _ytRoot(){ return document.getElementById(window._ytHost||'a-ytasks-content'); }
function _ytBucketFilter(b){ window._ytF.bucket=(window._ytF.bucket===b?'':b); _ytClientFilter(); }
function _ytTypeFilter(k){ window._ytF.video_type=(window._ytF.video_type===k?'':k); _ytClientFilter(); }
function _ytClearFilters(){ window._ytF={q:'',creator:'',channel:'',video_type:'',bucket:''}; var root=_ytRoot(); if(root){ var sr=root.querySelector('.yt-search'); if(sr)sr.value=''; root.querySelectorAll('.vt-filt-sel').forEach(function(s){s.selectedIndex=0;}); } _ytClientFilter(); }
function _ytClientFilter(){
  var f=window._ytF, root=_ytRoot(); if(!root) return;
  root.querySelectorAll('.vt-stat[data-ytb]').forEach(function(c){ c.classList.toggle('vt-stat-on', !!f.bucket && c.getAttribute('data-ytb')===f.bucket); });
  root.querySelectorAll('.yt-grid > .vt-card').forEach(function(c){
    var show=true;
    if(f.creator && c.getAttribute('data-creator')!==f.creator) show=false;
    if(show && f.channel && c.getAttribute('data-channel')!==f.channel) show=false;
    if(show && f.video_type && c.getAttribute('data-vt')!==f.video_type) show=false;
    if(show && f.bucket){ if(f.bucket==='over'){ show=c.getAttribute('data-over')==='1'; } else if(f.bucket!=='all'){ show=c.getAttribute('data-ytbucket')===f.bucket; } }
    if(show && f.q){ show=(c.getAttribute('data-txt')||'').indexOf(f.q)>=0; }
    c.style.display=show?'':'none';
  });
  // series groups respond to youtuber + search filters (channel/type/bucket apply to the flat grid)
  root.querySelectorAll('.yt-sgroup').forEach(function(g){
    var show=true;
    if(f.creator && g.getAttribute('data-creator')!==f.creator) show=false;
    if(show && f.q) show=(g.getAttribute('data-txt')||'').indexOf(f.q)>=0;
    g.style.display=show?'':'none';
  });
}

// ---- Assign Work (create a youtuber task) ----
function openYtAssign(){
  var ppl=(window._ytPeople||[]).filter(function(p){return p.profile_id;});
  if(!ppl.length){ toast('Add a YouTuber first under Production Team.',true); return; }
  var yOpt=ppl.map(function(p){return '<option value="'+p.profile_id+'">'+esc(p.name||('YouTuber #'+p.profile_id))+'</option>';}).join('');
  var chOpt='<option value="">— No channel —</option>'+(window._ytChannels||[]).map(function(c){return '<option value="'+esc(c.name)+'">'+esc(c.name)+'</option>';}).join('');
  var tyOpt='<option value="">— Type —</option>'+(window._ytTypes||[]).map(function(c){return '<option value="'+esc(c.name)+'">'+esc(c.name)+'</option>';}).join('');
  showModal('Assign Work to a YouTuber',
    '<div class="form-grid vt-form">'
    +'<div class="form-group" style="grid-column:1/-1"><label>Video Title</label><input id="yta-title" class="input" placeholder="e.g. Physics One Shot — Motion in a Plane"></div>'
    +'<div class="form-group" style="grid-column:1/-1"><label>YouTuber</label><select id="yta-yt" class="input">'+yOpt+'</select></div>'
    +'<div class="form-group"><label>Channel</label><select id="yta-ch" class="input">'+chOpt+'</select></div>'
    +'<div class="form-group"><label>Video Type</label><select id="yta-ty" class="input">'+tyOpt+'</select></div>'
    +'<div class="form-group"><label>Format</label><select id="yta-stream" class="input"><option value="">— Not set —</option><option value="recorded">Recorded</option><option value="live">Live</option></select></div>'
    +'<div class="form-group"><label>Priority</label><select id="yta-pri" class="input"><option value="normal">Normal</option><option value="urgent">Urgent</option></select></div>'
    +'<div class="form-group" style="grid-column:1/-1"><label>Deadline</label><input id="yta-dl" class="input" type="datetime-local"></div>'
    +'<div class="form-group" style="grid-column:1/-1"><label>Reference / Brief <span style="font-weight:600;color:var(--text-muted)">(optional)</span></label><input id="yta-ref" class="input" placeholder="Reference link or note"></div>'
    +'<div class="form-group" style="grid-column:1/-1"><label>Remarks <span style="font-weight:600;color:var(--text-muted)">(optional)</span></label><textarea id="yta-rem" class="input" rows="2" placeholder="Instructions for the youtuber"></textarea></div>'
    +'<div class="form-group" style="grid-column:1/-1"><div class="yt-chks"><label class="yt-chk"><input type="checkbox" id="yta-appr" checked> Require PM/Admin approval after submission</label>'
      +'<label class="yt-chk"><input type="checkbox" id="yta-thumb"> Needs a thumbnail (graphics)</label></div></div>'
    +'</div>',
    '<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="submitYtAssign(this)">'+ic('check')+' Assign</button>');
}
async function submitYtAssign(btn){
  var title=(document.getElementById('yta-title').value||'').trim();
  var yid=+(document.getElementById('yta-yt').value||0);
  if(!title){ toast('Enter a video title',true); return; }
  if(!yid){ toast('Choose a youtuber',true); return; }
  var body={ creator_type:'youtuber', youtuber_id:yid, title:title,
    channel_name:document.getElementById('yta-ch').value||'',
    video_type:document.getElementById('yta-ty').value||'',
    streaming:document.getElementById('yta-stream').value||'',
    priority:document.getElementById('yta-pri').value||'normal',
    reference:document.getElementById('yta-ref').value||'',
    remarks:document.getElementById('yta-rem').value||'',
    approval_required:document.getElementById('yta-appr').checked,
    thumbnail_required:document.getElementById('yta-thumb').checked };
  var dl=document.getElementById('yta-dl').value; if(dl) body.deadline=dl;
  if(btn){ btn.disabled=true; btn.textContent='Assigning…'; }
  try{ await api('/api/production/tasks','POST',body); closeModal(); toast('Assigned to the youtuber.'); loadAYtTasks(); }
  catch(e){ toast((e&&e.message)||'Could not assign',true); if(btn){ btn.disabled=false; btn.innerHTML=ic('check')+' Assign'; } }
}

// ---- Creator review actions ----
async function ytApprove(id){
  try{ await api('/api/production/tasks/'+id+'/approve-creator','POST',{}); toast('Approved.'); loadAYtTasks(); }
  catch(e){ toast((e&&e.message)||'Failed',true); }
}
function ytReview(id, action){
  var titleMap={changes:'Request Changes',reshoot:'Ask for a Reshoot',reject:'Reject Submission'};
  var needDl=(action==='changes'||action==='reshoot');
  showModal(titleMap[action]||'Review',
    '<div class="form-grid vt-form">'
    +'<div class="form-group" style="grid-column:1/-1"><label>Remarks</label><textarea id="ytr-rem" class="input" rows="3" placeholder="What needs to change / why"></textarea></div>'
    +'<div class="form-group" style="grid-column:1/-1"><label>New Deadline'+(needDl?'':' <span style="font-weight:600;color:var(--text-muted)">(optional — leave empty for a final reject)</span>')+'</label><input id="ytr-dl" class="input" type="datetime-local"></div>'
    +'</div>',
    '<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="submitYtReview('+id+",'"+action+"',this)\">Submit</button>");
}
async function submitYtReview(id, action, btn){
  var rem=(document.getElementById('ytr-rem').value||'').trim();
  var dl=(document.getElementById('ytr-dl').value||'').trim();
  if(!rem){ toast('Remarks are required',true); return; }
  if((action==='changes'||action==='reshoot') && !dl){ toast('A new deadline is required',true); return; }
  var ep={changes:'request-creator-changes',reshoot:'reshoot-creator',reject:'reject-creator'}[action];
  var body={remarks:rem}; if(dl){ body.new_deadline=dl; } if(action==='reject'&&dl){ body.allow_resubmit=true; }
  if(btn){ btn.disabled=true; btn.textContent='Submitting…'; }
  try{ await api('/api/production/tasks/'+id+'/'+ep,'POST',body); closeModal(); toast('Done.'); loadAYtTasks(); }
  catch(e){ toast((e&&e.message)||'Failed',true); if(btn){ btn.disabled=false; btn.textContent='Submit'; } }
}
function ytPublish(id){
  showModal('Add YouTube Link',
    '<div class="form-grid vt-form"><div class="form-group" style="grid-column:1/-1"><label>Published YouTube URL</label><input id="ytp-url" class="input" placeholder="https://youtu.be/..."></div>'
    +'<div class="form-group" style="grid-column:1/-1"><div class="vt-hint">Adding the link marks this video as Uploaded and starts live-view tracking.</div></div></div>',
    '<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="submitYtPublish('+id+',this)">'+ic('check')+' Publish</button>');
}
async function submitYtPublish(id, btn){
  var url=(document.getElementById('ytp-url').value||'').trim();
  if(!url){ toast('Paste the YouTube link',true); return; }
  if(btn){ btn.disabled=true; btn.textContent='Saving…'; }
  try{ await api('/api/production/tasks/'+id+'/youtube','POST',{youtube_url:url}); closeModal(); toast('Published.'); loadAYtTasks(); }
  catch(e){ toast((e&&e.message)||'Failed',true); if(btn){ btn.disabled=false; btn.innerHTML=ic('check')+' Publish'; } }
}

async function ytDownloadReport(){
  try{
    var r=await fetch(API+'/api/production/report.csv?creator_type=youtuber',{headers:{Authorization:'Bearer '+TOKEN}});
    if(!r.ok) throw new Error('Download failed');
    var u=URL.createObjectURL(await r.blob());
    var a=document.createElement('a'); a.href=u; a.download='youtuber_report.csv';
    document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(u);
    toast('Report downloaded.');
  }catch(e){ toast('Could not download the report',true); }
}
