console.log('MVS Smart Paste build 2026-07-20 v5 + scheduling + premium PDF v2');
const spUMAP={'∫':'\\int ','π':'\\pi ','θ':'\\theta ','Δ':'\\Delta ','δ':'\\delta ','λ':'\\lambda ','μ':'\\mu ','α':'\\alpha ','β':'\\beta ','γ':'\\gamma ','ω':'\\omega ','Σ':'\\sum ','σ':'\\sigma ','×':'\\times ','·':'\\cdot ','÷':'\\div ','±':'\\pm ','∞':'\\infty ','≈':'\\approx ','≠':'\\ne ','≤':'\\le ','≥':'\\ge ','→':'\\to ','←':'\\leftarrow ','−':'-','–':'-','η':'\\eta ','Ω':'\\Omega ','ε':'\\epsilon ','ρ':'\\rho ','ν':'\\nu ','°':'^\\circ '};
const spSUP={'⁰':'0','¹':'1','²':'2','³':'3','⁴':'4','⁵':'5','⁶':'6','⁷':'7','⁸':'8','⁹':'9','ⁿ':'n','⁻':'-'};
const spSUB={'₀':'0','₁':'1','₂':'2','₃':'3','₄':'4','₅':'5','₆':'6','₇':'7','₈':'8','₉':'9','ₓ':'x'};

function spIsChem(t){
  const hasArrow=/(->|→|⟶|⇌|⟹|==>)/.test(t);
  const chemTokens=(t.match(/(?:^|[\s+(])(?:\d+)?(?:H|He|Li|Be|B|C|N|O|F|Ne|Na|Mg|Al|Si|P|S|Cl|Ar|K|Ca|Fe|Cu|Zn|Ag|Au|Hg|Pb|Sn|Mn|Cr|Ni|Co|Ba|Sr|I|Br)\w*\d*(?:[+\-]\d*)?/g)||[]).length;
  return hasArrow && chemTokens>=2;
}
function spChemTex(t){
  let s=t.replace(/→|⟶|⟹/g,'->').replace(/⇌/g,'<=>').replace(/==>/g,'->');
  s=s.replace(/->\s*[\(\[]([^\)\]]+)[\)\]]/g,'->[$1]');
  return '$\\ce{'+s.trim()+'}$';
}
function spSegParse(s){
  const out=[]; let depth=0, buf='';
  const push=m=>{ if(buf){ out.push({m:m,t:buf}); buf=''; } };
  for(const ch of s){
    if(ch==='\u0000'){ if(depth===0) push(false); depth++; continue; }
    if(ch==='\u0001'){ depth=Math.max(0,depth-1); if(depth===0) push(true); continue; }
    buf+=ch;
  }
  push(depth>0);
  return out;
}
/* bare-LaTeX fixer: content pasted without $..$ still renders as math */
function spBareMath(t){
  if(!t) return t;
  return String(t).split(/(\$[^$]+\$)/g).map(function(seg){
    if(seg.length>1&&seg[0]==='$'&&seg[seg.length-1]==='$') return seg;
    let s=seg;
    const math=[]; const M=x=>{ math.push(x); return '\u0006'+(math.length-1)+'\u0007'; };
    // \boxed{...} (allow one nested brace level, e.g. \text{} inside)
    s=s.replace(/\\boxed\{((?:[^{}]|\{[^{}]*\})+)\}/g,function(m,c){ return M('\\boxed{'+((c.trim().indexOf(' ')>=0)?'\\text{'+c.trim()+'}':c)+'}'); });
    // any other latex command with brace groups (one nested level): \frac{a}{b}, \propto, \times ...
    s=s.replace(/\\[a-zA-Z]+(?:\s*\{(?:[^{}]|\{[^{}]*\})*\})*/g,function(m){ return M(m); });
    // paren fractions typed plain: (T)/(400) -> \frac{T}{400}
    s=s.replace(/\(([A-Za-z0-9.,+\-*^{}_\\ ]{1,14})\)\s*\/\s*\(([A-Za-z0-9.,+\-*^{}_\\ ]{1,14})\)/g,function(m,x,y){ if(!/[\d_^]/.test(x+y)) return m; return M('\\frac{'+x+'}{'+y+'}'); });
    // subscripts: f_o, f_c, f_{oc}
    s=s.replace(/\b([A-Za-z])_(\{[A-Za-z0-9]+\}|[A-Za-z0-9]{1,4})(?![A-Za-z0-9{])/g,function(m,x,y){ return M(x+'_'+y); });
    // superscripts with braces: 10^{-2}, x^{3}
    s=s.replace(/([A-Za-z0-9]+|\})\^(\{[^{}]+\})/g,function(m,x,y){ return M(x+'^'+y); });
    // restore protected math as $...$
    s=s.replace(/\u0006(\d+)\u0007/g,function(m,i){ return '$'+math[+i]+'$'; });
    return s;
  }).join('');
}
function spSmartFormat(raw){
  const MK0='\u0000', MK1='\u0001';
  const out=[];
  for(const line0 of raw.split(/\r?\n/)){
    const t=line0.trim();
    if(!t){ out.push(''); continue; }
    if(spIsChem(t)){ out.push(spChemTex(t)); continue; }
    if(/\\begin\{|\\end\{/.test(t)){ out.push(t); continue; }
    let s=t, hadMath=false;
    const M=x=>{ hadMath=true; return MK0+x+MK1; };
    // fractions FIRST (plain tokens like T2/T1, 273/373 — digit required)
    s=s.replace(/(^|[^\w^_{\\Ͱ-Ͽ])([A-Za-z0-9]+)\s*\/\s*([A-Za-z0-9]+)(?![\w}])/g,(m,pre,a,b)=>{ if(!/\d/.test(a+b)) return m; return pre+M('\\frac{'+a+'}{'+b+'}'); });
    // degree: 30° -> 30^{\circ}
    s=s.replace(/(\d+(?:\.\d+)?)\s*°/g,(m,a)=> M(a+'^{\\circ}'));
    // unicode superscripts (base included)
    s=s.replace(/([A-Za-z0-9}\)])?([⁰¹²³⁴⁵⁶⁷⁸⁹ⁿ⁻]+)/g,(m,b,sup)=> M((b||'')+'^{'+[...sup].map(c=>spSUP[c]||'').join('')+'}'));
    // unicode subscripts (base included)
    s=s.replace(/([A-Za-z0-9}\)])?([₀₁₂₃₄₅₆₇₈₉ₓ]+)/g,(m,b,sub)=> M((b||'')+'_{'+[...sub].map(c=>spSUB[c]||'').join('')+'}'));
    // square root (parenthesized group or single token)
    s=s.replace(/√\s*(\([^)]*\)|\S+)/g,(m,a)=> M('\\sqrt{'+a+'}'));
    s=s.replace(/√/g,()=> M('\\sqrt{}'));
    // unicode minus/dash stays plain
    s=s.replace(/[−–]/g,'-');
    // unicode symbol map (each symbol = its own math piece)
    for(const k in spUMAP){ if(k==='−'||k==='–'||k==='°') continue; if(s.includes(k)){ s=s.split(k).join(MK0+spUMAP[k]+MK1); hadMath=true; } }
    // math function names -> upright operators
    s=s.replace(/\b(sin|cos|tan|sec|csc|cot|log|ln)\b/g,(mm,fn)=> M('\\'+fn+' '));
    // caret superscripts (x^2)
    s=s.replace(/([A-Za-z0-9])\^(\d+)\b/g,(m,a,b)=> M(a+'^{'+b+'}'));
    // letter-digit subscripts (H2 -> H_{2})
    s=s.replace(/([A-Za-z])(\d)(?=[A-Za-z]|\b)/g,(m,a,b)=> M(a+'_{'+b+'}'));
    // fractions pass 2 (brace-aware: x^{3}/3, T_{2}/T_{1})
    s=s.replace(/(^|[^\w^_{\\Ͱ-Ͽ])([A-Za-z0-9]+(?:[_^]\{\d+\})?)\s*\/\s*([A-Za-z0-9]+(?:[_^]\{\d+\})?)(?![\w}])/g,(m,pre,a,b)=>{ if(!/[\d_^]/.test(a+b)) return m; return pre+M('\\frac{'+a+'}{'+b+'}'); });
    if(!hadMath){ out.push(s); continue; }
    const segs=spSegParse(s);
    const outside=segs.filter(g=>!g.m).map(g=>g.t).join(' ');
    const longWords=(outside.match(/[A-Za-z]{3,}/g)||[]).filter(w=>!/^(sin|cos|tan|sec|csc|cot|log|ln|min|max|mod|arg|deg)$/i.test(w)).length;
    if(longWords===0){
      // pure equation line -> wrap whole line
      const inner=segs.map(g=>g.t).join('').replace(/%/g,'\\%');
      out.push('$'+inner+'$');
    } else {
      // mixed English+math -> wrap only math pieces; merge single-space gaps
      const merged=[];
      for(let i=0;i<segs.length;i++){
        const g=segs[i];
        if(!g.m && g.t===' ' && i>0 && i<segs.length-1 && segs[i-1].m && segs[i+1].m){
          merged[merged.length-1].t+=' '; continue;
        }
        if(g.m && merged.length && merged[merged.length-1].m){ merged[merged.length-1].t+=g.t; continue; }
        merged.push({m:g.m,t:g.t});
      }
      out.push(merged.map(g=> g.m ? '$'+g.t.replace(/%/g,'\\%')+'$' : g.t).join(''));
    }
  }
  return out.join('\n');
}

/* ---- minimal MathML → LaTeX (web-copy path) ---- */
const spMOMAP={'∫':'\\int ','∑':'\\sum ','∏':'\\prod ','π':'\\pi ','θ':'\\theta ','Δ':'\\Delta ','×':'\\times ','·':'\\cdot ','±':'\\pm ','∞':'\\infty ','≤':'\\le ','≥':'\\ge ','≠':'\\ne ','−':'-','η':'\\eta ','μ':'\\mu ','λ':'\\lambda ','α':'\\alpha ','β':'\\beta ','γ':'\\gamma ','→':'\\to ','√':'\\sqrt{}'};
function spMl2Tex(node){
  if(node.nodeType===3) return node.nodeValue||'';
  const tag=(node.tagName||'').toLowerCase();
  const kids=[...node.childNodes].map(spMl2Tex).join('').trim();
  switch(tag){
    case 'annotation': case 'annotation-xml': return '';
    case 'mi': case 'mn': case 'mtext': return kids;
    case 'mo': return spMOMAP[kids]||kids;
    case 'mfrac': return '\\frac{'+spMl2Tex(node.children[0]).trim()+'}{'+spMl2Tex(node.children[1]).trim()+'}';
    case 'msup': return spMl2Tex(node.children[0]).trim()+'^{'+spMl2Tex(node.children[1]).trim()+'}';
    case 'msub': return spMl2Tex(node.children[0]).trim()+'_{'+spMl2Tex(node.children[1]).trim()+'}';
    case 'msubsup': return spMl2Tex(node.children[0]).trim()+'_{'+spMl2Tex(node.children[1]).trim()+'}^{'+spMl2Tex(node.children[2]).trim()+'}';
    case 'msqrt': return '\\sqrt{'+kids+'}';
    case 'mroot': return '\\sqrt['+spMl2Tex(node.children[1]).trim()+']{'+spMl2Tex(node.children[0]).trim()+'}';
    default: return kids;
  }
}
function spSanitizeMath(t){
  let x=' '+t+' ';
  for(const k in spUMAP){ x=x.split(k).join(k==='−'||k==='–'?'-':spUMAP[k]); }
  x=x.replace(/([A-Za-z0-9}\)])?([₀₁₂₃₄₅₆₇₈₉ₓ]+)/g,(m,b,sub)=>(b||'')+'_{'+[...sub].map(c=>spSUB[c]||'').join('')+'}');
  x=x.replace(/([A-Za-z0-9}\)])?([⁰¹²³⁴⁵⁶⁷⁸⁹ⁿ⁻]+)/g,(m,b,sup)=>(b||'')+'^{'+[...sup].map(c=>spSUP[c]||'').join('')+'}');
  x=x.replace(/\\\\/g,' ');
  x=x.replace(/\\text\{(sin|cos|tan|sec|csc|cot|log|ln)\s*\}/g,'\\$1 ');
  x=x.replace(/(^|[^\\])\b(sin|cos|tan|sec|csc|cot|log|ln)\b/g,'$1\\$2 ');
  x=x.replace(/\\text\{([A-Za-z0-9_^{}+\-.\\]+)\}/g,(m,c)=>/[\\_{}^0-9]/.test(c)?c:m);
  x=x.replace(/\s+/g,' ').trim();
  return x;
}
function spMathToTex(m){
  const ann=m.querySelector('annotation[encoding="application/x-tex"],annotation[encoding*="tex" i]');
  const t=(ann&&ann.textContent&&ann.textContent.trim())||spMl2Tex(m);
  return spSanitizeMath(t);
}
/* ---- clipboard HTML -> text with $..$ LaTeX (MathJax v2/v3 + KaTeX + MathML safe) ---- */
function spFromClipboardHTML(html){
  const doc=new DOMParser().parseFromString(html,'text/html');
  const T=(el,t)=>{ const sp=doc.createElement('span'); sp.textContent=t; el.replaceWith(sp); };
  // KaTeX display + inline (site render + our own copies) — keep annotation LaTeX, drop rendered twin
  doc.querySelectorAll('.katex-display').forEach(k=>{
    const m=k.querySelector('math');
    T(k,'\n $'+(m?spMathToTex(m):k.textContent).replace(/\s+/g,' ').trim()+'$ \n');
  });
  doc.querySelectorAll('.katex').forEach(k=>{
    const m=k.querySelector('math');
    T(k,' $'+(m?spMathToTex(m):k.textContent).replace(/\s+/g,' ').trim()+'$ ');
  });
  // MathJax v3 — visible CHTML spans + hidden assistive MathML: keep only the MathML
  doc.querySelectorAll('mjx-container').forEach(c=>{
    const am=c.querySelector('mjx-assistive-mml math');
    const disp=String(c.getAttribute('display')||'').toLowerCase()==='true';
    T(c,(disp?'\n':'')+' $'+(am?spMathToTex(am):c.textContent).replace(/\s+/g,' ').trim()+'$ '+(disp?'\n':''));
  });
  // MathJax v2 display blocks
  doc.querySelectorAll('.MathJax_Display').forEach(d=>{
    const sc=d.querySelector('script[type^="math/tex"]');
    T(d,'\n $'+(sc?(sc.textContent||'').trim():d.textContent.trim())+'$ \n');
  });
  // MathJax v2 inline scripts
  doc.querySelectorAll('script[type^="math/tex"]').forEach(sc=>{
    T(sc,' $'+(sc.textContent||'').trim()+'$ ');
  });
  // drop leftover rendered duplicates / hidden nodes
  doc.querySelectorAll('.MathJax_Preview,.MathJax,mjx-assistive-mml,[aria-hidden="true"],[style*="display:none"],[style*="display: none"],[style*="visibility:hidden"],[style*="visibility: hidden"]').forEach(n=>n.remove());
  // plain MathML
  doc.querySelectorAll('math').forEach(m=>{
    T(m,' $'+spMathToTex(m).replace(/\s+/g,' ').trim()+'$ ');
  });
  // preserve line breaks from block structure
  doc.querySelectorAll('br').forEach(b=>b.replaceWith(doc.createTextNode('\n')));
  doc.querySelectorAll('p,div,li,tr,h1,h2,h3,h4,h5,h6,section,article,blockquote,table,ul,ol').forEach(el=>{ el.appendChild(doc.createTextNode('\n')); });
  let txt=doc.body.innerText||doc.body.textContent||'';
  return txt.replace(/[ \t]+\n/g,'\n').replace(/\n{3,}/g,'\n\n').replace(/[ \t]{2,}/g,' ').trim();
}


/* ---- question types (Mission 75 Test Series) ---- */
const QTYPES=[['general','Written Answer (short / long)'],['match','Match the Following'],['fill','Fill in the Blanks'],['tf','True / False'],['num','Numerical / Formula based'],['diagram','Diagram / Graph based']];
/* ---- match-the-following formatter: builds a KaTeX two-column table ---- */
function spEscTex(t){ return t.replace(/([&%#_{}$])/g,'\\$1'); }
function spDedupCell(str){
  // MathJax/KaTeX wali sites se copy karne par formula clipboard me DO baar aata
  // hai (dikhne wala + screen-reader text). Cell ke body ke dono half same nikle
  // (exact ya characters ka multiset) to pehla half hi rakhte hain.
  const s0=String(str||'').trim();
  if(s0.length<6) return s0;
  const MAP={'\u00b9':'1','\u00b2':'2','\u00b3':'3','\u2070':'0','\u2074':'4','\u2075':'5','\u2076':'6','\u2077':'7','\u2078':'8','\u2079':'9','\u00bd':'12','\u00bc':'14','\u00be':'34','\u2080':'0','\u2081':'1','\u2082':'2','\u2083':'3','\u2084':'4','\u2085':'5','\u2086':'6','\u2087':'7','\u2088':'8','\u2089':'9'};
  const norm=x=>String(x).toLowerCase().replace(/\\[a-z]+/gi,'').split('').map(ch=>MAP[ch]||ch).join('').replace(/[^a-z0-9]/g,'');
  const head=(s0.match(/^\(\s*[A-Za-z0-9]{1,4}\s*\)\s*/)||[''])[0];
  const body=s0.slice(head.length);
  const n=norm(body);
  if(n.length>=4 && n.length%2===0){
    const h=n.length/2, A=n.slice(0,h), B=n.slice(h);
    const same=(A===B)||(A.split('').sort().join('')===B.split('').sort().join(''));
    if(same){
      let idx=-1;
      for(let i=1;i<=body.length;i++){ if(norm(body.slice(0,i)).length===h){ idx=i; break; } }
      if(idx>0) return (head+body.slice(0,idx)).trim();
    }
  }
  return s0;
}
function spCellTex(td){
  const c=td.cloneNode(true);
  // KaTeX (.katex-html) aur MathJax (mjx-math) apna visible duplicate
  // aria-hidden="true" mark karte hain - use hata do, warna formula 2 baar aata hai
  c.querySelectorAll('[aria-hidden="true"]').forEach(x=>{ if(!x.querySelector('math')) x.remove(); });
  c.querySelectorAll('math').forEach(m=>{ const t=spMathToTex(m).trim(); m.replaceWith(m.ownerDocument.createTextNode(' $'+t+'$ ')); });
  let t=(c.textContent||'').replace(/\s+/g,' ').replace(/\$\s+/g,'$').replace(/\s+\$/g,'$').trim();
  t=spDedupCell(t);
  // format only the non-math parts (math already converted from MathML)
  return t.split(/(\$[^$]+\$)/g).map(p=>/^\$/.test(p)?p:spSmartFormat(p)).join('');
}
function spToArrayCell(t){
  const parts=t.split(/(\$[^$]+\$)/g).filter(p=>p.trim()!=='');
  if(!parts.length) return '\\text{}';
  return parts.map(p=>{
    const m=p.match(/^\$([\s\S]+)\$$/);
    if(m){
      const pm=m[1].match(/^\((\s*[A-Za-z]{1,4}\s*\))\s*/);
      if(pm) return '\\text{'+pm[0].trim()+'}\\ '+m[1].slice(pm[0].length);
      return m[1];
    }
    return '\\text{'+spEscTex(p)+'}';
  }).join('\\ ');
}
function spMatchArray(rows,intro,hasHeader){
  const ncol=Math.max.apply(null,rows.map(r=>r.length));
  let head='';
  if(hasHeader&&rows.length){
    const hr=rows.shift();
    const cells=[]; for(let c=0;c<ncol;c++){ const t=(hr[c]||'').replace(/\$/g,'').trim(); cells.push('\\colorbox{#dce8f8}{\\text{\\textbf{'+spEscTex(t)+'}}}'); }
    head=cells.join(' & ')+'\\\\\\hline\n';
  }
  const body=rows.map(r=>{
    const cells=[]; for(let c=0;c<ncol;c++) cells.push(spToArrayCell(r[c]||''));
    return cells.join(' & ');
  }).join('\\\\\\hline\n');
  const colspec='|'+new Array(ncol+1).join('l|');
  const arr='$\\begin{array}{'+colspec+'}\\hline\n'+head+body+'\\\\\\hline\\end{array}$';
  return intro?intro+'\n'+arr:arr;
}
function spMatchFromTable(html){
  const doc=new DOMParser().parseFromString(html,'text/html');
  const tbl=doc.querySelector('table'); if(!tbl) return null;
  let hasHeader=false;
  const rows=[...tbl.querySelectorAll('tr')].map((tr,ri)=>{
    const cells=[...tr.querySelectorAll('th,td')].map(spCellTex);
    if(ri===0&&(tr.querySelectorAll('th').length>0||/column|list|सूची|स्तंभ|स्तम्भ/i.test(cells.join(' ')))) hasHeader=true;
    return cells;
  }).filter(r=>r.some(c=>c.trim()));
  if(rows.length<2) return null;
  const ncol=Math.max.apply(null,rows.map(r=>r.length));
  if(ncol===2) rows.forEach((r,i)=>{
    if(r.length===1){
      const s=r[0]||'';
      const rightish=/^\(\s*(\d{1,2}|[a-z]{1,4})\s*\)/.test(s);
      rows[i]=rightish?['',s]:[s,''];
    }
  });
  // intro = text outside the table (e.g. the instruction line)
  const clone=doc.body.cloneNode(true);
  clone.querySelectorAll('table').forEach(x=>x.remove());
  let intro=(clone.textContent||'').replace(/\s+/g,' ').trim();
  if(intro&&!/column|स्तंभ|match/i.test(intro)&&intro.length>120) intro='';
  if(intro) intro=spSmartFormat(intro);
  return spMatchArray(rows,intro,hasHeader);
}
function spMatchFromMarkers(t){
  const re=/\(\s*([A-Za-z]{1,4}|\d{1,2})\s*\)/g; let m; const marks=[];
  const stop=/^(sin|cos|tan|sec|csc|cot|log|ln|min|max|mod|the|and|for|are|not|all)$/i;
  while((m=re.exec(t))){ if(!stop.test(m[1])) marks.push({l:m[1],i:m.index,e:re.lastIndex}); }
  if(marks.length<4) return null;
  // Koi label DOBARA aaya (jaise har sub-question ke apne (A)-(D)) to ye
  // match-the-following hai hi nahi - passage/MCQ hai. Ye permanent guard hai.
  const seenL={};
  for(const x of marks){ const k=x.l.toLowerCase(); if(seenL[k]) return null; seenL[k]=1; }
  const isU=s=>/^[A-Z]{1,4}$/.test(s), isL=s=>/^[a-z]{1,4}$/.test(s), isD=s=>/^\d{1,2}$/.test(s);
  const isRm=s=>/^(i|ii|iii|iv|v|vi|vii|viii|ix|x|xi|xii)$/i.test(s);
  const hasU=marks.some(x=>isU(x.l)), hasL=marks.some(x=>isL(x.l)), hasD=marks.some(x=>isD(x.l));
  const hasRm=marks.some(x=>isL(x.l)&&isRm(x.l));                 // (i)-(iv) lowercase roman
  const hasPl=marks.some(x=>isL(x.l)&&!isRm(x.l));                // (a)/(b) plain letters
  let isC1;
  if(hasU&&(hasL||hasD)) isC1=x=>isU(x.l);          // (A)-(D) vs (1)-(8) or (i)-(iv)
  else if(hasL&&hasD) isC1=x=>isL(x.l);             // (a)-(d) vs (1)-(8)
  else if(hasPl&&hasRm) isC1=x=>isL(x.l)&&!isRm(x.l); // (a)-(d) vs (i)-(iv) - answers me common
  else return null;
  const col1=[],col2=[];
  marks.forEach((mk,k)=>{
    const end=k+1<marks.length?marks[k+1].i:t.length;
    const txt=spDedupCell(t.slice(mk.e,end).trim().replace(/\s+/g,' '));
    if(!txt) return;
    const item='('+mk.l+') '+txt;
    (isC1(mk)?col1:col2).push(item);
  });
  if(!col1.length||!col2.length) return null;
  // header labels + intro from the text before the first marker
  let h1='Column-I',h2='Column-II',intro='';
  const pre=t.slice(0,marks[0].i).trim();
  if(pre){
    const lines=pre.split(/\n+/).map(s=>s.trim()).filter(Boolean);
    const hl=lines.filter(s=>/list|column|सूची|स्तंभ|स्तम्भ/i.test(s));
    if(hl.length>=2){ h1=hl[hl.length-2]; h2=hl[hl.length-1]; }
    intro=lines.filter(s=>hl.slice(-2).indexOf(s)<0).join(' ').slice(0,200);
  }
  const fmt=s=>spSmartFormat(s);
  const rows=[[fmt(h1),fmt(h2)]];
  for(let r=0;r<Math.max(col1.length,col2.length);r++) rows.push([fmt(col1[r]||''),fmt(col2[r]||'')]);
  return spMatchArray(rows,intro?fmt(intro):null,true);
}
function spMarkerStats(t){
  const re=/\(\s*([A-Za-z]{1,4}|\d{1,2})\s*\)/g;
  const stop=/^(sin|cos|tan|sec|csc|cot|log|ln|min|max|mod|the|and|for|are|not|all)$/i;
  const marks=[]; let m;
  while((m=re.exec(t))){ if(!stop.test(m[1])) marks.push({l:m[1],i:m.index,e:re.lastIndex}); }
  const seen={}; let repeated=false;
  marks.forEach(x=>{ const k=x.l.toLowerCase(); if(seen[k]) repeated=true; seen[k]=(seen[k]||0)+1; });
  const isRm=x=>/^(i|ii|iii|iv|v|vi|vii|viii|ix|x|xi|xii)$/i.test(x);
  return {marks:marks, repeated:repeated, counts:seen,
    hasUpper:marks.some(x=>/^[A-Z]{1,4}$/.test(x.l)),
    hasRoman:marks.some(x=>isRm(x.l)),
    hasDigit:marks.some(x=>/^\d{1,2}$/.test(x.l))};
}
const _SP_SUP={'0':'\u2070','1':'\u00b9','2':'\u00b2','3':'\u00b3','4':'\u2074','5':'\u2075','6':'\u2076','7':'\u2077','8':'\u2078','9':'\u2079'};
function spFixBrokenSup(t){
  // Rendered maths copy karne par power apni line pe chala jata hai:
  //   "a velocity of 2 ms"  /  "-1"  /  ", and"
  // Aisi akeli power line ko wapas upar wali line pe superscript bana dete hain.
  const lines=String(t||'').split(/\r?\n/);
  const out=[];
  for(const ln of lines){
    const m=ln.trim().match(/^([\u2212\u2013-]?)(\d{1,2})([,.;:]?)$/);
    const prev=out.length?out[out.length-1]:'';
    if(m && /[A-Za-z\u0370-\u03ff\)\]]\s*$/.test(prev)){
      const sup=(m[1]?'\u207b':'')+m[2].split('').map(d=>_SP_SUP[d]||d).join('');
      out[out.length-1]=prev.replace(/\s+$/,'')+sup+(m[3]||'');
      continue;
    }
    // ", and" / "." jaisi continuation line bhi upar hi jud jaati hai
    const cont=ln.trim().match(/^([,.;:]\s*\S[\s\S]*|[,.;:])$/);
    if(cont && out.length && out[out.length-1].trim()){
      out[out.length-1]=out[out.length-1].replace(/\s+$/,'')+ln.trim();
      continue;
    }
    out.push(ln);
  }
  return out.join('\n');
}
function spItemsLookLabelled(t){
  // Match-the-following ke items chhote labels hote hain; sub-question wale
  // parts poore vaakya hote hain. Isi se dono ko alag karte hain.
  const st=spMarkerStats(t);
  if(st.marks.length<4) return false;
  let long=0;
  st.marks.forEach((mk,k)=>{
    const end=k+1<st.marks.length?st.marks[k+1].i:t.length;
    if(t.slice(mk.e,end).trim().length>70) long++;
  });
  return long===0;
}
function spLooksPassage(t){
  // Passage / comprehension MCQ: koi marker label DOBARA aata hai (har
  // sub-question ke apne (A)-(D) hote hain), ya lamba quoted passage hai
  const st=spMarkerStats(t);
  if(st.marks.length<3) return false;
  if(st.repeated) return true;
  if(/passage|paragraph|read the|\u0905\u0928\u0941\u091a\u094d\u091b\u0947\u0926/i.test(t) && st.marks.length>=4) return true;
  return false;
}
function spLooksMatch(t,html){
  // Match-the-following tabhi jab: koi label repeat na ho, do alag series hon,
  // aur "Column/List/सूची" jaisa header ya asli <table> mile
  if(html&&html.indexOf('<table')>=0) return true;
  const st=spMarkerStats(t);
  if(st.repeated||st.marks.length<4) return false;
  const series=(st.hasUpper?1:0)+(st.hasRoman?1:0)+(st.hasDigit?1:0)
    +((st.marks.some(x=>/^[a-z]{1,4}$/.test(x.l)&&!/^(i|ii|iii|iv|v|vi|vii|viii|ix|x)$/i.test(x.l)))?1:0);
  if(series<2) return false;
  return /column|list|match|\u0938\u0942\u091a\u0940|\u0938\u094d\u0924\u0902\u092d|\u0938\u0941\u092e\u0947\u0932/i.test(t);
}
function spFormatPassage(t){
  // Passage-based question ko saaf structure me laata hai:
  // intro line, quoted passage, har sub-question bold, har option apni line pe
  let s=String(t||'').replace(/\r/g,'').replace(/[ \t]+/g,' ').trim();
  if(!s) return null;
  // sub-question markers (i)/(ii)/(1)/(2) apni nayi line pe, bold
  s=s.replace(/\s*\((i{1,3}|iv|v|vi{0,3}|ix|x)\)\s*/gi,(m,g)=>'\n\n**('+g+')** ');
  // option markers (A)-(D) har ek apni line pe
  s=s.replace(/\s*\(([A-Da-d])\)\s*/g,(m,g)=>'\n('+g+') ');
  // quoted passage apne paragraph me - closing quote ke BAAD hi break,
  // warna opening quote aur pehle shabd ke beech line toot jati thi
  s=s.replace(/(\S)([\u201d"])(?=\s|$)/g,'$1$2\n\n');
  s=s.replace(/\n{3,}/g,'\n\n').replace(/[ \t]+\n/g,'\n').replace(/\n[ \t]+/g,'\n');
  // "...follow it:" jaisi intro line ke baad break
  s=s.replace(/(follow it\s*:|answer the questions[^\n:]*:)/i,'$1\n');
  return s.trim();
}
function spAskPasteType(cb){
  // NOTE: exam form khud ek modal ke andar khulta hai, isliye yahan showModal()
  // use NAHI kar sakte - wo form ko replace kar deta hai aur closeModal() poora
  // form band kar deta. Ye apna alag overlay hai, modal system ko chhuta hi nahi.
  const old=document.getElementById('sp-ask'); if(old) old.remove();
  const d=document.createElement('div');
  d.id='sp-ask'; d.className='sp-ask-ov';
  const done=kind=>{ const el=document.getElementById('sp-ask'); if(el) el.remove(); window._spPick=null; cb(kind); };
  window._spPick=done;
  d.innerHTML=`<div class="sp-ask-box" onclick="event.stopPropagation()">
      <div class="sp-ask-h">How should this be pasted?</div>
      <div class="sp-ask-sub">This paste could be a match-the-following table or a passage-based question. Choose the correct type so the formatting comes out right.</div>
      <div class="pt-opts">
        <button type="button" class="pt-opt" onclick="_spPick('match')"><b>Match the Following</b><span>Two columns pair up, for example (A) to (D) with (i) to (iv). Creates a bordered table.</span></button>
        <button type="button" class="pt-opt" onclick="_spPick('passage')"><b>Passage or MCQ Question</b><span>A passage with sub-questions, or options (A) to (D) under a question. Keeps each option on its own line.</span></button>
        <button type="button" class="pt-opt" onclick="_spPick('plain')"><b>Paste as it is</b><span>No automatic formatting.</span></button>
      </div>
      <div class="sp-ask-f"><button type="button" class="btn btn-ghost btn-sm" onclick="_spPick(null)">Cancel</button></div>
    </div>`;
  d.onclick=()=>done(null);
  document.body.appendChild(d);
}
function spFormatMatch(text,html){
  if(html&&html.indexOf('<table')>=0){ const r=spMatchFromTable(html); if(r) return r; }
  if(text&&/\(\s*[A-Za-z0-9]\s*\)/.test(text)){ const r=spMatchFromMarkers(text); if(r) return r; }
  return null;
}

/* ---- smart paste: website copies (MathML) + plain text, exam fields only ---- */
const spTrig=/[°-³¹×÷Ͱ-Ͽ⁰-ₓ←-⇿∀-⋿]|\^|->|[A-Za-z]\d(?!\d)|\d\s?\/\s?\d/;
document.addEventListener('paste',function(e){
  const t=e.target;
  if(!t||!(t.tagName==='TEXTAREA'||t.tagName==='INPUT')) return;
  if(!t.closest||!t.closest('#ex-qs')) return;
  const cd=e.clipboardData; if(!cd) return;
  let text=null;
  const html=cd.getData('text/html');
  const plain=cd.getData('text/plain')||'';
  const put=(val,msg)=>{
    const a=t.selectionStart||0, b=t.selectionEnd||0;
    t.value=t.value.slice(0,a)+val+t.value.slice(b);
    const p=a+val.length; t.selectionStart=t.selectionEnd=p; t.focus();
    t.dispatchEvent(new Event('input',{bubbles:true}));
    if(msg) toast(msg);
  };
  const asPassage=()=>{
    // Rendered maths wali site se copy hua ho to pehle MathML -> $...$ nikaalo,
    // phir tooti hui powers jodo, tabhi structure banao. Warna ms^-1 jaisa
    // formula tukdon me bikhar jata tha.
    let base=null;
    if(html&&html.indexOf('<math')>=0){ try{ base=spFromClipboardHTML(html); }catch(e){} }
    if(base==null) base=plain;
    base=spFixBrokenSup(base);
    const r=spFormatPassage(base);
    return r||base;
  };
  const asMatch=()=>spFormatMatch(plain,html);
  const asPlainSmart=()=>{
    if(html&&html.indexOf('<math')>=0){ const r=spFromClipboardHTML(html); if(r!=null) return spFixBrokenSup(r); }
    const fixed=spFixBrokenSup(plain);
    if(fixed!==plain) return spSmartFormat(fixed);
    return (plain&&spTrig.test(plain))?spSmartFormat(plain):null;
  };
  // 1) Pakka passage / MCQ (koi marker label repeat hota hai) -> kabhi table nahi
  if(spLooksPassage(plain)){
    e.preventDefault();
    put(asPassage(),'Pasted as a passage question - options kept on separate lines.');
    return;
  }
  // 2) Pakka match-the-following (asli table ya do alag series + Column header)
  if(spLooksMatch(plain,html)){
    const r=asMatch();
    if(r!=null){ e.preventDefault(); put(r,'Pasted & formatted as a match-the-following table.'); return; }
  }
  // 3) Doubt hai (markers to hain par confirm nahi) -> teacher se hi pooch lo
  const st=spMarkerStats(plain);
  if(st.marks.length>=4 && spItemsLookLabelled(plain) && asMatch()!=null){
    e.preventDefault();
    const snapshot={a:t.selectionStart||0,b:t.selectionEnd||0};
    spAskPasteType(kind=>{
      t.selectionStart=snapshot.a; t.selectionEnd=snapshot.b;
      if(kind==='match'){ const r=asMatch(); put(r!=null?r:plain,'Formatted as a match-the-following table.'); }
      else if(kind==='passage'){ put(asPassage(),'Formatted as a passage question.'); }
      else if(kind==='plain'){ put(plain); }
    });
    return;
  }
  // 4) Baaki sab: purana behaviour
  text=asPlainSmart();
  if(text==null) return; // ordinary paste, leave untouched
  e.preventDefault();
  put(text,'Pasted & formatted successfully.');
},true);

async function autoFormatField(){ return _autoFixField(); }
async function _ocrTo(fid, file, imgIdx){
  if(!file) return;
  if(file.size>15*1024*1024){ toast('Image too large (max 15MB)',true); return; }
  const ta=document.getElementById(fid); if(!ta) return;
  const b64=await _examReadImg(file);
  toast('Reading the screenshot with AI\u2026'); ta.classList.add('ai-busy');
  try{
    const r=await Promise.race([
      api('/api/teacher/ocr-question-ai','POST',{image_b64:b64, mime_type:(file.type||'image/jpeg')}),
      new Promise((_,rj)=>setTimeout(()=>rj(new Error('timeout')),45000))
    ]);
    if(r&&r.text&&String(r.text).trim()){
      const cur=(ta.value||'').trim();
      ta.value = cur ? (cur+'\n'+String(r.text).trim()) : String(r.text).trim();
      ta.dispatchEvent(new Event('input',{bubbles:true}));
      toast('Read from the screenshot \u2014 review the preview below.');
    } else throw new Error('empty');
  }catch(e){
    if(imgIdx!=null){ _setExamImg(imgIdx,b64); toast('Could not read as text \u2014 attached as an image instead. Check GEMINI_API_KEY or try a clearer crop.',true); }
    else toast('Could not read as text. Check GEMINI_API_KEY or try a clearer/tighter crop.',true);
  }finally{ ta.classList.remove('ai-busy'); }
}
async function ocrFillQuestion(inp,i){ const f=inp.files[0]; inp.value=''; await _ocrTo('exq-'+i, f, i); }
async function ocrFillAnswer(inp,i){ const f=inp.files[0]; inp.value=''; await _ocrTo('exa-'+i, f, null); }
// ---- import progress bar helpers ----
let _exProgTimer=null;
function _exProgShow(){ const p=document.getElementById('ex-prog'); if(!p) return; p.classList.add('on'); p.classList.remove('ai'); _exProgSet('Uploading\u2026',0); }
function _exProgSet(label,pct){ const l=document.getElementById('ex-prog-label'),c=document.getElementById('ex-prog-pct'),f=document.getElementById('ex-prog-fill'); if(l)l.textContent=label; if(c)c.textContent=Math.round(pct)+'%'; if(f)f.style.width=Math.min(100,pct)+'%'; }
function _exProgAI(){ // upload done -> AI structuring phase: percent creeps up while the server works
  const p=document.getElementById('ex-prog'); if(p)p.classList.add('ai');
  let pct=0; _exProgSet('Reading the questions\u2026',0);
  clearInterval(_exProgTimer);
  _exProgTimer=setInterval(()=>{ pct+=Math.max(.2,(95-pct)*.06); if(pct>=95)pct=95; _exProgSet('Reading the questions\u2026',pct); },400);
}
function _exProgDone(){ clearInterval(_exProgTimer); _exProgTimer=null; _exProgSet('Done',100); setTimeout(()=>{ const p=document.getElementById('ex-prog'); if(p){p.classList.remove('on');p.classList.remove('ai');} },900); }
function _exProgHide(){ clearInterval(_exProgTimer); _exProgTimer=null; const p=document.getElementById('ex-prog'); if(p){p.classList.remove('on');p.classList.remove('ai');} }
function _uploadWithProgress(url,fd){ // fetch cannot report upload progress - use XHR
  return new Promise((resolve,reject)=>{
    const x=new XMLHttpRequest();
    x.open('POST',url);
    x.setRequestHeader('Authorization','Bearer '+TOKEN);
    x.upload.onprogress=e=>{ if(e.lengthComputable) _exProgSet('Uploading\u2026 '+_fmtBytes(e.loaded)+' / '+_fmtBytes(e.total), e.loaded/e.total*100); };
    x.upload.onload=()=>_exProgAI();
    x.onload=()=>{ let d=null; try{ d=JSON.parse(x.responseText); }catch{} resolve({ok:x.status>=200&&x.status<300,status:x.status,data:d}); };
    x.onerror=()=>reject(new Error('Network error during upload'));
    x.timeout=300000; x.ontimeout=()=>reject(new Error('Upload timed out'));
    x.send(fd);
  });
}
function _fmtBytes(b){ if(b>1048576)return (b/1048576).toFixed(1)+' MB'; if(b>1024)return Math.round(b/1024)+' KB'; return b+' B'; }
function _applyImportedQs(list){
  _examQs=list.map(q=>{
    const qhi=(q.question_hi&&String(q.question_hi).trim())||'';
    if(_examType==='mcq'){
      let opts=(q.options||[]).slice(0,4); while(opts.length<4)opts.push('');
      let ohi=(q.options_hi||[]).map(o=>o?String(o):'').slice(0,4); while(ohi.length<4)ohi.push('');
      let ci=opts.findIndex(o=>o&&q.correct_option&&o.trim()===String(q.correct_option).trim());
      return {q:q.question||'',q_hi:qhi,opts:opts,opts_hi:ohi,correct:ci>=0?ci:0,marks:q.max_marks||1,expl:(q.explanation||''),expl_hi:(q.explanation_hi||''),image_b64:null,_tab:'en'};
    }
    const mhi=(q.model_answer_hi&&String(q.model_answer_hi).trim())||'';
    return {q:q.question||'',q_hi:qhi,model:q.model_answer||'',model_hi:mhi,marks:q.max_marks||5,image_b64:null,model_answer_image:null,_tab:'en'};
  });
  renderExamQs();
}
async function _importExamFile(f,endpoint,srcName){
  _exProgShow();
  try{
    const fd=new FormData(); fd.append('file',f); fd.append('test_type',_examType);
    const r=await _uploadWithProgress(API+endpoint,fd);
    if(!r.ok){ _exProgHide(); throw new Error((r.data&&r.data.detail)?r.data.detail:('Error '+r.status)); }
    const d=r.data;
    if(d&&d.questions&&d.questions.length){
      _exProgDone();
      _applyImportedQs(d.questions);
      toast('Imported '+d.questions.length+' questions from '+srcName+'. Review and edit.');
      if(d.note) setTimeout(()=>toast(d.note),1800);
    } else { _exProgHide(); toast('No questions found in the '+srcName+'.',true); }
  }catch(e){ _exProgHide(); toast(e.message,true); }
}
async function importExamDocx(inp){
  const f=inp.files[0]; inp.value=''; if(!f) return;
  await _importExamFile(f,'/api/teacher/parse-exam-docx','Word file');
}
async function importExamPdf(inp){
  const f=inp.files[0]; inp.value=''; if(!f) return;
  await _importExamFile(f,'/api/teacher/parse-exam-pdf','PDF');
}
function downloadStudentAnswer(attId,name){
  try{ api('/api/teacher/attempt/'+attId+'/marking','POST',{}).catch(()=>{}); }catch(e){}
  toast('Fetching the answer sheet\u2026');
  fetch(API+'/api/teacher/attempt/'+attId+'/answer',{headers:{Authorization:'Bearer '+TOKEN}}).then(async r=>{
    if(!r.ok){ toast('No answer sheet available for this student.',true); return; }
    const ct=(r.headers.get('content-type')||'').toLowerCase();
    const b=await r.blob();
    if(!b||!b.size){ toast('The answer sheet file is empty. Ask the student to upload it again.',true); return; }
    // ASAL type se sahi extension — PDF ho to .pdf (warna .jpg naam se PDF corrupt lagta tha)
    const ext=ct.indexOf('pdf')>=0?'pdf':(ct.indexOf('png')>=0?'png':(ct.indexOf('webp')>=0?'webp':'jpg'));
    const u=URL.createObjectURL(b);
    const a=document.createElement('a'); a.href=u; a.download='answer-'+(name||'student')+'.'+ext;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(()=>URL.revokeObjectURL(u),4000);
    toast('Answer sheet downloaded.');
  }).catch(e=>{
    toast('Could not download right now. Opening in a new tab instead.',true);
    try{ window.open(API+'/api/teacher/attempt/'+attId+'/answer?t='+encodeURIComponent(TOKEN),'_blank','noopener'); }catch(e2){}
  });
}
async function submitExam(){
  // ---- DPP mode: editor se DPP banao (answers already mandatory) ----
  if(window._dppMode){
    const title=val('ex-title'); if(!title){ toast('Enter a DPP title',true); return; }
    if(!_examQs.length){ toast('Add at least one question',true); return; }
    for(let i=0;i<_examQs.length;i++){ const q=_examQs[i];
      if(!(q.q||'').trim()&&!q.image_b64){ toast('Question '+(i+1)+': please fill the question',true); return; }
      if(!(q.model||'').trim()&&!q.model_answer_image){ toast('Question '+(i+1)+': model answer MANDATORY hai — answer bharo',true); return; } }
    const _em=window._dppEditMeta||{};
    const payload={ subject:(val('ex-sub')||_em.subject||''), class_name:((val('ex-cls-sel')||_em.class_name)||''),
      chapter:((val('ex-ch-sel')!==undefined&&val('ex-ch-sel')!=='')?val('ex-ch-sel'):(val('ex-ch')||_em.chapter||'')), part:((val('ex-part-sel')||_em.part)||''),
      title, medium:_examMedium||_em.medium||'English', client_key:(window._dppCk||''),
      questions:_examQs.map(q=>({ q:q.q||'', q_hi:q.q_hi||'', model:q.model||'', model_hi:q.model_hi||'',
        image:q.image_b64||null, alt_image:q.alt_image_b64||null, model_image:q.model_answer_image||null })) };
    const _dppEid=window._dppEditId;
    // Network error pe EK baar auto-retry (backend cold-start) — duplicate nahi banega
    // (client_key + server-side 90s dedupe). Edit PATCH idempotent hai. Form data modal me safe.
    let res=null, err=null;
    const _dppApi=()=> _dppEid
      ? api('/api/teacher/dpp-packs/'+_dppEid,'PATCH',payload)
      : api('/api/teacher/dpp-packs/create','POST',payload);
    try{ res=await _dppApi(); }
    catch(e1){
      err=e1;
      toast('Cannot reach the server — retrying in 4 seconds...',true);
      await new Promise(r=>setTimeout(r,4000));
      try{ res=await _dppApi(); err=null; }catch(e2){ err=e2; }
    }
    if(err||!res){ toast((err&&err.message)||(_dppEid?'Update failed':'Create failed'),true); return; }
    _clearQDraft(); _examQs=[];   // safal submit -> draft clear (closeModal ka save skip)
    window._dppMode=false; window._dppEditId=null; window._dppEditMeta=null; closeModal();
    toast(_dppEid?'DPP updated — the PDFs will rebuild on the next view or download.'
      :(res.duplicate?'DPP pehle hi ban gaya tha — card me dikhega.':'DPP created — ab card pe "Download PDF" ya "View" dabao. PDF click pe hi banti hai, timeout nahi hoga.'));
    await loadTDpp(); return;
  }
  const title=val('ex-title'); if(!title){ toast('Enter a test title',true); return; }
  if(!_examQs.length){ toast('Add at least one question',true); return; }
  const biling=(_examMedium==='Bilingual');
  for(let i=0;i<_examQs.length;i++){ const q=_examQs[i];
    if(!(q.q||'').trim()){ toast('Question '+(i+1)+': please fill the English question'+(biling?' (Hindi can stay blank \u2014 it auto-translates)':''),true); return; }
    if(_examType==='mcq'){ if(q.opts.some(o=>!(o||'').trim())){ toast('Question '+(i+1)+': fill all 4 English options',true); return; } }
    else { if(!(q.model||'').trim()){ toast('Question '+(i+1)+': add the English model answer',true); return; } } }
  const hiFilled=(arr)=>arr.some(o=>(o||'').trim());
  const questions=_examQs.map(q=>{
    if(_examType==='mcq'){
      const oh=(q.opts_hi||[]).map(o=>(o||'').trim());
      return {question_text:q.q,max_marks:parseInt(q.marks)||1,options:q.opts,correct_option:q.opts[q.correct],image_b64:q.image_b64||null,alt_image_b64:q.alt_image_b64||null,
              question_text_hi:biling?((q.q_hi||'').trim()||null):null,
              options_hi:(biling&&hiFilled(oh)&&oh.length===q.opts.length)?oh:null,
              explanation:(q.expl||'').trim()||null,
              explanation_hi:biling?((q.expl_hi||'').trim()||null):null};
    }
    return {question_text:q.q,max_marks:parseInt(q.marks)||1,model_answer:q.model,image_b64:q.image_b64||null,alt_image_b64:q.alt_image_b64||null,model_answer_image:q.model_answer_image||null,
            question_text_hi:biling?((q.q_hi||'').trim()||null):null,
            model_answer_hi:biling?((q.model_hi||'').trim()||null):null};
  });
  const _sched=(val('ex-sched')||'').trim(); const _chRaw=(val('ex-ch')||'').trim();
  const body={subject:val('ex-sub'),class_name:(val('ex-cls-test')||''),title:title,chapter:(_sched?(_chRaw+' \u27E6S:'+_sched+'\u27E7'):_chRaw),test_type:_examType,medium:_examMedium,duration_min:(parseInt(val('ex-dur'))||0),scheduled_at:_sched||null,questions:questions};
  try{
    const _editId=window._editExamId;
    if(_editId){ await api('/api/teacher/exam/'+_editId,'PATCH',body); }
    else{ await api('/api/teacher/exam','POST',body); }
    window._editExamId=null;
    _clearQDraft(); _examQs=[];   // safal submit -> draft clear (closeModal ka save skip)
    closeModal();
    toast(_editId?'Test updated successfully!':(biling?'Test created! Any blank Hindi fields are being auto-filled now.':'Test created successfully!'));
    loadTTests();
  }
  catch(e){
    if(window._editExamId&&/not found|404/i.test(e.message||'')){ window._pendingEdit={id:window._editExamId,body:body}; examPatchFailModal(); }
    else toast((window._editExamId?'Update failed: ':'')+e.message,true);
  }
}
async function viewExamAttempts(id){
  try{
    const d=await api('/api/teacher/exam/'+id+'/attempts');
    window._examAttData=d;
    const rows=d.attempts.length?d.attempts.map(a=>{
      const info=(a.status==='graded'?('Score: '+a.total_awarded+'/'+d.exam.total_marks+(a.verdict?' \u00b7 '+esc(a.verdict):'')):a.status==='marking'?'Marking in progress':a.status==='grading'?'Pending evaluation':'Awaiting submission')+(a.attempted_count!=null?' \u00b7 Answered '+a.attempted_count+'/'+(d.questions||[]).length:'');
      const btns=`<button class="btn btn-primary btn-sm" onclick="gradeManual(${a.attempt_id},${id})">${a.status==='graded'?'Edit Marks':'Grade Manually'}</button>`;
      const dl=a.has_answer?`<button class="btn btn-ghost btn-sm ansdl-btn" onclick="downloadStudentAnswer(${a.attempt_id},'${esc((a.student_name||'student').replace(/[^A-Za-z0-9]/g,'-'))}')">${ic('download')} Sheet</button>`:'';
      // naam pe click -> student ki poori detail usi row me khul jati hai
      const det=[
        ['Student ID', a.student_code],
        ['Phone', a.phone],
        ['Batch', a.batch],
        ['Class', a.class_level?('Class '+a.class_level):null],
        ['Medium', a.medium],
        ['Email', a.email],
        ['Subjects', (a.subjects||[]).join(', ')]
      ].filter(x=>x[1]).map(x=>`<div class="sd-item"><span>${x[0]}</span><b>${esc(String(x[1]))}</b></div>`).join('');
      const phone=(a.phone||'').replace(/[^0-9]/g,'');
      const acts=phone?`<div class="sd-acts"><a class="btn btn-ghost btn-sm" href="tel:${esc(phone)}">Call</a><a class="btn btn-ghost btn-sm" href="https://wa.me/${phone.length===10?('91'+phone):esc(phone)}" target="_blank" rel="noopener">WhatsApp</a></div>`:'';
      return `<div class="today-row tr-stu"><div style="min-width:0;flex:1">
          <div class="tr-sub sd-toggle" title="Click to see the full student details" onclick="_toggleStuDet(${a.attempt_id})">${esc(a.student_name||('Student #'+a.student_id))}<span class="sd-chev" id="sdc-${a.attempt_id}">\u203a</span></div>
          <div class="tr-topic">${info}</div>
          <div class="sd-box" id="sd-${a.attempt_id}" style="display:none">${det?`<div class="sd-grid">${det}</div>${acts}`:'<div class="sd-empty">No extra details are saved for this student yet.</div>'}</div>
        </div><div class="tmeta"><span class="tstatus ${a.status==='graded'?'done':''}">${a.status==='grading'?'pending evaluation':esc(a.status)}</span>${dl}${btns}</div></div>`;
    }).join(''):'<div class="empty-state"><p>No submissions yet.</p></div>';
    const resetBar=d.attempts.length?`<div style="display:flex;justify-content:flex-end;margin-bottom:10px"><button class="btn btn-danger btn-sm" onclick="examResetAttempts(${id})">${ic('refresh')} Allow Re-take (clear attempts)</button></div>`:'';
    showModal('Results \u2014 '+esc(d.exam.title), resetBar+rows);
  }catch(e){ toast(e.message,true); }
}
async function examResetAttempts(id){
  if(!confirm('Is test ke SAARE attempts clear kar dein?\n\nJin students ke marks purane bug ki wajah se 0 aaye the, wo dobara test de sakenge. Ye action undo nahi hoga (purane submissions hat jayenge).')) return;
  try{
    const r=await api('/api/teacher/exam/'+id+'/reset-attempts','POST',{});
    toast((r.removed||0)+' attempt(s) cleared. Students ab dobara de sakte hain.');
    viewExamAttempts(id);
  }catch(e){ toast(e.message||'Could not reset',true); }
}
function _toggleStuDet(id){
  const b=document.getElementById('sd-'+id); if(!b) return;
  const open=b.style.display==='none';
  b.style.display=open?'block':'none';
  const c=document.getElementById('sdc-'+id); if(c) c.classList.toggle('on',open);
}
async function loadAnsImg(attId,imgId){
  const wrap=document.getElementById(imgId+'-wrap');
  const el=document.getElementById(imgId);
  try{
    // serve ab ASAL type se bhejta hai (PDF/JPEG/PNG) — content-type dekh ke sahi dikhao
    const r=await fetch(API+'/api/teacher/attempt/'+attId+'/answer',{headers:{Authorization:'Bearer '+TOKEN}});
    if(!r.ok){ if(wrap) wrap.innerHTML='<div class="gm-noimg">No answer sheet uploaded (this may be an MCQ test).</div>'; return; }
    const ct=(r.headers.get('content-type')||'').toLowerCase();
    const b=await r.blob(); const u=URL.createObjectURL(b);
    if(ct.indexOf('pdf')>=0){
      if(wrap) wrap.innerHTML='<iframe class="gm-pdf" src="'+u+'" style="width:100%;height:70vh;border:1px solid var(--border);border-radius:10px"></iframe>'
        +'<div style="margin-top:8px"><a class="btn btn-ghost btn-sm" href="'+u+'" target="_blank" rel="noopener">Open the answer sheet in a new tab</a></div>';
      return;
    }
    if(el){ el.src=u; el.style.display='block'; }
  }catch(e){
    if(wrap) wrap.innerHTML='<div class="gm-noimg">The answer sheet could not be loaded. Please try again.</div>';
  }
}
function gradeManual(attId,examId){
  const d=window._examAttData; if(!d){ toast('Please reopen Results and try again.',true); return; }
  try{ api('/api/teacher/attempt/'+attId+'/marking','POST',{}).catch(()=>{}); }catch(e){}
  const att=(d.attempts||[]).find(a=>a.attempt_id===attId)||{};
  const qs=d.questions||[];
  const isSubj=(d.exam.test_type||'')!=='mcq';
  const ansBlock=isSubj?`<div class="gm-ans" id="gm-ans-img-wrap"><div class="gm-ans-lbl">Student's handwritten answer sheet</div><img id="gm-ans-img" class="gm-ans-img" style="display:none"></div>`:'';
  // pehle diye hue marks/remark wapas bhar do - warna edit karte waqt sab 0 dikhta tha
  const saved={}; (att.results||[]).forEach(r=>{ saved[r.q_no]=r; });
  const rows=qs.map(q=>{
    const sv=saved[q.q_no]||{};
    const mv=(sv.marks==null||sv.marks==='')?'':String(sv.marks);
    return `<div class="gm-q"><div class="gm-qtext"><b>Q${q.q_no}.</b> ${_fmtRich(q.question_text)}</div><div class="gm-qin"><input type="number" id="gm-m-${q.q_no}" class="form-control" value="${esc(mv)}" placeholder="0" min="0" max="${q.max_marks}" step="0.5" style="width:84px"><span class="gm-max">/ ${q.max_marks}</span><input id="gm-r-${q.q_no}" class="form-control" value="${esc(sv.remark||'')}" placeholder="Remark for this question (optional)"></div></div>`;
  }).join('');
  const hasSaved=(att.results||[]).length>0;
  // Agar attempt graded hai lekin per-question marks nahi aaye, matlab backend
  // (teacher_routes.py) purana hai - warna teacher chup-chaap 0 save kar dega
  const staleBackend=!hasSaved && att.status==='graded' && (att.total_awarded||0)>0;
  const savedNote=hasSaved
    ? `<div class="alert alert-info">Marks you saved earlier are already filled in below. Change only what you need, then save again.</div>`
    : (staleBackend
      ? `<div class="alert alert-danger">This student already has <b>${esc(String(att.total_awarded))}/${esc(String(d.exam.total_marks||''))}</b> saved, but the server did not send the question-wise marks, so the boxes below are blank. Please deploy the latest <b>teacher_routes.py</b> on the server first, otherwise saving now will overwrite the existing marks with zeros.</div>`
      : '');
  const vd=att.verdict||'Good';
  const vOpt=v=>`<option${vd===v?' selected':''}>${v}</option>`;
  showModal((hasSaved?'Edit Marks \u2014 ':'Grade Manually \u2014 ')+esc(att.student_name||'Student'),
    `<button class="btn btn-ghost btn-sm" onclick="viewExamAttempts(${examId})" style="margin-bottom:12px">${ic('back')} Back to Results</button>`
    +savedNote+ansBlock+`<div class="gm-list">${rows}</div>`
    +`<div class="form-group" style="margin-top:14px"><label>Overall feedback (shown to student)</label><textarea id="gm-fb" class="form-control" rows="2" placeholder="e.g. Good attempt. Work on diagrams.">${esc(att.feedback||'')}</textarea></div>`
    +`<div class="form-group"><label>Verdict</label><select id="gm-verdict" class="form-control">${vOpt('Excellent')}${vOpt('Good')}${vOpt('Needs Improvement')}</select></div>`
    +`<div class="gm-total" id="gm-total"></div>`
    +`<button class="btn btn-primary" style="width:100%" onclick="submitManualGrade(${attId},${examId})">${hasSaved?'Update Marks':'Save Marks'} (visible to student)</button>`);
  _gmTotal();
  qs.forEach(q=>{ const el=document.getElementById('gm-m-'+q.q_no); if(el) el.addEventListener('input',_gmTotal); });
  if(isSubj) renderMath(document.getElementById('modal-body')), loadAnsImg(attId,'gm-ans-img');
}
function _gmTotal(){
  const d=window._examAttData; const qs=(d&&d.questions)||[];
  let got=0,max=0;
  qs.forEach(q=>{ const v=parseFloat(val('gm-m-'+q.q_no)); if(!isNaN(v)) got+=v; max+=(+q.max_marks||0); });
  const el=document.getElementById('gm-total');
  if(el) el.innerHTML='Total so far: <b>'+(Math.round(got*100)/100)+' / '+max+'</b>';
}
async function submitManualGrade(attId,examId){
  const d=window._examAttData; const qs=(d&&d.questions)||[];
  const results=qs.map(q=>({q_no:q.q_no,marks:parseFloat(val('gm-m-'+q.q_no))||0,remark:val('gm-r-'+q.q_no)}));
  try{ await api('/api/teacher/attempt/'+attId+'/grade-manual','POST',{results:results,feedback:val('gm-fb'),verdict:val('gm-verdict')}); toast('Marks saved. Student can see them now.'); viewExamAttempts(examId); }
  catch(e){ toast(e.message,true); }
}
async function gradeAttemptNow(attId,examId){
  const body=document.getElementById('modal-body');
  if(body){ body.innerHTML=`<div class="grade-prog"><div class="grade-prog-spin"></div><div class="grade-prog-title">Checking with AI\u2026</div><div class="grade-prog-sub">Reading the handwritten answers and grading each question.</div><div class="gp-bar"><div class="gp-fill" id="gp-fill" style="width:0%"></div></div><div class="gp-pct" id="gp-pct">0%</div></div>`; }
  let pct=0;
  const timer=setInterval(()=>{ pct+=Math.max(0.6,(93-pct)*0.07); if(pct>93)pct=93; const f=document.getElementById('gp-fill'),p=document.getElementById('gp-pct'); if(f)f.style.width=pct.toFixed(0)+'%'; if(p)p.textContent=pct.toFixed(0)+'%'; },350);
  try{
    await api('/api/teacher/attempt/'+attId+'/grade','POST',{});
    clearInterval(timer);
    const f=document.getElementById('gp-fill'),p=document.getElementById('gp-pct'); if(f)f.style.width='100%'; if(p)p.textContent='100%';
    toast('Graded! Marks are now visible to the student.');
    setTimeout(()=>viewExamAttempts(examId),550);
  }catch(e){ clearInterval(timer); toast(e.message,true); viewExamAttempts(examId); }
}

function monthName(ym){ const m=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']; const mo=parseInt(ym.slice(5))-1; return (m[mo]||ym.slice(5))+" '"+ym.slice(2,4); }
