/* dashboard countdown banner */
async function loadVTBanner(){
  const el=document.getElementById('t-vt-banner'); if(!el) return;
  try{
    const d=await api('/api/teacher/video-tasks/my');
    // v115: My Tasks ka sidebar badge bhi dashboard pe hi refresh ho
    const _actN=(d.tasks||[]).filter(t=>t.status==='assigned').length;
    const _tb=document.getElementById('t-vt-badge'); if(_tb){ _tb.style.display=_actN?'inline-block':'none'; _tb.textContent=_actN; }
    const nxt=d.next_deadline;
    if(!nxt){ el.style.display='none'; el.innerHTML=''; return; }
    el.style.display='block';
    el.innerHTML=`<div class="vt-banner" onclick="tPage('vtasks',null)" style="cursor:pointer">
      <div style="width:40px;height:40px;border-radius:11px;background:rgba(184,148,31,.15);color:#8a6d10;display:flex;align-items:center;justify-content:center;flex-shrink:0">${ic('clipboard')}</div>
      <div style="flex:1;min-width:160px"><div style="font-weight:800;font-size:.86rem">${esc(nxt.title)}</div>
        <div style="font-size:.7rem;color:var(--text-muted)">${nxt.channel?esc(nxt.channel)+' · ':''}Due ${esc(nxt.deadline_nice)} — tap to open My Tasks</div></div>
      <div class="vt-count" id="tvt-banner-cd" data-secs="${nxt.seconds_left||0}"></div></div>`;
    const cd=document.getElementById('tvt-banner-cd');
    const paint=()=>{ let s=+cd.dataset.secs; s=Math.max(0,s-1); cd.dataset.secs=s;
      const m=Math.floor(s%3600/60),ss=s%60;
      const cls=s<=0?'over':(s<86400?'urgent':'');
      const cells=s>=86400?[[''+Math.floor(s/86400),'days'],[''+String(Math.floor(s%86400/3600)).padStart(2,'0'),'hrs'],[''+String(m).padStart(2,'0'),'min'],[''+String(ss).padStart(2,'0'),'sec']]
        :[[''+String(Math.floor(s/3600)).padStart(2,'0'),'hrs'],[''+String(m).padStart(2,'0'),'min'],[''+String(ss).padStart(2,'0'),'sec']];
      cd.innerHTML=cells.map(x=>`<div class="vt-cd ${cls}"><b>${x[0]}</b><small>${x[1]}</small></div>`).join(''); };
    paint(); if(window._tvtBannerInt) clearInterval(window._tvtBannerInt);
    window._tvtBannerInt=setInterval(()=>{ if(!document.getElementById('tvt-banner-cd')){ clearInterval(window._tvtBannerInt); return; } paint(); },1000);
  }catch(e){ el.style.display='none'; }
}

/* ================= VIDEO TASK MANAGER (admin) ================= */
let _vtTeachers=[], _vtChannels=[], _vtTypes=[], _vtF={teacher_id:0,status:'',channel_id:0,video_type:'',collab:'',q:''}, _vtTimer=null;
// v134: video type ko streaming (live/recorded/both) ke hisaab se filter karo
function _vtScopeOk(t,stream){ const sc=(t&&t.streaming_scope)||'both'; return !stream||sc==='both'||sc===stream; }
function _vtTypeOptsHtml(types,streamVal,selectedName,placeholder){
  return `<option value="">${placeholder||'— Select type —'}</option>`+
    (types||[]).filter(t=>_vtScopeOk(t,streamVal)).map(c=>`<option value="${esc(c.name)}" ${selectedName===c.name?'selected':''}>${esc(c.name)}</option>`).join('');
}
function _vtFilterTypes(streamSelId,typeSelId,types){
  const s=(document.getElementById(streamSelId)||{}).value||'';
  const ts=document.getElementById(typeSelId); if(!ts) return;
  ts.innerHTML=_vtTypeOptsHtml(types,s,ts.value);
}
const VT_LBL={assigned:'Assigned',submitted:'Submitted',approved:'Approved',editing_soon:'Editing Soon',editing_done:'Editing Done',uploaded:'Uploaded',reshoot:'Reshoot',rejected:'Rejected',not_completed:'Not Completed',proposal:'Pending Approval'};
function _vtQs(){ const f=_vtF,q=[]; if(f.teacher_id)q.push('teacher_id='+f.teacher_id); if(f.status)q.push('status='+f.status); if(f.channel_id)q.push('channel_id='+f.channel_id); if(f.video_type)q.push('video_type='+encodeURIComponent(f.video_type)); return q.length?'?'+q.join('&'):''; }
function _vtPill(t,blink,who){
  let cls=t.status, lbl=VT_LBL[t.status]||t.status;
  // Legacy `status` 'editing_soon' me editor-assigned AUR editing-in-progress dono aate hain.
  // lifecycle zyada accurate hai — usse sahi label dikhao (warna editing shuru hone par bhi
  // "Editing Soon" dikhta tha).
  var _lc=t.lifecycle||'';
  if(_lc==='editing') lbl='Editing In Progress';
  else if(_lc==='editing_paused') lbl='Editing Paused';
  else if(_lc==='editor_assigned') lbl='Editing Soon';
  else if(_lc==='qc_pending') lbl='Editor Submitted';
  else if(_lc==='qc_changes') lbl='Changes Required';
  else if(_lc==='ready_for_youtube') lbl='Ready for YouTube';
  if((t.status==='assigned'||t.status==='reshoot'||t.status==='rejected')&&t.overdue){ cls='delayed'; lbl='Overdue'; }
  // teacher side: upload hone tak status blink karta rahe
  const bl=(blink&&t.status!=='uploaded'&&t.proposal_ok!=='pending')?' blink':'';
  let extra='';
  if(t.status==='submitted'&&t.on_time!=null&&t.kind!=='urgent') extra=` <span class="vt-pill ${t.on_time?'ontime':'delayed'}${bl}">${t.on_time?'On Time':'Delayed'}</span>`;
  const oc=who?` onclick="vtStatusOpen(${t.id},'${who}',event)" title="Tap for full status history"`:''; 
  return `<span class="vt-pill ${cls}${bl}${who?' lnk':''}"${oc}>${lbl}</span>${extra}`;
}
function vtThumbPreview(input){
  const file=input&&input.files&&input.files[0];
  if(file) _vtThumbFile(file);
}
function _vtDropOver(e,el){ e.preventDefault(); e.stopPropagation(); if(el) el.classList.add('drag'); }
function _vtDropLeave(e,el){ e.preventDefault(); e.stopPropagation(); if(el) el.classList.remove('drag'); }
function _vtDropFile(e,el){
  e.preventDefault(); e.stopPropagation(); if(el) el.classList.remove('drag');
  const f=e.dataTransfer&&e.dataTransfer.files&&e.dataTransfer.files[0];
  if(f) _vtThumbFile(f);
}
function _vtThumbFile(file){
  // v137: ye core ab file seedhe leta hai — click-browse aur drag-drop dono isi ko call karte hain.
  if(!file) return;
  const nameEl=document.getElementById('vt-thumb-name');
  const prev=document.getElementById('vt-thumb-prev');
  const setName=(t)=>{ if(nameEl) nameEl.textContent=t; };
  const setPrev=(src)=>{ if(prev) prev.innerHTML=`<img src="${src}" style="max-height:90px;border-radius:10px;border:1px solid var(--border)">`; };
  const fail=(msg)=>{ window._vtThumbB64=null; setName(msg||'Could not read this image'); };
  setName(file.name||'thumbnail');
  if(!/^image\//i.test(file.type||'')&&!/\.(jpe?g|png|webp|gif|bmp|heic|heif|avif)$/i.test(file.name||'')){
    fail('Please choose an image file'); return;
  }
  const reader=new FileReader();
  reader.onerror=()=>fail('Could not read the file');
  reader.onload=()=>{
    const dataUrl=reader.result;
    const img=new Image();
    img.onload=()=>{
      try{
        const MAXW=1280, sc=Math.min(1, MAXW/((img.naturalWidth||img.width)||MAXW));
        const w=Math.max(1,Math.round(((img.naturalWidth||img.width))*sc));
        const h=Math.max(1,Math.round(((img.naturalHeight||img.height))*sc));
        const cv=document.createElement('canvas'); cv.width=w; cv.height=h;
        const ctx=cv.getContext('2d'); ctx.fillStyle='#fff'; ctx.fillRect(0,0,w,h); ctx.drawImage(img,0,0,w,h);
        let out=cv.toDataURL('image/jpeg',0.82);
        if(out.length>1400000) out=cv.toDataURL('image/jpeg',0.6);
        if(out.length>1400000) out=cv.toDataURL('image/jpeg',0.42);
        window._vtThumbB64=out; setPrev(out); setName((file.name||'thumbnail')+' \u2713');
      }catch(e){
        if(String(dataUrl).length<1800000){ window._vtThumbB64=dataUrl; setPrev(dataUrl); setName((file.name||'thumbnail')+' \u2713'); }
        else fail('Image too large — please use a smaller one');
      }
    };
    img.onerror=()=>{
      if(String(dataUrl).length<1800000){ window._vtThumbB64=dataUrl; setPrev(dataUrl); setName((file.name||'thumbnail')+' \u2713 (original)'); }
      else fail('This format could not be previewed — try a JPG or PNG');
    };
    img.src=dataUrl;
  };
  reader.readAsDataURL(file);
}
function _vtThumb(t,who){
  const gth=(t.thumbnail && t.thumbnail.approved && t.thumbnail.url)?t.thumbnail.url:'';
  const has=!!(t.thumbnail_b64||t.thumbnail_link||gth);
  const _is='width:100%;height:100%;object-fit:cover;display:block';
  const img=t.thumbnail_b64?`<img src="${t.thumbnail_b64}" alt="" style="${_is}">`
    :(t.thumbnail_link?`<img src="${esc(t.thumbnail_link)}" onerror="this.remove()" alt="" style="${_is}">`
    :(gth?`<img src="${esc(gth)}" onerror="this.remove()" alt="" style="${_is}">`:''));
  const blink=who==='t';
  return `<div class="vt-thumb${has?' click':''}" style="aspect-ratio:16/9;height:auto;overflow:hidden;position:relative"${has?` onclick="vtThumbOpen(${t.id},'${who||'t'}')" title="Open full screen — download available"`:''}>${img||esc((t.title||'V').slice(0,1).toUpperCase())}<div class="vt-status">${_vtPill(t,blink,who)}</div>${has?`<span class="vt-dl">${ic('download')} View</span>`:''}</div>`;
}
function _vtTypeBadge(t){ return t.video_type?`<span class="vt-type">${ic('play')} ${esc(t.video_type)}</span>`:''; }
function vtThumbOpen(id,who){
  const t=(((who==='a')?window._avtMap:window._tvtMap)||{})[id]; if(!t) return;
  const name=((t.title||'thumbnail').replace(/[^\w\- ]+/g,'').trim().slice(0,60)||'thumbnail');
  if(t.thumbnail_b64){ openImageViewerSrc(t.thumbnail_b64,name+'.jpg'); return; }
  const link=t.thumbnail_link||((t.thumbnail&&t.thumbnail.approved&&t.thumbnail.url)?t.thumbnail.url:'')||'';
  if(/\.(png|jpe?g|webp|gif|bmp)(\?|#|$)/i.test(link)) openImageViewerSrc(link,name+'.jpg');
  else if(link) window.open(link,'_blank');
  else toast('No thumbnail attached to this task');
}
function vtStatusOpen(id,who,ev){
  if(ev){ ev.stopPropagation(); ev.preventDefault(); }
  const t=(((who==='a')?window._avtMap:window._tvtMap)||{})[id]; if(!t) return;
  let hist=(t.history||[]).slice();
  if(!hist.length){ // purane task — client-side synthesis
    if(t.created_at) hist.push({s:'assigned',at:t.created_at,note:'Task assigned'});
    if(t.submitted_at) hist.push({s:'submitted',at:t.submitted_at,note:'Video link submitted — '+(t.on_time?'on time':'delayed')});
    if(t.reviewed&&!['assigned','submitted'].includes(t.status)) hist.push({s:t.status,at:'',note:t.review_remarks||''});
  }
  const lbl=s=>(VT_LBL[s]||(s==='progress'?'Progress':s==='edited'?'Updated':s));
  const dotCls=s=>['submitted','approved','editing_done','uploaded'].includes(s)?'done':(['rejected'].includes(s)?'bad':'');
  const rows=hist.map(h=>`<div class="vt-tl-i ${dotCls(h.s)}"><div class="vt-tl-s">${esc(lbl(h.s))}</div>
    <div class="vt-tl-a">${esc(h.at||'')}</div>${h.note?`<div class="vt-tl-n">${esc(h.note)}</div>`:''}</div>`).join('');
  showModal(`Status History — ${esc(t.title)}`,`
    <div style="margin-bottom:14px;display:flex;gap:8px;align-items:center;flex-wrap:wrap">${_vtPill(t,false)}<span style="font-size:.72rem;color:var(--text-muted);font-weight:700">current status</span></div>
    ${t.is_collab?`<div class="cb-box" style="margin:0 0 14px"><div class="cb-head">${ic('users')} COLLAB TASK ${t.collab_all_verified?'<span class="cb-pill ok">All verified</span>':'<span class="cb-pill bad">Verify pending</span>'}</div><div class="cb-chips">${(t.collab_teachers||[]).map(c=>`<span class="cbnm ${c.verified?'ok':''}">${esc(c.name)}${c.verified?' — Approved':''}</span>`).join('')}</div><div style="margin-top:10px"><button class="btn btn-sm" onclick="aEditCollab(${t.id})">Edit Collaboration</button></div></div>`:''}
    <div class="vt-tl">${rows||'<div style="font-size:.8rem;color:var(--text-muted)">No history yet.</div>'}</div>`,
    `<button class="btn btn-primary" onclick="closeModal()">Close</button>`);
}
// ---- special tasks (One Shot / Rapid Revision / Projects) — teacher side ----
let _tvtView='', _tvtSpecSub='', _tvtSpecKind='', _tvtSpecCls='';
function tvtView(v){ _tvtView=(_tvtView===v?'':v); loadTVTasks(); }
function tvtSpecSubSet(s){ _tvtSpecSub=s||''; loadTVTasks(); }
function tvtSpecKindSet(k){ _tvtSpecKind=k||''; loadTVTasks(); }
function tvtSpecClsSet(c){ _tvtSpecCls=c||''; loadTVTasks(); }
function _vtOsUnit(t){ return t.kind==='project'?'videos':'chapters'; }
function _vtOsWeek(t){
  const w=[];
  if(t.weekly_quota) w.push(`Weekly: ${t.weekly_quota} videos`);
  if(t.weekly_day) w.push(`due every ${VTP_DLBL[t.weekly_day]||t.weekly_day}`);
  return w.length?`<span class="vt-os-week">${ic('clock')} ${w.join(' · ')}</span>`:'';
}
function _vtOsProg(t){
  return `<div class="vt-os-prog"><span class="n os-txt">${t.done} / ${t.total} ${_vtOsUnit(t)} done</span>
    <span class="vt-os-bar"><i style="width:${t.pct}%"></i></span><span class="n">${t.pct}%</span>
    <span class="vt-os-chev">${ic('chev-down')}</span></div>`;
}
function _vtKindLbl(t){ return {one_shot:'ONE SHOT',rapid_revision:'RAPID REVISION',project:'PROJECT'}[t.kind]||'PROJECT'; }
// ---- chapter production status (To Edit -> Edited -> Uploaded) ----
const _CHST={editing_soon:['To Edit','#d97706'],editing_done:['Edited','#2563eb'],uploaded:['Uploaded','#16a34a']};
/* v78: per-kind alag-alag colour system hata diya — saare special cards
   (One Shot / Rapid Revision / Projects) ek hi royal gold identity me.
   Pure CSS default = koi JS colour engine nahi = bulletproof. */
function _vtChBadge(c){
  const st=_CHST[c.edit_status||'']; if(!st||!c.link) return '';
  return `<span class="vt-chst" style="color:${st[1]};border-color:${st[1]}66;background:${st[1]}14">${st[0]}</span>`;
}
function _avtChSel(t,c){
  if(!c.link) return '';
  const cur=c.edit_status||'editing_soon';
  const st=_CHST[cur]||_CHST.editing_soon;
  return `<select class="vt-chst-sel" data-cid="${c.id}" style="color:${st[1]};border-color:${st[1]}59;background-color:${st[1]}14" onclick="event.stopPropagation()" onchange="avtChStatus(${t.id},${c.id},this.value)">
    ${Object.keys(_CHST).map(k=>`<option value="${k}" ${cur===k?'selected':''}>${_CHST[k][0]}</option>`).join('')}</select>`;
}
async function avtChStatus(tid,cid,st){
  try{
    await api('/api/admin/video-tasks/chapter-status','POST',{chapter_id:cid,status:st});
    const t=(window._avtMap||{})[tid]; const c=t&&(t.chapters||[]).find(x=>x.id===cid);
    if(c) c.edit_status=st;
    const sel=document.querySelector(`#avt-os-${tid} .vt-chst-sel[data-cid="${cid}"]`);
    if(sel){ const s2=_CHST[st]; if(s2){ sel.style.color=s2[1]; sel.style.borderColor=s2[1]+'59'; sel.style.backgroundColor=s2[1]+'14'; } }
    toast('Production status updated — '+(_CHST[st]?_CHST[st][0]:st));
  }catch(e){ toast(e.message||'Could not update the status'); }
}
function _avtVinSel(t,c){
  if(!c.link) return '';
  const v=c.vintage||'';
  const cls=v==='new'?'vt-vin-new':(v==='old'?'vt-vin-old':'vt-vin-blink');
  return `<select class="vt-vin-sel ${cls}" data-cid="${c.id}" title="Is this a NEW video (made this month) or an OLD one? Only NEW counts toward the target." onclick="event.stopPropagation()" onchange="avtChVintage(${t.id},${c.id},this.value)">
    <option value="" ${v===''?'selected':''} disabled>New / Old?</option>
    <option value="new" ${v==='new'?'selected':''}>New video</option>
    <option value="old" ${v==='old'?'selected':''}>Old video</option></select>`;
}
async function avtChVintage(tid,cid,v){
  if(!v) return;
  try{
    await api('/api/admin/video-chapters/'+cid+'/vintage','POST',{vintage:v});
    const t=(window._avtMap||{})[tid]; const c=t&&(t.chapters||[]).find(x=>x.id===cid);
    if(c) c.vintage=v;
    const sel=document.querySelector(`#avt-os-${tid} .vt-vin-sel[data-cid="${cid}"]`);
    if(sel){ sel.classList.remove('vt-vin-blink','vt-vin-new','vt-vin-old'); sel.classList.add(v==='new'?'vt-vin-new':'vt-vin-old'); }
    toast(v==='new'?'Marked NEW — counts toward this month\'s target':'Marked OLD — not counted this month');
  }catch(e){ toast(e.message||'Could not update'); }
}
function _vtChRow(t,c){
  if(c.link) return `<div class="vt-chr done" id="vt-chr-${t.id}-${c.id}"><span class="dot"></span><span class="nm">${esc(c.title)}</span>
    <span class="dt">${esc(c.submitted_at||'')}</span>${_vtChBadge(c)}
    <a class="lk" href="${esc(c.link)}" target="_blank" rel="noopener">${ic('play')} Open video</a>
    <button class="btn btn-ghost btn-sm" style="padding:3px 9px;font-size:.66rem" onclick="tvtChEdit(${t.id},${c.id})">Change</button></div>`;
  return `<div class="vt-chr" id="vt-chr-${t.id}-${c.id}"><span class="dot"></span><span class="nm">${esc(c.title)}</span>
    <span class="inp"><input class="input" id="tvt-ch-${t.id}-${c.id}" placeholder="https://drive.google.com/...">
    <button class="btn btn-primary btn-sm" style="padding:5px 12px" onclick="tvtChapterSave(${t.id},${c.id})">${ic('send')} Save</button></span></div>`;
}
function _vtSpecialT(sp){
  if(!sp||!sp.length) return `<div class="ws-empty"><p><b>No projects match this filter</b></p><small>Choose All Subjects / All Types, or wait for projects to be assigned.</small></div>`;
  return sp.map(t=>{
    const subTxt=t.kind==='project'
      ?`<b>${t.total||''} videos</b> to deliver — paste each video's link as you complete it`
      :(t.kind==='rapid_revision'
        ?`Rapid revision video for every chapter — paste each chapter's link`
        :`One-shot video for every chapter — paste each chapter's link`);
    const head=`<div class="vt-os-h" style="background:linear-gradient(135deg,${_vtPjCol(t.id)[0]},${_vtPjCol(t.id)[1]})" onclick="this.parentElement.classList.toggle('open')">
      <div><h4><span class="vt-os-kind ${t.kind}">${_vtKindLbl(t)}</span>${esc(t.subject||t.title)}</h4>
      <div class="os-sub">${subTxt} · ${t.kind==='project'?'Final deadline':'Deadline'}: <b>${esc(t.deadline_nice||'—')}</b>${t.total?'': ' · items will auto-fill shortly'}</div>
      ${_vtOsWeek(t)}</div>
      <button class="vt-os-hbtn" onclick="vtStatusOpen(${t.id},'t',event)">${ic('history')} History</button>
      ${_vtOsProg(t)}</div>`;
    const body=t.total?`<div>${t.chapters.map(c=>_vtChRow(t,c)).join('')}</div>`
      :`<div style="font-size:.78rem;color:var(--text-muted);padding:8px 4px">This subject's chapters are not in the syllabus manager / timetable yet — the list will appear here automatically once they are uploaded.</div>`;
    return `<div class="vt-os" id="vt-os-${t.id}" style="border-color:${_vtPjCol(t.id)[1]}55">${head}<div class="vt-os-b">${body}</div></div>`;
  }).join('');
}
function tvtChEdit(tid,cid){
  const t=(window._tvtMap||{})[tid]; if(!t) return;
  const c=(t.chapters||[]).find(x=>x.id===cid); if(!c) return;
  const row=document.getElementById(`vt-chr-${tid}-${cid}`);
  if(!row) return;
  row.outerHTML=`<div class="vt-chr" id="vt-chr-${tid}-${cid}"><span class="dot"></span><span class="nm">${esc(c.title)}</span>
    <span class="inp"><input class="input" id="tvt-ch-${tid}-${cid}" value="${esc(c.link||'')}" placeholder="https://drive.google.com/...">
    <button class="btn btn-primary btn-sm" style="padding:5px 12px" onclick="tvtChapterSave(${tid},${cid})">${ic('send')} Save</button></span></div>`;
}
async function tvtChapterSave(tid,cid){
  const inp=document.getElementById(`tvt-ch-${tid}-${cid}`);
  const link=(inp&&inp.value||'').trim();
  // v91: pehle se link hai aur input khaali kiya = link REMOVE (confirm ke saath)
  const t=(window._tvtMap||{})[tid]; const c=t&&(t.chapters||[]).find(x=>x.id===cid);
  const had=c&&(c.link||'').trim();
  if(!link&&!had){ toast('Paste the video link first'); return; }
  if(!link&&had&&!confirm('Remove this video link? The chapter will be marked as not submitted, and the admin will see this change.')) return;
  try{
    const r=await api(`/api/teacher/video-tasks/${tid}/chapter-link`,'POST',{chapter_id:cid,link});
    toast(!link?'Link removed.':(r.completed?'All items completed — great work!':`Saved — ${r.done}/${r.total} done.`));
    loadTVTasks();
  }catch(e){ toast(e.message||'Could not save'); }
}
// v115: Task Manager sidebar badge — page khole bina bhi naya proposal /
// review-pending submission ka count dikhe. Halka endpoint; login/dashboard
// load + notification poll (25s) pe auto-refresh hota hai.
function _setUrgentBadge(n){
  const b=document.getElementById('a-urgent-badge'); if(!b) return;
  n=n||0; b.style.display=n?'inline-block':'none'; b.textContent=n;
}
async function _avtBadgePoll(){
  // v164: skip for admins without the Task Manager (vtasks) section — this poll was
  // 403-ing on /video-tasks/badge every cycle and flooding the logs.
  if(window._adminMe && !adminAllowed('vtasks') && !adminAllowed('urgent')) return;
  if(document.hidden) return;   // v167: hidden tab skip
  try{
    const b=await api('/api/admin/video-tasks/badge');
    const badge=document.getElementById('a-vt-badge');
    if(badge){ const n=(b&&b.count)||0; badge.style.display=n?'inline-block':'none'; badge.textContent=n; }
    _setUrgentBadge(b&&b.urgent);
  }catch(e){}
}
function _avtCard(t){
      const isU=(t.kind==='urgent');
      const dlLbl=isU?'Upload Deadline':'Deadline';
      const dlBlink=(isU&&t.status!=='uploaded')?' vt-dl-blink':'';
      const upTxt=isU?(t.status==='uploaded'
        ?(t.on_time===true?`<span class="vt-up-ok">${ic('check')} Uploaded on time</span>`
         :t.on_time===false?`<span class="vt-up-late">${ic('alert')} Upload delayed vs the deadline</span>`:'')
        :`<span class="vt-up-wait">${ic('clock')} Awaiting upload — publish before the deadline</span>`):'';
      const reviewBtn=(t.status==='submitted')
        ?`<button class="btn btn-primary btn-sm ${t.reviewed?'':'vt-checking'}" onclick="openVTReview(${t.id})">${ic('check')} ${t.reviewed?'Review Again':'Checking — Review'}</button>`:'';
      const editBtn=(['approved','editing_soon','editing_done'].includes(t.status))
        ?`<button class="btn btn-ghost btn-sm" onclick="openVTReview(${t.id})">${ic('edit')} Update Status</button>`:'';
      const notifyBtn=(t.submitted_link)
        ?`<button class="btn btn-gold btn-sm" onclick="vtNotifyStudents(${t.id})" title="Send this video link to all students">${ic('send')} Send to Students</button>`:'';
      const editTaskBtn=`<button class="btn btn-ghost btn-sm" onclick="openVTEdit(${t.id})" title="Edit title, deadline, type, channel, thumbnail">${ic('edit')} Edit</button>`;
      const delTaskBtn=`<button class="btn btn-ghost btn-sm vt-del" onclick="vtDeleteTask(${t.id})" title="Delete this task permanently">${ic('trash')} Delete</button>`;
      const ytBtn=`<button class="btn btn-ghost btn-sm" onclick="openVtYtLink(${t.id},'${esc(t.youtube_url||'').replace(/'/g,'')}')" title="Post the published YouTube link">${ic('play')} ${t.youtube_url?'Edit YT Link':'Post YT Link'}</button>`;
      const histBtn=`<button class="btn btn-ghost btn-sm" onclick="vtStatusOpen(${t.id},'a',event)" title="See the full status timeline">${ic('history')} Timeline</button>`;
      const _aRefv=(t.reference_video||'').trim()||((/^https?:\/\//i.test((t.reference||'').trim()))?(t.reference||'').trim():'');
      const refvBtn=_aRefv?`<button class="btn btn-sm vt-refv-btn" onclick="window.open('${esc(_aRefv).replace(/'/g,'')}','_blank','noopener')" title="Teacher's reference video">${ic('play')} Reference Video</button>`:'';
      const convoBtn=`<button class="btn btn-ghost btn-sm" onclick="aVtConvo(${t.id})" title="Reference video, remarks and the conversation with the teacher">${ic('alert')} Video Needs${t.comment_count?` (${t.comment_count})`:''}</button>`;
      const _lcAssign=['approved','editor_assigned','editing','editing_paused','editing_done','qc_pending','qc_changes','ready_for_youtube'];
      const asgEditorBtn=(_lcAssign.indexOf(t.lifecycle)>=0 && !t.editor_id)
        ?`<button class="btn btn-ghost btn-sm" onclick="aAssignProd(${t.id},'editor')" title="Assign an editor to this approved video">${ic('play')} Assign Editor</button>`:'';
      const asgGfxBtn=(['approved','editor_assigned','editing'].indexOf(t.lifecycle)>=0 && !t.graphics_id)
        ?`<button class="btn btn-ghost btn-sm" onclick="aAssignProd(${t.id},'graphics')" title="Assign a graphics designer for the thumbnail">${ic('image')} Assign Graphics</button>`:'';
      const asgInfo=(t.editor_name||t.graphics_name)
        ?`<span class="vt-pill editing_soon" style="cursor:default">${[t.editor_name?('Editor: '+esc(t.editor_name)):'',t.graphics_name?('Graphics: '+esc(t.graphics_name)):''].filter(Boolean).join(' · ')}</span>`:'';
      return `<div class="vt-card st-${t.status}${t.status==='submitted'?' vt-sub-blink':''}" data-tid-card="${t.id}" data-done="${['approved','editing_soon','editing_done','uploaded'].includes(t.status)?1:0}" data-pending="${(!['approved','editing_soon','editing_done','uploaded','submitted'].includes(t.status))?1:0}" data-delayed="${((t.on_time===false)||(['assigned','reshoot','rejected'].includes(t.status)&&t.seconds_left!=null&&t.seconds_left<0))?1:0}" data-collab="${t.is_collab?1:0}" data-collabdone="${t.is_collab?(t.collab_all_verified?1:0):''}" data-tid="${t.teacher_id||0}" data-cid="${t.channel_id||0}" data-vt="${esc(t.video_type||'')}" data-vstatus="${t.status}">${_vtThumb(t,'a')}<div class="vt-body">
        <div class="vt-title">${esc(t.title)}${t.is_collab?_vtCollabChip(t,'a'):''}${t.status==='submitted'?`<span class="vt-newsub">${ic('bell')} NEW · ${t.is_collab?'Collab':esc(t.submitted_by_name||t.teacher)}</span>`:''}</div>
        <div class="vt-chips">${t.is_collab?`<span class="vt-pill assigned" style="cursor:pointer" onclick="event.stopPropagation();vtCollabPopup(${t.id},'a')">${ic('users')} Collab</span>`:`<span class="vt-pill assigned">${ic('user')} ${esc(t.teacher)}</span>`}${t.is_old?`<span class="vt-pill" style="background:rgba(120,113,108,.18);color:#78716c;font-weight:800">OLD · not counted</span>`:''}${_vtTypeBadge(t)}${t.channel?`<span class="vt-pill editing_soon">${ic('play')} ${esc(t.channel)}</span>`:''}${t.streaming?`<span class="vt-pill assigned"${t.streaming==='live'?' style="background:rgba(220,38,38,.15);color:#dc2626"':''}>${t.streaming==='live'?'Live':'Recorded'}</span>`:''}${asgInfo}</div>
        <div class="vt-meta">
          <span class="${dlBlink}">${ic('clock')} ${dlLbl}: <b>${esc(t.deadline_nice)}</b>${t.status==='assigned'&&t.seconds_left!=null?` · <span data-vt-cd="${t.id}" data-secs="${t.seconds_left}"></span>`:''}</span>
          ${t.submitted_at?`<span>${ic('check')} Submitted: <b>${esc(t.submitted_at)}</b>${isU?'':` ${t.on_time===true?'(on time)':(t.on_time===false?'(delayed)':'')}`}</span>`:''}
          ${upTxt?`<span>${upTxt}</span>`:''}
          ${t.youtube_url?`<span class="vt-yt-views">${ic('play')} Live views: <b>${t.yt_views!=null?(+t.yt_views).toLocaleString():'—'}</b>${t.yt_views_at?' · '+esc(t.yt_views_at):''} · <a href="${esc(t.youtube_url)}" target="_blank" rel="noopener">Open on YouTube</a></span>`:''}
          ${t.reference?`<span>Reference: ${esc(t.reference)}</span>`:''}
          ${t.remarks?`<span>Remarks: ${esc(t.remarks)}</span>`:''}
          ${t.review_remarks?`<span>Review: ${esc(t.review_remarks)}${t.reject_count?` · Reshoot #${t.reject_count}`:''}</span>`:''}
        </div>
        <div class="vt-foot">
          ${t.submitted_link?`<a class="btn btn-ghost btn-sm" href="${esc(t.submitted_link)}" target="_blank" rel="noopener">${ic('link')} Open Video</a>`:''}
          ${refvBtn}${histBtn}${convoBtn}${reviewBtn}${editBtn}${editTaskBtn}${asgEditorBtn}${asgGfxBtn}${ytBtn}${notifyBtn}
          <button class="btn btn-ghost btn-sm" onclick="vtMarkOld(${t.id},${t.is_old?'false':'true'})" title="Old = pre-portal content, will not count this month">${t.is_old?ic('refresh')+' Mark as New':ic('clock')+' Mark as Old'}</button>
          ${delTaskBtn}
        </div></div></div>`;
}
async function aVtConvo(id){
  let comments=[]; try{ const d=await api('/api/admin/video-tasks/'+id+'/comments'); comments=d.comments||[]; }catch(e){}
  const t=(window._avtMap&&window._avtMap[id])||{};
  _aVtConvoRender(id,t,comments);
}
function _aVtConvoRender(id,t,comments){
  const refVid=(t.reference_video||'').trim()||((/^https?:\/\//i.test((t.reference||'').trim()))?(t.reference||'').trim():'');
  const refBlock=refVid?`<a href="${esc(refVid)}" target="_blank" rel="noopener" class="btn btn-ghost btn-sm" style="margin-bottom:10px">${ic('play')} Open Reference Video</a>`:'';
  const remarks=(t.remarks||'').trim();
  const remBlock=remarks?`<div class="tvn-remarks"><div class="tvn-h">${ic('alert')} Remarks you sent</div><div class="tvn-body">${esc(remarks)}</div></div>`:'';
  function _bubble(c){
    const mine=(c.role!=='teacher');
    const who=esc((c.role||'').replace('production_manager','PM').replace('graphics','Graphics').replace('teacher','Teacher').replace('admin','Admin'));
    const img=c.attachment_url?`<img src="${esc(c.attachment_url)}" onclick="window.open('${esc(c.attachment_url)}','_blank')" style="max-width:190px;max-height:150px;border-radius:8px;margin-top:5px;cursor:pointer;display:block">`:'';
    return `<div class="tvn-msg ${mine?'mine':'them'}"><div class="tvn-msg-a">${esc(c.author)} · ${who}</div>${c.message?`<div class="tvn-msg-b">${esc(c.message)}</div>`:''}${img}<div class="tvn-msg-t">${esc(c.at)}</div></div>`;
  }
  // Video Needs teachers ke liye bana tha — default sirf creator (teacher) baat dikhao.
  const creatorC=comments.filter(c=>((c.audience||'creator')!=='internal'));
  const internalC=comments.filter(c=>((c.audience||'creator')==='internal'));
  const thread=creatorC.length?creatorC.map(_bubble).join(''):'<div style="color:var(--text-muted);font-size:.82rem;padding:6px 0">No messages with the teacher yet.</div>';
  const internalBtn=internalC.length?`<button class="btn btn-ghost btn-sm" style="margin-top:10px" onclick="var e=document.getElementById('avn-internal');if(e){var h=(e.style.display==='none');e.style.display=h?'block':'none';this.textContent=h?'Hide PM–Graphics chat':('Show PM–Graphics chat ('+${internalC.length}+')');}">${ic('users')} Show PM–Graphics chat (${internalC.length})</button>`:'';
  const internalThread=internalC.length?`<div id="avn-internal" style="display:none;margin-top:10px;border-top:1px dashed var(--border);padding-top:10px"><div style="font-weight:800;font-size:.76rem;color:var(--text-muted);margin-bottom:6px">PM ↔ Graphics (internal — teacher ko nahi dikhta)</div><div class="tvn-thread">${internalC.map(_bubble).join('')}</div></div>`:'';
  showModal('Video Needs — '+esc(t.title||''),
    `${refBlock}${remBlock}<div class="tvn-thread">${thread}</div>${internalBtn}${internalThread}
     <div class="form-group" style="margin-top:10px"><label>Reply to the teacher</label><textarea id="avn-reply" class="input" rows="2" placeholder="Type your message..."></textarea></div>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Close</button><button class="btn btn-primary" onclick="aVtConvoSend(${id})">${ic('send')} Send</button>`);
}
async function aVtConvoSend(id){
  const el=document.getElementById('avn-reply'); const msg=(el?el.value:'').trim();
  if(!msg){ toast('Type a message first',true); return; }
  try{
    await api('/api/admin/video-tasks/'+id+'/comments','POST',{message:msg});
    toast('Sent to the teacher');
    let comments=[]; try{ const d=await api('/api/admin/video-tasks/'+id+'/comments'); comments=d.comments||[]; }catch(e){}
    const t=(window._avtMap&&window._avtMap[id])||{};
    _aVtConvoRender(id,t,comments);
    if(typeof loadAVTasks==='function') loadAVTasks();
  }catch(e){ toast((e&&e.message)||'Could not send',true); }
}
async function aAssignProd(id, role){
  // role: 'editor' | 'graphics' — admin assigns from the video-task card using the production endpoints
  try{
    const ppl=await api('/api/production/people');
    const list=(role==='editor')?(ppl.editors||[]):(ppl.graphics||[]);
    if(!list.length){ toast('No '+(role==='editor'?'editors':'graphics designers')+' available. Add them under Production Team first.',true); return; }
    const label=(role==='editor')?'Editor':'Graphics Designer';
    const opts=list.map(p=>`<option value="${p.id}">${esc(p.name)}${p.active!=null?` · ${p.active} active`:''}</option>`).join('');
    const extra=(role==='graphics')?`<div class="form-group"><label>Thumbnail deadline (optional)</label><input id="aap-deadline" type="datetime-local" class="input"></div>`:'';
    showModal(`Assign ${label}`,
      `<div class="form-group"><label>Choose ${label.toLowerCase()}</label><select id="aap-sel" class="input"><option value="">Select...</option>${opts}</select></div>${extra}`,
      `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="aAssignProdSave(${id},'${role}')">${ic('check')} Assign</button>`);
  }catch(e){ toast((e&&e.message)||'Could not load team',true); }
}
async function aAssignProdSave(id, role){
  const sel=document.getElementById('aap-sel'); const val=sel?sel.value:'';
  if(!val){ toast('Please choose someone',true); return; }
  const body=(role==='editor')?{editor_id:parseInt(val,10)}:{graphics_id:parseInt(val,10)};
  if(role==='graphics'){ const dl=document.getElementById('aap-deadline'); if(dl&&dl.value) body.deadline=dl.value; }
  const path=(role==='editor')?`/api/production/tasks/${id}/assign-editor`:`/api/production/tasks/${id}/assign-graphics`;
  try{
    await api(path,'POST',body);
    closeModal(); toast((role==='editor'?'Editor':'Graphics designer')+' assigned');
    if(typeof loadAVTasks==='function') loadAVTasks();
  }catch(e){ toast((e&&e.message)||'Could not assign',true); }
}
async function vtMarkOld(id, isOld){
  try{ await api('/api/admin/video-tasks/'+id+'/mark-old','POST',{is_old:!!isOld});
    toast(isOld?'Marked as OLD — this will not count toward this month performance.':'Marked as NEW — this will count toward performance.');
    if(typeof loadAVTasks==='function') loadAVTasks(); else location.reload();
  }catch(e){ toast(e.message||'Failed',true); }
}
function _vtCollabChips(t){
  if(!t||!t.is_collab) return '';
  return (t.collab_teachers||[]).map(c=>`<span class="cbnm ${c.verified?'ok':''}">${esc(c.name)}</span>`).join('');
}
function _vtCollabHtml(t, canVerify){
  if(!t||!t.is_collab) return '';
  const all=t.collab_teachers||[];
  const done=all.filter(c=>c.verified), total=all.length, dn=done.length;
  const submitted=!!t.submitted_at || ['submitted','uploaded','approved','editing_soon','editing_done'].indexOf(t.status)>=0;
  const head = (total&&dn>=total)?`<span class="cb-pill ok">All ${total} teachers verified</span>`
             : (submitted?`<span class="cb-pill bad">${dn}/${total} verified</span>`:'');
  // Teacher ko (ya submit se pehle admin ko) sirf naam dikhein — koi verify button nahi
  if(!canVerify || !submitted){
    const chips=all.map(c=>`<span class="cbnm ${c.verified?'ok':''}">${esc(c.name)}${c.verified?' \u2014 Approved':''}</span>`).join('');
    const note=!submitted?`<div class="cb-sub" style="margin-top:8px">${canVerify?'Verification will be available after the video is submitted.':'The production manager will verify this.'}</div>`:'';
    return `<div class="cb-box"><div class="cb-head">COLLAB TEACHERS ${head}</div><div class="cb-chips">${chips}</div>${note}</div>`;
  }
  const pending=all.filter(c=>!c.verified);
  const pendChips=pending.map(c=>{ const safe=esc(String(c.name)).replace(/'/g,'');
    return `<span class="cbc cbc-pend"><span class="cbc-nm">${esc(c.name)}</span><button class="cbc-btn" onclick="vtVerifyTeacher(${t.id},${c.id},'${safe}',true)">Verify</button></span>`; }).join('');
  const doneChips=done.map(c=>{ const safe=esc(String(c.name)).replace(/'/g,'');
    return `<span class="cbc cbc-ok" onclick="vtVerifyTeacher(${t.id},${c.id},'${safe}',false)" title="Tap to cancel this verification">${esc(c.name)} <span class="cbc-x">Approved &times;</span></span>`; }).join('');
  return `<div class="cb-box"><div class="cb-head">COLLAB TEACHERS ${head}</div>`
    + (pending.length?`<div class="cb-sub">Tap to verify each teacher:</div><div class="cb-chips">${pendChips}</div>`:'')
    + (done.length?`<div class="cb-sub"${pending.length?' style="margin-top:9px"':''}>Verified — tap to cancel:</div><div class="cb-chips">${doneChips}</div>`:'')
    + `</div>`;
}
// ===== COLLAB: blinking chip -> popup (inline list hata diya; cards compact) =====
