/* ---------- teacher ranking board (admin) ---------- */
const _TRK_METRICS=[['dpp_cov','DPP Coverage','#0891b2','pct'],['test_cov','Test Coverage','#7c3aed','pct'],['lectures','Classes On-time','#a1741a','pct'],['doubts','Doubts Resolved','#059669','pct'],['attendance','Present Days','#dc2626','count'],['tasks','Tasks On-time','#b8941f','pct']];
async function loadATeacherRanks(days){
  const el=document.getElementById('a-tranks-content');
  softSpin(el);
  days=days||90;
  // Phase 5: premium engine leaderboard (month-scoped). Fail ho to purana activity board.
  try{ await renderPerfBoard('a-tranks-content','a'); return; }catch(e){ /* fallback below */ }
  try{
    const d=await api('/api/teacher/rankings?days='+days);
    const rows=d.results||d.teachers||d.rankings||d.rows||[];
    if(!rows.length){ el.innerHTML='<div class="card"><div class="card-body"><div class="ws-empty"><p>No teacher activity yet.</p></div></div></div>'; return; }
    const maxM={};
    _TRK_METRICS.forEach(m=>{ maxM[m[0]]=Math.max(1,...rows.map(r=>((r.metrics||{})[m[0]]||0))); });
    const medal=['#f59e0b','#a2946d','#b45309'];
    const av=function(r,sz){
      const ini=esc((r.name||'?').slice(0,1).toUpperCase());
      return r.photo
        ? `<img src="${r.photo}" style="width:${sz}px;height:${sz}px;border-radius:50%;object-fit:cover;border:3px solid #fff;box-shadow:0 3px 10px rgba(0,0,0,.18)">`
        : `<div style="width:${sz}px;height:${sz}px;border-radius:50%;background:linear-gradient(135deg,#b8941f,#a1741a);color:#fff;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:${Math.round(sz*.4)}px;border:3px solid #fff;box-shadow:0 3px 10px rgba(0,0,0,.18)">${ini}</div>`;
    };
    // podium (top 3)
    const pod=[rows[1],rows[0],rows[2]].filter(Boolean);
    const podHtml=`<div class="trk-podium">${pod.map(r=>{
      const h=r.rank===1?118:r.rank===2?88:72;
      const sz=r.rank===1?66:54;
      return `<div class="trk-pod"><div class="trk-pod-av" style="position:relative">${av(r,sz)}<span class="trk-medal" style="background:${medal[r.rank-1]}">${r.rank}</span></div>
        <div class="trk-pod-nm">${esc(r.name)}</div><div class="trk-pod-sc">${r.score}<small>/100</small></div>
        <div class="trk-pod-base" style="height:${h}px;background:linear-gradient(180deg,${medal[r.rank-1]}33,${medal[r.rank-1]}0d);border-top:4px solid ${medal[r.rank-1]}"><b>#${r.rank}</b></div></div>`;
    }).join('')}</div>`;
    // full board
    const board=rows.map(r=>{
      const bars=_TRK_METRICS.map(m=>{
        const raw=(r.metrics||{})[m[0]];
        const isPct=m[3]==='pct';
        const na=(raw===null||raw===undefined);
        const v=na?0:raw;
        const fill=na?0:(isPct?Math.max(0,Math.min(100,Math.round(v))):Math.round(v/maxM[m[0]]*100));
        const shown=na?'N/A':(isPct?(Math.round(v)+'%'):v);
        const mlbl=(m[0]==='attendance'&&r.attendance_source==='reports')?'Present Days (from reports)':m[1];
        return `<div class="trk-mrow"><span class="trk-mlbl">${mlbl}</span><div class="trk-mtrack"><div class="trk-mfill" style="width:${fill}%;background:${m[2]}"></div></div><b class="trk-mval">${shown}</b></div>`;
      }).join('');
      return `<div class="card trk-card"><div class="card-body">
        <div class="trk-head"><div style="position:relative">${av(r,46)}<span class="trk-medal sm" style="background:${medal[r.rank-1]||'#8a7c55'}">${r.rank}</span></div>
        <div style="flex:1;min-width:150px"><b style="font-size:.95rem">${esc(r.name)}</b><div style="font-size:.72rem;color:var(--text-muted)">${esc(r.user_id||'')}${r.subjects?' &middot; '+esc(r.subjects):''}</div></div>
        <div class="trk-score"><b>${r.score}</b><span>score</span></div></div>
        <div class="trk-mets">${bars}</div></div></div>`;
    }).join('');
    el.innerHTML=`<div class="card" style="margin-bottom:16px"><div class="card-body" style="display:flex;align-items:center;gap:12px;flex-wrap:wrap">
      <div style="font-size:1.8rem">&#127942;</div>
      <div style="flex:1;min-width:220px"><h3 style="margin:0 0 3px">Teacher Ranking Board</h3>
      <p style="margin:0;font-size:.8rem;color:var(--text-muted)">Quality score — DPP &amp; test chapter coverage, on-time classes, present days, doubts resolved (only unresolved hurt), and on-time production tasks (last ${days} days).</p></div>
      <div class="perf-tabs" style="margin:0">
        <div class="perf-tab${days===30?' active':''}" onclick="loadATeacherRanks(30)">30d</div>
        <div class="perf-tab${days===90?' active':''}" onclick="loadATeacherRanks(90)">90d</div>
        <div class="perf-tab${days===365?' active':''}" onclick="loadATeacherRanks(365)">1y</div>
      </div></div></div>
      ${podHtml}
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(min(330px,100%),1fr));gap:14px">${board}</div>
      ${_vtTaskRankHTML(d.task_ranking||[], 0)}
      <div id="a-dpp-ranks"><div class="card" style="margin-top:18px"><div class="card-body"><div class="spinner"></div></div></div></div>`;
    loadADppRanks();
  }catch(e){ el.innerHTML=errHtml(e); }
}
/* Admin: DPP rankings — sab packs + kaun kitni baar submit hua (click = podium modal) */
async function loadADppRanks(){
  const el=document.getElementById('a-dpp-ranks'); if(!el) return;
  try{
    const d=await api('/api/admin/dpp-rankings');
    window._aDppPacks=d.packs||[];
    window._aDppSub=window._aDppSub||'all';
    _renderADppRanks();
  }catch(e){ el.innerHTML=`<div class="card" style="margin-top:18px"><div class="card-body">${errHtml(e)}</div></div>`; }
}
function aDppSubPick(s){ window._aDppSub=s; _renderADppRanks(); }
function aDppSubPickIdx(i){
  const subs=[...new Set((window._aDppPacks||[]).map(p=>p.subject||'General'))].sort();
  aDppSubPick(subs[i]||'all');
}
function _renderADppRanks(){
  const el=document.getElementById('a-dpp-ranks'); if(!el) return;
  const packs=window._aDppPacks||[];
  const sel=window._aDppSub||'all';
  const bySub={};
  packs.forEach(p=>{ const s=p.subject||'General'; (bySub[s]=bySub[s]||[]).push(p); });
  const subs=Object.keys(bySub).sort();
  const list=sel==='all'?packs:(bySub[sel]||[]);
  const totSub=l=>l.reduce((a,p)=>a+(p.submitted||0),0);
  const rows=list.map(p=>`<tr class="dpp-rk-row" onclick="openDppRanking(${p.id},'admin')">
    <td><b>${esc(p.title||'DPP')}</b><div style="font-size:.68rem;color:var(--text-muted)">${esc(p.subject)}${p.chapter?' · '+esc(p.chapter):''} · ${p.part?esc(p.part):'Whole Chapter'}</div></td>
    <td>${esc(p.class_name||'—')}</td>
    <td>${esc(p.teacher||'—')}</td>
    <td style="text-align:center"><b>${p.submitted}</b></td>
    <td style="text-align:center"><span style="color:var(--success);font-weight:700">${p.checked}</span><span style="color:var(--text-muted)"> / </span><span style="color:var(--warning);font-weight:700">${p.pending}</span></td>
    <td style="text-align:center">${p.views||0}</td>
    <td style="text-align:center">${p.downloads||0}</td>
    <td style="text-align:right"><button class="btn btn-ghost btn-sm" onclick="event.stopPropagation();openDppRanking(${p.id},'admin')">${ic('chart')} Ranking</button></td></tr>`).join('');
  el.innerHTML=`<div class="card" style="margin-top:18px"><div class="card-header"><h3>${ic('clipboard')} DPP Rankings</h3><span class="xm-chip">${packs.length}</span></div>
    <div class="card-body"><p style="font-size:.78rem;color:var(--text-muted);margin-bottom:12px">Submissions for every DPP pack — the earliest submission earns Rank 1. Click a row for the podium and the full list (names are clickable).</p>
    ${packs.length?`<div class="dps-grid" style="margin-bottom:14px">`
      +`<div class="dps-card ${sel==='all'?'open':''}" onclick="aDppSubPick('all')"><div class="dps-name">All Subjects</div><div class="dps-count">${packs.length} DPP${packs.length===1?'':'s'} \u00b7 ${totSub(packs)} submissions</div><div class="dps-tick">${sel==='all'?'\u25b2':'\u25bc'}</div></div>`
      +subs.map((s,i)=>{const l=bySub[s];return `<div class="dps-card ${sel===s?'open':''}" onclick="aDppSubPickIdx(${i})"><div class="dps-name">${esc(s)}</div><div class="dps-count">${l.length} DPP${l.length>1?'s':''} \u00b7 ${totSub(l)} submission${totSub(l)===1?'':'s'}</div><div class="dps-tick">${sel===s?'\u25b2':'\u25bc'}</div></div>`;}).join('')
      +`</div>`
      +`<div class="mat-twrap"><table class="mat-table"><thead><tr><th>DPP</th><th>Class</th><th>Teacher</th><th style="text-align:center">Submitted</th><th style="text-align:center">Checked / Pending</th><th style="text-align:center">Views</th><th style="text-align:center">Downloads</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`
      :`<div class="ws-empty"><p>No DPP packs yet.</p></div>`}</div></div>`;
}

async function renderAdminHealth(){
  const wrap=document.getElementById('a-health-wrap'); if(!wrap) return;
  try{
    const ts=await api('/api/admin/teachers');
    if(!ts.length){ wrap.innerHTML=`<div class="empty-state"><p>No teachers added yet.</p></div>`; return; }
    const maxMonthly=Math.max(1,...ts.map(t=>t.monthly_classes_done||0));
    const rows=ts.map(t=>{
      const m=t.monthly_classes_done||0, done=t.total_classes_done||0, rs=t.reschedule_this_month||0;
      const lvl = !t.is_active?{c:'tag-low',l:'Inactive'} : m>=8?{c:'tag-high',l:'High'} : m>=3?{c:'tag-med',l:'Medium'} : {c:'tag-low',l:'Low'};
      const fillCol = lvl.c==='tag-high'?'#059669':lvl.c==='tag-med'?'#d97706':'#a2946d';
      const pct=Math.round((m/maxMonthly)*100);
      // subject + class ka pair (Hindi Class 10 aur Hindi Class 12 alag hain)
      const sc=(t.subject_classes||[]).filter(x=>x&&x.subject);
      let pairs=sc.length
        ? sc.map(x=>({s:(x.subject||'').trim(), c:String(x.class||x.class_level||'').trim()}))
        : [...new Set((t.subjects||[]).map(x=>(x||'').trim()).filter(Boolean))].map(s=>({s,c:''}));
      const seen=new Set(); pairs=pairs.filter(p=>{ const k=p.s+'|'+p.c; if(seen.has(k)) return false; seen.add(k); return true; });
      const subs=pairs.slice(0,4).map(p=>`<span class="chip">${esc(p.s)}${p.c?`<b style="opacity:.65;font-weight:700;margin-left:5px">${esc(p.c)}</b>`:''}</span>`).join('')+(pairs.length>4?`<span class="chip">+${pairs.length-4}</span>`:'')||'<span style="color:var(--text-muted)">—</span>';
      return `<tr><td><strong>${esc(t.name)}</strong><div style="font-size:.72rem;color:var(--text-muted)">${esc(t.user_id)}</div></td><td>${subs}</td><td><strong>${done}</strong> <span style="color:var(--text-muted);font-size:.78rem">total</span><div class="eff-bar"><div class="eff-fill" style="width:${pct}%;background:${fillCol}"></div></div><div style="font-size:.72rem;color:var(--text-muted);margin-top:3px">${m} this month</div></td><td><span class="tag ${rs>=3?'tag-reschedule':'tag-done'}">${rs}</span> <span style="color:var(--text-muted);font-size:.72rem">this month</span></td><td><span class="tag ${lvl.c}">${lvl.l}</span></td></tr>`;
    }).join('');
    wrap.innerHTML=`<div class="hide-scroll health-scroll"><table class="health-table"><thead><tr><th>Teacher</th><th>Subjects</th><th>Classes (Activity)</th><th>Reschedule</th><th>Status</th></tr></thead><tbody>${rows}</tbody></table></div>${ts.length>5?`<div style="text-align:center;font-size:.72rem;color:var(--text-muted);padding-top:8px">Showing 5 of ${ts.length} teachers \u00b7 scroll for more</div>`:''}`;
  }catch(e){ wrap.innerHTML=errHtml(e); }
}
