async function reviewLetterRemark(tid){
  const el=document.getElementById('lr-reply-'+tid);
  const t=(el&&el.value||'').trim();
  if(t.length<3){ toast('Please write a reply — the teacher should understand what was clarified.',true); return; }
  try{ const r=await api(`/api/admin/letter-remarks/${tid}/review`,'POST',{reply:t}); toast(r.message); loadAApprovals(); }catch(e){ toast(e.message,true); }
}
