// Teacher ke subjects ko class ke hisaab se baanto.
// PEHLE subject_classes (asli subject+class pairing) dekhte hain — naam se
// guess NAHI karte, warna "Economics" (jo 10 aur 12 dono me hai) dono classes
// me dikhne lagta tha. Jinki class saved nahi, wo "Class not set" me jaate hain.
function _teacherSubjByClass(subjects, subjectClasses){
  const cat=window._allSubjects||{'10':[],'12':[]};
  const find=(nm,cl)=>(cat[cl]||[]).find(x=>(x.name||'').toLowerCase()===(nm||'').toLowerCase());
  const sc=(subjectClasses||[]).filter(x=>x&&x.subject);
  if(sc.length){
    const c10=[],c12=[],other=[];
    sc.forEach(x=>{
      const cl=String(x.class||x.class_level||'');
      const hit=cl?find(x.subject,cl):null;
      if(cl==='10') c10.push(hit||{name:x.subject,code:''});
      else if(cl==='12') c12.push(hit||{name:x.subject,code:''});
      else other.push(x.subject);
    });
    return {c10,c12,other};
  }
  // koi pairing nahi -> class guess mat karo, sab "Class not set" me
  return {c10:[],c12:[],other:(subjects||[]).slice()};
}
function _codeChips(list){ return list.map(s=>`<span class="code-chip">${esc(s.name)} <b>${esc(s.code)}</b></span>`).join(''); }
async function loadAMaterial(){
  const el=document.getElementById('a-material-content');
  el.innerHTML=`<div class="sm-head"><h2>Classes Material</h2></div><div id="a-mat-tree"></div>`;
  _renderMaterialTree('a-mat-tree','/api/admin/materials-tree','/api/admin');
}

async function loadAReports(){
  const el=document.getElementById('a-reports-content');
  softSpin(el);
  try{
    const d=await api('/api/admin/class-reports');
    const pt=(d.per_teacher||[]).filter(t=>t.classes_done>0);
    const LBL=t=>t.on_time_pct==null?'\u2014':t.on_time_pct+'%';
    const cls=v=>v==null?'':(v>=80?'good':(v>=60?'warn':'bad'));
    const cards=pt.length?pt.map(t=>`<div class="rp-row">
        <span class="rp-badge ${t.on_time_pct==null?'unknown':(t.on_time_pct>=80?'ontime':(t.on_time_pct>=60?'minor':'late'))}">${LBL(t)} on time</span>
        <div class="rp-main"><div class="rp-title">${esc(t.name)}</div><div class="rp-meta">${esc((t.subjects||[]).join(', ')||'\u2014')} \u00b7 ${t.classes_done} classes \u00b7 avg delay ${t.avg_delay==null?'\u2014':t.avg_delay+' min'}</div></div>
        <span class="rp-dur">${t.week_hours}h wk \u00b7 ${t.month_hours}h mo</span>
      </div>`).join(''):'<div class="ws-empty"><p>No class reports yet</p><small>Reports appear once teachers mark classes Done.</small></div>';
    const opts='<option value="">All teachers</option>'+(d.teachers||[]).map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');
    el.innerHTML=`<div class="sm-head"><h2>Teacher Reports</h2><p>Punctuality and teaching hours from every submitted class report.</p></div>
      <div class="card"><div class="card-header"><h3>Teachers</h3></div><div class="card-body">${cards}</div></div>
      <div style="display:flex;justify-content:flex-end;margin:18px 0 10px"><select class="form-control" style="max-width:220px" id="a-rp-filter" onchange="_renderClassReports('a-rp-detail','/api/admin/class-reports'+(this.value?('?teacher_id='+this.value):''),true)">${opts}</select></div>
      <div id="a-rp-detail"></div>`;
    _renderClassReports('a-rp-detail','/api/admin/class-reports',true);
  }catch(e){ el.innerHTML=errHtml(e); }
}

// ============ LOGIN CREDENTIAL ROWS (per-field copy, like the app) ============
// renders: [Login ID  | value | copy] [Password | value | eye | copy] [Copy both]
function _credRows(uid,pass,shareWith){
  return `<div class="cred-box">
    <div class="cred-row"><span class="cred-lab">Login ID</span>
      <div class="cred-val" id="cred-uid">${esc(uid)}</div>
      <button class="cred-btn" title="Copy ID" onclick="copyCred(this,'uid')">${ic('copy')}</button></div>
    <div class="cred-row"><span class="cred-lab">Password</span>
      <div class="cred-val" id="cred-pass">${esc(pass)}</div>
      <button class="cred-btn" title="Show / hide password" onclick="toggleCredPass(this)">${ic('eyeOff')}</button>
      <button class="cred-btn" title="Copy password" onclick="copyCred(this,'pass')">${ic('copy')}</button></div>
    <button class="btn btn-ghost btn-sm cred-all" onclick="copyCred(this,'both')">${ic('copy')} Copy both (ID + password)</button>
    ${shareWith?`<div style="font-size:.72rem;color:var(--text-muted);margin-top:8px">Share these with the ${esc(shareWith)} — tap any copy button; only that one value is copied.</div>`:''}
  </div>`;
}
function copyCred(btn,what){
  const uid=(document.getElementById('cred-uid')||{}).textContent||'';
  const passEl=document.getElementById('cred-pass')||{};
  // masked dots are never copied — always the real password
  const pass=(passEl.dataset&&passEl.dataset.masked==='1') ? (passEl.dataset.real||'') : (passEl.textContent||'');
  const text = what==='uid' ? uid : what==='pass' ? pass : `Login ID: ${uid}\nPassword: ${pass}`;
  navigator.clipboard.writeText(text).then(()=>{
    toast(what==='both' ? 'ID + password copied!' : (what==='uid' ? 'Login ID copied!' : 'Password copied!'));
    if(what!=='both'){ const old=btn.innerHTML; btn.innerHTML=ic('check'); btn.classList.add('ok');
      setTimeout(()=>{ btn.innerHTML=old; btn.classList.remove('ok'); },1200); }
  });
}
function toggleCredPass(btn){
  const el=document.getElementById('cred-pass'); if(!el) return;
  if(el.dataset.masked==='1'){ el.textContent=el.dataset.real||''; el.dataset.masked='0'; btn.innerHTML=ic('eyeOff'); btn.title='Hide password'; }
  else{ el.dataset.real=el.textContent; el.textContent='\u2022'.repeat(Math.max(el.textContent.length,6)); el.dataset.masked='1'; btn.innerHTML=ic('eye'); btn.title='Show password'; }
}

// ============ ADMIN: LOGIN CREDENTIALS (pehle current dikhao, reset optional) ============
function openResetPassword(role,profileId,name){
  showModal('Login Credentials \u2014 '+name,
    `<div id="rp-current" style="margin-bottom:4px"><div style="font-size:.85rem;color:var(--text-muted)">Loading current credentials...</div></div>
     <div style="border-top:1.5px dashed var(--border);margin:14px 0 4px;padding-top:14px">
       <div style="font-size:.74rem;font-weight:800;letter-spacing:.07em;color:var(--text-muted);text-transform:uppercase;margin-bottom:6px">Reset Password (sirf agar badalna ho)</div>
       <div class="form-group"><label>New Password (optional)</label><input class="form-control" id="rp-pass" placeholder="Leave empty to auto-generate" autocomplete="new-password"></div>
     </div>
     <div id="rp-result" style="display:none;margin-top:14px;padding:14px 14px 6px;border-radius:12px;background:var(--primary-50);border:1px solid var(--border)"></div>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Close</button><button class="btn btn-primary" id="rp-save" onclick="doResetPassword('${role}',${profileId})">Reset Password</button>`);
  api('/api/admin/credentials?role='+role+'&profile_id='+profileId).then(r=>{
    const el=document.getElementById('rp-current'); if(!el) return;
    el.innerHTML = r.password
      ? `<div style="font-size:.78rem;color:var(--text-muted)">Current login credentials:</div>`+_credRows(r.user_id,r.password,role)
      : `<div style="font-size:.82rem;color:var(--text-muted);background:var(--panel);border:1px dashed var(--border);border-radius:10px;padding:10px 12px">The current password is not in the saved record (older account). Reset it once below \u2014 the new password will show immediately and stay visible here from next time.</div>`;
  }).catch(e=>{ const el=document.getElementById('rp-current'); if(el) el.innerHTML=`<div style="font-size:.82rem;color:#dc2626">${esc(e.message)}</div>`; });
}
async function doResetPassword(role,profileId){
  const btn=document.getElementById('rp-save'); btn.disabled=true; btn.textContent='Resetting...';
  try{
    const r=await api('/api/admin/reset-password','POST',{role,profile_id:profileId,password:document.getElementById('rp-pass').value.trim()});
    document.getElementById('rp-result').innerHTML=
      `<div style="font-size:.78rem;color:var(--text-muted)">New login credentials:</div>`+_credRows(r.user_id,r.password,role);
    document.getElementById('rp-result').style.display='block';
    // current box bhi update — ab yehi password aage se saved rahega
    const cur=document.getElementById('rp-current');
    if(cur) cur.innerHTML=`<div style="font-size:.78rem;color:var(--text-muted)">Current login credentials:</div>`+_credRows(r.user_id,r.password,role);
    btn.textContent='Done \u2713';
    toast('Password reset successfully.');
  }catch(e){ toast(e.message,true); btn.disabled=false; btn.textContent='Reset Password'; }
}
async function toggleTeacherStudents(pid,current,btn){
  const next=current?0:1;
  if(btn) btn.disabled=true;
  try{
    await api(`/api/admin/teachers/${pid}/students-access`,'POST',{allowed:!!next});
    toast(next?'My Students ENABLED for this teacher.':'My Students DISABLED for this teacher.');
    loadATeachers();
  }catch(e){ toast(e.message||'Could not update',true); if(btn) btn.disabled=false; }
}
async function loadATeachers(){
  const el=document.getElementById('a-teachers-content');
  try{
 await ensureSubjects();
 const ts=await api('/api/admin/teachers');
 let html=`<div class="card-header" style="padding:0 4px 18px;border:none"><h3 style="font-size:1.3rem">All Teachers <span style="color:var(--text-muted);font-weight:600;font-size:.9rem">(${ts.length})</span></h3><button class="btn btn-primary btn-sm" onclick="openAddTeacher()">${ic('users')} Add Teacher</button></div>`;
 if(ts.length===0){ el.innerHTML=html+`<div class="empty-state"><p>No teachers yet. Use "Add Teacher" to create one.</p></div>`; return; }
 html+=`<div class="tcard-grid">`;
 ts.forEach(t=>{
   const sc=_teacherSubjByClass(t.subjects,t.subject_classes);
   const _inNios=(t.in_nios!==false);
   const cls10=(_inNios&&sc.c10.length)?`<div class="tcard2-cls"><div class="tcard2-cls-h">Class 10</div>${_codeChips(sc.c10)}</div>`:'';
   const cls12=(_inNios&&sc.c12.length)?`<div class="tcard2-cls"><div class="tcard2-cls-h">Class 12</div>${_codeChips(sc.c12)}</div>`:'';
   const other=(_inNios&&sc.other.length)?`<div class="tcard2-cls"><div class="tcard2-cls-h" style="color:var(--warning)">Class not set \u2014 fix via Edit</div>${sc.other.map(s=>`<span class="code-chip">${esc(s)}</span>`).join('')}</div>`:'';
   const catBlocks=(t.categories||[]).map(c=>`<div class="tcard2-cls"><div class="tcard2-cls-h" style="color:#b8941f">${esc(c.category)}</div>${(c.subjects||[]).length?c.subjects.map(s=>`<span class="code-chip">${esc(s)}</span>`).join(''):'<span class="tcard2-sub">No subjects yet</span>'}</div>`).join('');
   const none=(!(_inNios&&sc.c10.length)&&!(_inNios&&sc.c12.length)&&!(_inNios&&sc.other.length)&&!(t.categories||[]).length)?`<div class="tcard2-sub" style="margin-top:10px">No subjects assigned yet.</div>`:'';
   const ph=`tphoto-${t.profile_id}`;
   html+=`<div class="tcard2"><div class="tcard2-head"><div class="tcard2-photo${t.has_photo?' clickable':''}" id="${ph}" onclick="viewPhoto('${ph}','${esc((t.name||'').replace(/'/g,''))}',${t.profile_id})" title="${t.has_photo?'View photo':'Upload photo'}">${esc(initials(t.name||'T'))}</div><div style="flex:1"><div class="tcard2-name">${esc(t.name)}</div><div class="tcard2-sub"><code>${esc(t.user_id)}</code> · ${esc(t.phone||'no phone')}</div><span class="tag ${t.is_active?'tag-done':'tag-low'}" style="margin-top:6px">${t.is_active?'Active':'Inactive'}</span></div></div>
     ${cls10}${cls12}${other}${catBlocks}${none}
     <div class="tcard2-stats"><div class="mini-stat"><div class="n">${t.total_classes_done||0}</div><div class="l">Classes</div></div><div class="mini-stat"><div class="n">${t.monthly_classes_done||0}</div><div class="l">This Month</div></div><div class="mini-stat"><div class="n">${t.reschedule_this_month||0}</div><div class="l">Reschedule</div></div></div>
     <div class="tcard2-actions"><button class="btn btn-primary btn-sm" onclick="openNotifyTeacher(${t.profile_id},'${esc((t.name||'').replace(/'/g,''))}')">${ic('bell')} Notify</button><button class="btn btn-ghost btn-sm" onclick='openEditTeacher(${t.profile_id},${JSON.stringify({name:t.name,phone:t.phone,subjects:t.subjects||[],is_active:t.is_active}).replace(/'/g,"&#39;")})'>${ic('edit')} Edit</button><button class="btn btn-ghost btn-sm" onclick="openTeacherPhoto(${t.profile_id})">${ic('upload')} Photo</button><button class="btn btn-ghost btn-sm" onclick="openResetPassword('teacher',${t.profile_id},'${esc((t.name||'').replace(/'/g,''))}')">${ic('shield')} Password</button><button class="btn btn-ghost btn-sm" onclick="openTeacherCategories(${t.profile_id},'${esc((t.name||'').replace(/'/g,''))}')">${ic('grid')} Categories</button><button class="btn btn-ghost btn-sm" onclick="toggleTeacherStudents(${t.profile_id},${t.can_see_students?1:0},this)" style="${t.can_see_students?'color:#059669;font-weight:800':'color:#b07f1e'}">${ic('users')} Students: ${t.can_see_students?'ON':'OFF'}</button><button class="btn btn-danger btn-sm" onclick="deleteTeacher(${t.profile_id},'${esc((t.name||'').replace(/'/g,''))}')">${ic('trash')}</button></div></div>`;
 });
 html+=`</div>`;
 el.innerHTML=html;
 ts.forEach(t=>{ if(t.has_photo) loadImgInto('tphoto-'+t.profile_id,'/api/admin/teacher/'+t.profile_id+'/photo'); });
  }catch(e){ el.innerHTML=errHtml(e); }
}
function openNotifyTeacher(tid,name){
  showModal('Send Notification to '+name,
    `<div class="alert alert-info">This message goes only to <strong>${esc(name)}</strong>.</div><div class="form-group"><label>Title</label><input class="form-control" id="nt-title" placeholder="e.g. Upload today's notes"></div><div class="form-group"><label>Message</label><textarea class="form-control" id="nt-msg" rows="3" placeholder="Type your message..."></textarea></div><div id="nt-status"></div>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" id="nt-btn" onclick="sendNotifyTeacher(${tid})">Send</button>`);
}
async function sendNotifyTeacher(tid){
  const title=val('nt-title'), message=val('nt-msg');
  if(!title||!message){ toast('Title and message are required.',true); return; }
  const btn=document.getElementById('nt-btn'); btn.disabled=true; btn.textContent='Sending...';
  try{ const r=await api('/api/admin/teacher/'+tid+'/notify','POST',{title,message}); toast(r.message||'Notification sent.'); closeModal(); }
  catch(e){ document.getElementById('nt-status').innerHTML=`<div class="alert alert-danger">${esc(e.message)}</div>`; btn.disabled=false; btn.textContent='Send'; }
}
function openEditSubjects(tid,current){
  const cat=window._allSubjects||{'10':[],'12':[]};
  const set=new Set((current||[]).map(s=>(s||'').toLowerCase()));
  const box=(list,cls)=>list.map(s=>`<label class="subj-check"><input type="checkbox" class="subj-cb" data-cls="${cls}" value="${esc(s.name)}"${set.has(s.name.toLowerCase())?' checked':''}> ${esc(s.name)} <span class="code">${esc(s.code)}</span></label>`).join('')||'<span style="color:var(--text-muted);font-size:.82rem">No subjects</span>';
  showModal('Edit Subjects',
    `<div class="form-group"><label>Select subjects (both classes allowed)</label><div class="subj-cols"><div class="subj-col"><div class="subj-col-h">Class 10</div>${box(cat['10'],'10')}</div><div class="subj-col"><div class="subj-col-h">Class 12</div>${box(cat['12'],'12')}</div></div></div><div id="esub-status"></div>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" id="esub-btn" onclick="saveEditSubjects(${tid})">Save</button>`);
}
async function saveEditSubjects(tid){
  const subjects=[...document.querySelectorAll('.subj-cb:checked')].map(c=>c.value);
  const btn=document.getElementById('esub-btn'); btn.disabled=true; btn.textContent='Saving...';
  try{ await api('/api/admin/teacher/'+tid,'PATCH',{subjects}); toast('Subjects updated.'); closeModal(); loadATeachers(); }
  catch(e){ document.getElementById('esub-status').innerHTML=`<div class="alert alert-danger">${esc(e.message)}</div>`; btn.disabled=false; btn.textContent='Save'; }
}
async function ensureSubjects(){
  if(window._allSubjects) return window._allSubjects;
  try{ window._allSubjects=await api('/api/admin/subjects'); }catch(e){ window._allSubjects={'10':[],'12':[]}; }
  return window._allSubjects;
}
function _subjBoxes(list,cls){
  if(!list||!list.length) return '<span style="color:var(--text-muted);font-size:.82rem">No subjects available</span>';
  return list.map(s=>`<label class="subj-check"><input type="checkbox" class="subj-cb" data-cls="${cls}" value="${esc(s.name)}"> ${esc(s.name)} <span class="code">${esc(s.code)}</span></label>`).join('');
}
async function openAddTeacher(){
  let subj; try{ subj=await ensureSubjects(); }catch(e){ subj=null; }
  subj=subj||window._allSubjects||{'10':[],'12':[]};
  subj['10']=subj['10']||[]; subj['12']=subj['12']||[];
  showModal('Add Teacher',
 `<div class="alert alert-info">Enter the name, gender and phone, then select the subjects. <strong>User ID and password are generated automatically.</strong></div><div class="form-group"><label>Teacher Name</label><input class="form-control" id="at-name" placeholder="Rahul Sharma"></div><div class="form-group"><label>Gender</label><select class="form-control" id="at-gender"><option value="male">Male (Sir)</option><option value="female">Female (Ma'am)</option></select></div><div class="form-group"><label>Phone Number</label><input class="form-control" id="at-phone" placeholder="9876543210"></div><div class="form-group"><label>Subjects &mdash; select from either class (or both)</label><div class="subj-cols"><div class="subj-col"><div class="subj-col-h">Class 10</div>${_subjBoxes(subj['10'],'10')}</div><div class="subj-col"><div class="subj-col-h">Class 12</div>${_subjBoxes(subj['12'],'12')}</div></div></div>`,
 `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="submitAddTeacher()">Add Teacher</button>`);
}
async function submitAddTeacher(){
  const name=val('at-name');
  const subjects=[...document.querySelectorAll('.subj-cb:checked')].map(c=>c.value);
  if(!name){ toast('Teacher name is required.',true); return; }
  try{
 const password=genPassword();
 const r=await api('/api/admin/teachers/add','POST',{name,user_id:'auto',password,role:'teacher',subjects,gender:val('at-gender'),phone:val('at-phone')});
 showCredentials('Teacher',name,r.user_id,password);
 if(document.getElementById('a-page-teachers').classList.contains('active'))loadATeachers();
  }catch(e){ toast(e.message,true); }
}

async function openEditTeacher(pid,data){
  await ensureSubjects();
  const sc=(data.subject_classes||[]).filter(x=>x&&x.subject);
  // IMPORTANT: sirf wahi subject tick hota hai jiski class SAAF likhi ho.
  // Blank class wale (Economics/Hindi jaise naam dono classes me hote hain)
  // kisi bhi list me tick NAHI hote — admin khud sahi class chunta hai.
  const sel10=sc.filter(x=>String(x.class||x.class_level||'')==='10').map(x=>x.subject);
  const sel12=sc.filter(x=>String(x.class||x.class_level||'')==='12').map(x=>x.subject);
  const unknown=sc.filter(x=>!String(x.class||x.class_level||'')).map(x=>x.subject);
  const warn=unknown.length
    ? `<div class="alert alert-warning" style="font-size:.8rem">These subjects have no saved class (the same name exists in both classes): <b>${unknown.map(esc).join(', ')}</b>. Choose the correct class below and save.</div>`
    : '';
  showModal('Edit Teacher',
    `<div class="form-group"><label>Name</label><input class="form-control" id="et-name" value="${esc(data.name||'')}"></div>
     <div class="form-group"><label>Phone</label><input class="form-control" id="et-phone" value="${esc(data.phone||'')}"></div>
     ${warn}
     <div class="form-group"><label>Class 10 Subjects <span style="font-size:.72rem;color:var(--text-muted);font-weight:600">(tap to select)</span></label><div id="et-s10">${subjectCheckboxes('et-s10','10',sel10)}</div></div>
     <div class="form-group"><label>Class 12 Subjects <span style="font-size:.72rem;color:var(--text-muted);font-weight:600">(tap to select)</span></label><div id="et-s12">${subjectCheckboxes('et-s12','12',sel12)}</div></div>
     <div class="form-group"><label>Status</label><select class="form-control" id="et-active"><option value="1"${data.is_active?' selected':''}>Active</option><option value="0"${!data.is_active?' selected':''}>Inactive</option></select></div>
     <div id="et-status"></div>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" id="et-btn" onclick="saveEditTeacher(${pid})">Save</button>`);
}
async function saveEditTeacher(pid){
  const sc=[...pickedSubjects('et-s10').map(s=>({subject:s,class:'10'})),
            ...pickedSubjects('et-s12').map(s=>({subject:s,class:'12'}))];
  if(!sc.length){ toast('Please select at least one subject.',true); return; }
  const btn=document.getElementById('et-btn'); btn.disabled=true; btn.textContent='Saving...';
  try{
    await api('/api/admin/teacher/'+pid,'PATCH',{name:val('et-name'),phone:val('et-phone'),subject_classes:sc,is_active:val('et-active')==='1'});
    toast('Teacher updated.'); closeModal(); loadATeachers();
  }catch(e){ document.getElementById('et-status').innerHTML=`<div class="alert alert-danger">${esc(e.message)}</div>`; btn.disabled=false; btn.textContent='Save'; }
}
async function deleteTeacher(pid,name){
  if(!confirm(`"${name}" will be permanently deleted. Continue?`)) return;
  try{ await api('/api/admin/teacher/'+pid,'DELETE'); toast('Teacher deleted.'); loadATeachers(); }catch(e){ toast(e.message,true); }
}
