let _aStu=[]; let _aCounts={total:0,subjects:[]}; let _stuFilter=''; let _stuClass=''; let _stuSearch=''; let _stuPage=1; let _stuSize=10;
let _stuSess=''; let _stuMed=''; let _stuBatch='';   // master filters: Exam Session + Medium + Batch
let _aStuPageRows=[]; let _aStuTotal=0;
let _aStuFC={total:0,batches:[],classes:[],sessions:[],subjects:[]};
async function loadAStudents(){
  const el=document.getElementById('a-students-content');
  try{
    _stuFilter='';_stuSearch='';_stuPage=1;_stuSess='';_stuMed='';_stuBatch='';_stuClass='';_stuSrcFilter='';
    window._aPortalOv=await api('/api/admin/portal-overview').catch(()=>null);
    await _stuReloadCounts();
    await _stuReload();
    // v170: fresh open par hi filters reset hote hain (upar). Background SWR refresh ab
    // filters/search ko WIPE na kare — sirf current filters ke saath list dobara laaye.
    _curLoader=function(){ try{ _stuReloadCounts(); }catch(e){} _stuReload(); };
  }catch(e){ el.innerHTML=errHtml(e); }
}
function _stuQP(){
  return 'q='+encodeURIComponent(_stuSearch||'')+'&source='+encodeURIComponent(_stuSrcFilter||'')
    +'&cls='+encodeURIComponent(_stuClass||'')+'&session='+encodeURIComponent(_stuSess||'')
    +'&medium='+encodeURIComponent(_stuMed||'')+'&batch='+encodeURIComponent(_stuBatch||'')
    +'&subject='+encodeURIComponent(_stuFilter?_stuFParts().sub:'')
    +'&page='+_stuPage+'&page_size='+_stuSize;
}
async function _stuReload(){
  try{ const d=await api('/api/admin/students-paged?'+_stuQP()); _aStuPageRows=d.students||[]; _aStuTotal=d.total||0; }
  catch(e){ _aStuPageRows=[]; _aStuTotal=0; }
  _aStu=_aStuPageRows;  // current page — openStudentProfile jaise purane references isi par kaam karein
  aRenderStudents();
}
async function _stuReloadCounts(){
  try{ _aStuFC=await api('/api/admin/student-filter-counts?source='+encodeURIComponent(_stuSrcFilter||'')
      +'&session='+encodeURIComponent(_stuSess||'')+'&medium='+encodeURIComponent(_stuMed||'')
      +'&cls='+encodeURIComponent(_stuClass||'')); }
  catch(e){ _aStuFC={total:0,batches:[],classes:[],sessions:[],subjects:[]}; }
}
function _aStuCounts(){
  // Session + Medium filter lagakar per-subject counts — "April 2027 me Physics kitne?"
  let list=_aStu;
  if(_stuSrcFilter) list=list.filter(s=>(s.source||'mvs_app')===_stuSrcFilter);
  if(_stuSess) list=list.filter(s=>(s.exam_session||'')===_stuSess);
  if(_stuMed) list=list.filter(s=>(s.medium||'')===_stuMed);
  const m={};
  list.forEach(s=>{
    const cls=String(s.class_level||''); const seen=new Set();
    (s.subjects||[]).forEach(x=>{
      const k=x+'|'+cls; if(seen.has(k)) return; seen.add(k);
      if(!m[k]) m[k]={subject:x,class:cls,count:0};
      m[k].count++;
    });
  });
  return Object.values(m).sort((a,b)=>b.count-a.count||String(a.subject).localeCompare(String(b.subject)));
}
let _pp={q:'',cls:'',sess:''};
function openPortalPending(){
  const ov=window._aPortalOv;
  _pp={q:'',cls:'',sess:''};
  if(!ov||!ov.portal_reachable){
    showModal('Portal Pending',
      `<div class="alert alert-warning">The MVS Portal <b>unlocked-students</b> endpoint is not live yet. Once Endpoint 2 from <b>MVS_PORTAL_STUDENT_SYNC.md</b> is implemented, every student who has not selected a batch in Class Manager will appear here.</div>`,
      `<button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
    return;
  }
  showModal('Portal Pending \u2014 Class Manager not opened yet',
    `<p style="font-size:.82rem;color:var(--text-muted);margin-bottom:10px">These students have <b>unlocked class access on the MVS Portal</b> but haven\u2019t opened Class Manager and selected a batch even once. Remind them to tap the Class Manager card.</p>
     <input class="form-control" placeholder="Search name or phone..." oninput="_pp.q=this.value;ppRender()">
     <div id="pp-filters"></div>
     <div id="pp-count" style="font-size:.74rem;font-weight:800;color:var(--text-muted);margin-bottom:8px"></div>
     <div class="hide-scroll" id="pp-list" style="max-height:46vh"></div>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
  ppRender();
}
function ppSet(k,v){ _pp[k]=(_pp[k]===v?'':v); ppRender(); }
function ppRender(){
  const ov=window._aPortalOv||{}; const all=ov.pending||[];
  const fEl=document.getElementById('pp-filters'), lEl=document.getElementById('pp-list'), cEl=document.getElementById('pp-count');
  if(!fEl||!lEl) return;
  const sessions=[...new Set(all.map(p=>p.session).filter(Boolean))];
  const chip=(k,v,label)=>`<span class="pp-chip ${_pp[k]===v?'active':''}" onclick="ppSet('${k}','${esc(v)}')">${label}</span>`;
  fEl.innerHTML=`<div class="pp-filter"><span style="font-size:.7rem;font-weight:800;color:var(--text-muted)">CLASS</span>${chip('cls','10','Class 10')}${chip('cls','12','Class 12')}${sessions.length?`<span style="font-size:.7rem;font-weight:800;color:var(--text-muted);margin-left:8px">SESSION</span>${sessions.map(x=>chip('sess',x,esc(x))).join('')}`:''}</div>`;
  let list=all;
  if(_pp.cls) list=list.filter(p=>String(p.class_level||'')===_pp.cls);
  if(_pp.sess) list=list.filter(p=>(p.session||'')===_pp.sess);
  if(_pp.q){ const q=_pp.q.toLowerCase(); list=list.filter(p=>(p.name||'').toLowerCase().includes(q)||(p.phone||'').includes(q)); }
  cEl.textContent=`${list.length} of ${all.length} students`;
  lEl.innerHTML=list.length?list.map((p,i)=>`<div class="topper-row"><div class="rank-b">${i+1}</div><div class="topper-name">${esc(p.name||'Student')}<div class="topper-sub">${esc(p.phone)}${p.class_level?' \u00b7 Class '+esc(String(p.class_level)):''}${p.session?' \u00b7 '+esc(p.session):''}</div></div><a class="btn btn-ghost btn-sm" href="tel:${esc(p.phone)}">${ic('user')} Call</a></div>`).join('')
    :`<div class="empty-state"><p>${all.length?'No students match these filters.':'Everyone with unlocked access has onboarded. \ud83c\udf89'}</p></div>`;
}
// ============ MVS PORTAL PRIORITY SYNC ============
function openPortalSync(){
  showModal('Sync with MVS Portal',
    `<p style="font-size:.83rem;color:var(--text-muted);margin-bottom:12px">Every <b>MVS App</b> student will be checked on the MVS Portal. A student found on the portal (Class Joining = <b>Included</b>) is moved to the <b>MVS Portal</b> category, and their class, medium and subjects are refreshed from the portal.</p>
     <div class="alert alert-info" style="font-size:.8rem">Rule: <b>The MVS Portal takes top priority</b> — a student found on the portal will always remain in the MVS Portal category.</div>
     <div id="psy-out" style="margin-top:12px"></div>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Close</button><button class="btn btn-primary" id="psy-btn" onclick="runPortalSync()">Start Sync</button>`);
}
async function runPortalSync(){
  const btn=document.getElementById('psy-btn'); btn.disabled=true; btn.textContent='Syncing\u2026';
  const out=document.getElementById('psy-out');
  out.innerHTML=`<div class="prog-wrap"><div class="prog-bar"><div class="prog-fill" id="psy-fill"></div></div><div class="prog-text" id="psy-text">Starting\u2026</div></div>`;
  let afterId=0, total=0, done=0, moved=0, rows=[], more=true;
  try{
    while(more){
      const r=await api('/api/admin/students/sync-portal','POST',{after_id:afterId,limit:300});
      if(r.total!=null) total=r.total;
      done+=r.checked||0; moved+=r.moved||0; afterId=r.last_id||afterId; more=!!r.has_more;
      rows=rows.concat(r.students||[]);
      const pct=total?Math.min(100,Math.round(done/total*100)):(more?60:100);
      const f=document.getElementById('psy-fill'), t=document.getElementById('psy-text');
      if(f) f.style.width=pct+'%';
      if(t) t.textContent=`${pct}% \u2014 ${done}${total?'/'+total:''} checked \u00b7 ${moved} moved to Portal`;
    }
    const list=rows.slice(0,200).map((x,i)=>`<div class="topper-row"><div class="rank-b">${i+1}</div><div class="topper-name">${esc(x.name||'Student')}<div class="topper-sub">${esc(x.phone||'')} \u00b7 ${esc(x.user_id||'')}</div></div><span class="xm-chip" style="background:rgba(201,150,46,.16);color:#b07f1e">\u2192 MVS PORTAL</span></div>`).join('');
    out.innerHTML=`<div class="alert alert-success"><b>${moved}</b> student(s) moved to MVS Portal (out of ${done} checked).</div>${list?`<div class="hide-scroll" style="max-height:40vh;margin-top:10px">${list}</div>`:''}`;
    toast(`${moved} moved to MVS Portal`); loadAStudents();
  }catch(e){ out.innerHTML=`<div class="alert alert-danger">${esc(e.message)}</div>`; }
  btn.disabled=false; btn.textContent='Start Sync';
}
// ============ FIX MEDIUM (backfill from MVS Portal) ============
function openMediumFix(){
  showModal('Fix Medium from MVS Portal',
    `<p style="font-size:.83rem;color:var(--text-muted);margin-bottom:12px">Jin students ka <b>Medium khaali</b> their medium will be filled from the MVS Portal. This also fixes students already in the MVS Portal category (normal Sync skips them). Only the medium is set — no other field changes.</p>
     <div class="alert alert-info" style="font-size:.8rem">If the medium is wrong or empty, the student does not receive study material in the correct language — so this is important.</div>
     <div id="mfx-out" style="margin-top:12px"></div>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Close</button><button class="btn btn-primary" id="mfx-btn" onclick="runMediumFix()">Start</button>`);
}
async function runMediumFix(){
  const btn=document.getElementById('mfx-btn'); btn.disabled=true; btn.textContent='Fixing\u2026';
  const out=document.getElementById('mfx-out');
  out.innerHTML=`<div class="prog-wrap"><div class="prog-bar"><div class="prog-fill" id="mfx-fill"></div></div><div class="prog-text" id="mfx-text">Starting\u2026</div></div>`;
  let afterId=0, total=0, done=0, filled=0, notFound=0, noMed=0, rows=[], more=true;
  try{
    while(more){
      const r=await api('/api/admin/students/backfill-medium','POST',{after_id:afterId,limit:40,deep:true});
      if(r.total!=null) total=r.total;
      done+=r.checked||0; filled+=r.filled||0; notFound+=r.not_found||0; noMed+=r.no_medium||0;
      afterId=r.last_id||afterId; more=!!r.has_more;
      rows=rows.concat(r.students||[]);
      const pct=total?Math.min(100,Math.round(done/total*100)):(more?60:100);
      const f=document.getElementById('mfx-fill'), t=document.getElementById('mfx-text');
      if(f) f.style.width=pct+'%';
      if(t) t.textContent=`${pct}% \u2014 ${done}${total?'/'+total:''} checked \u00b7 ${filled} medium set`;
    }
    const list=rows.slice(0,200).map((x,i)=>`<div class="topper-row"><div class="rank-b">${i+1}</div><div class="topper-name">${esc(x.name||'Student')}<div class="topper-sub">${esc(x.phone||'')} \u00b7 ${esc(x.user_id||'')}</div></div><span class="xm-chip" style="background:rgba(16,185,129,.15);color:#059669">${esc(x.medium||'')}</span></div>`).join('');
    const diag=(notFound||noMed)?`<div class="alert alert-info" style="font-size:.8rem;margin-top:8px">Baaki khaali reh gaye: <b>${notFound}</b> were not found on the portal (phone did not match), <b>${noMed}</b> were found on the portal but their medium is empty there too. ${noMed?'For those whose medium is empty on the portal too, it must be filled by the portal team or set manually in the app.':''}</div>`:'';
    out.innerHTML=`<div class="alert alert-success"><b>${filled}</b> student(s) ka medium set hua (${done} checked).</div>${diag}${list?`<div class="hide-scroll" style="max-height:40vh;margin-top:10px">${list}</div>`:''}`;
    toast(`${filled} medium set from Portal`); loadAStudents();
  }catch(e){ out.innerHTML=`<div class="alert alert-danger">${esc(e.message)}</div>`; }
  btn.disabled=false; btn.textContent='Start';
}
