async function asClassChange(){
  await ensureSubjects();
  const cls=val('as-class');
  const b=document.getElementById('as-batch'); if(b) b.innerHTML=batchOptions(val('as-batch'),cls);
  renderStudentSubjects();
}
function renderStudentSubjects(){
  const cls=val('as-class'); const wrap=document.getElementById('as-subj-wrap'); if(!wrap) return;
  if(!cls){ wrap.innerHTML='<span style="color:var(--text-muted);font-size:.82rem">Select a class to see its subjects.</span>'; return; }
  const list=(window._allSubjects&&window._allSubjects[cls])||[];
  if(!list.length){ wrap.innerHTML='<span style="color:var(--text-muted);font-size:.82rem">No subjects for this class.</span>'; return; }
  wrap.innerHTML=`<div class="subj-grid">${list.map(s=>`<label class="subj-check"><input type="checkbox" class="ssubj-cb" value="${esc(s.name)}"> ${esc(s.name)} <span class="code">${esc(s.code)}</span></label>`).join('')}</div>`;
}
async function submitAddStudent(){
  const name=val('as-name'); const phone=val('as-phone');
  const subjects=[...document.querySelectorAll('.ssubj-cb:checked')].map(c=>c.value);
  if(!name||!phone){ toast('Name and phone are required.',true); return; }
  try{
 const uidRes=await api('/api/auth/generate-uid?name='+encodeURIComponent(name));
 const user_id=uidRes.user_id;
 const password=genPassword();
 if(!val('as-batch')){ toast('Please select a batch.',true); return; }
 await api('/api/admin/students/add','POST',{name,user_id,password,role:'student',phone,batch:val('as-batch'),class_name:val('as-class'),class_level:val('as-class'),medium:val('as-medium'),subjects});
 showCredentials('Student',name,user_id,password);
 if(document.getElementById('a-page-students').classList.contains('active'))loadAStudents();
  }catch(e){ toast(e.message,true); }
}

