function openResetData(){
  showModal('\u26a0\ufe0f Reset Portal Data',
    `<div class="alert alert-danger"><b>Students, teachers and admins are completely safe</b> \u2014 their accounts, profiles, subjects and deadlines will not be touched. Only the content data selected below is permanently deleted.</div>
     <div class="rst-list">${RESET_CATS.map(c=>`<label class="rst-row"><input type="checkbox" value="${c.id}" checked><div><b>${c.name}</b><span>${c.d}</span></div></label>`).join('')}</div>
     <div class="form-group" style="margin-top:14px"><label>Type <b>RESET PORTAL DATA</b> to confirm</label><input class="form-control" id="rst-confirm" placeholder="RESET PORTAL DATA"></div>
     <div id="rst-out"></div>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-danger" id="rst-btn" onclick="doResetData()">${ic('trash')} Delete Selected Data</button>`);
}
async function doResetData(){
  if(val('rst-confirm')!=='RESET PORTAL DATA'){ toast('Please type RESET PORTAL DATA exactly.',true); return; }
  const cats=[...document.querySelectorAll('.rst-row input:checked')].map(x=>x.value);
  if(!cats.length){ toast('Select at least one category.',true); return; }
  const btn=document.getElementById('rst-btn'); btn.disabled=true; btn.textContent='Deleting\u2026';
  try{
    const r=await api('/api/admin/reset-data','POST',{confirm:'RESET PORTAL DATA',categories:cats});
    const rows=Object.entries(r.deleted||{}).map(([k,v])=>`<div class="rl-row"><span>${esc((RESET_CATS.find(c=>c.id===k)||{}).name||k)}</span><b>${v} deleted</b></div>`).join('');
    document.getElementById('rst-out').innerHTML=`<div class="alert alert-success" style="margin-top:12px"><b>Done!</b></div><div style="margin-top:8px">${rows}</div>${(r.errors||[]).length?`<div class="alert alert-warning" style="margin-top:8px">Issues: ${esc(r.errors.join(', '))}</div>`:''}`;
    btn.textContent='Deleted'; toast(r.message);
  }catch(e){ document.getElementById('rst-out').innerHTML=`<div class="alert alert-danger">${esc(e.message)}</div>`; btn.disabled=false; btn.innerHTML='Delete Selected Data'; }
}
