const ADMIN_SECTIONS=[
  ['dashboard','Dashboard'],['approvals','Approvals'],['live','Live Users'],['timetable','Time Table'],
  ['qbank','Study Material'],['material','Classes Material'],['doubts','Doubts'],['tests','Tests Tracker'],
  ['vtasks','Task Manager'],['ytasks','YouTuber Tasks'],['urgent','Urgent Videos'],['teachers','Teachers'],['reports','Teacher Reports'],['tranks','Teacher Ranking'],
  ['compliance','Class Compliance'],['attendance','Attendance'],['payouts','Payouts'],['students','Students'],
  ['notify','Send Notice'],['subjects','Subjects'],['syllabus','Syllabus Manager'],['categories','Teacher Categories'],['matcheck','Material Checker'],['complaints','Complaints'],['feedback','Feedback'],['admins','Admin Users']
];
let _aaFull=false, _aaSel=new Set(['dashboard']), _aaEdit={};
window._sddOpen=new Set();
document.addEventListener('click',()=>{ if(window._sddOpen.size){ window._sddOpen.clear(); document.querySelectorAll('.sdd.open').forEach(d=>d.classList.remove('open')); } });
function _aaSecName(k){ const f=ADMIN_SECTIONS.find(x=>x[0]===k); return f?f[1]:k; }
function _sddLabel(full,sel){
  if(full) return 'Full Access — Everything';
  const names=[...sel].filter(k=>k!=='dashboard').map(_aaSecName);
  if(!names.length) return 'Dashboard only';
  return 'Dashboard · '+names.slice(0,2).join(' · ')+(names.length>2?` +${names.length-2} more`:'');
}
function sddHTML(key,full,sel,editId){
  const open=window._sddOpen.has(key);
  const eid=editId?`,${editId}`:'';
  const rows=ADMIN_SECTIONS.map(([k,v])=>{
    const locked=k==='dashboard';
    const on=full||sel.has(k);
    return `<div class="sdd-row${full||locked?' dis':''}" onclick="${full||locked?'':`sddChip('${key}','${k}',event${eid})`}"><span class="sdd-cb${on?' on':''}">${on?'\u2713':''}</span><span>${v}</span>${locked?'<span class="sdd-hint">always included</span>':''}</div>`;
  }).join('');
  return `<div class="sdd${open?' open':''}" id="sdd-${key}">
    <div class="sdd-trig" onclick="sddToggle('${key}',event)"><span class="tt">${_sddLabel(full,sel)}</span>${!full&&sel.size>1?`<span class="sdd-count">${sel.size} sections</span>`:''}<span class="sdd-chev">\u25BC</span></div>
    <div class="sdd-panel">
      <div class="sdd-row full" onclick="sddFull('${key}',event${eid})"><span class="sdd-cb${full?' on':''}">${full?'\u2713':''}</span><span>Full Access — Everything</span><span class="sdd-hint">all ${ADMIN_SECTIONS.length} sections</span></div>
      ${rows}
    </div></div>`;
}
function sddToggle(key,ev){ ev.stopPropagation(); const el=document.getElementById('sdd-'+key); if(!el) return; const willOpen=!el.classList.contains('open'); window._sddOpen.clear(); document.querySelectorAll('.sdd.open').forEach(d=>d.classList.remove('open')); if(willOpen){ el.classList.add('open'); window._sddOpen.add(key); } }
function _sddState(editId){ return editId?(_aaEdit[editId]||{full:false,sel:new Set(['dashboard'])}):{full:_aaFull,sel:_aaSel}; }
function sddChip(key,k,ev,editId){ if(ev)ev.stopPropagation(); const st=_sddState(editId); if(st.sel.has(k)) st.sel.delete(k); else st.sel.add(k); sddRerender(key,editId); }
function sddFull(key,ev,editId){ if(ev)ev.stopPropagation(); if(editId){ const st=_aaEdit[editId]; if(st) st.full=!st.full; } else { _aaFull=!_aaFull; } sddRerender(key,editId); }
function sddRerender(key,editId){ const box=document.getElementById('sdd-wrap-'+key); if(!box) return; const st=_sddState(editId); box.innerHTML=sddHTML(key,st.full,st.sel,editId); }
async function loadAAdmins(){
  const el=document.getElementById('a-admins-content');
  softSpin(el);
  let admins=[];
  try{ const d=await api('/api/admin/admins'); admins=d.admins||[]; }
  catch(e){ el.innerHTML=errHtml(e); return; }
  window._aaAdmins=admins;
  const rows=admins.map(a=>{
    const badge=a.full_access?'<span class="adm-badge-full">FULL ACCESS</span>':`<span class="adm-badge-secs">${(a.sections||[]).length} SECTIONS</span>`;
    const off=a.is_active?'':'<span class="adm-badge-off">DEACTIVATED</span>';
    const secs=a.full_access?[]:(a.sections||[]).filter(s=>s!=='dashboard');
    const secLine=secs.length?`<div class="adm-meta">Access: ${secs.map(_aaSecName).join(' · ')}</div>`:`<div class="adm-meta">${a.full_access?'Can open every section, including Payouts.':'Dashboard only'}</div>`;
    const st=_aaEdit[a.id];
    const editBox=(st&&st.open)?`<div style="flex-basis:100%"></div><div class="adm-edit"><div class="ae-title">Edit Admin</div><div class="aa-grid"><div class="form-group" style="margin-bottom:10px"><label>Name</label><input class="form-control" id="aa-ename-${a.id}" value="${esc(st.name)}" maxlength="60"></div><div class="form-group" style="margin-bottom:10px"><label>Access</label><div id="sdd-wrap-edit-${a.id}">${sddHTML('edit-'+a.id,st.full,st.sel,a.id)}</div></div></div><div style="display:flex;gap:8px;margin-top:2px"><button class="btn btn-primary btn-sm" onclick="aaSaveEdit(${a.id})">Save Changes</button><button class="btn btn-ghost btn-sm" onclick="aaEditClose(${a.id})">Cancel</button></div></div>`:'';
    return `<div class="adm-row${a.is_active?'':' off'}"><div class="adm-ava">${esc(initials(a.name))}</div><div class="adm-main"><div class="adm-name">${esc(a.name)} ${badge} ${off}</div><div class="adm-meta">User ID: <b>${esc(a.user_id)}</b>${a.created_at?' · since '+esc(a.created_at.slice(0,10)):''}</div>${secLine}</div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-ghost btn-sm" onclick="openResetPassword('admin',${a.id},'${esc(a.name).replace(/'/g,'')}')">Login</button><button class="btn btn-ghost btn-sm" onclick="aaEditOpen(${a.id})">${(st&&st.open)?'Close':'Edit'}</button><button class="btn ${a.is_active?'btn-danger':'btn-primary'} btn-sm" onclick="aaToggleAdmin(${a.id},'${esc(a.name).replace(/'/g,'')}',${a.is_active})">${a.is_active?'Deactivate':'Activate'}</button></div>${editBox}</div>`;
  }).join('');
  el.innerHTML=`
    <div class="sm-head"><h2>Admin Users</h2><p>Create admins with exactly the access they need — their panel shows only the sections you allow. Everything else, including Payouts, stays hidden.</p></div>
    <div class="card"><div class="card-header"><h3>Create New Admin</h3></div><div class="card-body">
      <div class="alert alert-info">Just enter a name — the User ID and password are generated automatically. Pick the sections this admin may open, or give Full Access.</div>
      <div class="aa-grid"><div class="form-group"><label>Name</label><input class="form-control" id="aa-name" placeholder="e.g. Coordinator Raj" maxlength="60"></div>
      <div class="form-group"><label>Access</label><div id="sdd-wrap-new">${sddHTML('new',_aaFull,_aaSel)}</div></div></div>
      <button class="btn btn-primary" onclick="submitAddAdmin()">Create Admin</button>
      <div id="aa-result"></div>
    </div></div>
    <div class="card"><div class="card-header"><h3>Existing Admins</h3><span class="tc-count">${admins.length}</span></div><div class="card-body">${rows||'<div class="ws-empty"><p>No admins yet</p></div>'}</div></div>`;
}
async function submitAddAdmin(){
  const name=val('aa-name').trim();
  if(!name){ toast('Please enter a name.',true); return; }
  const body={name, sections:_aaFull?null:[..._aaSel]};
  try{
    const r=await api('/api/admin/admins/add','POST',body);
    const secs=r.full_access?'Full Access — every section':(r.sections||[]).map(_aaSecName).join(' · ');
    document.getElementById('aa-result').innerHTML=`<div class="adm-cred"><h4>Admin Created — share these credentials</h4><p>This password is shown only once. Copy it now and share it with ${esc(r.name)}.</p>
      <div class="adm-cred-row"><span class="k">Name</span><code>${esc(r.name)}</code></div>
      <div class="adm-cred-row"><span class="k">User ID</span><code id="aa-cred-uid">${esc(r.user_id)}</code><button class="btn btn-ghost btn-sm" onclick="aaCopy('aa-cred-uid')">Copy</button></div>
      <div class="adm-cred-row"><span class="k">Password</span><code id="aa-cred-pw">${esc(r.password)}</code><button class="btn btn-ghost btn-sm" onclick="aaCopy('aa-cred-pw')">Copy</button></div>
      <div class="adm-cred-row"><span class="k">Access</span><span style="font-size:.8rem;font-weight:700">${esc(secs)}</span></div></div>`;
    document.getElementById('aa-name').value='';
    _aaFull=false; _aaSel=new Set(['dashboard']);
    toast('Admin created.');
    loadAAdmins_keepResult();
  }catch(e){ toast(e.message,true); }
}
async function loadAAdmins_keepResult(){
  const keep=document.getElementById('aa-result')?document.getElementById('aa-result').innerHTML:'';
  await loadAAdmins();
  const rb=document.getElementById('aa-result');
  if(rb&&keep) rb.innerHTML=keep;
}
function aaCopy(elId){
  const t=(document.getElementById(elId)||{}).textContent||'';
  if(!t) return;
  if(navigator.clipboard&&navigator.clipboard.writeText){ navigator.clipboard.writeText(t).then(()=>toast('Copied: '+t)); }
  else{ const ta=document.createElement('textarea'); ta.value=t; document.body.appendChild(ta); ta.select(); try{ document.execCommand('copy'); toast('Copied: '+t); }catch(e){} ta.remove(); }
}
function aaEditOpen(id){
  const a=(window._aaAdmins||[]).find(x=>x.id===id);
  if(!a) return;
  if(_aaEdit[id]&&_aaEdit[id].open){ delete _aaEdit[id]; }
  else{ _aaEdit[id]={open:true, name:a.name, full:!!a.full_access, sel:new Set(a.full_access?['dashboard']:(a.sections&&a.sections.length?a.sections:['dashboard']))}; }
  loadAAdmins();
}
function aaEditClose(id){ delete _aaEdit[id]; loadAAdmins(); }
async function aaSaveEdit(id){
  const st=_aaEdit[id];
  if(!st) return;
  const name=((document.getElementById('aa-ename-'+id)||{}).value||'').trim();
  if(!name){ toast('Name cannot be empty.',true); return; }
  try{
    const r=await api('/api/admin/admins/'+id+'/edit','POST',{name, sections:st.full?null:[...st.sel], full_access:st.full});
    toast(r.message||'Admin updated.');
    if(window._adminMe&&window._adminMe.id===id){
      const an=document.getElementById('a-name'); if(an) an.textContent=name;
      const av=document.getElementById('a-avatar'); if(av) av.textContent=initials(name);
      window._adminMe.name=name; NAME=name;
    }
    delete _aaEdit[id];
    loadAAdmins();
  }catch(e){ toast(e.message,true); }
}
async function aaToggleAdmin(id,name,isActive){
  const msg=isActive?`Deactivate ${name}? They will not be able to log in until you activate them again.`:`Activate ${name} again?`;
  if(!confirm(msg)) return;
  try{ const r=await api('/api/admin/admins/'+id+'/toggle','POST',{}); toast(r.message||'Done.'); loadAAdmins(); }
  catch(e){ toast(e.message,true); }
}

