async function openStudent(){
  try{_saveSession();}catch(e){}
  try{initNavAccordion();}catch(e){} try{initNavCollapse();}catch(e){} [400,1200].forEach(function(d){ setTimeout(function(){ try{ document.querySelectorAll(".app .sidebar-nav").forEach(function(nav){ if(typeof _accGroupClose==="function") _accGroupClose(nav,false); }); }catch(e){} }, d); });
  // batch mode sabse pehle — taaki sidebar/pages sahi dikhein
  api('/api/student/profile').then(p=>{
    window._sBatch=p.batch_name||p.batch||'';
    window._sClass=p.class_level||'12';
    window._sSubjects=p.subjects||[];
    applyBatchMode();
  }).catch(()=>{});
  // Profile complete? (subjects + batch + medium sab chahiye)
  try{
 const p=await api('/api/student/profile');
 if(!p.class_level || !p.subjects || p.subjects.length===0 || !p.batch_name || !p.medium || !STUDENT_BATCHES.some(b=>b.name===p.batch_name)){
 _prefillSubjects=p.subjects||[];
 showSubjectScreen(p);
 return;
 }
  }catch(e){ /* if profile fails, continue to app */ }
  enterStudentApp();
}
function selectBatch(name){
  selectedBatch=name;
  const b=STUDENT_BATCHES.find(x=>x.name===name);
  document.querySelectorAll('#batch-grid .batch-opt').forEach(el=>{
    el.className='btn batch-opt '+(el.dataset.b===name?'btn-primary':'btn-ghost');
  });
  document.getElementById('medium-wrap').style.display='block';
  document.getElementById('subj-cls-tag').textContent='(Class '+b.cls+')';
  selectClass(b.cls); // batch decides the class -> loads that class's subjects
}
function selectMedium(m){
  selectedMedium=m;
  document.getElementById('med-Hindi').className=m==='Hindi'?'btn btn-primary':'btn btn-ghost';
  document.getElementById('med-English').className=m==='English'?'btn btn-primary':'btn btn-ghost';
}
function enterStudentApp(){
  document.getElementById('subject-screen').style.display='none';
  document.getElementById('teacher-app').classList.remove('active');
  document.getElementById('student-app').classList.add('active');
  document.getElementById('s-name').textContent=NAME;
  document.getElementById('s-avatar').textContent=initials(NAME);
  loadTopAvatar('student');
  document.querySelectorAll('#student-app .nav-item').forEach(n=>n.classList.remove('active'));
  document.querySelector('#student-app .nav-item').classList.add('active');
  try{ initStudentSupport(); }catch(e){}
  sPage('dashboard',null);
  notifPopupOnOpen('student');
  loadStudentLiveBanner();
  startStudentHeartbeat();
  startStudentPreload();
}
// Sab main pages ko background mein pehle se load kar do — pehli click par bhi
// spinner nahi dikhega, sab kuch instant khulega (silent refresh hota rahega).
let _preloaded=false;
function startStudentPreload(){
  if(_preloaded) return; _preloaded=true;
  const jobs=[loadSTimetable,()=>{ if(sMode()!=='syc') loadSMaterials(); },loadSQBank,loadSTeachers,()=>{ if(sMode()==='live'&&!window._sDppOpenPid) loadSDpp(); },loadSTests,loadSDoubts,loadSProgress,loadSProfile];
  jobs.forEach((fn,i)=>{ setTimeout(()=>{ try{ fn(); }catch(e){} }, 1200+i*450); });
}
async function loadStudentLiveBanner(){
  try{ if(sMode()==='live'){ const ents=await api('/api/student/timetable-plan'); startLiveCountdown(ents); } }catch(e){}
}
function showSubjectScreen(p){
  selectedClass=null; selectedSubjects=[]; selectedBatch=null; selectedMedium=null;
  document.getElementById('subject-screen').style.display='flex';
  document.getElementById('subject-list-wrap').style.display='none';
  document.getElementById('medium-wrap').style.display='none';
  document.getElementById('batch-grid').innerHTML=STUDENT_BATCHES.map(b=>
    `<button class="btn btn-ghost batch-opt" data-b="${esc(b.name)}" style="justify-content:space-between;font-size:.82rem;padding:10px 12px" onclick="selectBatch('${esc(b.name)}')">${esc(b.name)}<span style="font-size:.66rem;opacity:.75;background:rgba(255,255,255,.14);padding:2px 7px;border-radius:99px">Class ${b.cls}</span></button>`).join('');
  // prefill (existing students): medium pre-select if already saved
  if(p&&p.medium) selectMedium(p.medium);
}
async function selectClass(cls){
  selectedClass=cls; selectedSubjects=[];
  const wrap=document.getElementById('subject-checkboxes');
  wrap.innerHTML='<div class="spinner" style="margin:20px auto"></div>';
  document.getElementById('subject-list-wrap').style.display='block';
  try{
 const subs=await api('/api/student/available-subjects?class_level='+cls);
 if(subs.length===0){ wrap.innerHTML='<p style="color:#fff;text-align:center">No subjects available (please contact the admin).</p>'; return; }
 wrap.innerHTML=subs.map(s=>`<label style="display:flex;align-items:center;gap:8px;padding:8px;color:#fff;cursor:pointer"><input type="checkbox" value="${esc(s.name)}" onchange="toggleSubject(this)"> ${esc(s.name)} ${s.code?'('+esc(s.code)+')':''}</label>`).join('');
 // pre-tick subjects the student had already chosen earlier
 wrap.querySelectorAll('input[type=checkbox]').forEach(cb=>{
   if(_prefillSubjects.includes(cb.value) && selectedSubjects.length<7){ cb.checked=true; selectedSubjects.push(cb.value); }
 });
 updateSubjCount();
  }catch(e){ wrap.innerHTML='<p style="color:#fff">Error: '+esc(e.message)+'</p>'; }
}
function toggleSubject(cb){
  if(cb.checked){
 if(selectedSubjects.length>=7){ cb.checked=false; toast('No more than 7. ',true); return; }
 selectedSubjects.push(cb.value);
  }else{
 selectedSubjects=selectedSubjects.filter(s=>s!==cb.value);
  }
  updateSubjCount();
}
function updateSubjCount(){ document.getElementById('subj-count').textContent=selectedSubjects.length+'/7'; }
async function saveSubjects(){
  if(!selectedBatch){ toast('Please select your batch first.',true); return; }
  if(!selectedMedium){ toast('Please select your medium (Hindi/English).',true); return; }
  if(!selectedClass){ toast('Please select a class.',true); return; }
  if(selectedSubjects.length===0){ toast('Please select at least one subject.',true); return; }
  const btn=document.getElementById('save-subj-btn'); btn.disabled=true; btn.textContent='Saving...';
  try{
 await api('/api/student/set-subjects','POST',{class_level:selectedClass,subjects:selectedSubjects,batch_name:selectedBatch,medium:selectedMedium});
 toast('Profile saved successfully!');
 enterStudentApp();
  }catch(e){ toast(e.message,true); }
  btn.disabled=false; btn.textContent='Save & Continue →';
}
// ============ BATCH MODE ============
// live = Lakshya/Udaan (timetable + sab kuch)
// rec  = Manzil/Aarambh (recorded; Classes Material milta hai)
// syc  = Safalta/Jeet — On Demand/SYC (recorded; sirf Study Material)
function sMode(){
  const b=(window._sBatch||'').toLowerCase();
  if(b.includes('safalta')||b.includes('jeet')) return 'syc';
  if(b.includes('manzil')||b.includes('aarambh')) return 'rec';
  return 'live';
}
function applyBatchMode(){
  const m=sMode();
  document.querySelectorAll("#student-app .nav-item").forEach(n=>{
    const oc=n.getAttribute('onclick')||'';
    // On Demand/SYC: Classes Material hatao (sirf Study Material)
    if(oc.includes("sPage('materials'")) n.style.display=(m==='syc')?'none':'';
    // Recorded batches (sab): DPP Submit ki zaroorat nahi
    if(oc.includes("sPage('dpp'")) n.style.display=(m!=='live')?'none':'';
  });
}
function sPage(page,el){
  navPush('student-app',page);
  if(page==='materials'&&sMode()==='syc'){ toast('Your batch uses Study Material only.'); page='qbank'; el=null; }
  if(page==='dpp'&&sMode()!=='live'){ toast('DPPs are not part of recorded batches.'); page='dashboard'; el=null; }
  document.querySelectorAll('#student-app .page').forEach(p=>p.classList.remove('active'));
  document.getElementById('s-page-'+page).classList.add('active');
  if(el){ document.querySelectorAll('#student-app .nav-item').forEach(n=>n.classList.remove('active')); el.classList.add('active'); }
  const titles={dashboard:'Home',timetable:'Time Table',materials:'Classes Material',teachers:'Know Your Teacher',dpp:'DPP Submit',tests:'Tests',doubts:'Doubts',progress:'Progress',syllabus:'Syllabus Tracker',resultcard:'Result Card',notifications:'Notifications',profile:'My Profile',qbank:'Study Material',complaints:'Complaints',feedback:'Feedback & Ratings'};
  _setPage(titles[page]||page);
  document.getElementById('s-title').textContent=titles[page]||page;
  stopCountdown();
  _curLoader=function(){ _sLoadPage(page); };
  _sLoadPage(page);
}
function _sLoadPage(page){
  if(page==='dashboard') loadSDashboard();
  else if(page==='timetable') loadSTimetable();
  else if(page==='materials') loadSMaterials();
  else if(page==='teachers') loadSTeachers();
  else if(page==='dpp') loadSDpp();
  else if(page==='tests') loadSTests();
  else if(page==='doubts') loadSDoubts();
  else if(page==='progress') loadSProgress();
  else if(page==='syllabus') loadSSyllabus();
  else if(page==='resultcard') loadSResultCards();
  else if(page==='notifications') loadSNotif();
  else if(page==='profile') loadSProfile();
  else if(page==='qbank') loadSQBank();
  else if(page==='complaints') loadSComplaints();
  else if(page==='feedback') loadSFeedback();
}

async function loadSProfile(){
  const el=document.getElementById('s-profile-content');
  try{
    const p=await api('/api/student/profile');
    const subs=(p.subjects||[]).map(s=>`<span class="chip">${esc(s)}</span>`).join('')||'<span style="color:var(--text-muted)">No subjects selected yet</span>';
    const rows=[
      ['User ID', p.user_id||'—'],
      ['Phone', p.phone||'—'],
      ['Email', p.email||'—'],
      ['Batch', p.batch_name||'—'],
      ['Medium', p.medium||'—'],
      ['Class', p.class_level?('Class '+p.class_level):'—'],
      ['Exam Session', (p.exam_session_label||_sylSessName(p.exam_session)||'—')],
      ['Exam Stream', p.exam_stream?('Stream '+p.exam_stream):'—'],
      ['NIOS Reference', p.nios_ref||'—'],
    ];
    el.innerHTML=`<div class="card glass-soft"><div class="card-body">
      <div class="prof-head">
        <div class="prof-photo" id="prof-photo">${esc(initials(p.name||'S'))}</div>
        <div class="prof-id"><h2>${esc(p.name||'Student')}</h2><span class="chip" style="margin-top:6px">${esc(p.batch_name||'MVS Foundation Student')}</span></div>
        <button class="btn btn-primary btn-sm" onclick="openSetStudentPhoto()">${ic('upload')} Change Photo</button>
      </div>
      <div class="prof-grid">
        ${rows.map(([k,v])=>`<div class="prof-cell"><div class="prof-k">${k}</div><div class="prof-v">${esc(v)}</div></div>`).join('')}
      </div>
      <div class="prof-cell" style="margin-top:14px"><div class="prof-k">Subjects</div><div class="slist-chips" style="margin-top:6px">${subs}</div></div>
    </div></div>`;
    // load photo if set
    if(p.has_photo){
      try{ const r=await fetch(API+_selfPhoto('student'),{headers:{Authorization:'Bearer '+TOKEN}});
        if(r.ok){ const u=URL.createObjectURL(await r.blob()); const d=document.getElementById('prof-photo'); d.style.backgroundImage=`url(${u})`; d.textContent=''; } }catch(e){}
    }
  }catch(e){ el.innerHTML=errHtml(e); }
}

// Manish Verma Classes App — lectures live here, not in this portal.
// ============ MANISH VERMA CLASSES APP — SMART OPEN ============
// Android: app installed -> app khulta hai; nahi -> seedha Play Store listing
// iOS: Manish Verma Classes ki apni App Store listing (id6768236345)
// Desktop: web platform
const MVC_ANDROID_PKG='com.manish.verma.classes';
const MVC_PLAY_URL='https://play.google.com/store/apps/details?id='+MVC_ANDROID_PKG;
const MVC_WEB_URL='https://classes.mvsfoundation.in/';
const MVC_IOS_URL='https://apps.apple.com/app/manish-verma-classes/id6768236345';
function openMVC(){
  const ua=navigator.userAgent||'';
  // iPad newer iOS me khud ko "Macintosh" batata hai — touch se pakdo
  const isIOS=/iphone|ipad|ipod/i.test(ua)||(/macintosh/i.test(ua)&&navigator.maxTouchPoints>1);
  const isAndroid=!isIOS&&/android/i.test(ua);

  if(isIOS){
    // iOS: app ki apni App Store listing seedha App Store app me khulti hai.
    // App installed hai to wahan "Open" button hota hai (Apple 1-tap direct open
    // sirf tab deta hai jab app me universal links configure hon — abhi nahi hain).
    location.href='itms-apps://apps.apple.com/app/manish-verma-classes/id6768236345';
    setTimeout(()=>{ if(!document.hidden) location.href=MVC_IOS_URL; },1400);
    return;
  }
  if(isAndroid){
    // intent: app installed -> app khulti hai; nahi -> seedha Play Store listing
    location.href='intent://open/#Intent;scheme=mvc;package='+MVC_ANDROID_PKG
      +';S.browser_fallback_url='+encodeURIComponent(MVC_PLAY_URL)+';end';
    setTimeout(()=>{ if(!document.hidden) location.href=MVC_PLAY_URL; },1500);
    return;
  }
  window.open(MVC_WEB_URL,'_blank');   // desktop -> web platform
}
function mvcIosSheet(){
  const old=document.getElementById('mvc-sheet'); if(old) old.remove();
  const ov=document.createElement('div'); ov.id='mvc-sheet'; ov.className='mvc-ov';
  ov.innerHTML=`<div class="mvc-sh">
      <div class="mvc-grab"></div>
      <div class="mvc-ttl">Watch on Manish Verma Classes</div>
      <a class="mvc-btn mvc-app" href="${MVC_WEB_URL}">${ic('play')} Open the App</a>
      <a class="mvc-btn mvc-store" href="itms-apps://apps.apple.com/app/manish-verma-classes/id6768236345">${ic('upload')} Get it on the App Store</a>
      <p class="mvc-note">If the app is installed, <b>Open the App</b> will launch it directly. Otherwise, install it from the App Store.</p>
      <button class="mvc-cancel" onclick="document.getElementById('mvc-sheet').remove()">Cancel</button>
    </div>`;
  ov.addEventListener('click',e=>{ if(e.target===ov) ov.remove(); });
  document.body.appendChild(ov);
  requestAnimationFrame(()=>ov.classList.add('show'));
}
const _WS_PRIO_IC={lecture:'play',test:'edit',dpp:'clipboard',material:'book'};
const _WS_TASK_ACT={lecture:'mvc',dpp:'dpp',test:'tests',material:'materials'};
function wsGo(page){ if(page==='mvc'){ openMVC(); return; } navTo('student-app',page); }

// Recorded batches (Safalta/Jeet/Manzil/Aarambh): timetable nahi hota —
// sirf recorded subjects + Watch (app) + pending lecture verifications
// ============ APP REVIEW (moderated) ============
function starRow(sel,name){
  return `<div class="str-row" id="${name}">${[1,2,3,4,5].map(i=>`<span class="str ${i<=sel?'on':''}" onclick="setStars('${name}',${i})">\u2605</span>`).join('')}</div>`;
}
function setStars(name,n){
  window['_'+name]=n;
  document.querySelectorAll('#'+name+' .str').forEach((el,i)=>el.classList.toggle('on',i<n));
}
async function openWriteReview(){
  let mine={exists:false};
  try{ mine=await api('/api/student/app-review'); }catch(e){}
  window._rvStars=mine.rating||5;
  showModal('\u2b50 Rate & Review',
    `<p style="font-size:.83rem;color:var(--text-muted);margin-bottom:10px">Write your review here \u2014 on Save you will be taken straight to the <b>Play Store</b>, where you can paste and post it (the text is copied for you).</p>
     <label class="ex-lbl">Your Rating</label>${starRow(window._rvStars,'rvStars')}
     <label class="ex-lbl" style="margin-top:12px">Your Review</label>
     <textarea class="form-control" id="rv-text" rows="5" placeholder="Share your experience with the app and the classes\u2026">${esc(mine.review||'')}</textarea>
     <div id="rv-status"></div>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" id="rv-btn" onclick="submitReview()">${ic('upload')} Save &amp; Review on Play Store</button>`);
}
async function submitReview(){
  const text=val('rv-text');
  const btn=document.getElementById('rv-btn'); btn.disabled=true; btn.textContent='Saving\u2026';
  try{
    await api('/api/student/app-review','POST',{rating:window._rvStars||5,review:text});
    closeModal();
    postToStore(text);
  }catch(e){ document.getElementById('rv-status').innerHTML=`<div class="alert alert-danger">${esc(e.message)}</div>`; btn.disabled=false; btn.innerHTML='Save &amp; Review on Play Store'; }
}
function postToStore(text){
  try{ navigator.clipboard.writeText(text||''); toast('Review copied \u2014 paste it on the store!'); }catch(e){}
  const ua=navigator.userAgent||'';
  const isIOS=/iphone|ipad|ipod/i.test(ua)||(/macintosh/i.test(ua)&&navigator.maxTouchPoints>1);
  if(isIOS){ location.href='https://apps.apple.com/app/manish-verma-classes/id6768236345?action=write-review'; return; }
  if(/android/i.test(ua)){ location.href='market://details?id='+MVC_ANDROID_PKG+'&showAllReviews=true';
    setTimeout(()=>{ if(!document.hidden) location.href=MVC_PLAY_URL+'&showAllReviews=true'; },1200); return; }
  window.open(MVC_PLAY_URL+'&showAllReviews=true','_blank');
}
function renderRecordedTimetable(el){
  const subs=window._sSubjects||[];
  const rows=subs.length?subs.map(s=>`<div class="rb-row">
      <div class="rb-ic">${ic('play')}</div>
      <div class="rb-main"><div class="rb-sub">${esc(s)}</div><div class="rb-note">Recorded lectures \u00b7 watch anytime in the app</div></div>
      <button class="btn btn-primary btn-sm rb-watch" onclick="openMVC()" title="Open the Manish Verma Classes app to watch this subject's recorded lectures">${ic('play')} Watch Lectures</button>
    </div>`).join(''):`<div class="empty-state"><p>No subjects on your profile yet. Please contact the admin.</p></div>`;
  el.innerHTML=`<div id="s-verify-wrap"></div>
    <div class="rb-grid">
      <div class="rb-hero">
        <div class="rb-badge">${ic('play')} RECORDED BATCH</div>
        <h2>${esc(window._sBatch||'Your Batch')}</h2>
        <p>All classes in your batch are <b>pre-recorded</b> \u2014 there is no live timetable. Watch every lecture for your subjects <b>anytime, at your own pace</b>, in the Manish Verma Classes app.</p>
        <button class="btn rb-cta" onclick="openMVC()">${ic('play')} Open the App &amp; Start Watching</button>
      </div>
      <div class="ps-card" id="rb-ps-card"></div>
    </div>
    <div class="sm-head" style="margin-top:24px"><h2>Your Recorded Subjects</h2></div>
    <div class="rb-list">${rows}</div>`;
  _renderPlayCard();
  _loadPendingVerifications();
}
// Play Store card — live rating/downloads (backend 12h cache se)
async function _renderPlayCard(){
  const box=document.getElementById('rb-ps-card'); if(!box) return;
  let a={name:'Manish Verma Classes',dev:'MVS FOUNDATION',rating:'4.6',reviews:'1.53K',downloads:'50K+',icon:null};
  try{ a=await api('/api/student/app-info'); }catch(e){}
  const icon=a.icon?`<img class="ps-icon" src="${esc(a.icon)}" alt="">`:`<div class="ps-icon ps-icon-f">MVS</div>`;
  box.innerHTML=`${icon}
    <div class="ps-name">${esc(a.name)}</div>
    <div class="ps-dev">${esc(a.dev)}</div>
    <div class="ps-stats">
      <div class="ps-stat"><b>${esc(a.rating)} \u2605</b><span>${esc(a.reviews)} reviews</span></div>
      <div class="ps-div"></div>
      <div class="ps-stat"><b>${esc(a.downloads)}</b><span>Downloads</span></div>
    </div>
    <button class="ps-btn" onclick="openMVC()">${ic('play')} Open the App</button>
    <button class="ps-rev" onclick="openWriteReview()">\u2b50 Rate &amp; Review</button>
    <div class="ps-links"><a href="${MVC_PLAY_URL}" target="_blank" rel="noopener">Google Play</a><i></i><a href="${MVC_IOS_URL}" target="_blank" rel="noopener">App Store</a></div>`;
}
function dismissPrio(ev){
  ev.stopPropagation();
  const c=ev.target.closest('.prio-card'); if(c) c.remove();
  try{ localStorage.setItem('s_prio_hide', new Date().toLocaleDateString('en-CA')); }catch(e){}
}
async function loadSDashboard(){
  const el=document.getElementById('s-dashboard-content');
  try{
    let w={},prof={};
    try{ w=await api('/api/student/workspace'); }catch(e){ w={}; }
    try{ prof=await api('/api/student/profile'); }catch(e){}
    const batch=prof.batch_name||'';
    document.getElementById('s-batch').textContent=batch||'Student';

    // ---- My Stats (clickable cards: syllabus / DPP / tests / doubts + batch rank chip)
    let _ms={syl:null,dpp:null,test:null,doubt:null,rank:null};
    try{
      const perf=await api('/api/student/performance');
      _ms.dpp={done:perf.dpp.done,total:perf.dpp.total,pend:Math.max(0,perf.dpp.total-perf.dpp.done)};
      _ms.test={done:perf.tests.done,total:perf.tests.total,miss:Math.max(0,perf.tests.total-perf.tests.done)};
    }catch(e){}
    try{
      const ov2=await api('/api/syllabus/overview');
      let cw=0,tw=0;
      (ov2.subjects||[]).forEach(x=>{ if(x.calc){ const pm=x.calc.paper_marks||x.calc.total_pe_marks||0; tw+=pm; cw+=Math.min(pm,x.calc.covered_paper||0); } });
      if(tw>0) _ms.syl={pct:Math.round(cw/tw*100)};
    }catch(e){}
    try{
      const db2=await api('/api/student/doubts');
      const res=(db2||[]).filter(x=>x.status==='resolved').length;
      _ms.doubt={total:(db2||[]).length,res:res,pend:(db2||[]).length-res};
    }catch(e){}
    try{
      const bb2=await api('/api/student/batch-board');
      if(bb2&&bb2.me) _ms.rank={r:bb2.me.rank,t:bb2.total};
    }catch(e){}
    // v114: Classes Material ke naye uploads ka nav badge (cache-friendly)
    try{ const mats0=await api('/api/student/materials-v2'); window._sMatNew=_matNewIds('student',mats0); _matBadge('student'); }catch(e){}

    // ---- Today's Priority (hidden when the upcoming-test banner already covers a test)
    const _up=await _sUpcomingExam();
    const p=w.priority||{kind:'lecture',label:"Watch today's lecture",title:'Open the Manish Verma Classes App',action:'mvc'};
    const isLec=p.action==='mvc'||p.kind==='lecture';
    const _dupeTest=_up&&(p.kind==='test'||p.action==='tests');
    const _prioHidden=(()=>{ try{ return localStorage.getItem('s_prio_hide')===new Date().toLocaleDateString('en-CA'); }catch(e){ return false; } })();
    const prio=(_dupeTest||_prioHidden)?'':`<div class="prio-card"><button class="prio-x" onclick="dismissPrio(event)" title="Hide for today">&times;</button><div class="prio-ic">${ic(_WS_PRIO_IC[p.kind]||'play')}</div><div class="prio-body"><div class="prio-tag">Today's Priority</div><h3>${esc(p.label||'')}</h3>${p.title?`<p>${esc(p.title)}</p>`:''}</div><button class="prio-btn" onclick="wsGo('${isLec?'mvc':(p.action||'materials')}')">${isLec?'Open MVC App':'Start now'}</button></div>`;

    // ---- Today's Tasks
    const tasks=(w.tasks||[]);
    const tasksHtml=`<div class="card"><div class="card-header"><h3>Today's Tasks</h3></div><div class="card-body">${
      tasks.length?tasks.map(t=>`<div class="task-row ${t.done?'done':''}"><div class="task-box ${t.done?'on':''}">${t.done?ic('check'):''}</div><div class="task-txt">${esc(t.text)}</div>${t.done?'':`<button class="task-go" onclick="wsGo('${_WS_TASK_ACT[t.kind]||'materials'}')">Go \u2192</button>`}</div>`).join(''):'<div class="ws-empty"><div class="big">\u2705</div><p>You\u2019re all caught up!</p></div>'}</div></div>`;

    // ---- Pending Work
    const pn=w.pending||{dpps:0,tests:0,unread:0,deadlines_today:0};
    const cell=(n,l,pg)=>`<div class="pend-cell" onclick="wsGo('${pg}')"><div class="pend-num ${n===0?'zero':''}">${n}</div><div class="pend-lbl">${l}</div></div>`;
    const _rec=sMode()!=='live';
    if(_rec) pn.deadlines_today=0;
    const allZero=(pn.dpps+pn.tests+pn.unread+pn.deadlines_today)===0;
    const pendHtml=`<div class="card"><div class="card-header"><h3>Pending Work</h3></div><div class="card-body">${
      allZero?'<div class="ws-empty"><div class="big">\ud83c\udf89</div><p>Nothing pending. Great work!</p><small>Keep the momentum going.</small></div>'
      :`<div class="pend-grid">${_rec?'':cell(pn.dpps,'Pending DPPs','dpp')}${cell(pn.tests,'Pending Tests','tests')}${sMode()==='syc'?'':cell(pn.unread,'Unread Materials','materials')}${_rec?'':cell(pn.deadlines_today,'Due Today','timetable')}</div>`}</div></div>`;

    // ---- Study Progress overview
    const ov=w.overview||{materials_read:0,materials_total:0,dpp_pct:0,test_pct:0,subjects:0};
    const ovHtml=`<div class="card"><div class="card-header"><h3>Study Progress</h3></div><div class="card-body"><div class="ovv-grid"><div class="ovv-cell"><div class="ovv-num">${ov.subjects}</div><div class="ovv-lbl">Subjects</div></div><div class="ovv-cell"><div class="ovv-num">${ov.materials_read}/${ov.materials_total}</div><div class="ovv-lbl">Materials Read</div></div><div class="ovv-cell"><div class="ovv-num">${ov.dpp_pct}%</div><div class="ovv-lbl">DPP Done</div></div><div class="ovv-cell"><div class="ovv-num">${ov.test_pct}%</div><div class="ovv-lbl">Tests Done</div></div></div></div></div>`;

    // ---- Material Progress per subject
    const mp=(w.material_progress||[]).filter(x=>x.total>0);
    const mpHtml=`<div class="card"><div class="card-header"><h3>Material Progress</h3></div><div class="card-body">${
      mp.length?mp.map(s=>`<div class="mprog-row"><div class="mprog-top"><span class="mprog-sub">${esc(s.subject)}</span><span class="mprog-val">${s.done}/${s.total} chapters \u00b7 ${s.pct}%</span></div><div class="mprog-track"><div class="mprog-fill" style="width:${s.pct}%"></div></div></div>`).join(''):'<div class="ws-empty"><p>No materials yet</p><small>Chapter progress will appear as teachers add notes.</small></div>'}</div></div>`;

    // ---- Upcoming Deadlines
    const dls=_rec?[]:(w.deadlines||[]);
    const dlHtml=`<div class="card"><div class="card-header"><h3>Upcoming Deadlines</h3></div><div class="card-body">${
      dls.length?dls.map(d=>{const wl=d.days_left===0?'Today':(d.days_left===1?'Tomorrow':('in '+d.days_left+' days'));return `<div class="dl-row"><span class="dl-dot ${d.urgency}"></span><div class="dl-main"><div class="dl-title">${esc(d.title)}</div><div class="dl-sub">${esc(d.subject||'')} \u00b7 ${esc((d.type||'').toUpperCase())}</div></div><span class="dl-when ${d.urgency}">${wl}</span></div>`;}).join(''):'<div class="ws-empty"><div class="big">\ud83d\uddd3\ufe0f</div><p>No upcoming deadlines</p><small>You\u2019re ahead of schedule!</small></div>'}</div></div>`;

    // ---- Recent Activity
    const ac=(w.activity||[]);
    const acHtml=`<div class="card"><div class="card-header"><h3>Recent Activity</h3></div><div class="card-body">${
      ac.length?ac.map(a=>`<div class="act-row"><span class="act-dot"></span><div class="act-main"><div class="act-txt">${esc(a.text)}</div><div class="act-when">${esc(a.subject||'')}${a.when?' \u00b7 '+esc(a.when.replace('T',' ')):''}</div></div></div>`).join(''):'<div class="ws-empty"><p>No recent activity</p><small>Your opened & submitted work will show here.</small></div>'}</div></div>`;

    // ---- Quick Actions
    const qa=[['Open MVC App','play','mvc','mvc'],['Time Table','calendar','timetable',''],['Classes Material','book','materials',''],['Study Material','folder','qbank',''],['Submit DPP','clipboard','dpp',''],['Attempt Test','edit','tests',''],['Ask Doubt','help','doubts',''],['Progress','chart','progress','']];
    const qaHtml=`<div class="card"><div class="card-header"><h3>Quick Access</h3></div><div class="card-body"><div class="qa-grid">${qa.map(([l,i,pg,cls])=>`<button class="qa-btn ${cls}" onclick="wsGo('${pg}')"><div class="qa-ic">${ic(i)}</div><div class="qa-lbl">${l}</div></button>`).join('')}</div></div></div>`;

    const _statCell=(num,lbl,sub,pg,accent)=>`<div class="mstat-cell" onclick="wsGo('${pg}')" role="button">
        <div class="mstat-num ${accent?'acc':''}">${num}</div><div class="mstat-lbl">${lbl}</div><div class="mstat-sub">${sub}</div></div>`;
    const statsHtml=`<div class="card"><div class="card-header"><h3>My Stats</h3>${_ms.rank?`<span class="mstat-rank" onclick="wsGo('progress')" title="See your batch ranking">Batch Rank <b>#${_ms.rank.r}</b><small>/${_ms.rank.t}</small></span>`:''}</div><div class="card-body"><div class="mstat-grid">
      ${_statCell(_ms.syl?_ms.syl.pct+'%':'0%','Syllabus Covered',_ms.syl?'tap to open tracker':'start now — tap','syllabus',!_ms.syl)}
      ${_ms.dpp?_statCell(_ms.dpp.done+'/'+_ms.dpp.total,'DPPs Submitted',_ms.dpp.pend?(_ms.dpp.pend+' pending'):'all done','dpp',_ms.dpp.pend>0):''}
      ${_ms.test?_statCell(_ms.test.done+'/'+_ms.test.total,'Tests Given',_ms.test.miss?(_ms.test.miss+' missed'):'none missed','tests',_ms.test.miss>0):''}
      ${_ms.doubt?_statCell(_ms.doubt.total,'Doubts Asked',_ms.doubt.res+' resolved · '+_ms.doubt.pend+' pending','doubts',_ms.doubt.pend>0):''}
    </div></div></div>`;
    setIf(el,`${greetingCard(NAME)}<div id="s-live-banner" style="display:none"></div>
      ${prio}
      <div id="s-today-wrap"></div>
      ${statsHtml}
      ${qaHtml}`);
    loadStudentLiveBanner();
    _renderTodayClassesStudent();
    _sSchedBanner(el,_up);
  }catch(e){ el.innerHTML=errHtml(e); }
}

// Today's Classes on the student dashboard — subject, teacher (photo + name) and time slot.
// ---------- Today's / Tomorrow's / Custom-date classes (smart dropdown) ----------
let _tcMode='today', _tcDate=null;
async function _renderTodayClassesStudent(){
  const wrap=document.getElementById('s-today-wrap'); if(!wrap) return;
  if(sMode()!=='live'){
    setIf(wrap,`<div class="card"><div class="card-body" style="display:flex;gap:14px;align-items:center;flex-wrap:wrap">
        <div class="rb-ic" style="flex-shrink:0">${ic('play')}</div>
        <div style="flex:1;min-width:200px"><b>Recorded batch \u2014 no live classes.</b><div style="font-size:.8rem;color:var(--text-muted)">Watch the recorded lectures of your subjects anytime in the Manish Verma Classes app.</div></div>
        <button class="btn btn-primary btn-sm" onclick="openMVC()" title="Open the Manish Verma Classes app to watch the recorded lectures">${ic('play')} Watch Now</button>
      </div></div>`);
    return;
  }
  try{
    const plan=await api('/api/student/timetable-plan');
    window._tcPlan=plan||[];
    _tcPaint();
  }catch(e){ wrap.innerHTML=''; }
}
function _tcPaint(){
  const wrap=document.getElementById('s-today-wrap'); if(!wrap) return;
  const plan=window._tcPlan||[];
  const todayStr=istDateKey();
  const tmr=istNow(); tmr.setDate(tmr.getDate()+1);
  const tmrStr=tmr.toLocaleDateString('en-CA');
  const selDate=_tcMode==='today'?todayStr:_tcMode==='tomorrow'?tmrStr:(_tcDate||todayStr);
  const selD=new Date(selDate+'T00:00:00');
  const title=_tcMode==='today'?"Today's Classes":_tcMode==='tomorrow'?"Tomorrow's Classes":'Classes';
  const dStr=selD.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'});
  const list=plan.filter(e=>e.date===selDate).sort((a,b)=>_timeKey(a.time)-_timeKey(b.time));
  const ddBtn=(m,lbl)=>`<button class="tc-dd-btn ${_tcMode===m?'on':''}" onclick="tcSetDay('${m}')">${lbl}</button>`;
  const dd=`<div class="tc-dd">${ddBtn('today','Today')}${ddBtn('tomorrow','Tomorrow')}<button class="tc-dd-btn ${_tcMode==='custom'?'on':''}" onclick="tcSetDay('custom')">Pick date</button></div>`;
  let calHtml='';
  if(_tcMode==='custom'){
    const y=selD.getFullYear(), mo=selD.getMonth();
    const first=new Date(y,mo,1), dim=new Date(y,mo+1,0).getDate();
    const startDow=(first.getDay()+6)%7;
    const hasCls={}; plan.forEach(e=>{ if(e.date) hasCls[e.date]=1; });
    let cells='';
    ['M','T','W','T','F','S','S'].forEach(d=>cells+=`<span class="tc-cal-h">${d}</span>`);
    for(let k=0;k<startDow;k++) cells+='<span></span>';
    for(let d=1;d<=dim;d++){
      const iso=y+'-'+String(mo+1).padStart(2,'0')+'-'+String(d).padStart(2,'0');
      cells+=`<button class="tc-cal-d ${iso===selDate?'on':''} ${hasCls[iso]?'has':''} ${iso===todayStr?'today':''}" onclick="tcPickDate('${iso}')">${d}</button>`;
    }
    calHtml=`<div class="tc-cal"><div class="tc-cal-title">${selD.toLocaleDateString('en-GB',{month:'long',year:'numeric'})}</div><div class="tc-cal-grid">${cells}</div></div>`;
  }
  let rows='';
  if(!list.length){
    rows=`<div class="ws-empty"><div class="big">\u2615</div><p>No classes on ${dStr}</p><small>${_tcMode==='today'?'Use the free time to revise or clear pending work.':'Check another day from the buttons above.'}</small></div>`;
  }else{
    const nowMin=new Date().getHours()*60+new Date().getMinutes();
    rows=list.map(c=>{
      const isTest=(c.type||'')==='test'||/test|exam/i.test(c.chapter||'');
      // photo sirf tab jab teacher ki asli photo ho — initials wala S circle hata diya
      const photo=c.teacher_id?`<img class="tc-photo" src="" data-tid="${c.teacher_id}" alt="">`:'';
      const topic=esc(c.part||c.chapter||'');
      // v114: auto-Done HATA diya — 90 min ke baad bhi report ke bina "Done" nahi.
      // Teacher report submit kare (class_done) to Done + report ki asli duration;
      // slot nikal jaaye par report na ho to neutral "Class Held On".
      let chip='';
      if(c.class_done){
        chip='<span class="tc-chip done">Done</span>';
        if(c.duration_min) chip+=`<span class="tc-chip tc-dur" title="Actual class duration from the teacher's report">${c.duration_min} min</span>`;
      }
      else if(_tcMode==='today'){
        const st=_timeKey(c.time);
        if(st>nowMin) chip='<span class="tc-chip">Upcoming</span>';
        else if(nowMin<=st+90) chip='<span class="tc-chip live">Live</span>';
        else chip='<span class="tc-chip held" title="The class slot is over. It turns Done as soon as the teacher submits the class report.">Class Held On</span>';
      }
      else if(selDate<todayStr) chip='<span class="tc-chip held" title="The class slot is over. It turns Done as soon as the teacher submits the class report.">Class Held On</span>';
      else chip='<span class="tc-chip blink">Upcoming</span>';
      // report ke asli start-end time bhi slot ke neeche dikhao
      const actualTm=(c.class_done&&c.start_time&&c.end_time)?`<span class="tc-ta">${esc(c.start_time)} \u2013 ${esc(c.end_time)}</span>`:'';
      // class materials shortcut — report ke baad Class Notes ka seedha download button
      let matBtn='';
      if(c.class_done&&c.lecture_id&&(c.has_notes||c.has_dpp)){
        if(c.has_notes&&!c.has_dpp) matBtn=`<div class="tc-mat"><button class="tc-mat-btn" onclick="event.stopPropagation();tcMatDl(${c.lecture_id},'pdf')" title="Download this class's notes (PDF)">Class Notes</button></div>`;
        else if(c.has_dpp&&!c.has_notes) matBtn=`<div class="tc-mat"><button class="tc-mat-btn" onclick="event.stopPropagation();tcMatDl(${c.lecture_id},'dpp')" title="Download this class's DPP (PDF)">DPP</button></div>`;
        else matBtn=`<div class="tc-mat"><button class="tc-mat-btn" onclick="tcMatMenu(event,${c.lecture_id},${c.has_notes?1:0},${c.has_dpp?1:0})" title="Download this class's notes / DPP">Class Materials</button></div>`;
      }
      return `<div class="tc-row tc-link" onclick="sPage('timetable',null)" title="Open Time Table"><div class="tc-time"><span class="tc-t">${esc(c.time||'TBA')}</span>${actualTm}</div><div class="tc-body"><div class="tc-sub">${esc(c.subject)}${isTest?'<span class="tc-tag">TEST</span>':''}</div>${topic?`<div class="tc-topic">${topic}</div>`:''}</div><div class="tc-teach">${photo}<span class="tc-tname">${esc(c.teacher_name||'\u2014')}</span></div>${chip}${matBtn}<span class="slist-go">&rsaquo;</span></div>`;
    }).join('');
  }
  setIf(wrap,`<div class="card"><div class="card-header" style="flex-wrap:wrap;gap:8px"><h3>${title}</h3><span class="tc-date">${dStr}</span><span class="tc-count">${list.length} class${list.length===1?'':'es'}</span>${dd}</div>${calHtml}<div class="card-body">${rows}</div></div>`);
  wrap.querySelectorAll('img.tc-photo[data-tid]').forEach(async im=>{
    try{
      const r=await fetch(API+`/api/student/teacher/${im.dataset.tid}/photo`,{headers:{Authorization:'Bearer '+TOKEN}});
      if(!r.ok){ im.remove(); return; }   // photo nahi to circle hi hatao
      im.src=URL.createObjectURL(await r.blob());
    }catch(e){ im.remove(); }
  });
}
function tcSetDay(m){ _tcMode=m; if(m==='custom'&&!_tcDate) _tcDate=new Date().toLocaleDateString('en-CA'); _tcPaint(); }
function tcPickDate(iso){ _tcDate=iso; _tcPaint(); }
// Class Materials popup: Class Notes / DPP download
function tcMatMenu(ev,lid,hasNotes,hasDpp){
  ev.stopPropagation();
  document.querySelectorAll('.tc-mat-pop').forEach(x=>x.remove());
  const pop=document.createElement('div');
  pop.className='tc-mat-pop';
  pop.innerHTML=`${hasNotes?`<button onclick="tcMatDl(${lid},'pdf')">Class Notes (PDF)</button>`:''}${hasDpp?`<button onclick="tcMatDl(${lid},'dpp')">DPP (PDF)</button>`:''}`;
  pop.addEventListener('click',e=>e.stopPropagation());
  ev.target.closest('.tc-mat').appendChild(pop);
  setTimeout(()=>document.addEventListener('click',()=>pop.remove(),{once:true}),10);
}
async function tcMatDl(lid,kind){
  document.querySelectorAll('.tc-mat-pop').forEach(x=>x.remove());
  try{
    const r=await fetch(API+`/api/student/lecture/${lid}/file?kind=${kind}`,{headers:{Authorization:'Bearer '+TOKEN}});
    if(!r.ok) throw new Error('nf');
    const bl=await r.blob();
    const a=document.createElement('a'); a.href=URL.createObjectURL(bl);
    a.download=(kind==='dpp'?'DPP':'Class-Notes')+'.pdf'; a.click();
    toast((kind==='dpp'?'DPP':'Class notes')+' download started.');
  }catch(e){ toast('File not available yet.'); }
}
function _timeKey(t){
  if(!t) return 9999;
  const m=String(t).match(/(\d{1,2})[:.](\d{2})\s*(am|pm)?/i);
  if(!m) return 9999;
  let h=parseInt(m[1]), mi=parseInt(m[2]); const ap=(m[3]||'').toLowerCase();
  if(ap==='pm'&&h<12) h+=12; if(ap==='am'&&h===12) h=0;
  return h*60+mi;
}

let _sttEntries=[]; let _sttActiveSub='';
async function _loadRecordedSubjects(){
  const wrap=document.getElementById('s-rec-wrap'); if(!wrap) return;
  try{
    const m=await api('/api/student/my-subjects-mode');
    const rec=m.recorded||[];
    if(!rec.length){ wrap.innerHTML=''; return; }
    // subject-wise assigned teacher ka photo (logo) — na ho to initials, blink ke saath
    let ts=[]; try{ ts=await api('/api/student/my-teachers'); }catch(e){}
    const tmap={}; (ts||[]).forEach(t=>{ if(t&&t.subject) tmap[t.subject]=t; });
    const rows=rec.map(s=>{
      const t=tmap[s];
      const pid=`rect-${t?t.teacher_id:0}-${String(s).replace(/[^a-z0-9]/gi,'')}`;
      const ava=(t&&t.has_photo)
        ? `<div class="rec-ic rec-logo rec-tphoto" id="${pid}" title="${esc(t.name)}"></div>`
        : `<div class="rec-ic rec-logo rec-tinit" title="${t?esc(t.name):''}">${t?esc(initials(t.name)):ic('play')}</div>`;
      const note=t
        ? `${esc(t.name)} ${esc(t.suffix||'')} \u2014 recorded classes, watch anytime in the app`
        : `Recorded classes \u2014 watch anytime in the app`;
      return `<div class="rec-row">${ava}<div class="rec-main"><div class="rec-sub">${esc(s)}</div><div class="rec-note">${note}</div></div><button class="btn btn-primary btn-sm" onclick="openMVC()" title="Open the Manish Verma Classes app to watch the recorded lectures">${ic('play')} Watch Lectures</button></div>`;
    }).join('');
    setIf(wrap,`<div class="rec-card"><div class="rec-head"><div class="rec-badge">${rec.length}</div><div><div class="rec-title">Recorded Subjects</div><div class="rec-sub2">These subjects have no live timetable \u2014 their lectures are pre-recorded in the Manish Verma Classes App.</div></div></div>${rows}</div>`);
    // teacher photos async load (auth header ke saath)
    (ts||[]).filter(t=>t&&t.has_photo&&rec.includes(t.subject)).forEach(async t=>{
      try{
        const r=await fetch(API+`/api/student/teacher/${t.teacher_id}/photo`,{headers:{Authorization:'Bearer '+TOKEN}});
        if(!r.ok) return;
        const u=URL.createObjectURL(await r.blob());
        const key=`rect-${t.teacher_id}-${String(t.subject).replace(/[^a-z0-9]/gi,'')}`;
        const d=document.getElementById(key);
        if(d){ d.style.backgroundImage=`url(${u})`; }
      }catch(e){}
    });
  }catch(e){ wrap.innerHTML=''; }
}
async function loadSTimetable(){
  const el=document.getElementById('s-timetable-content');
  softSpin(el);
  try{
 // profile pehle — recorded batch ka timetable hota hi nahi
 try{ const p0=await api('/api/student/profile'); window._sBatch=p0.batch_name||p0.batch||window._sBatch||''; window._sClass=p0.class_level||window._sClass||'12'; window._sSubjects=p0.subjects||window._sSubjects||[]; applyBatchMode(); }catch(e){}
 if(sMode()!=='live'){ renderRecordedTimetable(el); return; }
 _sttEntries=await api('/api/student/timetable-plan');
 // scaffolding sirf pehli baar — revisit par sections apni jagah silently update hote hain (no blank flash)
 if(!document.getElementById('s-tline-wrap')) el.innerHTML=`<div id="s-rec-wrap"></div><div id="s-verify-wrap"></div><div id="s-tline-wrap"></div>`;
 _loadRecordedSubjects();
 /* verify-lectures "Lectures to Complete" list hata di — isse timetable neeche chala jaata
    tha. Ab timetable seedha dikhta hai; lecture completion/XP Syllabus Tracker se hoti hai. */
 try{ const p=await api('/api/student/profile'); window._sBatch=p.batch_name||p.batch||'Lakshya'; window._sClass=p.class_level||'12'; }catch(e){ window._sBatch='Lakshya'; window._sClass='12'; }
 // build subject -> teacher photo map (progress marker)
 window._sttTeacherMap={};
 try{ const ts=await api('/api/student/my-teachers');
   ts.forEach(t=>{ window._sttTeacherMap[t.subject]={name:t.name,url:null,has_photo:t.has_photo,tid:t.teacher_id}; });
   await Promise.all(ts.filter(t=>t.has_photo).map(async t=>{
     try{ const r=await fetch(API+`/api/student/teacher/${t.teacher_id}/photo`,{headers:{Authorization:'Bearer '+TOKEN}});
       if(r.ok) window._sttTeacherMap[t.subject].url=URL.createObjectURL(await r.blob()); }catch(e){}
   }));
 }catch(e){}
 renderStudentTimetable(_sttEntries,'s-tline-wrap',{emptyMsg:'No timetable for your subjects yet.',onTab:'sSetSubj',subjectDrop:true,activeSubject:_sttActiveSub||'',tipTeacherMap:window._sttTeacherMap,batch:window._sBatch,classLevel:window._sClass});
  }catch(e){ el.innerHTML=errHtml(e); }
}
function sSetSubj(s){ _sttActiveSub=decodeURIComponent(s||''); renderStudentTimetable(_sttEntries,'s-tline-wrap',{emptyMsg:'No timetable for your subjects yet.',onTab:'sSetSubj',subjectDrop:true,activeSubject:_sttActiveSub,tipTeacherMap:window._sttTeacherMap,batch:window._sBatch,classLevel:window._sClass}); }

async function loadSToday(){
  const el=document.getElementById('s-today-content');
  try{
 const plan=await api('/api/student/timetable-plan');
 const t=new Date(); t.setDate(t.getDate()+1);
 const tmrStr=`${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,'0')}-${String(t.getDate()).padStart(2,'0')}`;
 const dayName=t.toLocaleDateString('en-GB',{weekday:'long'});
 const dateNice=t.toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'});
 const rows=plan.filter(e=>e.date===tmrStr).sort((a,b)=>(a.time||'').localeCompare(b.time||''));
 el.innerHTML=`<div class="card"><div class="card-header"><h3> Next Day — ${dayName}, ${dateNice}</h3></div><div class="card-body">${
 rows.length?rows.map(e=>`<div class="today-row"><div><div class="tr-sub">${_isTest(e.chapter)?'':''} ${esc(e.subject)}</div><div class="tr-topic">${esc(e.part||e.chapter||'')}</div></div><div class="tmeta"><span class="tchip">${esc(e.day||dayName)}</span><span class="tchip"> ${esc(e.time||'TBA')}</span></div></div>`).join(''):'<div class="empty-state"><div class="empty-icon"></div><p>No classes scheduled for tomorrow!</p></div>'}</div></div>`;
  }catch(e){ el.innerHTML=errHtml(e); }
}

async function loadSMaterials(){
  const el=document.getElementById('s-materials-content');
  softSpin(el);
  try{
    // DPP section ke packs bhi laao — table me part-wise / whole-chapter rows banenge
    try{ const dd=await api('/api/student/dpp-packs'); window._sMatDppPacks=dd.packs||[]; }catch(e){ window._sMatDppPacks=[]; }
    const mats=await api('/api/student/materials-v2');
    window._sMats=mats;
    window._sMatNew=_matNewIds('student',mats); _matBadge('student');
    const packCount=(window._sMatDppPacks||[]).length;
    if(mats.length===0&&packCount===0){ el.innerHTML=`<div class="card"><div class="card-body"><div class="empty-state"><div class="empty-icon"></div><p>No study material uploaded yet. Once teachers add notes or DPP, they will appear here.</p></div></div></div>`; return; }
    const bySub={};
    mats.forEach(m=>{ (bySub[m.subject]=bySub[m.subject]||[]).push(m); });
    (window._sMatDppPacks||[]).forEach(p=>{ const s=p.subject||'Other'; if(!bySub[s]) bySub[s]=[]; });  // sirf DPP wala subject bhi dikhe
    const cards=Object.keys(bySub).sort().map(sub=>{
      const items=bySub[sub];
      const nPacks=(window._sMatDppPacks||[]).filter(p=>(p.subject||'')===sub).length;
      const nNotes=items.filter(m=>m.type==='notes').length, nDpp=items.filter(m=>m.type==='dpp').length+nPacks, nTest=items.filter(m=>m.type==='test').length, nOther=items.filter(m=>!['notes','dpp','test'].includes(m.type)).length;
      let badges='';
      if(nNotes) badges+=`<span class="sm-badge sm-notes">${nNotes} Class Notes</span>`;
      if(nDpp) badges+=`<span class="sm-badge sm-dpp">${nDpp} DPP</span>`;
      if(nTest) badges+=`<span class="sm-badge sm-test">${nTest} Tests</span>`;
      if(nOther) badges+=`<span class="sm-badge sm-other">${nOther} Other</span>`;
      const nNew=items.filter(m=>window._sMatNew&&window._sMatNew.has(m.id)).length;
      return `<div class="sm-card" onclick="openSubjectMaterials('${encodeURIComponent(sub)}')">${nNew?`<span class="sm-new-pill">${nNew} NEW</span>`:''}<div class="sm-icon">${ic('book')}</div><div class="sm-body"><div class="sm-title">${esc(sub)}</div><div class="sm-badges">${badges||'<span class="sm-badge">No files</span>'}</div></div><span class="sm-arrow">›</span></div>`;
    }).join('');
    const newN=((window._sMatNew&&window._sMatNew.size)||0);
    el.innerHTML=`<div class="sm-head" style="display:flex;align-items:center;gap:14px;flex-wrap:wrap"><h2 style="margin-right:auto">Classes Material</h2>${newN?`<span class="mt-new-head">${newN} new upload${newN>1?'s':''} since your last visit <button class="mt-new-clear" onclick="_matAllRead('student')">Mark all read</button></span>`:''}</div><div class="sm-grid">${cards}</div>`;
  }catch(e){ el.innerHTML=errHtml(e); }
}
function openSubjectMaterials(encSub){
  const sub=decodeURIComponent(encSub);
  const el=document.getElementById('s-materials-content');
  const mats=(window._sMats||[]).filter(m=>m.subject===sub);
  const catMeta={'Class Notes':{icon:'book',badge:'sc-indigo'},'DPP':{icon:'clipboard',badge:'sc-green'},'Tests':{icon:'edit',badge:'sc-purple'}};
  const byCat={};
  mats.forEach(m=>{ const cat=m.type==='notes'?'Class Notes':m.type==='dpp'?'DPP':m.type==='test'?'Tests':(m.category||'Other Material'); (byCat[cat]=byCat[cat]||[]).push(m); });
  // ek baar CSS inject — card rows (table nahi, isliye phone par overflow/side-scroll nahi)
  if(!document.getElementById('mat-item-css')){
    var mst=document.createElement('style'); mst.id='mat-item-css';
    mst.textContent='.mat-item{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:11px 14px;border-bottom:1px solid var(--border)}'
      +'.mat-item:last-child{border-bottom:none}'
      +'.mat-item-info{flex:1;min-width:0}'
      +'.mat-item-title{font-weight:700;font-size:.9rem;word-break:break-word;line-height:1.35}'
      +'.mat-item-sub{font-size:.72rem;color:var(--text-muted);margin-top:2px;word-break:break-word;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}'
      +'.mat-open{flex:none;white-space:nowrap;padding:7px 15px}'
      // ~5 items dikhein, uske baad box ke ANDAR scroll (page endless nahi) + scrollbar dikhe
      +'.mat-scroll{max-height:340px;overflow-y:auto;-webkit-overflow-scrolling:touch}'
      +'.mat-scroll::-webkit-scrollbar{width:8px}'
      +'.mat-scroll::-webkit-scrollbar-thumb{background:var(--accent);border-radius:99px}'
      +'.mat-scroll::-webkit-scrollbar-track{background:rgba(0,0,0,.05);border-radius:99px}';
    document.head.appendChild(mst);
  }
  let html=`<div class="sm-head" style="display:flex;align-items:center;gap:14px;flex-wrap:wrap"><button class="btn btn-ghost btn-sm" onclick="loadSMaterials()">← Back</button><div><h2 style="margin:0;font-size:1.4rem">${esc(sub)}</h2><p style="margin:0">Class Notes, DPP &amp; Tests</p></div></div><div class="card"><div class="card-body">`;
  Object.keys(byCat).forEach(cat=>{
    const meta=catMeta[cat]||{icon:'folder',badge:'sc-amber'};
    const items=byCat[cat];
    html+=`<div class="mat-cat"><div class="mat-cat-head"><div class="mc-badge ${meta.badge}">${ic(meta.icon)}</div>${esc(cat)}<span class="mc-count">${items.length} file${items.length>1?'s':''}</span></div><div class="mat-scroll">`;
    items.forEach(m=>{ const fname=m.filename||((m.title||cat)+'.pdf'); const isNew=window._sMatNew&&window._sMatNew.has(m.id); const _sub=[m.part?esc(m.part):'', (m.title&&m.title!==m.chapter)?esc(m.title):''].filter(Boolean).join(' \u00b7 ');
      html+=`<div class="mat-item ${isNew?'mt-row-new':''}" onclick="_matRowSeen('student',this,${m.id})"><div class="mat-item-info"><div class="mat-item-title">${esc(m.chapter||m.title||'\u2014')}${isNew?'<span class="mt-new-tag">NEW</span>':''}</div>${_sub?`<div class="mat-item-sub">${_sub}</div>`:''}</div><button class="btn btn-primary btn-sm mat-open" onclick="event.stopPropagation();downloadMaterial('student',${m.id},'${esc(fname).replace(/'/g,'')}')">${ic('download')} Download</button></div>`; });
    html+=`</div>`;
  });
  // DPP packs — part-wise alag cards
  const packs=(window._sMatDppPacks||[]).filter(p=>(p.subject||'')===sub);
  if(packs.length){
    html+=`<div class="mat-cat"><div class="mat-cat-head"><div class="mc-badge sc-green">${ic('clipboard')}</div>DPP (Practice Papers)<span class="mc-count">${packs.length} DPP${packs.length>1?'s':''}</span></div><div class="mat-scroll">`;
    packs.forEach(p=>{ html+=`<div class="mat-item"><div class="mat-item-info"><div class="mat-item-title">${esc(p.title||'DPP')}</div><div class="mat-item-sub">${esc(p.chapter||'—')} · ${p.part?esc(p.part):'<b>Whole Chapter</b>'} · ${esc(p.medium||'English')}</div></div><button class="btn btn-primary btn-sm mat-open" title="Download this DPP PDF" onclick="sDppHub(${p.id},'q')">${ic('download')} Download</button></div>`; });
    html+=`</div>`;
  }
  html+=`</div></div>`;
  el.innerHTML=html;
}

// teacher photo ko div me background-image ki tarah load karo (auth header ke saath)
async function _loadPhotoInto(elId,url){
  // v163: dedupe via _imgBlobCache — the same teacher photo was re-fetched from the
  // server on EVERY render/background-refresh (the /photo 302 flood in Railway logs).
  // Now each photo is fetched once per session and reused from cache.
  try{
    window._photoUrls=window._photoUrls||{};
    const cached=_imgBlobCache[url];
    if(cached){ window._photoUrls[elId]=cached; const d0=document.getElementById(elId); if(d0){ d0.style.backgroundImage=`url(${cached})`; d0.textContent=''; } return; }
    const r=await fetch(API+url,{headers:{Authorization:'Bearer '+TOKEN}});
    if(!r.ok) return; const u=URL.createObjectURL(await r.blob());
    _imgBlobCache[url]=u; window._photoUrls[elId]=u;
    const d=document.getElementById(elId); if(d){ d.style.backgroundImage=`url(${u})`; d.textContent=''; } }catch(e){}
}
function _sDppCardHTML(pk,isNew){
  const checked=pk.my_status==='checked', subm=!!pk.submitted;
  const statusChip=checked?`<span class="dp-tag done">✔ Checked</span>`:(subm?`<span class="dp-tag pending">⏳ Checking…</span>`:`<span class="dp-tag">Pending</span>`);
  const srcChip=pk.source==='uploaded'?`<span class="chip-sub">Uploaded</span>`:`<span class="chip-sub"> ${pk.questions_n||0} Questions</span>`;
  const newTag=isNew?` <span class="dp-new">NEW</span>`:'';
  const avaId=`dppava-${pk.id}`;
  const ava=pk.has_teacher_photo
    ? `<div class="dpp-ava" id="${avaId}" title="${esc(pk.teacher||'Teacher')}"></div>`
    : `<div class="dpp-ava-init" title="${esc(pk.teacher||'Teacher')}">${esc(initials(pk.teacher||'T'))}</div>`;
  // uploaded DPP: card pe hi 2 alag button — Question Paper (hamesha) + Solution (submit ke baad)
  // created DPP: purana single View button
  const viewBtn=(pk.source==='uploaded')
    ? `<button class="btn btn-primary btn-sm" onclick="event.stopPropagation();openSDppPanel(${pk.id},'q')">${ic('file')} Question Paper</button>`
      + ((subm&&pk.has_solution)?`<button class="btn btn-success btn-sm" onclick="event.stopPropagation();openSDppPanel(${pk.id},'s')">${ic('check')} Solution</button>`:'')
    : (subm
      ? `<button class="btn btn-success btn-sm" onclick="openSDppPanel(${pk.id})">${ic('eye')} View Solution</button>`
      : `<button class="btn btn-primary btn-sm" onclick="openSDppPanel(${pk.id})">${ic('eye')} View Questions</button>`);
  const rankBtn=`<button class="btn btn-ghost btn-sm" title="See the ranking of the earliest submitters" onclick="openDppRanking(${pk.id},'student')">${ic('chart')} Ranking${(pk.submissions||0)>0?` (${pk.submissions})`:''}</button>`;
  const remBtn=checked?`<button class="btn btn-primary btn-sm" onclick="openDppRemarks(${pk.id})"> View Remarks</button>`:'';
  const subBtn=(!subm||pk.can_resubmit)?`<button class="btn ${subm?'btn-ghost':'btn-success'} btn-sm" onclick="openDppSubmit(${pk.id})">${ic('upload')} ${subm?'Re-submit':'Submit'}</button>`:'';
  const subDate=subm&&pk.my_submitted_at?`<span class="dpp-subdate"> Submitted: ${esc(pk.my_submitted_at)}</span>`:'';
  return `<div class="dpp-card premium" style="cursor:pointer" title="Tap to open this DPP" onclick="sDppCardToggle(${pk.id},event)">
    <div style="display:flex;gap:13px;align-items:flex-start">
      ${ava}
      <div style="flex:1;min-width:0">
        <div class="dpp-top"><div class="tr-sub"> ${esc(pk.subject)}</div><div class="dpp-chips">${pk.class_name?`<span class="xm-chip xm-chip-hl2">${ic('book')} ${esc(pk.class_name)}</span>`:''}${pk.medium?`<span class="xm-chip xm-chip-hl2">${esc(pk.medium)}</span>`:''}${srcChip}</div></div>
        <div class="dpp-title">${esc(pk.title||'DPP')}${newTag}</div>
        <div class="dpp-meta"> ${esc(pk.chapter||'—')}${pk.part?` · Part: ${esc(pk.part)}`:''}</div>
        <div class="dpp-meta"> ${esc(pk.teacher||'Teacher')}${pk.created_at?` · ${esc(pk.created_at)}`:''}</div>
        <div class="dpp-foot"><div style="display:flex;gap:7px;align-items:center;flex-wrap:wrap">${statusChip}${subDate}</div><div class="dpp-btns">
          ${viewBtn}${rankBtn}${subBtn}${remBtn}
        </div></div>
      </div>
    </div>
  </div>`;
}
// Card pe kahin bhi click = maximize (buttons pe nahi); expanded ho to band pe click = minimize
function sDppCardToggle(pid,ev){
  if(ev&&ev.target&&ev.target.closest('button,a,select,input,textarea')) return;
  openSDppPanel(pid);
}
function sDppSubject(i){
  const minimize=(window._sDppOpen===i);
  window._sDppOpen=minimize?-1:i;  // open card pe dobara click = minimize
  window._sDppOpenSub=minimize?'':(((window._sDppGroups||[])[i]||{}).subject||'');  // back pe yaad rahe
  (window._sDppGroups||[]).forEach((g,j)=>{
    const card=document.getElementById(`dps-${j}`), sec=document.getElementById(`dps-sec-${j}`);
    const open=(!minimize&&j===i);
    if(card){ card.classList.toggle('open',open); const t=card.querySelector('.dps-tick'); if(t) t.textContent=open?'▲':'▼'; }
    if(sec) sec.style.display=open?'block':'none';
  });
}
// loadSDpp serialize: concurrent calls se do _fillSDppPanel ek dusre ka expanded DOM wipe kar dete hain
let _loadSDppBusy=false,_loadSDppAgain=false;
async function loadSDpp(){
  if(_loadSDppBusy){ _loadSDppAgain=true; return; }
  _loadSDppBusy=true;
  try{ await _loadSDppReal(); }
  finally{ _loadSDppBusy=false; if(_loadSDppAgain){ _loadSDppAgain=false; loadSDpp(); } }
}
async function _loadSDppReal(){
  const el=document.getElementById('s-dpp-content');
  softSpin(el);
  try{
    const d=await api('/api/student/dpp-packs');
    const packs=(d&&d.packs)||[];
    window._sDppPacks=packs;
    let html=`<div class="card"><div class="card-header"><h3> DPP — Practice & Submit</h3><span class="chip-sub">${packs.length} DPP</span></div><div class="card-body">`;
    if(packs.length===0) html+=`<div class="empty-state"><div class="empty-icon"></div><p>No DPP available yet. Your teacher will add one soon.</p></div>`;
    else{
      // subject-wise groups (packs newest-first hain → har subject ka pehla = latest)
      const gmap={}; const groups=[];
      packs.forEach(pk=>{ const s=pk.subject||'Other';
        if(!gmap[s]){ gmap[s]={subject:s,items:[]}; groups.push(gmap[s]); }
        gmap[s].items.push(pk); });
      groups.forEach(g=>{ g.latestId=g.items[0].id; g.newPending=!g.items[0].submitted;
        g.done=g.items.filter(x=>x.submitted).length; });
      window._sDppGroups=groups;
      // Koi subject auto-select NAHI — pehle sirf cards dikhte hain. Card click karne par
      // hi us subject ki DPP list khulti hai. Selected subject naam se yaad rehta hai, isliye
      // DPP dekh ke back karne par 1st subject par reset nahi hota.
      let openIdx=-1;
      if(window._sDppOpenSub){ openIdx=groups.findIndex(g=>g.subject===window._sDppOpenSub); if(openIdx<0) window._sDppOpenSub=''; }
      const _op=window._sDppOpenPid||0;
      if(_op){ const _gi=groups.findIndex(g=>g.items.some(x=>x.id===_op)); if(_gi>=0){ openIdx=_gi; window._sDppOpenSub=groups[_gi].subject; } }
      window._sDppOpen=openIdx;
      // open panel ho to subject grid + baaki cards hide — sirf expanded DPP dikhti hai
      const openPid0=window._sDppOpenPid||0;
      if(!openPid0) html+=`<div class="dps-grid">`+groups.map((g,i)=>`
        <div class="dps-card ${i===openIdx?'open':''}" id="dps-${i}" onclick="sDppSubject(${i})">
          ${g.newPending?`<span class="dps-badge">NEW DPP</span>`:''}
          <div class="dps-name"> ${esc(g.subject)}</div>
          <div class="dps-count">${g.items.length} DPP · ${g.done}/${g.items.length} submitted</div>
          <div class="dps-tick">${i===openIdx?'▲':'▼'}</div>
        </div>`).join('')+`</div>`;
      // open panel wali DPP apne CARD ke andar expand hoti hai — back pe minimize
      const openPid=window._sDppOpenPid||0;
      html+=groups.map((g,i)=>`<div class="dps-sec" id="dps-sec-${i}" style="display:${i===openIdx?'block':'none'}">`
        +(openPid
          ? g.items.filter(pk=>pk.id===openPid).map(pk=>`<div class="dpp-card premium dpp-exp" id="dpp-exp-${pk.id}"><div class="spinner"></div></div>`).join('')
          : g.items.map(pk=>_sDppCardHTML(pk,pk.id===g.latestId)).join(''))
        +`</div>`).join('');
    }
    html+=`</div></div>`;
    // legacy materials-based DPPs (old records) — read-only archive
    try{
      const old=await api('/api/student/dpp-list');
      if(old&&old.length) html+=`<div class="card"><div class="card-header"><h3> Previous DPPs (Archive)</h3></div><div class="card-body">`
        +old.map(d2=>`<div class="today-row"><div><div class="tr-sub"> ${esc(d2.subject)}</div><div class="tr-topic">${esc(d2.chapter||'')} — ${esc(d2.title||'DPP')}</div></div><div class="tmeta"><button class="btn btn-ghost btn-sm" onclick="downloadMaterial('student',${d2.id},'DPP.pdf')">${ic('download')} Download</button></div></div>`).join('')
        +`</div></div>`;
    }catch(_e){}
    el.innerHTML=html;
    // teacher photos (avatar) — auth header ke saath fetch karke lagao
    packs.filter(pk=>pk.has_teacher_photo).forEach(pk=>{
      _loadPhotoInto(`dppava-${pk.id}`,`/api/student/teacher/${pk.teacher_id}/photo`); });
    // expanded card ke andar panel bharo
    if(window._sDppOpenPid){
      const t=document.getElementById('dpp-exp-'+window._sDppOpenPid);
      if(t) _fillSDppPanel(window._sDppOpenPid,t);
    }
  }catch(e){ el.innerHTML=errHtml(e); }
}
function _imgSrc(b64){
  if(!b64) return '';
  if(b64.startsWith('data:')) return b64;
  const mime=b64.startsWith('/9j/')?'image/jpeg':(b64.startsWith('iVBOR')?'image/png':(b64.startsWith('UklGR')?'image/webp':'image/png'));
  return `data:${mime};base64,${b64}`;
}
async function sDppDl(pid,kind){
  try{
    const r=await fetch(API+`/api/student/dpp-packs/${pid}/file?kind=${kind}`,{headers:{Authorization:'Bearer '+TOKEN}});
    if(r.status===403){ toast('Submit your DPP first to view the solution.',true); return; }
    if(!r.ok) throw new Error('nf');
    const bl=await r.blob(); const a=document.createElement('a');
    a.href=URL.createObjectURL(bl); a.download=(kind==='s'?'DPP-solutions.pdf':'DPP-questions.pdf'); a.click();
  }catch(e){ toast('File not available',true); }
}
// ---------- Uploaded DPP: PDF view (new tab) ----------
async function sDppViewPdf(pid){
  try{
    const r=await fetch(API+`/api/student/dpp-packs/${pid}/file?kind=q`,{headers:{Authorization:'Bearer '+TOKEN}});
    if(!r.ok) throw new Error('nf');
    const bl=await r.blob(); const u=URL.createObjectURL(bl);
    pdfViewerModal(u,'DPP — Questions','DPP-questions.pdf');
    setTimeout(()=>URL.revokeObjectURL(u),300000);
  }catch(e){ toast('File not available',true); }
}
// ---------- Created DPP: question-wise interactive view + Raise Doubt ----------
async function openSDppView(pid){
  showModal('DPP','<div class="spinner"></div>','');
  { const _mm=document.querySelector('#modal .modal'); if(_mm)_mm.classList.add('cx'); }
  try{
    const d=await api(`/api/student/dpp-packs/${pid}/questions`);
    const qs=d.questions||[];
    const html=`<div class="card" style="margin-bottom:12px;border:1.5px solid rgba(184,148,31,.3)"><div class="card-body" style="padding:14px 16px">
      <div style="display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap;align-items:flex-start"><div>
        <b style="font-size:1rem">${esc(d.title)}</b>
        <div style="font-size:.72rem;color:var(--text-muted);margin-top:3px">${esc(d.subject)}${d.chapter?' · '+esc(d.chapter):''}${d.part?' · '+esc(d.part):''}${d.teacher?' ·  '+esc(d.teacher):''}</div>
      </div><span class="chip" style="font-size:.62rem">${qs.length} Questions</span></div>
      <div style="font-size:.74rem;color:var(--text-muted);margin-top:9px;line-height:1.5">Kisi question me doubt ho to uske neeche <b>Raise Doubt</b> dabao — question ka text + image apne aap teacher ke paas chala jayega, <b>no screenshot needed</b>.</div>
    </div></div>`
    +qs.map(q=>`<div class="card" style="margin-bottom:10px"><div class="card-body" style="padding:14px 16px">
      <div style="font-size:.68rem;font-weight:800;letter-spacing:.06em;color:#8a6d10;margin-bottom:6px">QUESTION ${q.qno}</div>
      <div class="pl-qtext" id="dq-${q.qno}">${_fmtRich(q.q||'')}</div>
      ${q.image?`<img src="${_imgSrc(q.image)}" style="max-width:100%;border-radius:8px;margin-top:8px;border:1px solid var(--border)">`:''}
      ${q.alt_image?`<img src="${_imgSrc(q.alt_image)}" style="max-width:100%;border-radius:8px;margin-top:8px;border:1px solid var(--border)">`:''}
      ${d.submitted&&q.model?`<div style="margin-top:12px;padding:10px 12px;border-left:3px solid #15803d;background:rgba(21,128,61,.06);border-radius:8px"><div style="font-size:.68rem;font-weight:800;color:#15803d;margin-bottom:5px">MODEL ANSWER</div><div id="da-${q.qno}">${_fmtRich(q.model)}</div>${q.model_image?`<img src="${_imgSrc(q.model_image)}" style="max-width:100%;margin-top:8px;border-radius:8px">`:''}</div>`:''}
      <div style="margin-top:11px"><button class="btn btn-ghost btn-sm" onclick="sDppDoubtOpen(${pid},${q.qno},${q.qno})">${ic('headset')} Raise Doubt</button></div>
    </div></div>`).join('');
    showModal(esc(d.title), html, `<button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
    { const _mm=document.querySelector('#modal .modal'); if(_mm)_mm.classList.add('cx'); }
    qs.forEach(q=>{ const el=document.getElementById('dq-'+q.qno); if(el) renderMath(el); const a=document.getElementById('da-'+q.qno); if(a) renderMath(a); });
  }catch(e){ closeModal(); toast(e.message||'Could not open the DPP',true); }
}
