async function loadSLectures(){
  const el=document.getElementById('s-lectures-content');
  softSpin(el);
  try{
    const lecs=await api('/api/student/lectures');
    if(!lecs.length){ el.innerHTML=`<div class="sm-head"><h2>Lectures</h2><p>Mark each lecture done after watching it in the Manish Verma Classes App.</p></div><div class="card"><div class="card-body"><div class="ws-empty"><div class="big">\ud83c\udf93</div><p>No lectures yet</p><small>When your teacher posts a lecture report, it appears here.</small></div></div></div>`; return; }
    const cards=lecs.map(l=>{
      const st=l.status==='verified'?'verified':(l.cooling?'cooling':'pending');
      const stLabel=st==='verified'?'\u2714 Done':(st==='cooling'?'On cooldown':'Pending');
      let action='';
      if(l.status==='verified'){ action=`<span class="lec-status verified">\u2714 Verified</span>`; }
      else if(l.cooling){ action=`<button class="btn btn-ghost btn-sm" disabled>Try later</button>`; }
      else { action=`<button class="btn btn-primary btn-sm" onclick="markLectureDone(${l.id})">Mark as Done</button>`; }
      const files=[];
      if(l.has_pdf) files.push(`<button class="btn btn-ghost btn-sm" onclick="dlLectureFile(${l.id},'pdf')">${ic('download')} Notes</button>`);
      if(l.has_dpp) files.push(`<button class="btn btn-ghost btn-sm" onclick="dlLectureFile(${l.id},'dpp')">${ic('download')} DPP</button>`);
      return `<div class="lec-card"><div class="lec-head"><div><div class="lec-title">${esc(l.title)}</div><div class="lec-meta">${esc(l.subject)}${l.chapter?' \u00b7 '+esc(l.chapter):''}${l.part?' \u00b7 '+esc(l.part):''} \u00b7 ${esc(l.date)}</div></div><span class="lec-status ${st}">${stLabel}</span></div>${l.summary?`<div class="lec-body">${esc(l.summary)}</div>`:''}${l.homework?`<div class="lec-body"><b>Homework:</b> ${esc(l.homework)}</div>`:''}<div class="lec-actions">${files.join('')}${action}</div></div>`;
    }).join('');
    el.innerHTML=`<div class="sm-head"><h2>Lectures</h2><p>Watch in the MVC App, then mark it done here. Completed lectures build your progress & rank.</p></div>${cards}`;
  }catch(e){ el.innerHTML=errHtml(e); }
}

async function dlLectureFile(lectureId,kind){
  try{
    const r=await fetch(API+`/api/student/lecture/${lectureId}/file?kind=${kind}`,{headers:{Authorization:'Bearer '+TOKEN}});
    if(!r.ok){ toast('File not available',true); return; }
    const blob=await r.blob(); const u=URL.createObjectURL(blob);
    const a=document.createElement('a'); a.href=u; a.download=(kind==='dpp'?'DPP.pdf':'Notes.pdf'); a.click(); URL.revokeObjectURL(u);
  }catch(e){ toast(e.message,true); }
}

function _refreshAfterVerify(){ if(document.getElementById('s-page-timetable').classList.contains('active')) loadSTimetable(); else if(document.getElementById('s-page-progress').classList.contains('active')) loadSProgress(); else if(document.getElementById('s-page-dashboard').classList.contains('active')) loadSDashboard(); }

async function _loadPendingVerifications(){
  const wrap=document.getElementById('s-verify-wrap'); if(!wrap) return;
  try{
    const lecs=await api('/api/student/lectures');
    const pending=lecs.filter(l=>l.status!=='verified');
    if(!pending.length){ wrap.innerHTML=''; return; }
    const rows=pending.map(l=>{
      const cool=l.cooling;
      const btn=cool?`<button class="btn btn-ghost btn-sm" disabled>Try later</button>`:`<button class="btn btn-success btn-sm" onclick="markLectureDone(${l.id})">Mark Done</button>`;
      return `<div class="pv-row"><div class="pv-main"><div class="pv-title">${esc(l.title)}</div><div class="pv-meta">${esc(l.subject)}${l.chapter?' \u00b7 '+esc(l.chapter):''}${l.part?' \u00b7 '+esc(l.part):''} \u00b7 ${esc(l.teacher_name||'')}</div></div>${btn}</div>`;
    }).join('');
    wrap.innerHTML=`<div class="pv-card"><div class="pv-head"><span class="pv-badge">${pending.length}</span><div><div class="pv-htitle">Lectures to Complete</div><div class="pv-hsub">Mark each lecture done after watching and earn XP.</div></div></div>${rows}</div>`;
  }catch(e){ wrap.innerHTML=''; }
}

async function markLectureDone(lectureId){
  // v98: no verification question — one tap marks the lecture done (XP awarded once, server-side).
  try{
    const r=await api('/api/student/lecture/'+lectureId+'/mark-done','POST',{});
    toast(r.message||'Lecture marked done.');
    _refreshAfterVerify();
    _loadPendingVerifications();
  }catch(e){ toast(e.message||'Could not mark the lecture done',true); }
}

async function loadSProgress(){
  const el=document.getElementById('s-progress-content');
  softSpin(el);
  try{
    // ---------- 1) BATCH RANKING (podium + your rank + clickable list) ----------
    let rankSec='';
    try{
      const bb=await api('/api/student/batch-board');
      window._sbbRows=bb.rows||[]; window._sbbMe=bb.me||null;
      if(_sbbRows.length){
        const medal=['#f59e0b','#a2946d','#b45309'];
        const bav=(r,sz)=>`<div style="width:${sz}px;height:${sz}px;border-radius:50%;background:linear-gradient(135deg,#b8941f,#a1741a);color:#241a05;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:${Math.round(sz*.42)}px;border:3px solid #fff;box-shadow:0 3px 10px rgba(0,0,0,.18)">${esc((r.name||'?').slice(0,1).toUpperCase())}</div>`;
        const pod=[_sbbRows[1],_sbbRows[0],_sbbRows[2]].filter(Boolean);
        const podHtml=`<div class="trk-podium">${pod.map(r=>{
          const h=r.rank===1?110:r.rank===2?84:r.rank===3?68:60;
          const sz=r.rank===1?62:52;
          return `<div class="trk-pod trk-click" onclick="sbbCompare(${r.id})" title="Tap to compare"><div class="trk-pod-av" style="position:relative">${bav(r,sz)}<span class="trk-medal" style="background:${medal[r.rank-1]}">${r.rank}</span></div>
            <div class="trk-pod-nm">${esc(r.name)}${r.me?' <span class="trk-you">(you)</span>':''}</div><div class="trk-pod-sc">${r.xp}<small>XP</small></div>
            <div class="trk-pod-base" style="height:${h}px;background:linear-gradient(180deg,${medal[r.rank-1]}33,${medal[r.rank-1]}0d);border-top:4px solid ${medal[r.rank-1]}"><b>#${r.rank}</b></div></div>`;
        }).join('')}</div>`;
        const me=bb.me;
        const meHtml=me?`<div class="trk-me"><div class="trk-me-l"><div class="trk-me-rank">#${me.rank}</div><div><b>Your Rank</b><div class="trk-me-sub">of ${bb.total} students${bb.batch?` &middot; ${esc(bb.batch)}`:''} &middot; <b>${me.xp} XP</b></div></div></div><div class="trk-me-hint">Tap any student to compare</div></div>`:'';
        const maxXp=Math.max(1,..._sbbRows.map(r=>r.xp));
        const rows=_sbbRows.map(r=>`<div class="sbb-row ${r.me?'me':''}" onclick="sbbCompare(${r.id})">
          <span class="sbb-rank ${r.rank<=3?'top':''}">${r.rank}</span>
          <span class="sbb-av">${esc((r.name||'?').slice(0,1).toUpperCase())}</span>
          <div class="sbb-main"><div class="sbb-nm">${esc(r.name)}${r.me?' <span class="trk-you">(you)</span>':''}</div>
            <div class="sbb-track"><div class="sbb-fill" style="width:${Math.round(r.xp/maxXp*100)}%"></div></div></div>
          <b class="sbb-xp">${r.xp} XP</b></div>`).join('');
        rankSec=`<div class="card" style="border:1.5px solid rgba(184,148,31,.3)"><div class="card-header"><h3>&#127942; Batch Ranking${bb.batch?' — '+esc(bb.batch):''}</h3></div><div class="card-body">
          ${podHtml}${meHtml}
          <div class="hide-scroll sbb-scroll">${rows}</div>
          ${_sbbRows.length>5?`<div class="trk-scroll-hint">Showing top 5 &middot; scroll for all ${bb.total} students</div>`:''}
        </div></div>`;
      }
    }catch(e0){}

    // ---------- 2) SYLLABUS TRACKER PROGRESS (simple subject bars) ----------
    let sylSec='';
    try{
      const ov=await api('/api/syllabus/overview');
      const subs=(ov.subjects||[]).filter(x=>x.calc);
      const rows=subs.map(s=>{
        const c=s.calc, paper=c.paper_marks||c.total_pe_marks||100;
        const pct=Math.min(100,Math.round((c.covered_paper||0)/Math.max(paper,0.01)*100));
        return `<div class="mprog-row"><div class="mprog-top"><span class="mprog-sub">${esc(s.name)}</span><span class="mprog-val">${_sylN(c.covered_paper)}/${_sylN(paper)} paper marks &middot; ${pct}%</span></div><div class="mprog-track"><div class="mprog-fill" style="width:${pct}%;background:linear-gradient(90deg,#c9a227,#b8941f)"></div></div></div>`;
      }).join('');
      sylSec=`<div class="card"><div class="card-header"><h3>Syllabus Progress</h3><button class="btn btn-ghost btn-sm" onclick="sPage('syllabus',null)">Open Tracker</button></div><div class="card-body">${rows||'<div class="ws-empty"><p>No subjects planned yet &mdash; open the Syllabus Tracker and pick your chapters.</p></div>'}</div></div>`;
    }catch(e1){}

    // ---------- 3) STUDY SNAPSHOT (simple real numbers) ----------
    const d=await api('/api/student/performance');
    const snap=`<div class="card"><div class="card-header"><h3>Study Snapshot</h3></div><div class="card-body">
      <div class="ovv-grid">
        <div class="ovv-cell"><div class="ovv-num">${d.lectures.verified}/${d.lectures.total}</div><div class="ovv-lbl">Chapters Done</div></div>
        ${sMode()==='live'?`<div class="ovv-cell"><div class="ovv-num">${d.dpp.done}/${d.dpp.total}</div><div class="ovv-lbl">DPP Done</div></div>`:''}
        <div class="ovv-cell"><div class="ovv-num">${d.tests.done}/${d.tests.total}</div><div class="ovv-lbl">Tests Attempted</div></div>
        <div class="ovv-cell"><div class="ovv-num">${d.tests.avg_score}%</div><div class="ovv-lbl">Avg Test Score</div></div>
      </div>
      <div style="margin-top:12px;font-size:.76rem;color:var(--text-muted)">Chapter done (Syllabus Tracker) = <b>+20 XP</b> &middot; DPP submit = <b>+15 XP</b> &middot; Test attempt = <b>+25 XP</b> — yahi XP aapki batch ranking banata hai.</div>
    </div></div>`;

    el.innerHTML=(rankSec||'')+(sylSec||'')+snap;
    if(!rankSec&&!sylSec) el.innerHTML=snap;
  }catch(e){ el.innerHTML=errHtml(e); }
}
function sbbCompare(sid){
  const rows=window._sbbRows||[], me=window._sbbMe;
  const other=rows.find(r=>r.id===sid);
  if(!me||!other) return;
  if(other.id===me.id){
    showModal('That\'s you!',`<p style="font-size:.88rem">You are at <b>Rank #${me.rank}</b> in your batch with <b>${me.xp} XP</b>. Tap another student to see what it takes to catch them.</p>`,`<button class="btn btn-primary btn-sm" onclick="closeModal()">OK</button>`);
    return;
  }
  const gap=other.xp-me.xp;
  const ahead=gap>0;
  let body='';
  if(ahead){
    const lec=Math.ceil(gap/20), dpp=Math.ceil(gap/15), tst=Math.ceil(gap/25);
    body=`<div class="trk-cmp-head"><div class="trk-cmp-cell"><div class="trk-cmp-score">${me.xp}</div><div class="trk-cmp-who">You &middot; Rank #${me.rank}</div></div>
      <div class="trk-cmp-diff behind">${gap} XP behind</div>
      <div class="trk-cmp-cell"><div class="trk-cmp-score">${other.xp}</div><div class="trk-cmp-who">${esc(other.name)} &middot; Rank #${other.rank}</div></div></div>
      <div class="trk-sugg"><b>&#128161; Rank #${other.rank} tak kaise pahunche:</b><ul>
        <li><b>${lec}</b> verify lectures (+20 XP each) — or</li>
        <li><b>${dpp}</b> submit DPPs (+15 XP each) — or</li>
        <li><b>${tst}</b> attempt tests (+25 XP each)</li>
      </ul>
      <div class="trk-sugg-note">Inme se mix bhi chalega — roz thoda sa, aur aap ${esc(other.name)} ko catch kar loge. Har verified lecture/DPP/test se XP milta hai.</div></div>`;
  }else{
    body=`<div class="trk-cmp-head"><div class="trk-cmp-cell"><div class="trk-cmp-score">${me.xp}</div><div class="trk-cmp-who">You &middot; Rank #${me.rank}</div></div>
      <div class="trk-cmp-diff ahead">${Math.abs(gap)} XP ahead</div>
      <div class="trk-cmp-cell"><div class="trk-cmp-score">${other.xp}</div><div class="trk-cmp-who">${esc(other.name)} &middot; Rank #${other.rank}</div></div></div>
      <div class="trk-sugg"><b>&#127881; Great — you are ahead!</b><div class="trk-sugg-note">${esc(other.name)} se aap <b>${Math.abs(gap)} XP</b> aage ho. Apni ranking pakki rakhne ke liye roz lectures verify aur DPP karte raho.</div></div>`;
  }
  showModal(`${esc(other.name)} — Rank #${other.rank}`,body,`<button class="btn btn-primary btn-sm" onclick="closeModal()">Close</button>`);
}
function switchPerfGraph(tab,period){
  document.querySelectorAll('#s-progress-content .perf-tab').forEach(t=>t.classList.remove('active')); tab.classList.add('active');
  const d=window._perfData; if(!d) return;
  document.getElementById('perf-graph').innerHTML=_barChart(d.graphs[period]||[]);
}

