  if(!entries||entries.length===0){ el.innerHTML=`<div class="card"><div class="card-body"><div class="empty-state"><div class="empty-icon"></div><p>${opts.emptyMsg||'No timetable for your subjects yet.'}</p></div></div></div>`; return; }
