  const [subT,subD]=active?_count(tl[active]):[totalParts,doneParts];
  const subPct=subT?Math.round(subD/subT*100):0;
  _ttLast={entries,containerId,opts,student:true};
  const toggle=`<div class="tt-toggle"><button class="${_ttView==='timeline'?'active':''}" onclick="setTtView('timeline')">Chapter Timeline</button><button class="${_ttView==='weekly'?'active':''}" onclick="setTtView('weekly')">Weekly View</button></div>`;
