    for(const it of list){ const ds=it.kind==='event'?[it.data.date]:it.parts.map(p=>p.date); if(_statusOf(ds)==='current'&&_isToday(it)) return {name:nm(it),mode:'today',it}; }
    for(const it of list){ const ds=it.kind==='event'?[it.data.date]:it.parts.map(p=>p.date); if(_statusOf(ds)==='current') return {name:nm(it),mode:'live',it}; }
    for(const it of list){ const ds=it.kind==='event'?[it.data.date]:it.parts.map(p=>p.date); if(_statusOf(ds)==='upcoming') return {name:nm(it),mode:'next',it}; }
