  const _chT=_chapScope.length, _chD=_chapScope.filter(c=>c.done).length;
  const _chOn=_chapScope.filter(c=>!c.done&&(c.started||c.name===(_curLive?_curLive.name:null))).length;
  const _chUp=Math.max(0,_chT-_chD-_chOn);
  const chapChips=_chT?`<div class="ov-chapstats"><span class="ov-chip" onclick="ttChapters('${containerId}','all')" title="View all chapters">Total Chapters: <b>${_chT}</b></span><span class="ov-chip done" onclick="ttChapters('${containerId}','done')" title="View completed chapters">Completed: <b>${_chD}</b></span></div>`:'';
