  const body=_ttView==='weekly'
    ? renderStudentWeekly(tl,wkSubs,opts)
    : (active
        ? renderStudentChapters(tl[active],active,opts)
        : `<div class="card"><div class="card-body"><div class="empty-state"><p>${_noCls?'Select a class to begin, then choose a subject to view its progress and timetable.':'Now select a subject from the dropdown above to view its progress and timetable.'}</p></div></div></div>`);
