// ---- Drag and drop for PDF upload zones ----
function fdOver(e,el){ e.preventDefault(); e.stopPropagation(); el.classList.add('dragging'); }
function fdLeave(e,el){ e.preventDefault(); el.classList.remove('dragging'); }
function fdDrop(e,el,inputId,labelId){
  e.preventDefault(); e.stopPropagation(); el.classList.remove('dragging');
  const files=e.dataTransfer&&e.dataTransfer.files;
  if(!files||!files.length) return;
  const f=files[0];
  if(!/\.pdf$/i.test(f.name||'')){ toast('Please drop a PDF file.',true); return; }
  const inp=document.getElementById(inputId);
  if(!inp) return;
  try{ const dt=new DataTransfer(); dt.items.add(f); inp.files=dt.files; }
  catch(err){ toast('Drag and drop is not supported in this browser. Please click to choose the file.',true); return; }
  const lb=document.getElementById(labelId); if(lb) lb.textContent=f.name;
  toast('PDF selected: '+f.name);
}
