// ---- PDF re-upload replace warning (admin + teacher) ----
/* UPDATE 22: NIOS book chapter rules */
// grammar / writing-skills = NIOS book chapter nahi — progress counting me mat lao
function _isNonBookChapter(name){
  return /grammar|tense|reported speech|narration|direct and indirect|indirect speech|direct speech|conjunction|preposition|clause|modal|subject[ -]?verb|writing skill|notice writing|letter writing|article writing|essay|punctuation|active voice|passive voice|comprehension|unseen/i.test(String(name||''));
}
// merged chapter "Chapter 15 & 16 - X" / "Chapter 25 to 28 - X" -> individual chapter names
function _expandMergedChapter(name){
  const s=String(name||'').trim();
  const m=s.match(/chapter\s*[-–:]?\s*((?:\d+\s*(?:,|&|and|to|\-)?\s*)+\d+)\s*[-–:]/i)||s.match(/chapter\s*[-–:]?\s*((?:\d+\s*(?:,|&|and|to|\-)?\s*)+\d+)$/i);
  if(!m) return null;
  const seg=m[1];
  let nums=[];
  const rg=seg.match(/(\d+)\s*(?:to|\-)\s*(\d+)/i);
  if(rg){ const a=+rg[1],b=+rg[2]; if(b>a&&b-a<=15) for(let i=a;i<=b;i++) nums.push(i); }
  if(!nums.length) nums=(seg.match(/\d+/g)||[]).map(Number);
  nums=[...new Set(nums)].filter(n=>n>0&&n<100);
  if(nums.length<2) return null;
  return nums.map(n=>'Chapter '+n);
}
// subject dropdown chips: sirf book chapters count karo (merged -> individual)
function _countBookChapters(list){
  let n=0;
  (list||[]).forEach(it=>{ if(it.kind!=='chapter'||_isNonBookChapter(it.chapter)) return; n+=(_expandMergedChapter(it.chapter)||['']).length; });
  return n;
}

window._DEMO_TT_B64='';
function downloadDemoTT(){
  try{
    const bin=atob(window._DEMO_TT_B64); const u8=new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++) u8[i]=bin.charCodeAt(i);
    const url=URL.createObjectURL(new Blob([u8],{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'}));
    const a=document.createElement('a'); a.href=url; a.download='MVS_Timetable_Demo_All_Subjects.docx'; a.click();
    setTimeout(()=>URL.revokeObjectURL(url),5000);
  }catch(e){ toast('Download failed',true); }
}

/* UPDATE 22: PDF parse preview — split/delete/edit karke final upload */
window._pdfPreview=null;
function openPdfPreview(rows,opts){
  window._pdfPreview={rows:(rows||[]).map(r=>({subject:r.subject||'',chapter:r.chapter||'',part:r.part||'',date:r.date||'',day:r.day||'',time:r.time||'',type:r.type||'chapter',_grammar:(r.type||'chapter')!=='event'&&_isNonBookChapter(r.chapter),match_action:r.match_action||'',match_no:r.match_no||'',match_title:r.match_title||'',match_kind:r.match_kind||'',match_note:r.match_note||'',match_score:r.match_score,match_candidates:r.match_candidates||[]})),
    isAdmin:!!(opts&&opts.isAdmin), class_name:(opts&&opts.class_name)||'Class 12',
    replace:(opts&&opts.replace)?'true':'false',
    from_date:(opts&&opts.from_date)||'', skipped_before:+(opts&&opts.skipped_before)||0};
  showModal('Check Chapters \u2014 Preview',
   '<div id="pvw-head"></div><div class="pvw-list" id="pvw-list"></div>',
   '<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" id="pvw-btn" onclick="commitPdfPreview()">Final Upload</button>');
  renderPdfPreview();
}
function renderPdfPreview(){
  const P=window._pdfPreview; if(!P) return;
  const head=document.getElementById('pvw-head'), list=document.getElementById('pvw-list');
  if(!head||!list) return;
  const subs=[...new Set(P.rows.map(r=>r.subject).filter(Boolean))];
  const chaps=new Set(P.rows.filter(r=>r.type!=='event'&&!_isNonBookChapter(r.chapter)).map(r=>r.subject+'|'+(r.chapter||'').toLowerCase()));
  const gcount=new Set(P.rows.filter(r=>r.type!=='event'&&_isNonBookChapter(r.chapter)).map(r=>r.subject+'|'+(r.chapter||'').toLowerCase()));
  head.innerHTML=`<div class="alert alert-info" style="margin-bottom:8px"><strong>${P.rows.length} entries \u00b7 ${chaps.size} chapters</strong>${gcount.size?` <span style="color:#b07f1e">+ ${gcount.size} grammar</span>`:''} \u00b7 ${esc(P.class_name)}${subs.length?` \u00b7 ${esc(subs.join(', '))}`:''}<br><span style="font-size:.8rem">Nothing is saved yet. Use the <b>Chapter/Grammar</b> toggle to mark entries (grammar is not counted), <b>Split</b> to separate merged entries, and delete to remove extras \u2014 then tap <b>Final Upload</b>.</span></div>`
   + ((P.from_date&&P.replace==='true')?`<div class="alert alert-warning" style="margin-bottom:8px"><strong>Partial replace active:</strong> entries from <b>${esc(fmtNice(P.from_date))}</b> onwards will be replaced \u2014 everything before that date stays exactly as it is.${P.skipped_before?` ${P.skipped_before} PDF row${P.skipped_before===1?'':'s'} before that date ${P.skipped_before===1?'was':'were'} left out.`:''}</div>`:'')
   + _sylSummary(P.rows);
  const b=document.getElementById('pvw-btn');
  if(!P.rows.length){ list.innerHTML='<div class="ws-empty"><p>All rows have been deleted.</p></div>'; if(b) b.disabled=true; return; }
  if(b) b.disabled=false;
  let lastSub=null, html='';
  P.rows.forEach((r,i)=>{
    if(r.subject!==lastSub){ lastSub=r.subject; html+=`<div class="pvw-subj">${esc(r.subject||'(No subject)')}</div>`; }
    const merged=r.type!=='event'&&_expandMergedChapter(r.chapter);
    html+=`<div class="pvw-row${r.type==='event'?' ev':''}">
      <div class="pvw-date">${r.date?esc(fmtNice(r.date)):'\u2014'}${r.day?`<br>${esc(r.day)}`:''}${r.time?`<br>${esc(r.time)}`:''}</div>
      <div class="pvw-main">
        <input class="form-control pvw-ch" value="${esc(r.chapter||'')}" placeholder="Chapter name" onchange="pvwEdit(${i},'chapter',this.value)">
        <input class="form-control pvw-pt" value="${esc(r.part||'')}" placeholder="Part" onchange="pvwEdit(${i},'part',this.value)">
        ${_sylBadge(r)}
      </div>
      ${merged?'<span class="pvw-merged">Merged</span>':''}
      ${r.type!=='event'?`<div class="pvw-tog"><button class="${!r._grammar?'on':''}" onclick="pvwType(${i},'chapter')">Chapter</button><button class="${r._grammar?'on g':''}" onclick="pvwType(${i},'grammar')">Grammar</button></div>`:''}
      ${r.type!=='event'?`<button class="btn btn-ghost btn-sm" onclick="pvwSplit(${i})" title="Split into separate chapters">Split</button>`:''}
      <button class="btn btn-danger btn-sm" onclick="pvwDel(${i})" title="Delete this row">${ic('trash')}</button>
    </div>`;
  });
  list.innerHTML=html;
}
function pvwEdit(i,f,v){ const P=window._pdfPreview; if(P&&P.rows[i]) P.rows[i][f]=v; }
function pvwType(i,kind){
  const P=window._pdfPreview; if(!P||!P.rows[i]) return;
  const r=P.rows[i];
  if(kind==='grammar'){
    r._grammar=true;
    r.chapter='Grammar: '+(r.chapter||'').replace(/^grammar\s*[:\-]\s*/i,'');
  } else {
    r._grammar=false;
    r.chapter=(r.chapter||'').replace(/^grammar\s*[:\-]\s*/i,'');
  }
  renderPdfPreview();
}
function pvwDel(i){ const P=window._pdfPreview; if(!P) return; P.rows.splice(i,1); renderPdfPreview(); }
function pvwSplit(i){
  const P=window._pdfPreview; if(!P||!P.rows[i]) return;
  const r=P.rows[i];
  const names=_expandMergedChapter(r.chapter)||[(r.chapter||'Chapter')+' 1',(r.chapter||'Chapter')+' 2'];
  P.rows.splice(i,1,...names.map(nm=>Object.assign({},r,{chapter:nm})));
  renderPdfPreview();
  toast('Split into '+names.length+' chapters \u2014 you can edit the names now.');
}
async function commitPdfPreview(){
  const P=window._pdfPreview; if(!P) return;
  if(!P.rows.length){ toast('No rows left.',true); return; }
  const btn=document.getElementById('pvw-btn'); btn.disabled=true; btn.textContent='Uploading...';
  try{
    const r=await api((P.isAdmin?'/api/admin/':'/api/teacher/')+'timetable-pdf-commit','POST',{rows:P.rows,class_name:P.class_name,replace:P.replace,from_date:(P.from_date||'')});
    const isA=P.isAdmin; window._pdfPreview=null; closeModal();
    toast(r.added+' entries uploaded! ');
    if(isA) loadATimetable(); else loadTTimetable();
  }catch(e){ toast('Error: '+e.message,true); btn.disabled=false; btn.textContent='Final Upload'; }
}

function pdfReplaceWarn(subj, entries, warnId, cbId, cls){
  const w=document.getElementById(warnId); if(!w) return;
  subj=(subj||'').trim();
  if(!subj){ w.innerHTML=''; return; }
  const cl=String(cls||'').replace(/\D/g,'');
  // duplicate sirf SAME CLASS me — same-name subject ki dusri class alag timetable hai
  const n=(entries||[]).filter(e=>(e.subject||'').trim().toLowerCase()===subj.toLowerCase()
      &&(!cl||String(e.class_name||'').replace(/\D/g,'')===cl)).length;
  if(n>0){
    w.innerHTML=`<div class="alert alert-warning"><strong>${esc(subj)}</strong>${cls?` (${esc(cls)})`:''} already has <strong>${n}</strong> timetable entr${n===1?'y':'ies'} uploaded. Tick "Replace existing entries" below to replace the old timetable, otherwise the new entries will be added on top of it.</div>`;
    const cb=document.getElementById(cbId); if(cb&&!cb.checked) cb.checked=true;
  } else w.innerHTML='';
}

