async function renderPunchCard(wrapId){
  const wrap=document.getElementById(wrapId); if(!wrap) return;
  let d;
  try{ d=await api('/api/teacher/attendance/today'); }
  catch(e){ wrap.innerHTML=''; return; }
  if(d.policy&&d.policy.disabled){
    wrap.innerHTML=`<div class="myt-card" style="margin-bottom:18px">
      <div style="font-size:.66rem;font-weight:800;letter-spacing:.07em;color:var(--text-muted);text-transform:uppercase;margin-bottom:6px">My Daily Target — set by admin</div>
      <div class="myt-row"><span class="myt-chip gold">TARGET ${d.required_hours||8}h / DAY</span>${d.policy.label?`<span class="myt-chip">${esc(d.policy.label)}</span>`:''}</div>
      <div class="myt-note" style="margin-top:10px">Punch in/out is turned off for you on this portal — your attendance is managed on the other app.</div>
      <div id="myt-est-${wrapId}" style="margin-top:10px"></div>
    </div>`;
    // v105: card ke neeche is mahine ka estimated % + payout page ka rasta
    try{
      const ed=await api('/api/teacher/earnings?month='+curMonth());
      const est=document.getElementById('myt-est-'+wrapId);
      if(est&&ed&&ed.target_only){
        const sp=(ed.earnings&&ed.earnings.salary_pct!=null)?ed.earnings.salary_pct:0;
        const spc=sp>=85?'#15803d':sp>=65?'#b45309':'#b91c1c';
        est.innerHTML=`<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;border-top:1px dashed var(--border);padding-top:10px">
          <div style="font-size:.8rem;font-weight:700">This month's estimated earnings: <b style="color:${spc}">est. ${sp}%</b> of salary</div>
          <button class="btn btn-primary btn-sm" onclick="tPage('payout')">View Estimated Earnings</button>
        </div>`;
      }
    }catch(e){}
    return;
  }
  const dateLbl=new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'short'});
  let statusHtml='', btnHtml='';
  if(!d.punch_in){
    statusHtml=`You have not punched in yet today`;
    btnHtml=`<button class="pw-punchbtn in" id="pw-btn" onclick="doPunch('in')">${ic('finger')} Punch In</button>`;
  } else if(!d.punch_out){
    statusHtml=`<span class="pw-live"><span class="d"></span>ON DUTY SINCE ${esc(d.punch_in)}</span>`;
    btnHtml=`<button class="pw-punchbtn out" id="pw-btn" onclick="doPunch('out')">${ic('finger')} Punch Out</button>`;
  } else {
    statusHtml=`<span class="pw-live" style="background:rgba(16,185,129,.12);color:#059669"><span class="d" style="background:#059669;animation:none"></span>DAY COMPLETE - ${d.hours!=null?d.hours+' HOURS':'DONE'}</span>`;
    btnHtml=`<button class="pw-punchbtn out" id="pw-btn" disabled>${ic('check')} Punched Out at ${esc(d.punch_out)}</button>`;
  }
  wrap.innerHTML=`<div class="pw-shell" style="margin-bottom:18px">
    <div class="pw-banner">${ic('finger')}<div class="pw-bigdate">${esc(dateLbl)}</div><div class="pw-clock" id="pw-clock"></div></div>
    <div class="pw-body">
      <div class="pw-status">${statusHtml}</div>
      ${btnHtml}
      <div class="pw-mini">
        <div class="m"><div class="l">Punch In</div><div class="v">${esc(d.punch_in||'--:--')}</div></div>
        <div class="m"><div class="l">Punch Out</div><div class="v">${esc(d.punch_out||'--:--')}</div></div>
        <div class="m"><div class="l">Counted</div><div class="v">${d.net_hours!=null?d.net_hours+' h':(d.hours!=null?d.hours+' h':'--')}</div></div>
        <div class="m"><div class="l">Target</div><div class="v">${d.required_hours?d.required_hours+' h':'--'}</div></div>
      </div>
      ${d.punch_in&&d.required_hours?`<div class="wt-prog" style="margin:10px 0 2px"><div class="${(d.net_hours||0)>=d.required_hours?'done':''}" style="width:${Math.min(100,Math.round((d.net_hours||0)/d.required_hours*100))}%"></div></div>
      <div style="display:flex;justify-content:space-between;font-size:.68rem;font-weight:700;color:rgba(255,255,255,.75)"><span>${(d.net_hours||0)} of ${d.required_hours}h counted${d.policy&&d.policy.break_minutes?` (break ${d.policy.break_minutes}m skipped)`:''}</span>${d.extra_hours>0?`<span style="color:#93c5fd">+${d.extra_hours}h extra — no extra payout</span>`:`<span>${Math.min(100,Math.round((d.net_hours||0)/d.required_hours*100))}%</span>`}</div>`:''}
      <div id="geo-note"></div>
      <div id="pw-rank-${wrapId}" class="pw-rankwrap"></div>
      <div class="pw-cap">Time is captured automatically in IST. The admin sees your attendance in real time.</div>
    </div></div>`;
  _pwTick();
  _fillPunchRank(wrapId);
  if(!_pwInt) _pwInt=setInterval(_pwTick,1000);
  if(!window._geoState.checked) _loadGeofence(); else _geoNote();
}
// geofence status cache
window._geoState=window._geoState||{checked:false,active:false,offices:[]};
async function _loadGeofence(){
  try{ const g=await api('/api/teacher/geofence'); window._geoState={checked:true,active:!!g.active,offices:g.offices||[],radius:g.radius||null}; }
  catch(e){ window._geoState={checked:true,active:false,offices:[]}; }
  _geoNote();
}
function _geoNote(txt,cls){
  const ns=document.querySelectorAll('#geo-note'); if(!ns.length) return;   // dashboard + attendance dono cards update (DOM me 2 ho sakte hain)
  let h='';
  if(txt){
    if(cls==='success'||cls==='error') window._geoFlash={txt,cls,at:Date.now()};   // re-render ke baad bhi dikhe (10 min tak)
    h=`<div class="alert alert-${cls==='error'?'danger':(cls||'info')}" style="margin-top:10px;font-size:.8rem">${txt}</div>`;
  } else {
    const f=window._geoFlash;
    if(f && Date.now()-f.at<10*60*1000) h=`<div class="alert alert-${f.cls==='error'?'danger':(f.cls||'info')}" style="margin-top:10px;font-size:.8rem">${f.txt}</div>`;
    else{
      window._geoFlash=null;
      if(window._geoState.active){ const rad=window._geoState.radius;
        const br=(window._geoState.offices||[]).map(o=>`${esc(o.name)}: ${o.radius||rad||0}m`).join(' · ');
        h=`<div style="font-size:.72rem;color:var(--text-muted);margin-top:8px;text-align:center">Location check ON — punch-in is allowed only from within the office radius${br?` (<b>${br}</b>)`:(rad?` (<b>${rad}m</b>)`:'')}.</div>`; }
    }
  }
  ns.forEach(n=>n.innerHTML=h);
}
function _stripTags(h){
  const d=document.createElement('div'); d.innerHTML=String(h||'');
  return d.textContent||'';
}
function _geoErrMsg(code){
  const ua=navigator.userAgent||'';
  const ios=/iPad|iPhone|iPod/.test(ua), and=/Android/i.test(ua);
  if(code===1){
    if(ios) return 'Location is BLOCKED. On iPhone: tap the <b>aA icon</b> in the address bar → Website Settings → Location → <b>Allow</b> (Location Services must be ON: Settings → Privacy &amp; Security → Location Services). Then tap "Try Again".';
    if(and) return 'Location is BLOCKED. Tap the <b>lock icon</b> in the address bar → Permissions → Location → <b>Allow</b>, then tap "Try Again".';
    return 'Location is BLOCKED. Tap the <b>lock icon</b> in the address bar → Site settings → Location → <b>Allow</b>, then tap "Try Again".';
  }
  if(code===2) return 'Could not get your location — turn on <b>GPS/Location</b> on your phone and try again.';
  if(code===3) return 'Location timed out — the GPS signal is weak. Move to an open area and tap "Try Again".';
  return 'Could not fetch your location. Please turn on GPS and try again.';
}
function _getLocation(onProg){
  return new Promise((res,rej)=>{
    if(!navigator.geolocation){ rej(new Error('This device/browser does not support location — please try Chrome or Safari on your mobile.')); return; }
    let best=null, settled=false, wid=null;
    const cleanup=()=>{ if(wid!=null){ try{navigator.geolocation.clearWatch(wid);}catch(e){} wid=null; } };
    const ok=()=>{ if(settled) return; settled=true; cleanup(); res(best); };
    const fail=m=>{ if(settled) return; settled=true; cleanup(); rej(new Error(m)); };
    // watchPosition: kai readings aati hain — pehli kabhi-kabhi bahut coarse hoti hai (PC/IP ±2000m),
    // GPS/WiFi lock hote hi behtar hoti hai. 14s tak ka BEST reading lete hain.
    wid=navigator.geolocation.watchPosition(
      pos=>{ const c={lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy:pos.coords.accuracy||9999};
             if(!best||c.accuracy<best.accuracy){ best=c; if(onProg) onProg(best); }
             if(best.accuracy<=25) ok(); },
      err=>{ if(err&&err.code===1) fail(_geoErrMsg(1)); },
      {enableHighAccuracy:true,maximumAge:0,timeout:20000});
    setTimeout(()=>{ if(best) ok(); else fail(_geoErrMsg(3)); }, window._GEO_MAX_WAIT||14000);
    setTimeout(()=>{ if(best&&best.accuracy>=1500) ok(); }, window._GEO_FAST_WAIT||6000);   // IP-based reading (PC) — aur improve nahi hogi
  });
}
async function doPunch(kind,confirm){
  const btn=document.getElementById('pw-btn');
  window._geoFlash=null;
  if(kind==='out'&&!confirm){ window._punchOutArmed=false; }
  if(!window._geoState.checked) await _loadGeofence();
  let payload={}, geoErr=null, wifiWhy=null;
  if(window._geoState.active){
    if(btn){ btn.disabled=true; btn.textContent='Location check...'; }
    // permission state pehle dekho — denied ho to GPS skip, WiFi fallback try hoga
    let denied=false;
    try{
      if(navigator.permissions&&navigator.permissions.query){
        const st=await navigator.permissions.query({name:'geolocation'});
        if(st&&st.state==='denied'){
          denied=true; geoErr=_geoErrMsg(1);
          if(!window._geoPermWatch){ window._geoPermWatch=true;   // settings me allow karte hi auto-punch
            st.onchange=()=>{ if(st.state==='granted'){ window._geoPermWatch=false; _geoNote('Permission granted — continuing your punch...','info'); doPunch(kind); } }; }
        }
        else if(st.state==='prompt') _geoNote('The browser will ask for <b>location permission</b> — tap <b>Allow</b> and your punch happens automatically.','info');
        else _geoNote('Checking your location...','info');
      } else _geoNote('Checking your location...','info');
    }catch(e){ _geoNote('Checking your location...','info'); }
    if(!denied){
      try{ payload=await _getLocation(b=>_geoNote(`Getting your location… (±${Math.round(b.accuracy)}m — waiting for the best reading)`,'info')); }
      catch(e){ geoErr=e.message; payload={}; }   /* GPS fail — neeche WiFi fallback try hoga */
    }
    if(geoErr || payload.accuracy==null || (payload.accuracy!=null && payload.accuracy>80)){
      // GPS weak/unavailable (upper floor / indoor). Hard block NAHI — request bhejo, backend
      // office WiFi se verify kar lega. Jo coords mile (agar mile) wahi bhej do.
      _geoNote('GPS weak/unavailable — verifying via <b>office WiFi</b> (upper floors ke liye)…','info');
      if(payload.accuracy==null) payload=(payload&&payload.lat!=null)?payload:{};
    }
  }
  if(btn){ btn.disabled=true; btn.textContent=kind==='in'?'Punching In...':'Punching Out...'; }
  if(kind==='out'&&confirm) payload.confirm=true;
  try{
    const r=await api('/api/teacher/attendance/punch-'+kind,'POST',payload);
    if(r.need_confirm){
      // <1h punch-out: teacher ko warn karo + dobara press pe confirm
      window._punchOutArmed=true;
      toast(r.message,true);
      _geoNote('<b>Short day warning</b> — '+esc(r.message),'error');
      document.querySelectorAll('.pw-punchbtn.out').forEach(b=>{
        b.disabled=false; b.classList.add('confirm-arm');
        b.innerHTML='Confirm Punch Out — mark Present (Short)';
        b.onclick=()=>doPunch('out',true);
      });
      return;   // re-render nahi — armed button apni jagah rahe
    }
    window._punchOutArmed=false;
    toast(r.message);
    if(r.wifi) _geoNote(`Verified via <b>Office WiFi</b> — you are at <b>${esc(r.office||'office')}</b>. Punch recorded.`,'success');
    else if(r.distance!=null) _geoNote(`Location verified — you are at <b>${esc(r.office||'office')}</b> (<b>${r.distance}m</b> from office).`,'success');
  }catch(e){
    const m=String(e.message||'');
    if(m.startsWith('outside|')){
      const parts=m.split('|');
      const [,branch,dist,rad]=parts.length===4?parts:[null,'office',parts[1],parts[2]];
      _geoNote(`<b>Outside Office Area</b> — you are <b>${dist}m</b> away from <b>${esc(branch)}</b> (allowed: ${rad}m). Please move closer to the office to punch.`,'error');
      toast('Outside office area — punch failed.',true);
    } else if(payload.wifi_fallback){
      const wifiHelp='<div style="margin-top:6px">If you are on <b>office WiFi</b>: this WiFi IP is not on the list yet — <b>ask the admin</b> to add it from Office Location → "New IPs" (a one-click job).</div>';
      _geoNote((wifiWhy||esc(m))+wifiHelp,'error');
      toast(_stripTags(wifiWhy||m),true);
    } else { toast(m,true); if(m.includes('Location')||m.includes('GPS')) _geoNote(esc(m),'error'); }
  }
  if(document.getElementById('t-punch-wrap')) renderPunchCard('t-punch-wrap');
  if(document.getElementById('ta-punch-wrap')) renderPunchCard('ta-punch-wrap');
  if(document.getElementById('ta-timing')) tMyTiming();
  if(document.getElementById('ta-history')) tAttHistory();
}

