let _tAttMonth='';
async function loadTAttendance(){
  const el=document.getElementById('t-attendance-content');
  if(window._tAttOff){ renderTTargetOnly(el); return; }
  _tAttMonth=_tAttMonth||curMonth();
  el.innerHTML=`<div class="sm-head"><h2>My Attendance</h2><p>Punch in / punch out daily. Your counted hours = punch gap <b>minus lunch break</b> (full time). Leaving before your assigned hours still marks you <b>Present (Short)</b>. Please take prior approval for any leave.</p></div>
    <div id="ta-timing"></div>
    <div class="att-grid">
      <div id="ta-punch-wrap"></div>
      <div class="card"><div class="card-header"><h3>Month Overview</h3><input type="month" class="form-control" style="width:auto;padding:6px 10px" id="ta-month" value="${_tAttMonth}" onchange="_tAttMonth=this.value;tAttHistory()"></div><div class="card-body" id="ta-cal"><div class="spinner"></div></div></div>
      <div class="card"><div class="card-header"><h3>Leave Requests</h3><button class="btn btn-primary btn-sm" onclick="openTLeave()">${ic('plus')} Apply Leave</button></div><div class="card-body" id="ta-leaves"><div class="spinner"></div></div></div>
    </div>
    <div class="card" style="margin-top:18px"><div class="card-header"><h3>Recent Days</h3></div><div class="card-body" id="ta-logs"><div class="spinner"></div></div></div>
    <div class="card" style="margin-top:18px"><div class="card-header"><h3>Full Month Record</h3><span id="ta-summary" style="display:flex;gap:8px;flex-wrap:wrap"></span></div><div class="card-body"><div id="ta-history"><div class="spinner"></div></div></div></div>`;
  renderPunchCard('ta-punch-wrap');
  tMyTiming();
  tAttHistory();
  tLeaveFetch();
}
// ---- My Work Timing card (teacher, read-only) ----
async function tMyTiming(){
  const box=document.getElementById('ta-timing'); if(!box) return;
  try{
    const [wp,td]=await Promise.all([api('/api/teacher/work-policy'),api('/api/teacher/attendance/today')]);
    const p=wp.policy||{};
    const wtChip=p.work_type==='part_time'?'<span class="myt-chip blue">PART TIME</span>':'<span class="myt-chip gold">FULL TIME</span>';
    const modeChip=p.mode==='flexible'?'<span class="myt-chip">FLEXIBLE · MIN 1H</span>'
      :p.mode==='fixed'?`<span class="myt-chip">FIXED · ${esc(p.entry_time||'')} – ${esc(p.exit_time||'')}</span>`
      :'<span class="myt-chip">HOURS ONLY · NO FIXED TIME</span>';
    const brkChip=(p.work_type==='full_time'&&p.break_minutes)?`<span class="myt-chip">LUNCH ${p.break_minutes}M — NOT COUNTED</span>`:'';
    const req=p.required||8;
    const net=(td&&td.net_hours!=null)?td.net_hours:null;
    const pct=net!=null?Math.min(100,Math.round(net/req*100)):0;
    const extra=(td&&td.extra_hours)||0;
    const state=net==null?'<span class="myt-chip">NOT PUNCHED IN YET</span>'
      :td.punch_out&&net>=req?'<span class="myt-chip green">DAY TARGET COMPLETE</span>'
      :td.punch_out?'<span class="myt-chip gold">PRESENT · SHORT</span>'
      :net>=req?'<span class="myt-chip green">TARGET DONE — STILL ON DUTY</span>':'<span class="myt-chip">ON DUTY</span>';
    box.innerHTML=`<div class="myt-card">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;flex-wrap:wrap">
        <div><div style="font-size:.66rem;font-weight:800;letter-spacing:.07em;color:var(--text-muted);text-transform:uppercase;margin-bottom:6px">My Work Timing — set by admin</div>
          <div class="myt-row">${wtChip}${modeChip}${brkChip}<span class="myt-chip gold">TARGET ${req}h / DAY</span></div></div>
        ${state}
      </div>
      <div class="wt-prog" style="margin-top:14px"><div class="${net!=null&&net>=req?'done':''}" style="width:${pct}%"></div></div>
      <div style="display:flex;justify-content:space-between;font-size:.74rem;font-weight:700;color:var(--text-muted);margin-top:6px">
        <span>Today: <b style="color:var(--text)">${net!=null?net+' h':'—'}</b> counted of ${req}h</span>
        ${extra>0?`<span style="color:#2563eb">+${extra}h extra today (no extra payout)</span>`:'<span>'+pct+'% of target</span>'}
      </div>
      ${p.work_type==='full_time'&&p.break_minutes?`<div class="myt-note">Lunch break of <b>${p.break_minutes} minutes</b> is skipped from your counted hours — e.g. a ${req}+${Math.round(p.break_minutes/60*10)/10}h punch gap counts as ${req}h.</div>`:''}
    </div>`;
  }catch(e){ box.innerHTML=''; }
}
// ---- Leave (teacher) ----
async function tLeaveFetch(){
  const box=document.getElementById('ta-leaves'); if(!box) return;
  try{
    const d=await api('/api/teacher/leaves/my');
    const rows=d.leaves||[];
    box.innerHTML=rows.length?rows.map(l=>{
      const pill=l.status==='approved'?'<span class="po-pill green">APPROVED</span>':l.status==='rejected'?'<span class="po-pill red">REJECTED</span>':'<span class="po-pill amber">PENDING</span>';
      return `<div class="lv-row"><div style="min-width:0"><div class="lv-d">${esc(fmtNice(l.start_date))}${l.end_date!==l.start_date?' → '+esc(fmtNice(l.end_date)):''} <span style="font-weight:600;color:var(--text-muted)">(${l.leave_type==='half'?'Half day':'Full day'})</span></div>
        <div class="lv-r">${esc(l.reason)}${l.admin_remark?` · <b>Admin:</b> ${esc(l.admin_remark)}`:''}</div></div>${pill}</div>`;
    }).join(''):`<div class="pay-empty">No leave requests yet. Need a day off? Apply first — approved leave is marked as <b>Leave</b>, not absent. Without approval, the day counts as <b>AB</b>.</div>`;
  }catch(e){ box.innerHTML=errHtml(e); }
}
function openTLeave(){
  const today=new Date().toISOString().slice(0,10);
  showModal('Apply for Leave',`
    <div class="form-grid vt-form">
      <div class="form-group"><label>From Date</label><input id="tlv-from" type="date" class="input" value="${today}" min="${today}"></div>
      <div class="form-group"><label>To Date</label><input id="tlv-to" type="date" class="input" value="${today}" min="${today}"></div>
      <div class="form-group" style="grid-column:1/-1"><label>Leave Type</label><select id="tlv-type" class="input"><option value="full">Full Day</option><option value="half">Half Day (same date)</option></select></div>
      <div class="form-group" style="grid-column:1/-1"><label>Reason</label><textarea id="tlv-reason" class="input" rows="2" placeholder="e.g. Family function, medical appointment..."></textarea></div>
    </div>
    <p style="font-size:.74rem;color:var(--text-muted)">Your request goes to the admin for approval. <b>Approved</b> leave is marked as Leave in your record; leave taken <b>without approval</b> is marked AB (absent).</p>`,
    `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="tLeaveApply()">${ic('send')} Send for Approval</button>`);
}
async function tLeaveApply(){
  const payload={start_date:val('tlv-from'),end_date:val('tlv-to'),leave_type:val('tlv-type'),reason:(val('tlv-reason')||'').trim()};
  if(!payload.start_date||!payload.end_date){ toast('Please pick the leave dates'); return; }
  if(payload.reason.length<3){ toast('Please write a short reason'); return; }
  try{
    await api('/api/teacher/leaves/apply','POST',payload);
    closeModal(); toast('Leave request sent for approval.');
    tLeaveFetch(); tAttHistory();
  }catch(e){ toast(e.message||'Could not apply'); }
}
async function tAttHistory(){
  const box=document.getElementById('ta-history'); if(!box) return;
  const cal=document.getElementById('ta-cal'), logs=document.getElementById('ta-logs');
  try{
    const d=await api('/api/teacher/attendance/history?month='+encodeURIComponent(_tAttMonth||curMonth()));
    const sm=document.getElementById('ta-summary');
    if(sm) sm.innerHTML=`<span class="po-pill green">PRESENT ${d.present_days}</span><span class="po-pill blue">LEAVE ${d.leave_days||0}</span>${d.short_days?`<span class="po-pill amber">SHORT ${d.short_days} (PRESENT)</span>`:''}<span class="po-pill red">AB ${d.absent_days||0}</span><span class="po-pill gold">${d.total_hours} COUNTED HRS</span>${d.extra_hours>0?`<span class="po-pill" style="background:rgba(37,99,235,.12);color:#1d4ed8">+${d.extra_hours}H EXTRA (NO PAYOUT)</span>`:''}`;
    // ---- calendar ----
    if(cal){
      const [yy,mm]=d.month.split('-').map(Number);
      const daysIn=new Date(yy,mm,0).getDate();
      const byDate={}; d.rows.forEach(r=>byDate[r.date]=r);
      const leaves=new Set(d.leave_dates||[]);
      const now=new Date(); const isCur=(now.getFullYear()===yy&&now.getMonth()+1===mm);
      const lastEl=isCur?now.getDate():daysIn;
      const _off=(new Date(yy,mm-1,1).getDay()+6)%7;
      let cells='';
      for(let _b=0;_b<_off;_b++) cells+='<div class="cal-d blank"></div>';
      for(let day=1;day<=daysIn;day++){
        const ds=`${yy}-${String(mm).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
        const r=byDate[ds];
        let cls='';
        if(r){ cls=r.status==='present'?' on':(r.status==='short'?' sh':''); }
        else if(leaves.has(ds)) cls=' lv';
        else if(day<=lastEl&&!isCur||(isCur&&day<now.getDate())) cls=' ab';
        if(isCur&&day>now.getDate()) cls='';
        const today=isCur&&now.getDate()===day;
        cells+=`<div class="cal-d${cls}${today?' today':''}${(!cls&&isCur&&day>now.getDate())?' future':''}">${day}</div>`;
      }
      cal.innerHTML=`<div class="cal-head">
          <div class="cal-stat g"><div class="n">${d.present_days}</div><div class="l">Present</div></div>
          <div class="cal-stat" style="--x:1"><div class="n" style="color:#1d4ed8">${d.leave_days||0}</div><div class="l">Leave</div></div>
          <div class="cal-stat"><div class="n" style="color:#b45309">${d.short_days||0}</div><div class="l">Short</div></div>
          <div class="cal-stat r"><div class="n">${d.absent_days||0}</div><div class="l">AB</div></div>
          <div class="cal-stat b"><div class="n">${d.total_hours}</div><div class="l">Hours</div></div>
        </div>
        <div class="cal-wk"><span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span><span>Sun</span></div>
        <div class="cal-grid">${cells}</div>
        <div class="cal-leg"><span><i style="background:rgba(16,185,129,.6)"></i>Present</span><span><i style="background:rgba(59,130,246,.55)"></i>Leave</span><span><i style="background:rgba(245,158,11,.6)"></i>Present · Short (early leave)</span><span><i style="background:rgba(220,38,38,.45)"></i>AB</span><span><i style="outline:2px solid #b8941f;outline-offset:-1px;background:transparent"></i>Today</span></div>`;
    }
    // ---- recent logs ----
    if(logs){
      const recent=d.rows.slice(0,6);
      const pill=r=>r.status==='present'?'<span class="po-pill green">PRESENT</span>':r.status==='short'?'<span class="po-pill amber">PRESENT · SHORT</span>':r.status==='working'?'<span class="po-pill blue">ON DUTY</span>':'<span class="po-pill amber">NO PUNCH</span>';
      logs.innerHTML=recent.length?recent.map(r=>`<div class="log-row">
          <div><div class="d">${esc(fmtNice(r.date))}</div><div class="t">${esc(r.punch_in||'-')} ${r.punch_out?'to '+esc(r.punch_out):''}${r.net_hours!=null?' - '+r.net_hours+' hrs counted':''}${r.extra_hours>0?` <span class="att-x">+${r.extra_hours}h extra</span>`:''}</div></div>
          ${pill(r)}
        </div>`).join(''):`<div class="pay-empty">No attendance yet this month. Punch in on any working day and it will appear here.</div>`;
    }
    // ---- full table ----
    const stPill=s=>s==='present'?'<span class="po-pill green">PRESENT</span>':s==='short'?'<span class="po-pill amber">PRESENT · SHORT</span>':s==='working'?'<span class="po-pill blue">ON DUTY</span>':'-';
    if(!d.rows.length){ box.innerHTML=`<div class="empty-state"><p>No attendance recorded in ${esc(fmtMonthLabel(d.month))} yet.</p></div>`; return; }
    box.innerHTML=`<div style="overflow-x:auto"><table class="att-table"><thead><tr><th>Date</th><th>Day</th><th>Punch In</th><th>Punch Out</th><th>Counted</th><th>Extra</th><th>Status</th></tr></thead><tbody>${
      d.rows.map(r=>`<tr><td>${esc(fmtNice(r.date))}</td><td>${esc(r.day)}</td><td>${esc(r.punch_in||'-')}</td><td>${esc(r.punch_out||'-')}</td><td>${r.net_hours!=null?`<b>${r.net_hours} h</b>`:'-'}${r.net_hours!=null&&r.hours!=null&&r.net_hours!==r.hours?`<div class="att-brk">gap ${r.hours}h − break</div>`:''}</td><td>${r.extra_hours>0?`<b style="color:#2563eb">+${r.extra_hours}h</b>`:'—'}</td><td>${stPill(r.status)}</td></tr>`).join('')
    }</tbody></table></div>`;
  }catch(e){ box.innerHTML=errHtml(e); if(cal)cal.innerHTML=''; if(logs)logs.innerHTML=''; }
}

// ---- Appointment letter (shared builder) ----
function buildLetterHTML(c){
  const today=new Date().toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'});
  const jd=c.joining_date?new Date(c.joining_date).toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'}):'as mutually agreed';
  const rules=(c.rules||[]).length?`<div style="margin-top:14px"><strong>Rules and Conditions</strong><ol class="al-rules" style="margin:8px 0 0 18px">${c.rules.map(r=>`<li>${esc(r)}</li>`).join('')}</ol></div>`:'';
  const sig=c.accepted?`<div style="margin-top:6px"><span class="al-sig">${esc(c.signature_name||c.teacher_name||'')}</span><div style="font-size:.78rem;color:var(--text-muted)">Digitally signed by ${esc(c.signature_name||'')} on ${esc(c.accepted_at||'')}</div></div>`:`<div style="margin-top:22px;border-bottom:1.5px solid var(--border);width:220px"></div><div style="font-size:.78rem;color:var(--text-muted);margin-top:4px">Signature of Teacher</div>`;
  return `<div class="al-letter">
    <div class="al-lh"><div class="b">MVS FOUNDATION</div><div class="s">Manish Verma Classes - NIOS Coaching Institute, Delhi</div></div>
    <div style="display:flex;justify-content:space-between;font-size:.82rem;color:var(--text-muted)"><span>Ref: MVS/APT/${esc((c.teacher_name||'T').split(' ')[0].toUpperCase())}</span><span>Date: ${esc(today)}</span></div>
    <h2>APPOINTMENT LETTER</h2>
    <p>Dear <strong>${esc(c.teacher_name||'Teacher')}</strong>,</p>
    <p>We are pleased to appoint you as <strong>${esc(c.designation||'Subject Teacher')}</strong> at MVS Foundation (Manish Verma Classes), effective <strong>${esc(jd)}</strong>. Your terms of engagement are as follows:</p>
    <table class="terms">
      <tr><td>Designation</td><td>${esc(c.designation||'Subject Teacher')}</td></tr>
      <tr><td>Date of Joining</td><td>${esc(jd)}</td></tr>
      ${(c.breakup||[]).length?c.breakup.map(b=>`<tr><td>${esc(b.label)}</td><td>${fmtINR(b.amount)}</td></tr>`).join(''):`<tr><td>Monthly Base Salary</td><td>${fmtINR(c.base_salary)}</td></tr>
      <tr><td>Fixed Monthly Allowances</td><td>${fmtINR(c.allowances)}</td></tr>`}
      <tr><td style="font-weight:700">Gross Monthly Salary</td><td style="font-weight:700">${fmtINR(c.gross_salary||(c.base_salary+(c.allowances||0)))}</td></tr>
      <tr><td>Payable Working Days</td><td>${c.working_days} days per month</td></tr>
      <tr><td>Per Day Rate</td><td>${fmtINR(c.per_day_rate)}</td></tr>
    </table>
    <p><strong>Attendance and Payment Policy.</strong> Daily attendance is recorded through the portal Punch In and Punch Out system. For every payable working day not attended, a deduction equal to the per day rate (${fmtINR(c.per_day_rate)}) is applied. Payments for extra classes, bonuses and any deductions are always itemised with reasons in the Payout section of your portal, so you can see exactly where full payment is made and where a deduction applies.</p>
    ${rules}
    <p style="margin-top:16px">We look forward to working with you towards the success of our students.</p>
    <div style="display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;margin-top:26px">
      <div><div style="font-weight:700">Accepted by</div>${sig}</div>
      <div style="text-align:right"><div style="font-weight:700">For MVS Foundation</div><div class="al-sig" style="margin-top:6px">Manish Verma</div><div style="font-size:.78rem;color:var(--text-muted)">Director, MVS Foundation</div></div>
    </div>
  </div>`;
}
