function _letterHTML(d){
  const t=d.teacher, pay=d.pay, tg=d.targets;
  if((pay.payout_mode||'standard')==='contract') return _contractLetterHTML(d);
  const maxPot=pay.class_retainer+pay.class_quality+pay.notes_dpp+pay.doubt_resolution+pay.project_delivery;
  const refNo=d.letter.ref;
  // v91: digital signatures — founder ka authorised sign + teacher ka typed sign (accept ke baad)
  const lt=d.letter||{};
  const _sigCss="font-family:'Great Vibes',cursive;font-size:26px;color:#1a2a4a;line-height:1.05";
  const fndSig=`<div style="${_sigCss}">Manish Verma</div>`;
  const tchrSig=(lt.accepted&&lt.signature_name)?`<div style="${_sigCss}">${esc(lt.signature_name)}</div>`:`<div style="height:28px"></div>`;
  const tchrDate=(lt.accepted&&lt.signed_at)?`Digitally signed on ${esc(lt.signed_at)}`:'Date: ___________________';
  const payRows=[
   ['Class Conduct Retainer','Earned by conducting all scheduled timetable classes for the month. Proportionally reduced only if classes are not conducted without prior approval.',pay.class_retainer],
   ['Class Quality Incentive','Earned by starting every class on time, maintaining full scheduled duration, and keeping portal attendance records accurate.',pay.class_quality],
   ['Notes, DPP & Weekly Tests','Earned by uploading complete Class Notes and DPP within 24 hours for every class conducted, and creating the required Weekly Tests (MCQ / Subjective) each month.',pay.notes_dpp],
   ['Doubt Resolution Bonus','Earned by resolving 100% of student doubts assigned on the portal within an average of 15 hours. Proportionally reduced for unresolved doubts.',pay.doubt_resolution],
   ['Project, Task & Content Delivery','Earned by submitting all production tasks and projects on time, and achieving monthly content targets: Weekly Tests, One Shot & Revision Videos, YouTube Live Sessions, and Shorts.',pay.project_delivery]
  ];
  const _tl=tg.labels||{};
  const targetRows=[
   [(_tl.tests||'Weekly Tests')+' (MCQ / Subjective)', tg.tests_target+' per month', 'AUTO'],
   ['Class Notes Upload (within 24 hrs)', '100% of classes conducted', 'AUTO'],
   ['DPP Upload (within 24 hrs)', '100% of classes conducted', 'AUTO'],
   [_tl.videos||'One Shot / Revision Videos', tg.videos_target+' per month', 'MANUAL'],
   [_tl.live||'YouTube Live Sessions', tg.live_target+' per month', 'MANUAL'],
   [(_tl.shorts||'Shorts')+' (\u2265 60 seconds)', tg.shorts_target+' per month', 'MANUAL'],
   ['Doubt Resolution', '100% of assigned doubts', 'AUTO'],
   ['Project / Production Tasks', '100% on-time delivery', 'MANUAL']
  ].concat((tg.custom||[]).map(c=>[c.name, c.count+' per month', 'MANUAL']));
  const details=[['Designation',t.designation],['Department',t.department],['Date of Joining','as mutually agreed'],['Reporting To','Academic Head, MVS Foundation'],['Mode of Work','Offline — MVS Foundation'],['Contract Type','Performance-Linked Engagement (renewable annually)']];
  return `<div style="${_DOC_FONT}">
  ${_LH(refNo,d.letter.date,true)}
  <div style="text-align:center;margin-bottom:16px"><div style="display:inline-block;border-top:2px solid #0F2A54;border-bottom:2px solid #0F2A54;padding:5px 28px"><span style="font-weight:800;font-size:14px;letter-spacing:3px;color:#0F2A54;text-transform:uppercase">Letter of Appointment</span></div></div>
  ${_P('Dear <strong>'+esc(t.name)+',</strong>')}
  ${_P('We are pleased to extend this offer of appointment to you as <strong>'+esc(t.designation)+'</strong> in the <strong>'+esc(t.department)+'</strong> division at <strong>Manish Verma Study Foundation (MVS)</strong>. This letter outlines the terms of your engagement, including how your compensation is earned, the performance targets you are expected to meet, and the professional standards required. Please read carefully — by signing and returning a copy you accept all terms herein.')}
  ${_SEC('1. Appointment Details')}
  <table style="width:100%;border-collapse:collapse;font-size:9.5px;margin-bottom:10px"><tbody>
   ${details.map(r=>`<tr style="border-bottom:1px solid #e4ebf5"><td style="padding:5px 9px;font-weight:700;color:#0F2A54;width:36%;background:#f7f9fc">${r[0]}</td><td style="padding:5px 9px;color:#1a2a3a">${esc(r[1])}</td></tr>`).join('')}
  </tbody></table>
  ${_SEC('2. Work-Based Earnings Model')}
  ${_P('At MVS Foundation, <strong>you earn based on the work you deliver</strong> — not a fixed salary that is then reduced for non-performance. Each component of your monthly pay is attached to a specific category of work. Complete that work fully and on time, and you earn the full amount for that component. This model is designed to be transparent, fair, and motivating.')}
  <div style="background:linear-gradient(135deg,#0F2A54,#1a3d70);border-radius:8px;padding:12px 16px;margin-bottom:12px;display:flex;justify-content:space-between;align-items:center;gap:10px">
   <div style="color:#fff">
    <div style="font-size:9px;opacity:.65;margin-bottom:2px;letter-spacing:.5px;text-transform:uppercase">Maximum Monthly Earning Potential</div>
    <div style="font-size:26px;font-weight:900">${_inr(maxPot)}</div>
    <div style="font-size:8.5px;opacity:.65;margin-top:2px">Achieved by completing 100% of all commitments each month</div>
   </div>
   <div style="display:flex;gap:10px">
    <div style="background:rgba(255,255,255,.1);border-radius:7px;padding:8px 14px;text-align:center;min-width:100px"><div style="color:#FF6B2B;font-weight:900;font-size:15px">${_inr(pay.class_retainer)}</div><div style="color:rgba(255,255,255,.9);font-size:8px;font-weight:700;margin-top:3px">Class Conduct Retainer (60%)</div><div style="color:rgba(255,255,255,.5);font-size:7.5px;margin-top:1px">Conduct all scheduled classes</div></div>
    <div style="background:rgba(255,255,255,.1);border-radius:7px;padding:8px 14px;text-align:center;min-width:100px"><div style="color:#FF6B2B;font-weight:900;font-size:15px">${_inr(maxPot-pay.class_retainer)}</div><div style="color:rgba(255,255,255,.9);font-size:8px;font-weight:700;margin-top:3px">Performance Incentives</div><div style="color:rgba(255,255,255,.5);font-size:7.5px;margin-top:1px">Content, doubts & tasks</div></div>
   </div>
  </div>
  <table style="width:100%;border-collapse:collapse;font-size:9.5px;margin-bottom:10px">
   <thead><tr style="background:#0F2A54;color:#fff"><th style="padding:6px 9px;text-align:left;font-weight:700;width:28%">Earnings Component</th><th style="padding:6px 9px;text-align:left;font-weight:700">How It Is Earned</th><th style="padding:6px 9px;text-align:right;font-weight:700;width:16%">Max / Month</th></tr></thead>
   <tbody>
   ${payRows.map((r,i)=>`<tr style="background:${i%2===0?'#fff':'#f7f9fc'};border-bottom:1px solid #e4ebf5;vertical-align:top"><td style="padding:7px 9px;font-weight:700;color:#0F2A54">${r[0]}</td><td style="padding:7px 9px;color:#3a4a5c;line-height:1.55;font-size:9px">${r[1]}</td><td style="padding:7px 9px;text-align:right;font-weight:800;color:#1a2a3a;font-size:11px">${_inr(r[2])}</td></tr>`).join('')}
   <tr style="background:#0F2A54;color:#fff"><td colspan="2" style="padding:7px 9px;font-weight:800">Maximum Monthly Earning Potential</td><td style="padding:7px 9px;text-align:right;font-weight:900;font-size:13px">${_inr(maxPot)}</td></tr>
   </tbody></table>
  ${_P('<em>Your portal\u2019s "Payout" dashboard shows a real-time breakdown of earnings accumulated vs remaining potential throughout each month. Payment is released by the 5th of the following month.</em>','color:#5A6B85;font-size:9px')}
  <div style="page-break-after:always"></div>
  ${_SEC('3. Professional Conduct Standards')}
  ${_P('The following standards are mandatory. They exist to protect student experience and institute reputation. Non-compliance does not result in a penalty against a fixed salary — rather, it means the work for that component is considered incomplete and the corresponding earnings are not released.')}
  ${_LETTER_RULES.map(s=>`<div style="margin-bottom:10px">
    <div style="font-weight:800;font-size:10.5px;color:${s.color};margin-bottom:6px">${s.num} &nbsp; ${esc(s.title)}</div>
    ${s.rules.map((r,i)=>`<div style="display:flex;gap:7px;margin-bottom:4px"><div style="min-width:17px;height:17px;border-radius:50%;background:${s.color}20;color:${s.color};font-size:8.5px;font-weight:800;display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:1px">${i+1}</div><p style="font-size:9.5px;color:#1a2a3a;line-height:1.7;margin:0">${esc(r)}</p></div>`).join('')}
   </div>`).join('')}
  <div style="page-break-after:always"></div>
  ${_SEC('4. Monthly Earning Targets')}
  <div style="border:1.5px solid #FF6B2B;border-radius:6px;padding:8px 13px;background:#fffbf5;margin-bottom:8px">
   <div style="font-weight:800;font-size:9.5px;color:#FF6B2B;margin-bottom:3px">Targets Are Set by the Admin Each Month</div>
   <p style="font-size:9px;color:#3a2a2a;line-height:1.65;margin:0">The specific quantities for each target category (number of videos, tests, sessions, etc.) are determined by the Academic Admin and updated on your portal during the <strong>first week of every month</strong>. It is your responsibility to check your portal at the start of each month and confirm your targets before commencing work. The categories below are fixed; only the monthly quantities vary.</p>
  </div>
  <table style="width:100%;border-collapse:collapse;font-size:9px;margin-bottom:12px">
   <thead><tr style="background:#0F2A54;color:#fff"><th style="padding:5px 8px;text-align:left;font-weight:700;width:4%">#</th><th style="padding:5px 8px;text-align:left;font-weight:700">Target Category</th><th style="padding:5px 8px;text-align:center;font-weight:700;width:28%">Monthly Requirement</th><th style="padding:4px 8px;text-align:center;font-weight:700;width:10%">Tracking</th></tr></thead>
   <tbody>${targetRows.map((r,i)=>`<tr style="background:${i%2===0?'#fff':'#f7f9fc'};border-bottom:1px solid #e4ebf5"><td style="padding:4px 8px;color:#8899aa;font-weight:700">${i+1}</td><td style="padding:4px 8px;color:#1a2a3a;font-weight:500">${esc(r[0])}</td><td style="padding:4px 8px;text-align:center;font-weight:700;color:#0F2A54;font-size:9px">${esc(r[1])}</td><td style="padding:4px 8px;text-align:center"><span style="background:${r[2]==='AUTO'?'#e8f5e9':'#f0ebff'};color:${r[2]==='AUTO'?'#1b7a3e':'#6b3fd4'};border-radius:3px;padding:1px 6px;font-size:7.5px;font-weight:800">${r[2]}</span></td></tr>`).join('')}</tbody></table>
  ${_SEC('5. Non-Compliance — Earnings Impact','#c0392b')}
  ${_P('The following specifies how each type of non-compliance affects your monthly earnings. These are not arbitrary deductions — they reflect that the associated work was not completed to the required standard and the corresponding pay is therefore not released.')}
  <div style="display:flex;flex-direction:column;gap:4px;margin-bottom:10px">
   ${_LETTER_VIOLATIONS.map(v=>`<div style="border:1px solid #f0d8d5;border-left:3px solid #c0392b;border-radius:6px;overflow:hidden;background:#fff;display:grid;grid-template-columns:40% 60%">
     <div style="padding:6px 11px;border-right:1px solid #f0d8d5;background:#fffafa"><div style="font-size:9px;font-weight:800;color:#1a2a3a;line-height:1.45;margin-bottom:2px">${esc(v[0])}</div><div style="font-size:7.5px;color:#8899aa">Affects: <span style="font-weight:700;color:#c0392b">${esc(v[1])}</span></div></div>
     <div style="padding:6px 11px;display:flex;align-items:center"><p style="font-size:8.5px;color:#c0392b;line-height:1.55;margin:0">${esc(v[2])}</p></div>
    </div>`).join('')}
  </div>
  <div style="border-left:3px solid #c0392b;border-radius:0 6px 6px 0;padding:8px 13px;background:#fff8f7;margin-bottom:8px">
   <div style="font-weight:800;font-size:9.5px;color:#c0392b;margin-bottom:4px">Escalation & Contract Review</div>
   <p style="font-size:9px;color:#3a2a2a;line-height:1.7;margin:0">Accumulation of three (3) or more written notices within any rolling 60-day period, or earning below 40% of monthly potential for two consecutive months, will trigger a formal performance review with the Academic Head. MVS Foundation reserves the right to conclude this engagement with 30 days written notice in the event of persistent non-compliance.</p>
  </div>
  ${_SEC('6. General Terms')}
  ${_LETTER_TERMS.map(r=>`<div style="margin-bottom:5px;font-size:9.5px;line-height:1.6"><strong style="color:#0F2A54">${r[0]}: </strong>${esc(r[1])}</div>`).join('')}
  <div style="margin-top:12px;border-top:2px solid #e4ebf5;padding-top:10px;display:grid;grid-template-columns:1fr 1fr;gap:30px">
   <div><div style="font-weight:800;font-size:10px;color:#0F2A54;margin-bottom:6px">For Manish Verma Study Foundation</div>${fndSig}<div style="border-top:1.5px solid #0F2A54;padding-top:5px"><div style="font-weight:700;font-size:10px">Manish Verma</div><div style="font-size:8.5px;color:#5A6B85">Founder & Director, Manish Verma Study Foundation</div><div style="font-size:8.5px;color:#5A6B85;margin-top:2px">Date: ${esc(lt.date||'___________________')}</div></div></div>
   <div><div style="font-weight:800;font-size:10px;color:#0F2A54;margin-bottom:6px">Accepted by Teacher</div>${tchrSig}<div style="border-top:1.5px solid #0F2A54;padding-top:5px"><div style="font-weight:700;font-size:10px">${esc(t.name)}</div><div style="font-size:8.5px;color:#5A6B85">${esc(t.designation)}, ${esc(t.department)}</div><div style="font-size:8.5px;color:#5A6B85;margin-top:2px">${tchrDate}</div></div></div>
  </div>
  ${_DFOOT('Manish Verma Study Foundation | Plot No. 51-B, Maharani Enclave, West Delhi-110059','GST: 07AARCM9457H1ZQ · CIN: U85500DL2024NPL428819 · PAN: AARCM9457H','Ref: '+esc(refNo))}
  </div>`;
}

// ---------- Contract Letter (task/project based teachers — DU-SOL / IGNOU / freelance) ----------
function _contractLetterHTML(d){
  const t=d.teacher, pay=d.pay;
  const refNo=d.letter.ref, lt=d.letter||{};
  const _sigCss="font-family:'Great Vibes',cursive;font-size:26px;color:#1a2a4a;line-height:1.05";
  const fndSig=`<div style="${_sigCss}">Manish Verma</div>`;
  const tchrSig=(lt.accepted&&lt.signature_name)?`<div style="${_sigCss}">${esc(lt.signature_name)}</div>`:`<div style="height:28px"></div>`;
  const tchrDate=(lt.accepted&&lt.signed_at)?`Digitally signed on ${esc(lt.signed_at)}`:'Date: ___________________';
  const base=pay.contract_base||0, pr=pay.project_rate||0, wd=pay.working_days||26;
  const dRelax=pay.delay_relax||0, dDed=pay.delay_deduct||0, rRelax=pay.reject_relax||0, rDed=pay.reject_deduct||0;
  const inr=v=>'\u20B9'+(v||0).toLocaleString('en-IN');
  const details=[['Name',t.name],['Designation',t.designation||'Contract Teacher'],['Department',t.department||'Academic'],
    ['Employee Code',t.employee_code||'—'],['Date of Engagement','as mutually agreed'],['Reporting To','Academic Head, MVS Foundation'],
    ['Mode of Work','Online — MVS Foundation Portal'],['Engagement Type','Fixed-Salary Contract (task & project based, renewable annually)']];
  const earnRows=[['Fixed Monthly Salary','Paid in full every month when all assigned tasks & projects are delivered on time and no leave is taken.',inr(base)]];
  if(pr) earnRows.push(['Per-Project Bonus','An additional amount for every completed project, over and above the salary.',inr(pr)+' / project']);
  const dedRows=[
   ['Delayed Submissions', dRelax>0?`First ${dRelax} delay${dRelax>1?'s':''} each month are exempt. Thereafter, ${inr(dDed)} is deducted per delayed task.`:`${inr(dDed)} is deducted for every delayed task.`],
   ['Rejected Submissions', rRelax>0?`First ${rRelax} rejection${rRelax>1?'s':''} each month are exempt. Thereafter, ${inr(rDed)} is deducted per rejected task.`:`${inr(rDed)} is deducted for every rejected task.`],
   ['Leave / Absence', `Each approved leave day is deducted at ${inr(Math.round(base/(wd||26)))} per day (salary \u00F7 ${wd} working days), as reviewed by the admin at month-end.`]
  ];
  const terms=[
   ['Salary Payment','Your monthly salary is processed after the admin\u2019s month-end review of your work (including any leave) and is credited to your registered bank account within the <strong>first week of the following month</strong>.'],
   ['Punctuality & Deadlines','All assigned tasks and projects must be submitted on or before their deadlines. Delays beyond the free allowance attract deductions as set out in Section 3.'],
   ['Leave & Attendance','Leave must be informed in advance and approved by the Academic Head. Approved leave is deducted per day (salary \u00F7 working days). Unapproved or excessive absence may trigger a review of this engagement.'],
   ['Quality Standards','All submissions must meet MVS Foundation\u2019s content and quality guidelines. Rejected work beyond the free allowance attracts deductions and must be reworked promptly.'],
   ['Intellectual Property','All study material, tests, videos and content produced during this engagement are the exclusive property of MVS Foundation and may not be redistributed or commercially used elsewhere.'],
   ['Portal Exclusivity','All official academic activity \u2014 tasks, submissions and doubts \u2014 must be conducted through the MVS Foundation portal. Circumventing the portal is a breach of this agreement.'],
   ['Confidentiality','Student data, internal materials and business information must be kept strictly confidential during and after this engagement.'],
   ['Code of Conduct','Professional behaviour with students, parents and colleagues is required at all times. Any form of harassment will result in immediate termination.'],
   ['Non-Compete (6 months)','For six months after this engagement ends, you agree not to establish or join a competing NIOS online coaching service targeting the same student demographic.'],
   ['Amendments','MVS Foundation may revise the salary, rates, targets or standards with 15 days\u2019 written notice. Continued engagement constitutes acceptance of the revised terms, and your Contract Letter on the portal will be updated accordingly.'],
   ['Notice & Termination','Either party may conclude this engagement with 30 days\u2019 written notice. All dues are settled for work delivered up to the last working day.']
  ];
  const extra=(pay.contract_notes||'').trim();
  if(extra) terms.push(['Additional Terms', esc(extra).replace(/\n/g,'<br>')]);
  return `<div style="${_DOC_FONT}">
  ${_LH(refNo,d.letter.date,true)}
  <div style="text-align:center;margin-bottom:16px"><div style="display:inline-block;border-top:2px solid #0F2A54;border-bottom:2px solid #0F2A54;padding:5px 28px"><span style="font-weight:800;font-size:14px;letter-spacing:3px;color:#0F2A54;text-transform:uppercase">Contract Letter</span></div></div>
  ${_P('Dear <strong>'+esc(t.name)+',</strong>')}
  ${_P('We are pleased to confirm your engagement with <strong>Manish Verma Study Foundation (MVS)</strong> on a <strong>fixed-salary contract</strong>. This letter sets out your salary, how deductions apply, and the professional terms of your engagement. Please read it carefully \u2014 by signing below you accept all terms herein.')}
  ${_SEC('1. Engagement Details')}
  <table style="width:100%;border-collapse:collapse;font-size:9.5px;margin-bottom:10px"><tbody>
   ${details.map(r=>`<tr style="border-bottom:1px solid #e4ebf5"><td style="padding:5px 9px;font-weight:700;color:#0F2A54;width:36%;background:#f7f9fc">${r[0]}</td><td style="padding:5px 9px;color:#1a2a3a">${esc(r[1])}</td></tr>`).join('')}
  </tbody></table>
  ${_SEC('2. Your Salary')}
  ${_P('You are engaged on a <strong>fixed monthly salary</strong>. When your assigned tasks and projects are delivered on time and no leave is taken, you receive the full salary below. Deductions apply only as described in Section 3.')}
  <table style="width:100%;border-collapse:collapse;font-size:9.5px;margin-bottom:10px"><thead><tr style="background:#0F2A54;color:#fff"><th style="padding:6px 9px;text-align:left">Component</th><th style="padding:6px 9px;text-align:left">Basis</th><th style="padding:6px 9px;text-align:right;white-space:nowrap">Amount</th></tr></thead><tbody>
   ${earnRows.map(r=>`<tr style="border-bottom:1px solid #e4ebf5"><td style="padding:5px 9px;font-weight:700;color:#0F2A54">${r[0]}</td><td style="padding:5px 9px;color:#1a2a3a">${esc(r[1])}</td><td style="padding:5px 9px;text-align:right;font-weight:800;color:#0F2A54;white-space:nowrap">${r[2]}</td></tr>`).join('')}
  </tbody></table>
  ${_SEC('3. Deductions','#c0392b')}
  ${_P('A reasonable relaxation is provided each month before any deduction applies. Deductions reflect work not delivered to the agreed standard, or leave taken.')}
  <table style="width:100%;border-collapse:collapse;font-size:9.5px;margin-bottom:10px"><tbody>
   ${dedRows.map(r=>`<tr style="border-bottom:1px solid #e4ebf5"><td style="padding:5px 9px;font-weight:700;color:#c0392b;width:30%;background:#fff7f6">${r[0]}</td><td style="padding:5px 9px;color:#1a2a3a">${esc(r[1])}</td></tr>`).join('')}
  </tbody></table>
  ${_P('<em>Your portal\u2019s \"Payout\" dashboard shows a real-time view of tasks completed, on-time count, delays, rejections, leave and your net salary through the month. The final payout is released after the admin\u2019s month-end review.</em>','color:#5A6B85;font-size:9px')}
  ${_SEC('4. Terms & Conditions')}
  ${terms.map((r,i)=>`<div style="margin-bottom:6px;font-size:9.5px;line-height:1.65"><strong style="color:#0F2A54">${i+1}. ${r[0]}: </strong>${r[1]}</div>`).join('')}
  ${_SEC('5. Acceptance')}
  ${_P('By signing below, you confirm that you have read, understood and accepted the terms of this contract. This engagement is renewable and may be revised by mutual agreement; any revision will be reflected in an updated Contract Letter on your portal.')}
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:26px">
   <div><div style="font-weight:800;font-size:10px;color:#0F2A54;margin-bottom:6px">For Manish Verma Study Foundation</div>${fndSig}<div style="border-top:1.5px solid #0F2A54;padding-top:5px"><div style="font-weight:700;font-size:10px">Manish Verma</div><div style="font-size:8.5px;color:#5A6B85">Founder & Director, Manish Verma Study Foundation</div><div style="font-size:8.5px;color:#5A6B85;margin-top:2px">Date: ${esc(lt.date||'___________________')}</div></div></div>
   <div><div style="font-weight:800;font-size:10px;color:#0F2A54;margin-bottom:6px">Accepted by Teacher</div>${tchrSig}<div style="border-top:1.5px solid #0F2A54;padding-top:5px"><div style="font-weight:700;font-size:10px">${esc(t.name)}</div><div style="font-size:8.5px;color:#5A6B85">${esc(t.designation||'Contract Teacher')}, ${esc(t.department||'Academic')}</div><div style="font-size:8.5px;color:#5A6B85;margin-top:2px">${tchrDate}</div></div></div>
  </div>
  ${_DFOOT('Manish Verma Study Foundation | Plot No. 51-B, Maharani Enclave, West Delhi-110059','GST: 07AARCM9457H1ZQ · CIN: U85500DL2024NPL428819 · PAN: AARCM9457H','Ref: '+esc(refNo))}
  </div>`;
}

// ---------- Monthly Earnings Slip (ported from the Figma doc) ----------
function _slipHTML(d){
  const t=d.teacher, a=d.activity, e=d.earnings, tg=d.targets, pay=d.pay;
  const perf=e.perf_score, pc=_pfCol(perf), pbg=perf>=85?'#e8f5e9':perf>=65?'#fffbeb':'#fff8f7';
  const refNo='MVS/SAL/'+d.month_label.replace(' ','-').toUpperCase()+'/'+t.employee_code;
  const today=new Date().toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'});
  const kv=(k,v)=>`<div style="display:flex;justify-content:space-between;font-size:9px;margin-bottom:3px"><span style="color:#5A6B85">${k}</span><span style="font-weight:700;color:#1a2a3a">${esc(v||'—')}</span></div>`;
  const badges=[
   ['Classes',a.classes_conducted+'/'+a.classes_scheduled,a.classes_conducted===a.classes_scheduled],
   ['Notes',a.notes_uploaded+'/'+a.classes_conducted,a.notes_uploaded>=a.classes_conducted],
   ['DPP',a.dpp_uploaded+'/'+a.classes_conducted,a.dpp_uploaded>=a.classes_conducted],
   ['Tests',a.tests_created+'/'+tg.tests_target,a.tests_created>=tg.tests_target],
   ['Doubts',a.doubts_resolved+'/'+a.doubts_assigned,a.doubts_resolved===a.doubts_assigned],
   ['Tasks',a.tasks_on_time+'/'+a.tasks_assigned,a.tasks_on_time===a.tasks_assigned]
  ];
  const erow=(label,sub,amount,hl)=>`<tr style="border-bottom:1px solid #e4ebf5;background:${hl?'#f7f9fc':'#fff'}"><td style="padding:5px 9px"><div style="font-weight:${hl?700:500};font-size:9.5px;color:#1a2a3a">${label}</div>${sub?`<div style="font-size:8px;color:#8899aa;margin-top:1px">${sub}</div>`:''}</td><td style="padding:5px 9px;text-align:right;font-weight:${hl?800:600};font-size:${hl?'11px':'9.5px'};color:${hl?'#0F2A54':'#1a2a3a'}">${_inr(amount)}</td></tr>`;
  return `<div style="${_DOC_FONT}">
  ${_LH(refNo,today,false)}
  <div style="text-align:center;margin-bottom:14px"><div style="display:inline-block;border-top:2px solid #0F2A54;border-bottom:2px solid #0F2A54;padding:5px 28px"><span style="font-weight:800;font-size:13px;letter-spacing:2.5px;color:#0F2A54;text-transform:uppercase">Monthly Earnings Statement — ${esc(d.month_label)}</span></div></div>
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:14px">
   <div style="border:1px solid #e4ebf5;border-radius:7px;padding:10px 12px;background:#f7f9fc">
    <div style="font-weight:800;font-size:10px;color:#0F2A54;margin-bottom:7px;text-transform:uppercase;letter-spacing:.5px">Employee Details</div>
    ${kv('Name',t.name)}${kv('Employee ID',t.employee_code)}${kv('Designation',t.designation)}${kv('Department',t.department)}
   </div>
   <div style="border:1px solid #e4ebf5;border-radius:7px;padding:10px 12px;background:#f7f9fc">
    <div style="font-weight:800;font-size:10px;color:#0F2A54;margin-bottom:7px;text-transform:uppercase;letter-spacing:.5px">Payment Details</div>
    ${kv('Bank',t.bank)}${kv('Account No.',t.account_no)}${kv('IFSC',t.ifsc)}${kv('Pay Month',d.month_label)}
   </div>
  </div>
  <div style="display:grid;grid-template-columns:repeat(6,1fr);gap:6px;margin-bottom:14px">
   ${badges.map(b=>`<div style="border:1px solid ${b[2]?'#c3e6cb':'#f5c6cb'};border-radius:7px;padding:7px 5px;text-align:center;background:${b[2]?'#f0fff4':'#fff5f5'}"><div style="font-size:12px;font-weight:900;color:${b[2]?'#1b7a3e':'#c0392b'}">${b[1]}</div><div style="font-size:7.5px;color:${b[2]?'#1b7a3e':'#c0392b'};font-weight:600;margin-top:1px">${b[0]}</div></div>`).join('')}
  </div>
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px">
   <div>
    <div style="background:#0F2A54;color:#fff;padding:5px 9px;border-radius:5px 5px 0 0;font-weight:800;font-size:9.5px;letter-spacing:.5px">EARNINGS BREAKDOWN</div>
    <table style="width:100%;border-collapse:collapse;font-size:9.5px;border:1px solid #e4ebf5;border-top:none"><tbody>
     ${(e.components||[]).map(c=>c.na?erow(c.label,'not applicable this month',0):erow(c.label,(c.pct!=null?c.pct+'% achieved':'')+(c.weight?' · '+c.weight+'% of pay':''),c.earned)).join('')}
     ${erow('Base Earned (performance)',e.perf_score+'% performance score',e.base_earned!=null?e.base_earned:e.gross_earned,true)}
     ${(e.incentive||0)>0?erow('Dynamic Incentives (approved)','auto-calculated, admin-approved',e.incentive):''}
     ${(e.incentive||0)>0?erow('Gross Earnings (with incentives)','',(e.gross_with_incentive||((e.base_earned!=null?e.base_earned:e.gross_earned)+e.incentive)),true):''}
    </tbody></table>
   </div>
   <div style="display:flex;flex-direction:column;gap:10px">
    <div>
     <div style="background:#c0392b;color:#fff;padding:5px 9px;border-radius:5px 5px 0 0;font-weight:800;font-size:9.5px;letter-spacing:.5px">DEDUCTIONS</div>
     <table style="width:100%;border-collapse:collapse;font-size:9.5px;border:1px solid #e4ebf5;border-top:none"><tbody>
      <tr style="border-bottom:1px solid #e4ebf5"><td style="padding:5px 9px;color:#1a2a3a">TDS / Income Tax</td><td style="padding:5px 9px;text-align:right;color:#c0392b;font-weight:700">${_inr(e.tds)}</td></tr>
      <tr style="border-bottom:1px solid #e4ebf5"><td style="padding:5px 9px;color:#1a2a3a">Other Deductions</td><td style="padding:5px 9px;text-align:right;color:#c0392b;font-weight:700">${_inr(e.other_deduct)}</td></tr>
      ${(e.leave_deduction||0)>0?`<tr style="border-bottom:1px solid #e4ebf5"><td style="padding:5px 9px;color:#1a2a3a">Unpaid Leave (${e.leave_unpaid_days} day${e.leave_unpaid_days===1?'':'s'} × ${_inr(e.leave_per_day||0)}/day)</td><td style="padding:5px 9px;text-align:right;color:#c0392b;font-weight:700">${_inr(e.leave_deduction)}</td></tr>`:''}
      ${(e.leave_paid_days||0)>0?`<tr style="border-bottom:1px solid #e4ebf5"><td style="padding:5px 9px;color:#5A6B85;font-style:italic">Paid Leave (${e.leave_paid_days} day${e.leave_paid_days===1?'':'s'}) — no deduction</td><td style="padding:5px 9px;text-align:right;color:#5A6B85">${_inr(0)}</td></tr>`:''}
      ${(e.reviewed_deduction||0)>0?`<tr style="border-bottom:1px solid #e4ebf5"><td style="padding:5px 9px;color:#1a2a3a">Reviewed Deductions (admin-approved)</td><td style="padding:5px 9px;text-align:right;color:#c0392b;font-weight:700">${_inr(e.reviewed_deduction)}</td></tr>`:''}
      <tr style="background:#fff8f7"><td style="padding:5px 9px;font-weight:800;color:#c0392b">Total Deductions</td><td style="padding:5px 9px;text-align:right;font-weight:800;color:#c0392b">${_inr(e.tds+e.other_deduct+(e.leave_deduction||0)+(e.reviewed_deduction||0))}</td></tr>
     </tbody></table>
    </div>
    <div style="background:linear-gradient(135deg,#0F2A54,#1a3d70);border-radius:8px;padding:12px 14px;color:#fff">
     <div style="font-size:8.5px;opacity:.65;letter-spacing:.5px;text-transform:uppercase;margin-bottom:2px">Net Payable — ${esc(d.month_label)}</div>
     <div style="font-size:24px;font-weight:900">${_inr(e.net_payable)}</div>
     ${(()=>{ const sl=(window._tSalLast&&window._tSalLast.month===d.month)?window._tSalLast:null;
        if(sl&&sl.status&&sl.status!=='pending'){ const lbl={finalized:'Finalized',in_progress:'Payment in progress',credited:'Credited',receipt_confirmed:'Receipt confirmed'}[sl.status]||sl.status;
          return `<div style="font-size:8px;opacity:.85;margin-top:3px">Payment status: ${esc(lbl)}${sl.pay_ref?(' \u00B7 ref: '+esc(sl.pay_ref)):''}</div>`; }
        return '<div style="font-size:8px;opacity:.6;margin-top:2px">Paid by the 5th of the following month</div>'; })()}
    </div>
    <div style="border:1px solid #e4ebf5;border-radius:7px;padding:9px 11px;background:${pbg}">
     <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px"><span style="font-size:9px;font-weight:700;color:#5A6B85">Performance Score</span><span style="font-size:13px;font-weight:900;color:${pc}">${perf}%</span></div>
     <div style="height:7px;border-radius:5px;background:#e4ebf5;overflow:hidden"><div style="height:100%;width:${Math.min(perf,100)}%;background:${pc};border-radius:5px"></div></div>
    </div>
    <div style="border:1px solid #e4ebf5;border-radius:7px;padding:8px 10px;background:#f7f9fc">
     <div style="display:flex;justify-content:space-between;font-size:9px;margin-bottom:3px"><span style="color:#5A6B85">Maximum this month was</span><span style="font-weight:800;color:#0F2A54">${_inr(e.max_potential)}</span></div>
     <div style="display:flex;justify-content:space-between;font-size:9px"><span style="color:#5A6B85">Unclaimed earnings</span><span style="font-weight:800;color:#c0392b">${_inr(e.max_potential-e.net_payable)}</span></div>
    </div>
   </div>
  </div>
  <div style="border:1px solid #e4ebf5;border-radius:6px;padding:8px 12px;background:#f7f9fc;margin-bottom:14px;font-size:8.5px;color:#5A6B85;line-height:1.6"><strong style="color:#0F2A54">Note:</strong> This earnings statement is generated from portal activity data for ${esc(d.month_label)}. All figures are auto-calculated based on your completed deliverables recorded on the MVS Foundation portal. If you believe any figure is incorrect, please raise a dispute through the portal within 5 working days of receipt. Disputes raised after this period will not be entertained.</div>
  <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:20px;border-top:2px solid #e4ebf5;padding-top:14px">
   ${(()=>{ const lt2=d.letter||{}; const sg="font-family:'Great Vibes',cursive;font-size:21px;color:#1a2a4a;line-height:1.05;height:25px";
     const rows=[['Prepared by','Accounts Team','Manish Verma Study Foundation',''],
      ['Authorised by','Manish Verma','Director, Manish Verma Study Foundation','Manish Verma'],
      ['Received by',t.name,t.designation,(lt2.accepted&&lt2.signature_name)?lt2.signature_name:'']];
     return rows.map(r=>`<div style="text-align:center"><div style="${sg}">${esc(r[3])}</div><div style="border-top:1px solid #0F2A54;padding-top:5px;margin-top:2px"><div style="font-weight:700;font-size:9px;color:#1a2a3a">${esc(r[1])}</div><div style="font-size:7.5px;color:#5A6B85">${esc(r[2])}</div><div style="font-size:7.5px;color:#8899aa">${r[0]}</div></div></div>`).join(''); })()}
  </div>
  ${_DFOOT('Manish Verma Study Foundation | Plot No. 51-B, Maharani Enclave, West Delhi-110059','This is a system-generated document — signed and authorised electronically','Earnings Stmt | '+esc(d.month_label))}
  </div>`;
}

// ---------- shared earnings components (teacher page + admin detail) ----------
function _ecard(title,desc,earned,max,subs){
  const pct=max>0?Math.min(earned/max,1):(earned>0?1:0);
  const col=pct>=1?'#1b7a3e':pct>=0.6?'var(--primary)':'#c0392b';
  return `<div class="card" style="margin-bottom:0"><div class="card-body" style="padding:16px">
   <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;margin-bottom:6px">
    <div><div style="font-weight:800;font-size:.92rem">${title}</div><div style="font-size:.7rem;color:var(--text-muted);margin-top:2px;line-height:1.5">${desc}</div></div>
    <div style="text-align:right;flex-shrink:0"><div style="font-weight:900;font-size:1.12rem;color:${col}">${_inr(earned)}</div><div style="font-size:.66rem;color:var(--text-muted)">of ${_inr(max)}</div></div>
   </div>
   <div style="height:7px;border-radius:6px;background:var(--border);overflow:hidden;margin:8px 0 6px"><div style="height:100%;width:${Math.round(pct*100)}%;background:${pct>=1?'linear-gradient(90deg,#1b7a3e,#34d399)':'linear-gradient(90deg,var(--primary),#e8c66a)'};border-radius:6px"></div></div>
   ${subs||''}
  </div></div>`;
}
const _esub=(l,r)=>`<div style="display:flex;justify-content:space-between;font-size:.71rem;color:var(--text-muted);padding:2px 0"><span>${l}</span><b style="color:var(--text)">${r}</b></div>`;

function _earnComponentsHTML(d){
  const e=d.earnings;
  const comps=e.components||[];
  if(!comps.length) return '';
  const cards=comps.map(c=>{
    if(c.na){
      return `<div class="card" style="margin-bottom:0;opacity:.62"><div class="card-body" style="padding:16px">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px">
         <div><div style="font-weight:800;font-size:.92rem">${esc(c.label)}</div><div style="font-size:.7rem;color:var(--text-muted);margin-top:2px">${esc(c.detail||'Not applicable this month')}</div></div>
         <div style="text-align:right;flex-shrink:0"><div style="font-size:.82rem;color:var(--text-muted);font-weight:700">Not applicable</div><div style="font-size:.66rem;color:var(--text-muted)">weight ${c.weight}%</div></div>
        </div></div></div>`;
    }
    return _ecard(esc(c.label), esc(c.detail||'')+' \u00B7 '+c.weight+'% of pay', c.earned, c.pool,
      _esub('Achievement', (c.pct!=null?c.pct+'%':'\u2014')));
  }).join('');
  return `<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(300px,100%),1fr));gap:14px">${cards}</div>`;
}

function _earnHeroHTML(d,actions){
  const e=d.earnings, pc=_pfCol(e.perf_score);
  return `<div class="po-hero" style="display:flex;justify-content:space-between;align-items:center;gap:18px;flex-wrap:wrap">
   <div>
    <div style="font-size:.72rem;opacity:.62;letter-spacing:.08em;text-transform:uppercase;margin-bottom:4px">Net Payable \u00B7 ${esc(d.month_label)}</div>
    <div style="font-size:2.2rem;font-weight:900;line-height:1.05">${_inr(e.net_payable)}</div>
    <div style="font-size:.74rem;opacity:.62;margin-top:6px">of maximum ${_inr(e.max_potential)} \u00B7 unclaimed ${_inr(Math.max(0,e.max_potential-e.net_payable))}</div>
    <div style="font-size:.72rem;opacity:.62;margin-top:3px">Base (performance-linked): ${_inr(e.base_earned!=null?e.base_earned:e.gross_earned)}${e.workload_level?(' \u00B7 workload '+esc(e.workload_level)):''}${e.limited_workload?' \u00B7 below team minimum':''}</div>
    ${(e.leave_deduction||0)>0?`<div style="font-size:.72rem;margin-top:5px;color:#fca5a5">Unpaid leave deduction: −${_inr(e.leave_deduction)} (${e.leave_unpaid_days} day${e.leave_unpaid_days===1?'':'s'} × ${_inr(e.leave_per_day||0)}/day)${(e.leave_paid_days||0)>0?` \u00B7 ${e.leave_paid_days} paid-leave day${e.leave_paid_days===1?'':'s'} (no deduction)`:''}</div>`:(e.leave_paid_days||0)>0?`<div style="font-size:.72rem;margin-top:5px;opacity:.7">${e.leave_paid_days} paid-leave day${e.leave_paid_days===1?'':'s'} — no salary deduction</div>`:''}
    ${(e.reviewed_deduction||0)>0?`<div style="font-size:.72rem;margin-top:5px;color:#fca5a5">Reviewed deductions (admin-approved): −${_inr(e.reviewed_deduction)}</div>`:''}
    ${(e.incentive||0)>0?`<div style="font-size:.72rem;margin-top:5px;color:#86efac">Dynamic incentives (approved): +${_inr(e.incentive)}</div>`:''}
   </div>
   <div style="text-align:center;min-width:120px">
    <div style="font-size:2rem;font-weight:900;color:${e.perf_score>=85?'#34d399':e.perf_score>=65?'#fbbf24':'#f87171'}">${e.perf_score}%</div>
    <div style="font-size:.68rem;opacity:.62;text-transform:uppercase;letter-spacing:.08em;margin-bottom:7px">Performance Score</div>
    <div style="height:7px;width:150px;margin:0 auto;border-radius:6px;background:rgba(255,255,255,.14);overflow:hidden"><div style="height:100%;width:${Math.min(e.perf_score,100)}%;background:${e.perf_score>=85?'#34d399':e.perf_score>=65?'#fbbf24':'#f87171'};border-radius:6px"></div></div>
   </div>
   ${actions?`<div style="display:flex;flex-direction:column;gap:8px">${actions}</div>`:''}
  </div>`;
}

function _activityStripHTML(d){
  const a=d.activity;
  const cov=(a.dpp_covered!=null)?a.dpp_covered:a.dpp_uploaded;
  const tiles=[
    {i:'calendar', l:'Classes',      v:a.classes_conducted+'/'+a.classes_scheduled, s:'conducted / scheduled', c:'#1b7a3e', bg:'linear-gradient(135deg,#eef7f0,#e2f2e8)', id:'act-classes-v'},
    {i:'clock',    l:'Late Starts',  v:a.late_classes, s:a.late_classes?'beyond 15-min grace':'all on time', c:a.late_classes?'#c0392b':'#1b7a3e', bg:a.late_classes?'linear-gradient(135deg,#fdf1f0,#fbe7e5)':'linear-gradient(135deg,#eef7f0,#e2f2e8)'},
    {i:'book',     l:'Notes',        v:a.notes_uploaded, s:'uploaded this month', c:'#9a6b00', bg:'linear-gradient(135deg,#fbf6e9,#f6edda)'},
    {i:'clipboard',l:'DPP',          v:a.dpp_uploaded, s:cov+' chapters covered', c:'#9a6b00', bg:'linear-gradient(135deg,#fbf6e9,#f6edda)'},
    {i:'edit',     l:'Tests',        v:a.tests_created, s:'created this month', c:'#9a6b00', bg:'linear-gradient(135deg,#fbf6e9,#f6edda)'},
    {i:'play',     l:'Videos',       v:a.videos_made, s:'one shot / revision', c:'#1a56a8', bg:'linear-gradient(135deg,#eef4fc,#e2ecfa)'},
    {i:'megaphone',l:'Live',         v:a.live_sessions, s:'YouTube sessions', c:'#1a56a8', bg:'linear-gradient(135deg,#eef4fc,#e2ecfa)'},
    {i:'sun',      l:'Shorts',       v:a.shorts_made, s:'made this month', c:'#1a56a8', bg:'linear-gradient(135deg,#eef4fc,#e2ecfa)'},
    {i:'help',     l:'Doubts',       v:a.doubts_resolved+'/'+a.doubts_assigned, s:'resolved / assigned', c:'#6d28d9', bg:'linear-gradient(135deg,#f4f0fc,#ece5fa)'},
    {i:'check',    l:'Tasks on time',v:a.tasks_on_time+'/'+a.tasks_assigned, s:'on-time / assigned', c:'#6d28d9', bg:'linear-gradient(135deg,#f4f0fc,#ece5fa)'}
  ];
  return `<div class="card" style="margin-top:18px"><div class="card-header"><h3>${ic('chart')} This Month's Activity (auto-tracked)</h3></div><div class="card-body">
   <div class="act-grid">${tiles.map(t=>`<div class="act-tile"><div class="act-ic" style="color:${t.c};background:${t.bg}">${ic(t.i)}</div><div class="act-tx"><div class="act-v"${t.id?(' id="'+t.id+'"'):''} style="color:${t.c}">${t.v}</div><div class="act-l">${t.l}</div><div class="act-s">${t.s}</div></div></div>`).join('')}</div>
  </div></div>`;
}

