async function aEarnFetch(){
  const body=document.getElementById('ae-body'), stats=document.getElementById('ae-stats');
  if(!body) return;
  try{
    const d=await api('/api/admin/earnings?month='+encodeURIComponent(_aEarnMonth));
    _aEarnData=d;
    const _st=(icn,val,lbl)=>`<div class="ae-stat"><div class="ae-stat-ic">${ic(icn)}</div><div><div class="ae-stat-v">${val}</div><div class="ae-stat-l">${lbl}</div></div></div>`;
    // v89: decided monthly salary ka total (max potential sum) — monthly kitna ja sakta hai
    const totSal=d.teachers.reduce((a,x)=>a+(x.target_only?0:((x.earnings&&x.earnings.max_potential)||0)),0);
    if(stats) stats.innerHTML=_st('users',d.teachers.length,'Teachers')+_st('trophy',_inr(totSal),'Monthly Salary (Total)')+_st('wallet',_inr(d.total_net),'Total Net Payable')+_st('chart',d.avg_perf+'%','Average Performance')+_st('calendar',esc(fmtMonthLabel(d.month)),'Pay Month');
    body.innerHTML=(d.total_net===0?`<div class="alert alert-info" style="margin-bottom:14px">The month has just begun — earnings build here automatically as teacher activity is recorded on the portal. There is no activity yet, so all figures show ₹0 (never demo numbers).</div>`:'')
     +((d.target_only_count||0)>0?`<div class="alert alert-info" style="margin-bottom:14px">${d.target_only_count} target-only teacher${d.target_only_count>1?'s':''}: payout runs on the assigned target via the other app — shown here only as an <b>estimated % of salary</b>, never as amounts.</div>`:'')
     +`<div class="ae-grid">${d.teachers.map(x=>{
       const e=x.earnings, pc=_pfCol(e.perf_score);
       const incent=e.incentive||0;
       // v91: appointment letter sign status — card pe turant update dikhta hai
       const ltr=x.letter||{};
       const lchip=ltr.accepted
        ?`<span title="Appointment letter digitally signed${ltr.signed_at?' on '+esc(ltr.signed_at):''}${ltr.signature_name?' as '+esc(ltr.signature_name):''}" style="display:inline-flex;align-items:center;gap:4px;padding:3px 9px;border-radius:20px;font-weight:800;font-size:.6rem;letter-spacing:.04em;color:#047857;background:#04785714;border:1px solid #04785733">${ic('check')} LETTER SIGNED</span>`
        :`<span title="Appointment letter not signed yet" style="display:inline-flex;align-items:center;gap:4px;padding:3px 9px;border-radius:20px;font-weight:800;font-size:.6rem;letter-spacing:.04em;color:#b45309;background:#b4530914;border:1px solid #b4530933">${ic('clock')} LETTER PENDING</span>`;
       // v104: target-only teacher — payment amounts kabhi nahi; target + estimated % only
       if(x.target_only){
         const sp=(e.salary_pct!=null?e.salary_pct:e.perf_score);
         const spc=sp>=85?'#15803d':sp>=65?'#b45309':'#b91c1c';
         const dedT=e.est_ded_total||0, dedN=(e.est_deductions||[]).length;
         const tl=(x.policy_target&&x.policy_target.label)||'set by admin';
         return `<div class="card ae-tcard" style="border:1.5px solid rgba(184,148,31,.45)"><div class="card-body" style="padding:16px 18px">
          <div style="display:flex;align-items:center;gap:12px">
           <div class="ae-ava" id="aephot-${x.teacher.id}">${esc(initials(x.teacher.name))}</div>
           <div style="flex:1;min-width:0">
            <div style="font-weight:800;font-size:.98rem">${esc(x.teacher.name)}</div>
            <div style="font-size:.7rem;color:var(--text-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(x.teacher.employee_code)} \u00B7 ${(x.teacher.subjects||[]).slice(0,2).map(esc).join(', ')||'\u2014'}</div>
           </div>
           <div style="display:flex;flex-direction:column;align-items:flex-end;gap:5px">
            <span title="Estimated share of the monthly salary — amounts are never shown for target-only teachers" style="display:inline-block;min-width:52px;text-align:center;padding:4px 10px;border-radius:20px;font-weight:800;font-size:.8rem;color:${spc};background:${spc}18">est. ${sp}%</span>
            <span style="display:inline-flex;align-items:center;gap:4px;padding:3px 9px;border-radius:20px;font-weight:800;font-size:.6rem;letter-spacing:.04em;color:#b91c1c;background:#b91c1c14;border:1px solid #b91c1c33">TARGET ONLY</span>
           </div>
          </div>
          <div style="display:flex;align-items:center;gap:7px;margin:11px 0 3px;padding:7px 11px;border-radius:10px;background:linear-gradient(135deg,rgba(22,163,74,.1),rgba(22,163,74,.04));border:1px solid rgba(22,163,74,.3);font-size:.74rem;font-weight:700;color:#15803d">${ic('check')} Assigned target ${esc(tl)} — fully met this month</div>
          <div class="ae-mini">
           <div><b style="color:${spc}">est. ${sp}%</b><span>Of Salary</span></div>
           <div><b style="color:${dedT>0?'#b91c1c':'#15803d'}">${dedT>0?'\u2212'+dedT+'%':'0%'}</b><span>Est. Deductions${dedN?' ('+dedN+')':''}</span></div>
           <div><b>${esc(tl)}</b><span>Target · Fully Met</span></div>
          </div>
          <div style="display:flex;gap:6px;flex-wrap:wrap">
           <button class="btn btn-ghost btn-sm" onclick="openEarnDetail(${x.teacher.id})">View</button>
           <button class="btn btn-primary btn-sm" onclick="openPayConfig(${x.teacher.id})">${ic('edit')} Pay Structure</button>
          </div>
         </div></div>`;
       }
       return `<div class="card ae-tcard"><div class="card-body" style="padding:16px 18px">
        <div style="display:flex;align-items:center;gap:12px">
         <div class="ae-ava" id="aephot-${x.teacher.id}">${esc(initials(x.teacher.name))}</div>
         <div style="flex:1;min-width:0">
          <div style="font-weight:800;font-size:.98rem">${esc(x.teacher.name)}</div>
          <div style="font-size:.7rem;color:var(--text-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(x.teacher.employee_code)} \u00B7 ${(x.teacher.subjects||[]).slice(0,2).map(esc).join(', ')||'—'}</div>
         </div>
         <div style="display:flex;flex-direction:column;align-items:flex-end;gap:5px">
          <span style="display:inline-block;min-width:52px;text-align:center;padding:4px 10px;border-radius:20px;font-weight:800;font-size:.8rem;color:${pc};background:${pc}18">${e.perf_score}%</span>
          ${lchip}
         </div>
        </div>
        <div class="ae-mini">
         <div><b>${_inr(e.base_earned!=null?e.base_earned:e.gross_earned)}</b><span>Base</span></div>
         <div><b>${_inr(incent)}</b><span>Incentives</span></div>
         <div><b style="color:var(--primary)">${_inr(e.net_payable)}</b><span>Net Payable</span></div>
        </div>
        <div style="display:flex;gap:6px;flex-wrap:wrap">
         <button class="btn btn-ghost btn-sm" onclick="openEarnDetail(${x.teacher.id})">View</button>
         <button class="btn btn-primary btn-sm" onclick="openPayConfig(${x.teacher.id})">${ic('edit')} Pay Structure</button>
         <button class="btn btn-ghost btn-sm" onclick="adminSlip(${x.teacher.id})">Slip</button>
         <button class="btn btn-ghost btn-sm" onclick="adminLetter(${x.teacher.id})">Letter</button>
        </div>
       </div></div>`;}).join('')}</div>`;
    // v89: payout cards pe teacher photos (auth-header fetch → blob)
    d.teachers.filter(x=>x.teacher&&x.teacher.has_photo).forEach(x=>loadImgInto('aephot-'+x.teacher.id,'/api/admin/teacher/'+x.teacher.id+'/photo'));
  }catch(e){ body.innerHTML=`<div class="card"><div class="card-body"><div class="empty-state"><p>${esc(e.message)}</p></div></div></div>`; }
}
function _aEarnRow(tid){ return (_aEarnData&&_aEarnData.teachers||[]).find(x=>x.teacher.id===tid); }

function openEarnDetail(tid){
  const x=_aEarnRow(tid); if(!x){ toast('Load the list first.',true); return; }
  const e=x.earnings, a=x.activity;
  const _isC=((x.pay&&x.pay.payout_mode)==='contract');
  if(_isC){
    showModal('Contract Payout — '+x.teacher.name+' ('+fmtMonthLabel(x.month)+')',
     _contractReviewHTML(x)+_contractActivityHTML(x),
     `<button class="btn btn-primary" onclick="openPayConfig(${tid})">${ic('edit')} Pay Structure</button>
      <button class="btn btn-ghost" onclick="adminSlip(${tid})">${ic('download')} Earnings Slip</button>
      <button class="btn btn-ghost" onclick="adminLetter(${tid})">${ic('book')} Contract Letter</button>
      <button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
    return;
  }
  if(x.target_only){
    showModal('Estimated Earnings \u00B7 '+x.teacher.name+' ('+fmtMonthLabel(x.month)+')',
     _earnTargetOnlyHTML(x)+_activityStripHTML(x),
     `<button class="btn btn-primary" onclick="openPayConfig(${tid})">${ic('edit')} Pay Structure</button>
      <button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
    return;
  }
  showModal('Earnings — '+x.teacher.name+' ('+fmtMonthLabel(x.month)+')',
   _earnHeroHTML(x)+'<div style="margin-top:4px">'+_earnComponentsHTML(x)+'</div>'+_activityStripHTML(x),
   `<button class="btn btn-primary" onclick="openPayConfig(${tid})">${ic('edit')} Pay Structure</button>
    <button class="btn btn-ghost" onclick="adminSlip(${tid})">${ic('download')} Earnings Slip</button>
    <button class="btn btn-ghost" onclick="adminLetter(${tid})">${ic('book')} Appointment Letter</button>
    <button class="btn btn-ghost" onclick="closeModal()">Close</button>`);
}
function _contractActivityHTML(x){
  const a=x.activity||{}, cs=(x.earnings&&x.earnings.contract_stats)||{};
  const inr=v=>'\u20B9'+(Math.round(v||0)).toLocaleString('en-IN');
  const row=(l,v,neg)=>`<div style="display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--border)"><span style="font-size:.84rem">${l}</span><span style="font-weight:700;color:${neg?'#c0392b':'#0F2A54'}">${neg?'– ':''}${inr(Math.abs(v))}</span></div>`;
  let bd=row('Fixed Monthly Salary',cs.salary||0,false);
  if(cs.project_earn) bd+=row('Project Bonus ('+(cs.projects||0)+')',cs.project_earn,false);
  if(cs.delay_cut) bd+=row('Delay Deduction',cs.delay_cut,true);
  if(cs.reject_cut) bd+=row('Rejection Deduction',cs.reject_cut,true);
  if(cs.leave_cut) bd+=row('Leave Deduction ('+(cs.leave_days||0)+'d)',cs.leave_cut,true);
  const act=(l,v)=>`<div style="display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px dashed var(--border);font-size:.84rem"><span style="color:var(--text-muted)">${l}</span><b>${v}</b></div>`;
  return `<div class="card" style="margin-bottom:12px"><div class="card-header"><h3>Payout Breakdown</h3></div><div class="card-body">${bd}
      <div style="display:flex;justify-content:space-between;padding:11px 0 0;font-weight:800;font-size:1.02rem"><span>Net Payable</span><span style="color:#0F2A54">${inr(cs.net||0)}</span></div></div></div>
    <div class="card"><div class="card-header"><h3>This Month's Work</h3></div><div class="card-body">
      ${act('Videos made',a.videos_made||0)}
      ${act('YouTube Live',a.live_sessions||0)}
      ${act('Shorts made',a.shorts_made||0)}
      ${act('Projects completed',cs.projects||0)}
      ${act('Tasks',(cs.on_time||0)+' on-time · '+(cs.delayed||0)+' delayed · '+(cs.rejected||0)+' rejected')}
    </div></div>`;
}
function _contractReviewHTML(x){
  const cs=(x.earnings&&x.earnings.contract_stats)||{};
  const rev=!!cs.reviewed;
  const inr=v=>'\u20B9'+(v||0).toLocaleString('en-IN');
  return `<div style="background:${rev?'linear-gradient(135deg,#e9f8ee,#dff3e6)':'linear-gradient(135deg,#fff4e5,#ffe9cc)'};border:1px solid ${rev?'#b6e3c6':'#f0cf9a'};border-radius:14px;padding:14px 16px;margin-bottom:14px">
    <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap">
      <div><div style="font-weight:800;font-size:.9rem;color:${rev?'#1f7a44':'#8a5a12'}">${rev?'\u2713 Reviewed & Released':'\u26A0 Pending Your Review'}</div>
      <div style="font-size:.72rem;color:var(--text-muted);margin-top:2px">${rev?'The teacher can now see their final payout.':'The teacher sees "under review" until you release this.'}</div></div>
      <div style="text-align:right"><div style="font-size:.68rem;color:var(--text-muted)">Net Payout</div><div style="font-weight:800;font-size:1.1rem;color:#0F2A54">${inr(cs.net||0)}</div></div>
    </div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:8px;margin:12px 0">
      <div style="background:#fff;border-radius:8px;padding:8px 10px;text-align:center"><div style="font-weight:800;color:#1f7a44">${cs.on_time||0}</div><div style="font-size:.62rem;color:var(--text-muted)">ON-TIME</div></div>
      <div style="background:#fff;border-radius:8px;padding:8px 10px;text-align:center"><div style="font-weight:800;color:#d97706">${cs.delayed||0}</div><div style="font-size:.62rem;color:var(--text-muted)">DELAYED</div></div>
      <div style="background:#fff;border-radius:8px;padding:8px 10px;text-align:center"><div style="font-weight:800;color:#c0392b">${cs.rejected||0}</div><div style="font-size:.62rem;color:var(--text-muted)">REJECTED</div></div>
      <div style="background:#fff;border-radius:8px;padding:8px 10px;text-align:center"><div style="font-weight:800;color:#5b3aa6">${cs.projects||0}</div><div style="font-size:.62rem;color:var(--text-muted)">PROJECTS</div></div>
    </div>
    <div style="display:flex;gap:10px;align-items:flex-end;flex-wrap:wrap">
      <div style="flex:1;min-width:140px"><label style="font-size:.7rem;font-weight:700;color:#8a5a12;display:block;margin-bottom:4px">Leave days this month</label>
        <input type="number" min="0" class="form-control" id="cr-leave" value="${cs.leave_days||0}"></div>
      <div style="font-size:.72rem;color:var(--text-muted);padding-bottom:10px">Per-day: ${inr(cs.per_day||0)} · Leave cut: <b>${inr(cs.leave_cut||0)}</b></div>
      <button class="btn btn-primary" onclick="acContractReview(${x.teacher.id},true)">${ic('check')} ${rev?'Update & Release':'Save & Release'}</button>
      ${rev?`<button class="btn btn-ghost btn-sm" onclick="acContractReview(${x.teacher.id},false)">Un-release</button>`:''}
    </div>
  </div>`;
}
async function acContractReview(tid, release){
  const ld=parseInt((document.getElementById('cr-leave')||{}).value)||0;
  try{
    await api('/api/admin/teacher/'+tid+'/contract-review','POST',{month:_aEarnMonth,leave_days:ld,reviewed:release});
    toast(release?'Payout released to teacher.':'Moved back to review.');
    closeModal(); await aEarnFetch(); openEarnDetail(tid);
  }catch(e){ toast(e.message||'Failed',true); }
}

function openPayConfig(tid){
  const x=_aEarnRow(tid); if(!x){ toast('Load the list first.',true); return; }
  const p=x.pay, g=x.targets, t=x.teacher;
  const num=(id,lbl,v,hint)=>`<div><label style="font-size:.7rem;color:var(--text-muted);font-weight:700;display:block;margin-bottom:4px">${lbl}</label><input type="number" min="0" class="form-control" id="${id}" value="${v}" oninput="_pcSum()">${hint?`<div style="font-size:.64rem;color:var(--text-muted);margin-top:3px">${hint}</div>`:''}</div>`;
  const txt=(id,lbl,v,ph)=>`<div><label style="font-size:.7rem;color:var(--text-muted);font-weight:700;display:block;margin-bottom:4px">${lbl}</label><input class="form-control" id="${id}" value="${esc(v||'')}" placeholder="${ph||''}"></div>`;
  const _tgL=g.labels||{};
  const tgRow=(key,defName,count)=>`<div class="pct-row"><input class="form-control pct-name" id="pc_lbl_${key}" value="${esc(_tgL[key]||defName)}" maxlength="60" placeholder="Target name"><input type="number" min="0" class="form-control pct-num" id="pc_${key}" value="${count}"><span class="pct-tag">CORE</span></div>`;
  window._pcCustom=(g.custom||[]).map(c=>({name:c.name,count:c.count}));
  showModal('Pay Structure — '+x.teacher.name,
   `<div class="alert alert-info">Full control: amounts, monthly targets, designation and bank details. Saving updates this teacher's live earnings and documents immediately.</div>
    <div style="background:#f4f0fc;border:1px solid #d9cdf3;border-radius:12px;padding:12px 16px;margin-bottom:12px">
     <label style="font-size:.7rem;color:#5b3aa6;font-weight:800;display:block;margin-bottom:6px;letter-spacing:.04em">PAYOUT MODE</label>
     <select class="form-control" id="pc_mode" onchange="_pcMode(this.value)" style="font-weight:700">
       <option value="standard"${(p.payout_mode||'standard')!=='contract'?' selected':''}>Standard — performance components (classes, notes, doubts, projects)</option>
       <option value="contract"${(p.payout_mode||'standard')==='contract'?' selected':''}>Contract — task &amp; project based (on-time pays, delay/rejection deducts)</option>
     </select>
     <div style="font-size:.66rem;color:#6b4ca0;margin-top:5px">Contract mode ignores the component split below — the teacher is paid only from the task/project rates &amp; deductions you set. Best for DU-SOL / IGNOU / freelance teachers.</div>
    </div>
    <div id="pc-contract-box" style="display:none;background:linear-gradient(135deg,#fbf6e9,#f6edda);border:1px solid #e6d9ac;border-radius:12px;padding:14px 16px;margin-bottom:12px">
     <div style="font-weight:800;font-size:.8rem;margin-bottom:6px;color:#7a5c00">CONTRACT PAYOUT — FIXED SALARY</div>
     <div style="font-size:.68rem;color:#8a6d1a;margin-bottom:10px">Teacher keeps the full fixed salary when work is on time. Deductions apply only for delays, rejections and leave. Per-project bonus is optional.</div>
     <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(150px,100%),1fr));gap:10px">
       ${num('pc_cbase','Fixed Monthly Salary (₹)',p.contract_base||0,'Full salary if all work is on time')}
       ${num('pc_prate','Per-Project Bonus (₹, optional)',p.project_rate||0,'Leave 0 if salary already covers projects')}
       ${num('pc_wdays','Working Days / Month',p.working_days||26,'Used for per-day leave deduction')}
     </div>
     <div style="font-weight:800;font-size:.74rem;margin:12px 0 8px;color:#7a5c00">DELAY DEDUCTION</div>
     <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">
       ${num('pc_drelax','Delays allowed (free)',p.delay_relax||0,'No deduction up to this many delays')}
       ${num('pc_dded','Deduction per extra delay (₹)',p.delay_deduct||0,'Charged for each delay beyond the free ones')}
     </div>
     <div style="font-weight:800;font-size:.74rem;margin:12px 0 8px;color:#7a5c00">REJECTION DEDUCTION</div>
     <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">
       ${num('pc_rrelax','Rejections allowed (free)',p.reject_relax||0,'No deduction up to this many rejections')}
       ${num('pc_rded','Deduction per extra rejection (₹)',p.reject_deduct||0,'Charged for each rejection beyond the free ones')}
     </div>
     <div style="margin-top:12px"><label style="font-size:.7rem;color:#7a5c00;font-weight:700;display:block;margin-bottom:4px">Extra Contract Terms <span style="font-weight:400;color:#8a6d1a">(optional — the Contract Letter is auto-generated with full salary, deductions &amp; standard terms; add anything extra only if needed)</span></label>
       <textarea class="form-control" id="pc_cnotes" rows="2" maxlength="600" placeholder="Leave blank — a complete premium contract letter is generated automatically.">${esc(p.contract_notes||'')}</textarea></div>
    </div>
    <div id="pc-standard-box">
    <div style="background:linear-gradient(135deg,#faf6e8,#f6efdb);border:1px solid #e6d9ac;border-radius:12px;padding:12px 16px;margin-bottom:12px">
     <label style="font-size:.7rem;color:#7a5c00;font-weight:800;display:block;margin-bottom:5px;letter-spacing:.04em">TOTAL MONTHLY SALARY — AUTO-SPLIT</label>
     <input type="number" min="0" class="form-control" id="pc_total" placeholder="e.g. 63000" style="font-weight:800;font-size:1rem" oninput="_pcSplit(this.value)">
     <div style="font-size:.66rem;color:#8a6d1a;margin-top:5px">As you enter the total, components split automatically — Classes <b>60%</b> · Tasks & Content <b>24%</b> · Notes/DPP/Tests <b>8%</b> · Doubts <b>4%</b> · Quality <b>4%</b> (classes first, then tasks, notes/DPP, doubts, quality). Every field can still be edited individually after the split.</div>
    </div>
    <div style="font-weight:800;font-size:.8rem;margin:4px 0 8px;color:var(--primary)">EARNINGS COMPONENTS (per month)</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(150px,100%),1fr));gap:10px">
     ${num('pc_retainer','Class Retainer (60%)',p.class_retainer)}
     ${num('pc_quality','Class Quality',p.class_quality)}
     ${num('pc_notesdpp','Notes + DPP + Tests',p.notes_dpp)}
     ${num('pc_doubt','Doubt Resolution',p.doubt_resolution)}
     ${num('pc_project','Project & Content',p.project_delivery)}
    </div>
    <div style="display:flex;justify-content:space-between;align-items:center;background:var(--hover);border-radius:10px;padding:9px 14px;margin-top:10px">
     <span style="font-size:.76rem;font-weight:700">Maximum Monthly Potential</span><b id="pc_max" style="font-size:1rem"></b>
    </div>
    <div id="pc_60" style="font-size:.68rem;color:var(--text-muted);margin-top:4px"></div>
    </div>
    <div id="pc-targets-box">
    <div style="font-weight:800;font-size:.8rem;margin:14px 0 8px;color:var(--primary)">MONTHLY TARGETS</div>
    <div style="font-size:.7rem;color:var(--text-muted);margin:-3px 0 10px">Core targets drive the earnings calculation — rename them anytime. Add your own extra targets below; they appear on the appointment letter.</div>
    <div style="display:flex;flex-direction:column;gap:8px">
     ${tgRow('tests','Weekly Tests',g.tests_target)}
     ${tgRow('videos','Videos (One Shot/Revision)',g.videos_target)}
     ${tgRow('live','YouTube Live',g.live_target)}
     ${tgRow('shorts','Shorts',g.shorts_target)}
    </div>
    <div id="pc_tg_custom" style="margin-top:8px"></div>
    </div>
    <div style="font-weight:800;font-size:.8rem;margin:14px 0 8px;color:var(--primary)">PROFILE & BANK (for letter & slip)</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(160px,100%),1fr));gap:10px">
     ${txt('pc_desig','Designation',t.designation==='Subject Teacher'?'':t.designation,'Subject Teacher')}
     ${txt('pc_dept','Department',t.department,'Academic — NIOS Coaching')}
     ${txt('pc_emp','Employee Code',t.employee_code,'MVS-T-000')}
     ${txt('pc_bank','Bank Name',t.bank,'HDFC Bank')}
     ${txt('pc_acct','Account No.',t.account_no)}
     ${txt('pc_ifsc','IFSC',t.ifsc)}
    </div>`,
   `<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="submitPayConfig(${tid})">${ic('check')} Save Pay Structure</button>`);
  _pcSum();
  _pcCustomRender();
  _pcMode((p.payout_mode||'standard'));
}
function _pcMode(mode){
  const ct=document.getElementById('pc-contract-box'), st=document.getElementById('pc-standard-box'), tg=document.getElementById('pc-targets-box');
  const isC=(mode==='contract');
  if(ct) ct.style.display=isC?'block':'none';
  if(st) st.style.display=isC?'none':'block';
  if(tg) tg.style.display=isC?'none':'block';
}
function _pcCustomRender(){
  const box=document.getElementById('pc_tg_custom'); if(!box) return;
  const rows=(window._pcCustom||[]).map((c,i)=>`<div class="pct-row"><input class="form-control pct-name" id="pc_c_name_${i}" value="${esc(c.name)}" maxlength="60" placeholder="Target name" oninput="_pcCustom[${i}].name=this.value"><input type="number" min="0" class="form-control pct-num" value="${c.count}" oninput="_pcCustom[${i}].count=this.value"><button class="btn btn-ghost btn-sm pct-del" title="Remove this target" onclick="_pcCustomDel(${i})">×</button></div>`).join('');
  box.innerHTML=rows+`<button class="btn btn-ghost btn-sm" onclick="_pcCustomAdd()">${ic('plus')} Add Target</button>`;
}
function _pcCustomAdd(){ window._pcCustom.push({name:'',count:4}); _pcCustomRender(); setTimeout(()=>{ const n=document.getElementById('pc_c_name_'+(window._pcCustom.length-1)); if(n) n.focus(); },60); }
function _pcCustomDel(i){ window._pcCustom.splice(i,1); _pcCustomRender(); }
function _pcSum(){
  const v=id=>parseInt((document.getElementById(id)||{}).value)||0;
  const mx=v('pc_retainer')+v('pc_quality')+v('pc_notesdpp')+v('pc_doubt')+v('pc_project');
  const el=document.getElementById('pc_max'); if(el) el.textContent=_inr(mx);
  const tt=document.getElementById('pc_total'); if(tt && document.activeElement!==tt) tt.value=mx||'';
  const r=document.getElementById('pc_60');
  if(r){ const pct=mx>0?Math.round(v('pc_retainer')/mx*100):0;
    r.textContent='Retainer is '+pct+'% of maximum '+(pct===60?'— matches the 60% rule.':pct<60?'— below the 60% rule ('+_inr(Math.round(mx*0.6))+' would be 60%).':'— above 60% (rule: 60%).'); }
}
function _pcSplit(total){
  total=Math.max(0,parseInt(total)||0);
  const s=(id,v)=>{const e=document.getElementById(id);if(e)e.value=v;};
  const r=Math.round(total*0.60), p=Math.round(total*0.24), n=Math.round(total*0.08), d=Math.round(total*0.04);
  s('pc_retainer',r); s('pc_project',p); s('pc_notesdpp',n); s('pc_doubt',d); s('pc_quality',total-r-p-n-d);
  _pcSum();
}
async function submitPayConfig(tid){
  const v=id=>(document.getElementById(id)||{}).value;
  const body={teacher_id:tid,
    class_retainer:v('pc_retainer'),class_quality:v('pc_quality'),notes_dpp:v('pc_notesdpp'),
    doubt_resolution:v('pc_doubt'),project_delivery:v('pc_project'),
    tests_target:v('pc_tests'),videos_target:v('pc_videos'),live_target:v('pc_live'),shorts_target:v('pc_shorts'),
    target_labels:{tests:v('pc_lbl_tests'),videos:v('pc_lbl_videos'),live:v('pc_lbl_live'),shorts:v('pc_lbl_shorts')},
    custom_targets:(window._pcCustom||[]).map(c=>({name:(c.name||'').trim(),count:parseInt(c.count)||0})).filter(c=>c.name),
    designation:v('pc_desig'),department:v('pc_dept'),employee_code:v('pc_emp'),
    bank_name:v('pc_bank'),account_no:v('pc_acct'),ifsc:v('pc_ifsc'),
    payout_mode:v('pc_mode')||'standard',
    contract_base:v('pc_cbase'),task_rate:0,project_rate:v('pc_prate'),working_days:v('pc_wdays'),
    delay_relax:v('pc_drelax'),delay_deduct:v('pc_dded'),
    reject_relax:v('pc_rrelax'),reject_deduct:v('pc_rded'),
    contract_notes:v('pc_cnotes')};
  try{ const r=await api('/api/admin/earnings/config','POST',body); toast(r.message); closeModal(); aEarnFetch(); }
  catch(e){ toast(e.message,true); }
}
function adminSlip(tid){
  const x=_aEarnRow(tid); if(!x){ toast('Load the list first.',true); return; }
  _printDocHTML(_slipHTML(x));
}
function adminLetter(tid){
  const x=_aEarnRow(tid); if(!x){ toast('Load the list first.',true); return; }
  _printDocHTML(_letterHTML(x));
}

// ---- Office Locations (geofence, multi-branch) setup ----
window._olOffices=[]; window._olIps=[]; window._olUnknown=[];
async function openOfficeLocation(){
  try{ const d=await api('/api/admin/office-location'); window._olOffices=(d.offices||[]).map(o=>({name:o.name,lat:o.lat,lng:o.lng,radius:o.radius})); window._olIps=(d.ips||[]).slice(); window._olUnknown=(d.unknown_ips||[]).slice(); }
  catch(e){ window._olOffices=[]; window._olIps=[]; window._olUnknown=[]; }
  showModal('Office Locations (Geofence)',
   `<div class="alert alert-info" style="font-size:.82rem">Add each branch's <b>name + location + radius</b>. A teacher can punch from within the radius of <b>any branch</b> — the <b>branch name and distance</b> are recorded with every punch. Punching from outside is <b>blocked</b>.</div>
    <div id="ol-list"></div>
    <div style="border:1px dashed var(--border);border-radius:12px;padding:14px;margin-top:6px">
      <div style="font-weight:700;font-size:.85rem;margin-bottom:8px">Add a New Branch</div>
      <div class="form-group"><label>Branch name</label><input class="form-control" id="ol-name" placeholder="e.g. Head Office / Sector 15 Branch"></div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">
        <div class="form-group"><label>Latitude</label><input class="form-control" id="ol-lat" placeholder="28.613900"></div>
        <div class="form-group"><label>Longitude</label><input class="form-control" id="ol-lng" placeholder="77.209000"></div>
      </div>
      <div class="form-group"><label>Radius (meter)</label><input class="form-control" id="ol-radius" type="number" min="5" max="500" value="30">
      <div style="font-size:.72rem;color:var(--text-muted);margin-top:4px">Mobile GPS typically has a 5-20m error — <b>20-30m is practical</b>; max 500m.</div></div>
      <div style="display:flex;gap:8px;flex-wrap:wrap">
        <button class="btn btn-ghost btn-sm" onclick="olUseCurrent()">${ic('location')} Use My Current Location</button>
        <button class="btn btn-primary btn-sm" onclick="olAddBranch()">+ Add Branch</button>
      </div>
      <div id="ol-note" style="margin-top:8px"></div>
    </div>
    <div style="border:1px dashed var(--border);border-radius:12px;padding:14px;margin-top:10px">
      <div style="font-weight:700;font-size:.85rem;margin-bottom:4px">Office WiFi / PC Punch</div>
      <div style="font-size:.76rem;color:var(--text-muted);margin-bottom:8px">A <b>PC, laptop or phone</b> connected to the office broadband/WiFi can punch <b>without location</b>. If the office IP <b>keeps changing</b> (broadband gives a new IP on every reconnect), do <b>not</b> add IPs one by one — add the <b>whole range once</b> (e.g. <b>146.196.33.0/24</b> or <b>146.196.33.*</b>) and every IP in that block will work. <b>Never add a home IP or a mobile/hotspot IP</b> — that would allow punching from home.</div>
      <div id="ol-ip-list"></div>
      <div id="ol-unknown"></div>
      <div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin:10px 0 2px">
        <input class="form-control" id="ol-ip-manual" placeholder="Add IP or range e.g. 146.196.33.0/24" style="flex:1;min-width:190px" onkeydown="if(event.key==='Enter'){event.preventDefault();olAddIpText();}">
        <button class="btn btn-primary btn-sm" onclick="olAddIpText()">Add</button>
      </div>
      <div style="font-size:.72rem;color:var(--text-muted);margin-bottom:6px">Tip: office IP badalta rehta hai to poori range daalo — <b>146.196.33.0/24</b> (yaani 146.196.33.0 se 146.196.33.255 tak sab). Ek baar mein permanent fix.</div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px">
        <button class="btn btn-ghost btn-sm" onclick="olAddMyIp()">${ic('location')} Add This PC's IP</button>
        <button class="btn btn-ghost btn-sm" onclick="olCheckIps()">Check IPs (ISP / location)</button>
        <button class="btn btn-danger btn-sm" onclick="olClearIps()">Clear all IPs</button>
      </div>
      <div id="ol-ip-note" style="margin-top:6px"></div>
    </div>`,
   `${window._olOffices.length?`<button class="btn btn-danger" onclick="olClear()">Remove All (Geofence OFF)</button>`:''}<button class="btn btn-primary" onclick="saveOfficeLocation()">Save (${window._olOffices.length} branch)</button>`);
  _olRenderList(); _olRenderIps();
  // Modal khulte hi ISP/location auto-check (silent) — taaki MOBILE/proxy flag turant dikhe
  // aur admin ko galti se mobile IP add karne se pehle warning mil jaye.
  if((window._olUnknown||[]).length || (window._olIps||[]).length){ try{ olCheckIps(true); }catch(e){} }
}
// ---- Client-side IP range matcher (backend jaisa) — exact IP + CIDR + wildcard ----
function _ipToInt(ip){
  const p=String(ip||'').trim().split('.');
  if(p.length!==4) return null;
  let n=0;
  for(const o of p){ if(!/^\d{1,3}$/.test(o)) return null; const v=+o; if(v<0||v>255) return null; n=(n*256)+v; }
  return n>>>0;
}
function _ipNorm(entry){
  // canonical string ya null. exact -> 'a.b.c.d'; range -> 'a.b.c.0/24'
  let e=String(entry||'').trim();
  if(!e) return null;
  if(e.indexOf('*')>=0){
    const parts=e.split('.'); if(parts.length!==4) return null;
    const nums=[]; let wild=0, seen=false;
    for(const p of parts){
      if(p==='*'){ seen=true; wild++; nums.push('0'); }
      else { if(seen) return null; if(!/^\d{1,3}$/.test(p)||+p>255) return null; nums.push(p); }
    }
    if(wild<1||wild>3) return null;
    return nums.join('.')+'/'+(32-8*wild);
  }
  if(e.indexOf('/')>=0){
    const parts=e.split('/'); const pfx=+parts[1];
    if(_ipToInt(parts[0])===null||!(pfx>=0&&pfx<=32)) return null;
    const bi=_ipToInt(parts[0]); const mask=pfx===0?0:((0xFFFFFFFF<<(32-pfx))>>>0);
    const net=(bi&mask)>>>0;
    return [net>>>24,(net>>>16)&255,(net>>>8)&255,net&255].join('.')+'/'+pfx;
  }
  return _ipToInt(e)===null?null:e;
}
function _ipMatch(ip, entry){
  const ii=_ipToInt(ip); if(ii===null) return false;
  const n=_ipNorm(entry); if(!n) return false;
  if(n.indexOf('/')<0) return _ipToInt(n)===ii;
  const parts=n.split('/'); const pfx=+parts[1];
  const bi=_ipToInt(parts[0]); const mask=pfx===0?0:((0xFFFFFFFF<<(32-pfx))>>>0);
  return ((ii&mask)>>>0)===((bi&mask)>>>0);
}
function _ipInList(ip, list){ return (list||[]).some(e=>_ipMatch(ip,e)); }
function _ip24(ip){ const p=String(ip||'').trim().split('.'); return p.length===4?`${p[0]}.${p[1]}.${p[2]}.0/24`:''; }
function _ip16(ip){ const p=String(ip||'').trim().split('.'); return p.length===4?`${p[0]}.${p[1]}.0.0/16`:''; }
function _olIpMeta(ip){
  const m=(window._olIpInfo||{})[ip];
  if(!m) return '';
  if(!m.ok) return '<span style="color:var(--text-muted)"> · location unknown</span>';
  const where=[m.city,m.region,m.country].filter(Boolean).join(', ');
  let flag='';
  if(m.mobile) flag=' <span style="color:#dc2626;font-weight:800">MOBILE DATA — risky (may match home network)</span>';
  else if(m.proxy||m.hosting) flag=' <span style="color:#dc2626;font-weight:800">PROXY/VPN — risky</span>';
  return `<span style="color:${(m.mobile||m.proxy||m.hosting)?'#dc2626':'var(--text-muted)'}"> · ${esc(m.isp||'')}${where?' · '+esc(where):''}${flag}</span>`;
}
function _olRenderIps(){
  const el=document.getElementById('ol-ip-list'); if(!el) return;
  const ips=window._olIps;
  if(!ips.length){
    el.innerHTML='<div style="font-size:.76rem;color:var(--text-muted);margin-bottom:8px">No WiFi IPs yet — punching from PC/4G will ask for GPS location.</div>';
  } else {
    const rows=ips.map((ip,i)=>`<div class="pc-task"><div class="t"><div class="tt">${esc(ip)}</div><div class="td">Office WiFi — punching on this network works without GPS${_olIpMeta(ip)}</div></div>
      <button class="btn btn-ghost btn-sm" onclick="olDelIp(${i})">Remove</button></div>`).join('');
    el.innerHTML=ips.length>5
      ? `<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:5px">
          <div style="font-size:.74rem;color:var(--text-muted)"><b>${ips.length}</b> WiFi IPs — scroll to see all</div>
          <button class="btn btn-ghost btn-sm" style="padding:3px 10px;font-size:.72rem" id="ol-ip-toggle" onclick="olToggleIps()">Hide list</button></div>
        <div id="ol-ip-scroll" style="max-height:332px;overflow-y:auto;padding-right:2px">${rows}</div>`
      : rows;
  }
  const un=document.getElementById('ol-unknown');
  if(un){
    // range-aware: jo IP already kisi added range/IP me aata hai use "New IPs" me na dikhao
    const list=(window._olUnknown||[]).filter(x=>!_ipInList(x.ip, window._olIps));
    if(!list.length){ un.innerHTML=''; }
    else{
      const info=window._olIpInfo||{};
      const isMobile=ip=>{const m=info[ip]; return !!(m&&m.ok&&(m.mobile||m.proxy||m.hosting));};
      const nMob=list.filter(x=>isMobile(x.ip)).length;
      const header=`<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin:10px 0 6px;flex-wrap:wrap">
          <div style="font-size:.78rem;font-weight:700">New IPs — blocked punch attempts (add if office WiFi, add the range, or remove):</div>
          <button class="btn btn-ghost btn-sm" style="padding:3px 10px;font-size:.72rem" onclick="olDismissAllUnknown()" title="These are not office WiFi (e.g. mobile data) — dismiss all so they stop appearing">Dismiss all</button>
        </div>`
        + (nMob?`<div style="font-size:.72rem;color:#b45309;margin:-2px 0 8px">${nMob} of these are <b>mobile-data</b> attempts (teacher punching without office WiFi) — <b>do not add</b> these; ask them to connect to office WiFi. Use <b>Remove</b> to stop the whole mobile range.</div>`:'');
      un.innerHTML=header+list.map((x,i)=>{
        const mob=isMobile(x.ip);
        return `<div class="pc-task"><div class="t"><div class="tt">${esc(x.ip)}${_olIpMeta(x.ip)}</div><div class="td">last try: ${esc(x.at||'-')}</div></div>
        <div style="display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end">
          <button class="btn btn-primary btn-sm" onclick="olAddUnknown(${i})" title="Add just this single IP">Add</button>
          <button class="btn btn-ghost btn-sm" onclick="olAddUnknownRange(${i})" title="Add the whole ${esc(_ip24(x.ip))} range">Add range</button>
          <button class="btn btn-ghost btn-sm" onclick="olDismissUnknown(${i})" title="${mob?'Not office WiFi — dismiss the whole mobile range so it never returns':'Never show this IP again'}">Remove</button>
        </div></div>`;
      }).join('');
    }
  }
}
async function olClearIps(){
  const nHas=(window._olIps||[]).length, uHas=(window._olUnknown||[]).length;
  if(!nHas && !uHas){ const n=document.getElementById('ol-ip-note'); if(n) n.innerHTML='<div style="font-size:.8rem;color:var(--text-muted)">List already empty.</div>'; return; }
  if(!confirm(`Saari IP list reset karein? (${nHas} added WiFi IPs + ${uHas} "New IPs" attempted-log) — dono saaf ho jayenge. Phir office WiFi se connect karke fresh add karo. (Baad me Save dabana zaroori.)`)) return;
  window._olIps=[];
  try{ await api('/api/admin/office-unknown-clear','POST',{}); window._olUnknown=[]; }catch(e){}
  window._olIpInfo={}; _olRenderIps();
  const n=document.getElementById('ol-ip-note');
  if(n) n.innerHTML='<div class="alert alert-success" style="font-size:.8rem;margin-bottom:0">Saari IPs (added + New IPs) reset ho gayi. Ab office ki WiFi se connect ho kar <b>Add This PC IP</b> karo (ya teachers se office WiFi par punch karwao -> wo "New IPs" me aayega -> Add). Aakhir me <b>Save</b> dabana.</div>';
}
async function olCheckIps(silent){
  const all=[...(window._olIps||[]), ...((window._olUnknown||[]).map(x=>x.ip))];
  const uniq=[...new Set(all.filter(Boolean).filter(ip=>ip.indexOf('/')<0&&ip.indexOf('*')<0))];
  const n=document.getElementById('ol-ip-note');
  if(!uniq.length){ if(!silent && n) n.innerHTML='<div style="font-size:.8rem;color:var(--text-muted)">No IPs to check.</div>'; return; }
  if(!silent && n) n.innerHTML='<div style="font-size:.8rem;color:var(--text-muted)">Checking IPs (ISP / location)…</div>';
  try{
    const r=await api('/api/admin/office-ip-info','POST',{ips:uniq});
    window._olIpInfo=r.info||{};
    _olRenderIps();
    if(silent) return;
    const risky=uniq.filter(ip=>{const m=window._olIpInfo[ip]; return m&&m.ok&&(m.mobile||m.proxy||m.hosting);});
    if(r.error==='lookup_unavailable'){ if(n) n.innerHTML='<div class="alert alert-warning" style="font-size:.8rem;margin-bottom:0">Location lookup is not available right now (network). Please try again shortly.</div>'; return; }
    if(n) n.innerHTML=risky.length
      ? `<div class="alert alert-warning" style="font-size:.82rem;margin-bottom:0"><b>${risky.length} IP risky</b> (mobile/proxy) — inhe check karke <b>Remove</b> use this if not on office broadband: <b>${risky.map(esc).join(', ')}</b>. Har IP ke aage ISP/city dikh raha hai — jo alag city/ISP ka ho wo bahar ka ho sakta hai.</div>`
      : '<div class="alert alert-success" style="font-size:.82rem;margin-bottom:0">No obvious mobile/proxy IP found. Check the ISP/city next to each IP — remove any that differ from your office (Excitel) network.</div>';
  }catch(e){ if(!silent && n) n.innerHTML='<div class="alert alert-warning" style="font-size:.8rem;margin-bottom:0">Check failed: '+esc(e.message||'error')+'</div>'; }
}
function olAddUnknown(i){
  const list=(window._olUnknown||[]).filter(x=>!_ipInList(x.ip, window._olIps));
  const x=list[i]; if(!x) return;
  window._olIps.push(x.ip); _olRenderIps();
  const n=document.getElementById('ol-ip-note');
  const r24=_ip24(x.ip);
  if(n) n.innerHTML=`<div class="alert alert-success" style="font-size:.8rem;margin-bottom:0">IP <b>${esc(x.ip)}</b> added — don't forget to Save.${r24?` If the office IP keeps changing, <a href="#" onclick="olSwapToRange('${esc(x.ip)}','${esc(r24)}');return false;" style="font-weight:700">add the whole ${esc(r24)} range instead</a>.`:''}</div>`;
}
// New IP ki poori /24 range add karo (dynamic office IP ka permanent fix)
function olAddUnknownRange(i){
  const list=(window._olUnknown||[]).filter(x=>!_ipInList(x.ip, window._olIps));
  const x=list[i]; if(!x) return;
  const r=_ip24(x.ip);
  const n=document.getElementById('ol-ip-note');
  if(!r){ if(n) n.innerHTML='<div class="alert alert-danger" style="font-size:.8rem;margin-bottom:0">Could not build a range for this IP.</div>'; return; }
  if(!window._olIps.includes(r)) window._olIps.push(r);
  _olRenderIps();
  if(n) n.innerHTML=`<div class="alert alert-success" style="font-size:.8rem;margin-bottom:0">Range <b>${esc(r)}</b> added — every IP from ${esc(r.split('/')[0].replace(/0$/,'0'))} to ${esc(r.split('.').slice(0,3).join('.'))}.255 now works. Don't forget to Save.</div>`;
}
// single IP ko usi /24 range se replace kar do
function olSwapToRange(ip, r){
  window._olIps=(window._olIps||[]).filter(e=>e!==ip);
  if(!window._olIps.includes(r)) window._olIps.push(r);
  _olRenderIps();
  const n=document.getElementById('ol-ip-note');
  if(n) n.innerHTML=`<div class="alert alert-success" style="font-size:.8rem;margin-bottom:0">Switched to range <b>${esc(r)}</b> — covers the whole office block. Don't forget to Save.</div>`;
}
// "New IP" ko permanently dismiss karo. Mobile/proxy IP ho to poori carrier range (/16)
// ignore karo (Jio jaise pool har baar naya IP dete hain) — warna exact IP.
async function olDismissUnknown(i){
  const list=(window._olUnknown||[]).filter(x=>!_ipInList(x.ip, window._olIps));
  const x=list[i]; if(!x) return;
  const n=document.getElementById('ol-ip-note');
  const info=(window._olIpInfo||{})[x.ip];
  const mob=!!(info&&info.ok&&(info.mobile||info.proxy||info.hosting));
  const entry=mob?_ip16(x.ip):x.ip;   // mobile -> whole /16, else exact
  try{
    await api('/api/admin/office-ip-dismiss','POST',{entry:entry});
    // client se woh saare unknown hata do jo is entry (range) me aate hain
    window._olUnknown=(window._olUnknown||[]).filter(y=>!_ipMatch(y.ip, entry));
    _olRenderIps();
    if(n) n.innerHTML=`<div class="alert alert-info" style="font-size:.8rem;margin-bottom:0">${mob?`Mobile range <b>${esc(entry)}</b> dismissed — no IP from this carrier block will appear again.`:`IP <b>${esc(x.ip)}</b> removed — it will not appear again.`}</div>`;
  }catch(e){ if(n) n.innerHTML=`<div class="alert alert-danger" style="font-size:.8rem;margin-bottom:0">${esc(e.message||'Could not remove')}</div>`; }
}
// Saare shown "New IPs" ek saath dismiss — mobile ko /16, baaki ko exact IP se ignore
async function olDismissAllUnknown(){
  const list=(window._olUnknown||[]).filter(x=>!_ipInList(x.ip, window._olIps));
  if(!list.length) return;
  if(!confirm(`Dismiss all ${list.length} New IP attempt(s)? These are not office WiFi (e.g. mobile data). They will stop appearing. (Office WiFi list par koi asar nahi.)`)) return;
  const info=window._olIpInfo||{};
  const entries=[...new Set(list.map(x=>{const m=info[x.ip]; const mob=!!(m&&m.ok&&(m.mobile||m.proxy||m.hosting)); return mob?_ip16(x.ip):x.ip;}).filter(Boolean))];
  const n=document.getElementById('ol-ip-note');
  try{
    await api('/api/admin/office-ip-dismiss','POST',{ips:entries});
    window._olUnknown=(window._olUnknown||[]).filter(y=>!entries.some(e=>_ipMatch(y.ip,e)));
    _olRenderIps();
    if(n) n.innerHTML=`<div class="alert alert-success" style="font-size:.8rem;margin-bottom:0">All New IP attempts dismissed (${entries.length} range/IP). They will not appear again.</div>`;
  }catch(e){ if(n) n.innerHTML=`<div class="alert alert-danger" style="font-size:.8rem;margin-bottom:0">${esc(e.message||'Could not dismiss')}</div>`; }
}
// manual IP/range add (text box)
function olAddIpText(){
  const inp=document.getElementById('ol-ip-manual'); const n=document.getElementById('ol-ip-note');
  const raw=(inp&&inp.value||'').trim();
  if(!raw){ if(n) n.innerHTML='<div class="alert alert-warning" style="font-size:.8rem;margin-bottom:0">Type an IP or range first (e.g. 146.196.33.0/24).</div>'; return; }
  const norm=_ipNorm(raw);
  if(!norm){ if(n) n.innerHTML='<div class="alert alert-danger" style="font-size:.8rem;margin-bottom:0">Invalid — use 146.196.33.141, 146.196.33.0/24, or 146.196.33.*</div>'; return; }
  if(window._olIps.includes(norm)){ if(n) n.innerHTML=`<div class="alert alert-info" style="font-size:.8rem;margin-bottom:0"><b>${esc(norm)}</b> is already on the list.</div>`; if(inp) inp.value=''; return; }
  window._olIps.push(norm); if(inp) inp.value=''; _olRenderIps();
  const isRange=norm.indexOf('/')>=0;
  if(n) n.innerHTML=`<div class="alert alert-success" style="font-size:.8rem;margin-bottom:0">${isRange?'Range':'IP'} <b>${esc(norm)}</b> added${isRange?' — covers the whole block':''} — don't forget to Save.</div>`;
}
async function olAddMyIp(){
  const n=document.getElementById('ol-ip-note');
  try{
    const d=await api('/api/admin/my-ip');
    const ip=String(d.ip||'').trim();
    if(!ip){ if(n) n.innerHTML='<div class="alert alert-danger" style="font-size:.8rem;margin-bottom:0">Could not detect the IP.</div>'; return; }
    if(_ipInList(ip, window._olIps)){ if(n) n.innerHTML=`<div class="alert alert-info" style="font-size:.8rem;margin-bottom:0">IP ${esc(ip)} is already covered by the list.</div>`; return; }
    window._olIps.push(ip); _olRenderIps();
    const r24=_ip24(ip);
    if(n) n.innerHTML=`<div class="alert alert-success" style="font-size:.8rem;margin-bottom:0">This PC's IP <b>${esc(ip)}</b> added — don't forget to Save.${r24?` If your office IP changes often, <a href="#" onclick="olSwapToRange('${esc(ip)}','${esc(r24)}');return false;" style="font-weight:700">add the whole ${esc(r24)} range instead</a>.`:''}</div>`;
  }catch(e){ if(n) n.innerHTML=`<div class="alert alert-danger" style="font-size:.8rem;margin-bottom:0">${esc(e.message)}</div>`; }
}
function olDelIp(i){ window._olIps.splice(i,1); _olRenderIps(); }
// v121: IP list collapse/expand (5+ IPs pe)
function olToggleIps(){
  const sc=document.getElementById('ol-ip-scroll'), t=document.getElementById('ol-ip-toggle');
  if(!sc||!t) return;
  const hid=sc.style.display==='none';
  sc.style.display=hid?'':'none';
  t.textContent=hid?'Hide list':`Show list (${window._olIps.length})`;
}
function _olRenderList(){
  const el=document.getElementById('ol-list'); if(!el) return;
  if(!window._olOffices.length){ el.innerHTML='<div class="alert alert-warning" style="font-size:.82rem">No branches yet — <b>geofence is OFF</b>; teachers can punch from anywhere (including home).</div>'; return; }
  el.innerHTML=window._olOffices.map((o,i)=>`<div class="pc-task"><div class="t"><div class="tt">${ic('location')} ${esc(o.name)}</div><div class="td">${o.lat}, ${o.lng} · radius <b>${o.radius}m</b></div></div>
    <button class="btn btn-ghost btn-sm" onclick="olDelBranch(${i})">Remove</button></div>`).join('');
  const sv=[...document.querySelectorAll('#modal button')].find(b=>b.textContent.startsWith('Save ('));
  if(sv) sv.textContent=`Save (${window._olOffices.length} branch)`;
}
function olUseCurrent(){
  const n=document.getElementById('ol-note');
  if(!navigator.geolocation){ if(n) n.innerHTML='<div class="alert alert-danger" style="font-size:.8rem">This device/browser does not support location — enter it manually.</div>'; return; }
  if(n) n.innerHTML='<div class="alert alert-info" style="font-size:.8rem;margin-bottom:0">Fetching your location... (please keep GPS on)</div>';
  navigator.geolocation.getCurrentPosition(
    pos=>{ document.getElementById('ol-lat').value=pos.coords.latitude.toFixed(6);
           document.getElementById('ol-lng').value=pos.coords.longitude.toFixed(6);
           if(n) n.innerHTML=`<div class="alert alert-success" style="font-size:.8rem;margin-bottom:0">Location filled (GPS accuracy ~${Math.round(pos.coords.accuracy||0)}m). Now type the branch name and tap Add.</div>`; },
    err=>{ if(n) n.innerHTML='<div class="alert alert-danger" style="font-size:.8rem;margin-bottom:0">Could not get the location — allow permission in the browser or enter it manually.</div>'; },
    {enableHighAccuracy:true,timeout:15000,maximumAge:0});
}
function olAddBranch(){
  const name=(document.getElementById('ol-name').value||'').trim();
  const lat=parseFloat(document.getElementById('ol-lat').value), lng=parseFloat(document.getElementById('ol-lng').value);
  const radius=parseInt(document.getElementById('ol-radius').value)||30;
  const n=document.getElementById('ol-note');
  const err=t=>{ if(n) n.innerHTML=`<div class="alert alert-danger" style="font-size:.8rem;margin-bottom:0">${t}</div>`; };
  if(!name) return err('Please enter the branch name.');
  if(window._olOffices.some(o=>o.name.toLowerCase()===name.toLowerCase())) return err(`A branch named '${esc(name)}' already exists.`);
  if(isNaN(lat)||isNaN(lng)) return err('Please fill in the latitude/longitude (or tap Use My Current Location).');
  if(radius<5||radius>500) return err('Please keep the radius between 5-500 metres.');
  if(window._olOffices.length>=6) return err('You can add a maximum of 6 branches.');
  window._olOffices.push({name,lat,lng,radius});
  document.getElementById('ol-name').value=''; document.getElementById('ol-lat').value=''; document.getElementById('ol-lng').value='';
  if(n) n.innerHTML='';
  _olRenderList();
}
function olDelBranch(i){ window._olOffices.splice(i,1); _olRenderList(); }
async function saveOfficeLocation(){
  if(!window._olOffices.length){ toast('Add at least 1 branch (or use Clear All to turn geofence OFF).',true); return; }
  try{ const r=await api('/api/admin/office-location','POST',{offices:window._olOffices,ips:window._olIps}); window._aOffices=null; toast(r.message); closeModal(); }
  catch(e){ toast(e.message,true); }
}
async function olClear(){
  if(!confirm('Removing all branches will turn geofencing OFF — teachers will be able to punch from anywhere. Are you sure?')) return;
  try{ const r=await api('/api/admin/office-location','POST',{clear:true}); window._aOffices=null; toast(r.message); closeModal(); }
  catch(e){ toast(e.message,true); }
}

/* ---- ADMIN: finalize / paid ---- */
async function payoutFinalize(tid,name){
  if(!confirm('FINALIZE the payout for '+fmtMonthLabel(_aEarnMonth||curMonth())+'? The calculation snapshot will now be frozen.')) return;
  try{ const r=await api('/api/admin/teacher/'+tid+'/payout-finalize','POST',{month:_aEarnMonth||curMonth()}); toast(r.message); if(window.aEarnFetch) aEarnFetch(); }
  catch(e){ toast(e.message,true); }
}
async function payoutPaid(tid,name){
  if(!confirm('Mark this payout as PAID?')) return;
  try{ const r=await api('/api/admin/teacher/'+tid+'/payout-paid','POST',{month:_aEarnMonth||curMonth()}); toast(r.message); if(window.aEarnFetch) aEarnFetch(); }
  catch(e){ toast(e.message,true); }
}

