    window._edtPasteH=function(e){ var items=(e.clipboardData||{}).items||[]; for(var i=0;i<items.length;i++){ if(items[i].type&&items[i].type.indexOf('image')===0){ _edtAddFile(items[i].getAsFile()); e.preventDefault(); } } };
