function initAdminTranslation(){
  var app=document.getElementById('admin-app'); if(!app) return;
  if(!document.getElementById('atr-css')){
    var st=document.createElement('style'); st.id='atr-css';
    st.textContent=[
      '#a-page-translation .atr-tabs{display:flex;gap:2px;border-bottom:1px solid var(--border,#e5ddcb);margin:4px 0 16px;overflow-x:auto}',
      '#a-page-translation .atr-tab{padding:11px 15px;font-size:.86rem;font-weight:700;color:#8a7d5c;cursor:pointer;border:none;background:none;border-bottom:2px solid transparent;white-space:nowrap}',
      '#a-page-translation .atr-tab.on{color:#a9791f;border-bottom-color:#e6ad4e}',
      '#a-page-translation .atr-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:12px;margin-bottom:16px}',
      '#a-page-translation .atr-card{border:1px solid var(--border,#e5ddcb);border-radius:14px;padding:15px;background:var(--card,#fff)}',
      'body.dark #a-page-translation .atr-card{background:#1b1508;border-color:#2c2410}',
      '#a-page-translation .atr-val{font-size:1.7rem;font-weight:800;line-height:1}',
      '#a-page-translation .atr-lbl{font-size:.72rem;color:#8a7d5c;margin-top:6px;font-weight:600}',
      '#a-page-translation .atr-row{border:1px solid var(--border,#e5ddcb);border-radius:12px;padding:12px 14px;margin-bottom:10px}',
      'body.dark #a-page-translation .atr-row{border-color:#2c2410}',
      '#a-page-translation .atr-en{font-weight:600;font-size:.9rem}',
      '#a-page-translation .atr-hi{font-size:.92rem;margin-top:4px}',
      '#a-page-translation .atr-iss{font-size:.76rem;color:#c1443a;margin-top:5px}',
      '#a-page-translation .atr-conf{display:inline-block;font-size:.72rem;font-weight:800;padding:3px 9px;border-radius:999px}',
      '#a-page-translation .atr-conf.hi{background:rgba(46,158,107,.14);color:#2e9e6b}',
      '#a-page-translation .atr-conf.mid{background:rgba(224,165,74,.18);color:#a9791f}',
      '#a-page-translation .atr-conf.lo{background:rgba(209,68,58,.14);color:#d1443a}',
      '#a-page-translation .atr-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}',
      '#a-page-translation .atr-form{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px;align-items:end;border:1px solid var(--border,#e5ddcb);border-radius:12px;padding:14px;margin-bottom:16px}',
      'body.dark #a-page-translation .atr-form{border-color:#2c2410}',
      '#a-page-translation .atr-lock{font-size:.68rem;font-weight:800;padding:2px 8px;border-radius:999px;background:rgba(230,173,78,.16);color:#a9791f;margin-left:6px}',
      '#a-page-translation .atr-set{display:flex;align-items:center;justify-content:space-between;border:1px solid var(--border,#e5ddcb);border-radius:11px;padding:12px 14px;margin-bottom:10px}',
      'body.dark #a-page-translation .atr-set{border-color:#2c2410}'
    ].join('');
    document.head.appendChild(st);
  }
  var nav=app.querySelector('.sidebar-nav');
  if(nav && !nav.querySelector('[onclick*="translation"]')){
    var items=[].slice.call(nav.querySelectorAll('.nav-item'));
    var anchor=items.filter(function(n){return (n.getAttribute('onclick')||'').indexOf("'admins'")>=0;})[0]
             ||items.filter(function(n){return (n.getAttribute('onclick')||'').indexOf("'settings'")>=0;})[0];
    var d=document.createElement('div'); d.className='nav-item'; d.setAttribute('onclick',"aPage('translation',this)");
    d.innerHTML=(typeof ic==='function'?ic('grid'):'')+'<span>Translation Center</span>';
    if(anchor){ anchor.parentNode.insertBefore(d, anchor.nextSibling); } else { nav.appendChild(d); }
  }
  var main=app.querySelector('.main');
  if(main && !document.getElementById('a-page-translation')){
    var pg=document.createElement('div'); pg.className='page'; pg.id='a-page-translation';
    pg.innerHTML='<div id="a-tr-content"><div class="spinner"></div></div>';
    main.appendChild(pg);
  }
}

function loadATranslation(){
  if(!window._atrTab) window._atrTab='overview';
  _atrRender();
}
window.atTab=function(t){ window._atrTab=t; _atrRender(); };

function _atrRender(){
  var el=document.getElementById('a-tr-content'); if(!el) return;
  var tab=window._atrTab||'overview';
  var tabs=[['overview','Overview'],['glossary','Glossary'],['reviews','Review Queue'],['scan','Scan & Migrate'],['history','History'],['settings','Settings']];
  var head='<div class="atr-tabs">'+tabs.map(function(t){ return '<button class="atr-tab'+(tab===t[0]?' on':'')+'" onclick="atTab(\''+t[0]+'\')">'+t[1]+'</button>'; }).join('')+'</div>';
  el.innerHTML=head+'<div id="a-tr-body"><div class="spinner"></div></div>';
  if(tab==='overview') _atrOverview();
  else if(tab==='glossary') _atrGlossary();
  else if(tab==='reviews') _atrReviews();
  else if(tab==='scan') _atrScan();
  else if(tab==='history') _atrHistory();
  else if(tab==='settings') _atrSettings();
}

function _atrBody(){ return document.getElementById('a-tr-body'); }
function _atrConfCls(c){ return c>=85?'hi':(c>=55?'mid':'lo'); }
function _ape2(s){ return (typeof _ape==='function')?_ape(s):String(s==null?'':s); }

function _atrOverview(){
  api('/api/admin/translation/overview').then(function(o){
    var b=_atrBody(); if(!b) return;
    var cards=[['Total Questions',o.total_questions],['Translated',o.translated_questions],['Pending Reviews',o.pending_reviews],['Fixed',o.fixed_reviews],['Glossary Terms',o.glossary_terms],['Locked Terms',o.locked_terms]];
    b.innerHTML='<div class="atr-grid">'+cards.map(function(c){ return '<div class="atr-card"><div class="atr-val">'+(c[1]==null?0:c[1])+'</div><div class="atr-lbl">'+c[0]+'</div></div>'; }).join('')+'</div>'+
      '<p style="color:#8a7d5c;font-size:.86rem;line-height:1.6">This system translates exam content into subject-aware, exam-safe Hindi. Numbers, formulas and scientific names are protected; approved glossary terms are enforced; low-confidence translations are flagged for review. Use <b>Scan &amp; Migrate</b> to bring existing content onto the quality system.</p>';
  }).catch(function(e){ var b=_atrBody(); if(b)b.innerHTML='<div style="color:#c1443a;padding:16px">Could not load. '+_ape2(e&&e.message||'')+'</div>'; });
}

function _atrGlossary(){
  var b=_atrBody(); if(!b) return;
  api('/api/admin/glossary').then(function(r){
    var terms=r.terms||[];
    var form='<div class="atr-form">'+
      '<div class="form-group"><label>Subject</label><input class="form-control" id="atg-subject" placeholder="e.g. Physics (blank = all)"></div>'+
      '<div class="form-group"><label>Chapter</label><input class="form-control" id="atg-chapter" placeholder="optional"></div>'+
      '<div class="form-group"><label>English Term</label><input class="form-control" id="atg-en" placeholder="e.g. Current"></div>'+
      '<div class="form-group"><label>Preferred Hindi</label><input class="form-control" id="atg-hi" placeholder="e.g. विद्युत धारा"></div>'+
      '<div class="form-group"><label><input type="checkbox" id="atg-lock"> Locked (enforce)</label></div>'+
      '<div class="form-group"><label><input type="checkbox" id="atg-dnt"> Keep English</label></div>'+
      '<button class="btn btn-primary" onclick="atGlossAdd()">Add Term</button></div>';
    var list=terms.length?terms.map(function(t){
      return '<div class="atr-row"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px">'+
        '<div><span class="atr-en">'+_ape2(t.english_term)+'</span> &rarr; <b>'+(t.do_not_translate?'<i>keep English</i>':_ape2(t.preferred_hindi))+'</b>'+(t.locked?'<span class="atr-lock">LOCKED</span>':'')+
        '<div style="font-size:.74rem;color:#8a7d5c;margin-top:3px">'+_ape2(t.subject||'all subjects')+(t.chapter?' / '+_ape2(t.chapter):'')+'</div></div>'+
        '<div style="display:flex;gap:8px;flex-shrink:0">'+
          '<button class="btn btn-sm" onclick="atGlossLock('+t.id+','+(t.locked?'false':'true')+')">'+(t.locked?'Unlock':'Lock')+'</button>'+
          '<button class="btn btn-sm btn-danger" onclick="atGlossDel('+t.id+')">Delete</button>'+
        '</div></div></div>';
    }).join(''):'<div style="color:#9c8f6e;padding:14px">No glossary terms yet. Add the subject terms your papers use most.</div>';
    b.innerHTML=form+'<div style="font-weight:800;margin:6px 0 10px">Terms ('+terms.length+')</div>'+list;
  }).catch(function(e){ b.innerHTML='<div style="color:#c1443a;padding:16px">Could not load glossary.</div>'; });
}
window.atGlossAdd=function(){
  var g=function(id){var e=document.getElementById(id);return e?e.value.trim():'';};
  var en=g('atg-en'); if(!en){ toast('English term required',true); return; }
  api('/api/admin/glossary','POST',{subject:g('atg-subject'),chapter:g('atg-chapter'),english_term:en,preferred_hindi:g('atg-hi'),
    locked:document.getElementById('atg-lock').checked,do_not_translate:document.getElementById('atg-dnt').checked})
    .then(function(){ toast('Term added'); _atrGlossary(); }).catch(function(e){ toast((e&&e.message)||'Failed',true); });
};
window.atGlossLock=function(id,val){ api('/api/admin/glossary/'+id,'PATCH',{locked:val}).then(function(){ _atrGlossary(); }); };
window.atGlossDel=function(id){ api('/api/admin/glossary/'+id,'DELETE').then(function(){ toast('Deleted'); _atrGlossary(); }); };

function _atrReviews(){
  var b=_atrBody(); if(!b) return;
  api('/api/admin/translation/reviews').then(function(r){
    var rv=r.reviews||[];
    if(!rv.length){ b.innerHTML='<div style="color:#9c8f6e;padding:20px">No translations need review. All clear.</div>'; return; }
    b.innerHTML=rv.map(function(x){
      var cc=_atrConfCls(x.confidence);
      return '<div class="atr-row"><div style="display:flex;justify-content:space-between;gap:10px"><div style="font-size:.74rem;color:#8a7d5c">'+_ape2(x.subject||'')+(x.chapter?' / '+_ape2(x.chapter):'')+' \u00b7 '+_ape2(x.question_ref)+'</div><span class="atr-conf '+cc+'">'+x.confidence+'%</span></div>'+
        '<div class="atr-en">EN: '+_ape2(x.english_text)+'</div>'+
        '<div class="atr-hi">HI: '+_ape2(x.current_hindi||'(none)')+'</div>'+
        (x.issues&&x.issues.length?'<div class="atr-iss">Issues: '+_ape2(x.issues.join('; '))+'</div>':'')+
        '<div class="atr-actions">'+
          (x.content_type==='exam'?'<button class="btn btn-sm btn-primary" onclick="atRetranslate('+x.content_id+','+x.id+')">Re-translate</button>':'')+
          '<button class="btn btn-sm" onclick="atReviewEdit('+x.id+')">Edit &amp; Apply</button>'+
          '<button class="btn btn-sm" onclick="atReviewReject('+x.id+')">Keep Existing</button>'+
        '</div></div>';
    }).join('');
  }).catch(function(e){ b.innerHTML='<div style="color:#c1443a;padding:16px">Could not load reviews.</div>'; });
}
window.atRetranslate=function(qid,rid){ toast('Re-translating\u2026'); api('/api/admin/translation/retranslate/'+qid,'POST',{}).then(function(r){ toast('Re-translated (confidence '+(r.confidence!=null?r.confidence+'%':'n/a')+')'); _atrReviews(); }).catch(function(e){ toast((e&&e.message)||'Failed',true); }); };
window.atReviewReject=function(rid){ api('/api/admin/translation/reviews/'+rid+'/resolve','POST',{action:'reject'}).then(function(){ toast('Kept existing'); _atrReviews(); }); };
window.atReviewEdit=function(rid){
  var hi=prompt('Enter the corrected Hindi translation:'); if(hi==null) return;
  api('/api/admin/translation/reviews/'+rid+'/resolve','POST',{action:'apply',hindi:hi}).then(function(){ toast('Applied'); _atrReviews(); }).catch(function(e){ toast((e&&e.message)||'Failed',true); });
};

function _atrScan(){
  var b=_atrBody(); if(!b) return;
  b.innerHTML='<p style="color:#8a7d5c;font-size:.88rem;line-height:1.6;margin-bottom:14px">Scan existing translated questions. Safe fixes (like ordinal joins &ldquo;12 वीं&rdquo;&rarr;&ldquo;12वीं&rdquo;) are applied automatically and recorded in History; questions that look untranslated or broken are flagged in the Review Queue. Nothing is overwritten without review.</p>'+
    '<div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:14px">'+
    '<label style="font-size:.82rem;color:#8a7d5c">Content:</label>'+
    '<select class="form-control" id="atr-scan-type" style="width:auto"><option value="exam">Test / Exam questions</option><option value="lecture">Lecture questions</option></select>'+
    '<button class="btn btn-primary" id="atr-scan-btn" onclick="atScanRun()">Run Legacy Scan</button></div>'+
    '<div id="atr-scan-out"></div>';
}
window.atScanRun=function(){
  var btn=document.getElementById('atr-scan-btn'); if(btn){ btn.disabled=true; btn.textContent='Scanning\u2026'; }
  var ctSel=document.getElementById('atr-scan-type'); var ctype=ctSel?ctSel.value:'exam';
  var out=document.getElementById('atr-scan-out');
  var totals={scanned:0,verified:0,repaired:0,flagged:0};
  function batch(offset){
    api('/api/admin/translation/scan','POST',{offset:offset,limit:200,content_type:ctype}).then(function(r){
      var c=r.counts||{}; Object.keys(totals).forEach(function(k){ totals[k]+=(c[k]||0); });
      if(out) out.innerHTML='<div class="atr-grid">'+
        [['Scanned',totals.scanned],['Verified',totals.verified],['Auto-repaired',totals.repaired],['Flagged for review',totals.flagged]].map(function(x){ return '<div class="atr-card"><div class="atr-val">'+x[1]+'</div><div class="atr-lbl">'+x[0]+'</div></div>'; }).join('')+'</div>'+
        (r.remaining>0?'<div style="color:#8a7d5c;font-size:.82rem">'+r.remaining+' remaining\u2026</div>':'<div style="color:#2e9e6b;font-weight:700">Scan complete.</div>');
      if(r.remaining>0){ batch(r.next_offset); }
      else if(btn){ btn.disabled=false; btn.textContent='Run Legacy Scan'; }
    }).catch(function(e){ if(out)out.innerHTML='<div style="color:#c1443a">Scan failed: '+_ape2(e&&e.message||'')+'</div>'; if(btn){btn.disabled=false;btn.textContent='Run Legacy Scan';} });
  }
  batch(0);
};

function _atrHistory(){
  var b=_atrBody(); if(!b) return;
  api('/api/admin/translation/versions').then(function(r){
    var vs=r.versions||[];
    if(!vs.length){ b.innerHTML='<div style="color:#9c8f6e;padding:20px">No changes yet. Repairs, re-translations and edits will appear here and can be reverted.</div>'; return; }
    b.innerHTML='<div style="font-weight:800;margin-bottom:10px">Recent Changes ('+vs.length+')</div>'+vs.map(function(v){
      return '<div class="atr-row"><div style="display:flex;justify-content:space-between;gap:10px"><div style="font-size:.74rem;color:#8a7d5c">'+_ape2(v.content_type)+' #'+v.content_id+' \u00b7 '+_ape2(v.question_ref)+' \u00b7 '+_ape2(v.reason)+'</div><div style="font-size:.72rem;color:#8a7d5c">'+_ape2(v.at)+'</div></div>'+
        '<div class="atr-hi" style="color:#c1443a;text-decoration:line-through">'+_ape2(v.old_value||'(empty)')+'</div>'+
        '<div class="atr-hi" style="color:#2e9e6b">'+_ape2(v.new_value||'(empty)')+'</div>'+
        (v.reason!=='revert'?'<div class="atr-actions"><button class="btn btn-sm" onclick="atRevert('+v.id+')">Revert to old</button></div>':'')+
      '</div>';
    }).join('');
  }).catch(function(e){ b.innerHTML='<div style="color:#c1443a;padding:16px">Could not load history.</div>'; });
}
window.atRevert=function(vid){ api('/api/admin/translation/versions/'+vid+'/revert','POST',{}).then(function(){ toast('Reverted'); _atrHistory(); }).catch(function(e){ toast((e&&e.message)||'Failed',true); }); };

function _atrSettings(){
  var b=_atrBody(); if(!b) return;
  api('/api/admin/translation/settings').then(function(r){
    var s=r.settings||{};
    function toggle(key,label,on){ return '<div class="atr-set"><div style="font-weight:600;font-size:.9rem">'+label+'</div><button class="btn btn-sm '+(on?'btn-primary':'')+'" onclick="atSet(\''+key+'\',\''+(on?'off':'on')+'\')">'+(on?'ON':'OFF')+'</button></div>'; }
    b.innerHTML=toggle('gemini_verification','Gemini verification',(s.gemini_verification!=='off'))+
      toggle('strict_mode','Strict mode (flag more aggressively)',(s.strict_mode==='on'))+
      '<div class="atr-set"><div style="font-weight:600;font-size:.9rem">Confidence threshold (flag below)</div><input class="form-control" style="width:90px" id="atr-thr" value="'+_ape2(s.confidence_threshold||'70')+'" onchange="atSet(\'confidence_threshold\',this.value)"></div>';
  }).catch(function(e){ b.innerHTML='<div style="color:#c1443a;padding:16px">Could not load settings.</div>'; });
}
window.atSet=function(k,v){ var o={}; o[k]=v; api('/api/admin/translation/settings','POST',o).then(function(){ toast('Saved'); if(k!=='confidence_threshold')_atrSettings(); }); };

/* ============================================================
   PHASE 5 — Admin: Teacher Categories (premium management UI)
   Drives the Phase 4 API. NIOS/existing pages untouched.
   ============================================================ */
function initAdminCategories(){
  var app=document.getElementById('admin-app'); if(!app) return;
  if(!document.getElementById('cat-admin-css')){
    var st=document.createElement('style'); st.id='cat-admin-css';
    st.textContent=[
      '#a-page-categories .cat-top{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:16px}',
      '#a-page-categories .cat-add{padding:9px 16px;border-radius:10px;border:none;background:linear-gradient(135deg,#e6ad4e,#c98a2e);color:#241a05;font-weight:800;cursor:pointer;font-size:.86rem}',
      '#a-page-categories .cat-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:14px}',
      '#a-page-categories .cat-card{border:1px solid var(--border);border-radius:16px;padding:18px;background:var(--card);display:flex;flex-direction:column;gap:12px;transition:.16s}',
      '#a-page-categories .cat-card:hover{transform:translateY(-2px);box-shadow:0 10px 26px rgba(15,23,42,.08);border-color:#d9b978}',
      'body.dark #a-page-categories .cat-card{background:var(--card);border-color:var(--border)}',
      '#a-page-categories .cat-hd{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}',
      '#a-page-categories .cat-nm{font-weight:800;font-size:1.12rem;line-height:1.2}',
      '#a-page-categories .cat-key{font-family:ui-monospace,monospace;font-size:.72rem;color:#8a7d5c;margin-top:3px}',
      '#a-page-categories .cat-desc{font-size:.82rem;color:#8a7d5c;min-height:1.1em}',
      '#a-page-categories .cat-pill{font-size:.68rem;font-weight:800;padding:4px 10px;border-radius:999px;white-space:nowrap;text-transform:uppercase;letter-spacing:.04em}',
      '#a-page-categories .cat-pill.on{background:rgba(5,150,105,.14);color:#059669}',
      '#a-page-categories .cat-pill.off{background:rgba(120,113,108,.16);color:#78716c}',
      '#a-page-categories .cat-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}',
      '#a-page-categories .cat-stat{background:rgba(230,173,78,.08);border-radius:11px;padding:10px;text-align:center}',
      'body.dark #a-page-categories .cat-stat{background:rgba(230,173,78,.06)}',
      '#a-page-categories .cat-stat b{display:block;font-size:1.2rem;font-weight:800;color:#b8941f}',
      '#a-page-categories .cat-stat span{font-size:.68rem;color:#8a7d5c;text-transform:uppercase;letter-spacing:.03em}',
      '#a-page-categories .cat-acts{display:flex;flex-wrap:wrap;gap:7px;margin-top:2px}',
      '#a-page-categories .cat-btn{flex:1;min-width:78px;padding:8px 10px;border-radius:9px;border:1px solid var(--border);background:transparent;color:inherit;font-weight:700;font-size:.78rem;cursor:pointer;transition:.14s}',
      '#a-page-categories .cat-btn:hover{border-color:#b8941f;color:#b8941f}',
      '#a-page-categories .cat-btn.danger:hover{border-color:#c1443a;color:#c1443a}',
      '.catf-list{display:flex;flex-direction:column;gap:2px;max-height:52vh;overflow:auto;margin:6px 0}',
      '.catf-row{display:flex;align-items:center;gap:11px;padding:10px 12px;border-radius:10px;cursor:pointer}',
      '.catf-row:hover{background:rgba(230,173,78,.08)}',
      '.catf-cb{width:20px;height:20px;border-radius:6px;border:2px solid #cbb98f;display:flex;align-items:center;justify-content:center;font-size:.8rem;color:#fff;flex:0 0 auto}',
      '.catf-cb.on{background:#059669;border-color:#059669}'
    ].join('');
    document.head.appendChild(st);
  }
  var nav=app.querySelector('.sidebar-nav');
  if(nav && !nav.querySelector('[onclick*="categories"]')){
    var items=[].slice.call(nav.querySelectorAll('.nav-item'));
    var anchor=items.filter(function(n){return (n.getAttribute('onclick')||'').indexOf("'syllabus'")>=0;})[0]
             ||items.filter(function(n){return (n.getAttribute('onclick')||'').indexOf("'subjects'")>=0;})[0]
             ||items.filter(function(n){return (n.getAttribute('onclick')||'').indexOf("'admins'")>=0;})[0];
    var d=document.createElement('div'); d.className='nav-item'; d.setAttribute('onclick',"aPage('categories',this)");
    d.innerHTML=(typeof ic==='function'?ic('grid'):'')+'<span>Teacher Categories</span>';
    if(anchor){ anchor.parentNode.insertBefore(d, anchor.nextSibling); } else { nav.appendChild(d); }
  }
  var main=app.querySelector('.main');
  if(main && !document.getElementById('a-page-categories')){
    var pg=document.createElement('div'); pg.className='page'; pg.id='a-page-categories';
    pg.innerHTML='<div id="a-categories-content"><div class="spinner"></div></div>';
    main.appendChild(pg);
  }
}

function loadACategories(){
  var el=document.getElementById('a-categories-content'); if(!el) return;
  try{ softSpin(el); }catch(e){ el.innerHTML='<div class="spinner"></div>'; }
  api('/api/admin/categories').then(function(r){
    window._catData=r||{categories:[],features:[]};
    _renderACategories();
  }).catch(function(e){
    el.innerHTML='<div style="padding:24px;color:#c1443a">Could not load categories. '+esc((e&&e.message)||'')+'</div>';
  });
}

function _renderACategories(){
  var el=document.getElementById('a-categories-content'); if(!el) return;
  var d=window._catData||{}; var cats=d.categories||[];
  var head='<div class="cat-top"><div><div style="font-weight:800;font-size:1.05rem">Workspaces</div>'
    +'<div style="font-size:.82rem;color:#8a7d5c">One teacher account, category-based workspaces. Renaming is safe — the internal ID never changes.</div></div>'
    +'<button class="cat-add" onclick="catOpenEdit(0)">+ Add Category</button></div>';
  if(!cats.length){ el.innerHTML=head+'<div style="color:#9c8f6e;padding:22px">No categories yet. Use \u201cAdd Category\u201d to create one.</div>'; return; }
  var cards=cats.map(function(c){
    var on=(c.status==='active');
    return '<div class="cat-card">'
      +'<div class="cat-hd"><div><div class="cat-nm">'+esc(c.display_name)+'</div>'
        +'<div class="cat-key">'+esc(c.internal_key)+'</div></div>'
        +'<span class="cat-pill '+(on?'on':'off')+'">'+(on?'Active':'Inactive')+'</span></div>'
      +'<div class="cat-desc">'+esc(c.description||c.short_name||'')+'</div>'
      +'<div class="cat-stats">'
        +'<div class="cat-stat"><b>'+(c.teacher_count||0)+'</b><span>Teachers</span></div>'
        +'<div class="cat-stat"><b>'+(c.subject_count||0)+'</b><span>Subjects</span></div>'
        +'<div class="cat-stat"><b>'+(c.feature_count||0)+'</b><span>Features</span></div>'
      +'</div>'
      +'<div class="cat-acts">'
        +'<button class="cat-btn" onclick="catOpenEdit('+c.id+')">Edit</button>'
        +'<button class="cat-btn" onclick="catOpenSubjects('+c.id+')">Subjects</button>'
        +'<button class="cat-btn" onclick="catOpenMaterials('+c.id+')">Materials</button>'
        +'<button class="cat-btn" onclick="catOpenPayRates('+c.id+')">Pay Rates</button>'
        +'<button class="cat-btn" onclick="catOpenFeatures('+c.id+')">Features</button>'
        +'<button class="cat-btn '+(on?'danger':'')+'" onclick="catToggle('+c.id+','+(on?'0':'1')+')">'+(on?'Deactivate':'Activate')+'</button>'
      +'</div>'
    +'</div>';
  }).join('');
  el.innerHTML=head+'<div class="cat-grid">'+cards+'</div>';
}

function _catById(id){ return ((window._catData||{}).categories||[]).filter(function(c){return c.id===id;})[0]; }

function catOpenEdit(id){
  var c=id?_catById(id):null; var isNew=!c;
  var body='<div class="form-group"><label class="form-label">Display Name</label>'
    +'<input id="cat-nm" class="form-control" maxlength="120" placeholder="e.g. DU SOL" value="'+esc(c?c.display_name:'')+'"></div>'
    +(isNew?'<div style="font-size:.74rem;color:#8a7d5c;margin:-4px 0 10px">A permanent internal ID is generated automatically from this name and never changes, even if you rename the category later.</div>'
           :'<div class="form-group"><label class="form-label">Internal ID (permanent)</label><input class="form-control" value="'+esc(c.internal_key)+'" disabled style="opacity:.7;font-family:ui-monospace,monospace"></div>')
    +'<div class="form-group"><label class="form-label">Short Name</label>'
    +'<input id="cat-short" class="form-control" maxlength="40" placeholder="Optional" value="'+esc(c?c.short_name:'')+'"></div>'
    +'<div class="form-group"><label class="form-label">Description</label>'
    +'<textarea id="cat-desc" class="form-control" rows="2" maxlength="300" placeholder="Optional">'+esc(c?c.description:'')+'</textarea></div>'
    +'<div style="display:flex;gap:10px"><div class="form-group" style="flex:1"><label class="form-label">Icon</label>'
    +'<input id="cat-icon" class="form-control" maxlength="40" placeholder="e.g. grid" value="'+esc(c?c.icon:'')+'"></div>'
    +'<div class="form-group" style="width:120px"><label class="form-label">Order</label>'
    +'<input id="cat-order" type="number" class="form-control" value="'+(c?c.display_order:0)+'"></div></div>';
  var footer='<button class="btn btn-ghost" onclick="closeModal()">Cancel</button>'
    +'<button class="btn btn-primary" onclick="catSave('+(id||0)+')">'+(isNew?'Create Category':'Save Changes')+'</button>';
  showModal(isNew?'Add Category':'Edit Category', body, footer);
}

async function catSave(id){
  var name=(document.getElementById('cat-nm').value||'').trim();
  if(!name){ toast('Display name is required',true); return; }
  var payload={display_name:name,
    short_name:(document.getElementById('cat-short').value||'').trim(),
    description:(document.getElementById('cat-desc').value||'').trim(),
    icon:(document.getElementById('cat-icon').value||'').trim(),
    display_order:parseInt(document.getElementById('cat-order').value||'0',10)||0};
  try{
    if(id) await api('/api/admin/categories/'+id,'PATCH',payload);
    else   await api('/api/admin/categories','POST',payload);
    closeModal(); toast(id?'Category updated':'Category created'); loadACategories();
  }catch(e){ toast((e&&e.message)||'Could not save',true); }
}

async function catToggle(id,to){
  try{ await api('/api/admin/categories/'+id+'/status','POST',{status:to==1||to==='1'?'active':'inactive'});
    toast('Status updated'); loadACategories();
  }catch(e){ toast((e&&e.message)||'Could not update',true); }
}

async function catOpenFeatures(id){
  var c=_catById(id);
  showModal('Features · '+(c?c.display_name:''), '<div class="spinner"></div>', '');
  try{
    var r=await api('/api/admin/categories/'+id+'/features');
    var feats=((r.category||{}).features)||[];
    window._catFeat={id:id, feats:feats.map(function(f){return {key:f.key,label:f.label,enabled:!!f.enabled};})};
    _renderCatFeatures();
  }catch(e){ document.getElementById('modal-body').innerHTML='<div style="color:#c1443a;padding:12px">'+esc((e&&e.message)||'Could not load features')+'</div>'; }
}

function _renderCatFeatures(){
  var st=window._catFeat||{feats:[]};
  var rows=st.feats.map(function(f,i){
    return '<div class="catf-row" onclick="catFeatToggle('+i+')"><span class="catf-cb'+(f.enabled?' on':'')+'">'+(f.enabled?'\u2713':'')+'</span><span>'+esc(f.label)+'</span></div>';
  }).join('');
  document.getElementById('modal-body').innerHTML='<div style="font-size:.82rem;color:#8a7d5c;margin-bottom:6px">Tick the sidebar sections this workspace should show. Turning a feature off hides it for every teacher in this category.</div><div class="catf-list">'+rows+'</div>';
  document.getElementById('modal-footer').innerHTML='<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="catFeatSave()">Save Features</button>';
}

function catFeatToggle(i){ var st=window._catFeat; if(!st)return; st.feats[i].enabled=!st.feats[i].enabled; _renderCatFeatures(); }

async function catFeatSave(){
  var st=window._catFeat; if(!st) return;
  var map={}; st.feats.forEach(function(f){ map[f.key]=!!f.enabled; });
  try{ await api('/api/admin/categories/'+st.id+'/features','PUT',{features:map});
    closeModal(); toast('Features updated'); loadACategories();
  }catch(e){ toast((e&&e.message)||'Could not save',true); }
}

/* ============================================================
   PHASE 6 — Admin: assign categories + subjects to a teacher
   ============================================================ */
function openTeacherCategories(tid, name){
  showModal('Category Access · '+name, '<div class="spinner"></div>', '');
  api('/api/admin/teachers/'+tid+'/category-access').then(function(r){
    window._tcaState={tid:tid, cats:(r.categories||[])};
    _renderTeacherCats();
  }).catch(function(e){
    document.getElementById('modal-body').innerHTML='<div style="color:#c1443a;padding:12px">'+esc((e&&e.message)||'Could not load')+'</div>';
  });
}

function _renderTeacherCats(){
  var st=window._tcaState||{cats:[]};
  if(!document.getElementById('tca-css')){
    var s=document.createElement('style'); s.id='tca-css';
    s.textContent=[
      '.tca-cat{border:1px solid var(--border);border-radius:12px;margin-bottom:10px;overflow:hidden}',
      'body.dark .tca-cat{border-color:var(--border)}',
      '.tca-hd{display:flex;align-items:center;gap:11px;padding:12px 14px;cursor:pointer}',
      '.tca-hd:hover{background:rgba(230,173,78,.07)}',
      '.tca-cb{width:20px;height:20px;border-radius:6px;border:2px solid #cbb98f;display:flex;align-items:center;justify-content:center;font-size:.8rem;color:#fff;flex:0 0 auto}',
      '.tca-cb.on{background:#b8941f;border-color:#b8941f}',
      '.tca-nm{font-weight:800}',
      '.tca-key{font-family:ui-monospace,monospace;font-size:.7rem;color:#8a7d5c}',
      '.tca-subs{padding:4px 14px 12px 45px;display:flex;flex-wrap:wrap;gap:8px}',
      '.tca-subs.dis{opacity:.4;pointer-events:none}',
      '.tca-chip{display:inline-flex;align-items:center;gap:7px;padding:6px 11px;border-radius:999px;border:1px solid var(--border);cursor:pointer;font-size:.8rem;font-weight:600}',
      '.tca-chip.on{background:rgba(184,148,31,.14);border-color:#b8941f;color:#8a6d12}',
      'body.dark .tca-chip.on{color:#e6c15a}'
    ].join('');
    document.head.appendChild(s);
  }
  var html=st.cats.map(function(c,ci){
    var subs=(c.subjects||[]).map(function(su,si){
      return '<span class="tca-chip'+(su.assigned?' on':'')+'" onclick="tcaToggleSub('+ci+','+si+')">'
        +'<span style="font-weight:800">'+(su.assigned?'\u2713':'+')+'</span>'+esc(su.name)+(su.code?' <span class="tca-key">'+esc(su.code)+'</span>':'')+'</span>';
    }).join('') || '<span style="color:#9c8f6e;font-size:.8rem">No subjects in this category yet — add them in Teacher Categories → Subjects.</span>';
    return '<div class="tca-cat">'
      +'<div class="tca-hd" onclick="tcaToggleCat('+ci+')"><span class="tca-cb'+(c.assigned?' on':'')+'">'+(c.assigned?'\u2713':'')+'</span>'
        +'<div style="flex:1"><div class="tca-nm">'+esc(c.display_name)+'</div><div class="tca-key">'+esc(c.internal_key)+'</div></div></div>'
      +'<div class="tca-subs'+(c.assigned?'':' dis')+'">'+subs+'</div>'
    +'</div>';
  }).join('') || '<div style="color:#9c8f6e;padding:12px">No active categories. Create one in Teacher Categories.</div>';
  document.getElementById('modal-body').innerHTML='<div style="font-size:.82rem;color:#8a7d5c;margin-bottom:10px">Tick the workspaces this teacher can access, then choose their subjects inside each. Renaming a category later never affects this.</div>'+html;
  document.getElementById('modal-footer').innerHTML='<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="tcaSave()">Save Access</button>';
}

function tcaToggleCat(ci){
  var c=window._tcaState.cats[ci]; c.assigned=!c.assigned;
  if(!c.assigned){ (c.subjects||[]).forEach(function(s){ s.assigned=false; }); }
  _renderTeacherCats();
}
function tcaToggleSub(ci,si){
  var c=window._tcaState.cats[ci]; if(!c.assigned) return;
  c.subjects[si].assigned=!c.subjects[si].assigned; _renderTeacherCats();
}
async function tcaSave(){
  var st=window._tcaState; if(!st) return;
  var access=st.cats.filter(function(c){return c.assigned;}).map(function(c){
    return {category_id:c.id, subject_ids:(c.subjects||[]).filter(function(s){return s.assigned;}).map(function(s){return s.id;})};
  });
  try{ await api('/api/admin/teachers/'+st.tid+'/category-access','PUT',{access:access});
    closeModal(); toast('Category access updated');
  }catch(e){ toast((e&&e.message)||'Could not save',true); }
}

/* ============================================================
   PHASE 7 — Teacher header category switcher + feature-gated sidebar
   NIOS has every feature ON (backfill), so NIOS teachers see no change:
   nothing is hidden, and a single-category teacher gets no dropdown.
   ============================================================ */
var T_NAV_FEATURE={dashboard:'dashboard',vtasks:'my_tasks',timetable:'timetable',
  students:'students',dpp:'dpp',tests:'tests',material:'classes_material',
  extmat:'study_material',doubts:'doubts',performance:'performance',
  payout:'payout',notifications:'notifications',lectures:'classes_material',
  predicted:'tests',mysubjects:'my_subjects',subjectmaterials:'subject_materials',matchecker:'material_checker'};

async function initTeacherCategories(){
  try{
    var r=await api('/api/teacher/categories');
    var cats=(r&&r.categories)||[];
    window._tCats=cats;
    if(!cats.length){ return; }               // no category -> leave portal as-is
    try{ _tInjectCategoryNav(); }catch(e){}
    try{ var p=await api('/api/teacher/profile'); window._tCanSeeStudents=!!p.can_see_students; }catch(e){}
    // keep previously active if still valid, else first
    var cur=window._tActiveCat&&cats.filter(function(c){return c.id===window._tActiveCat.id;})[0];
    _tSetActiveCat(cur||cats[0], false);
    _tRenderSwitcher();
    // the dashboard was rendered before the active workspace was known — re-render it
    // so a non-NIOS teacher lands on their workspace dashboard, not the NIOS one.
    try{
      var dpg=document.getElementById('t-page-dashboard');
      if(dpg && dpg.classList.contains('active')){
        if(_tIsCatWorkspace()) loadTCatDashboard(); else loadTDashboard();
      }
    }catch(e){}
  }catch(e){}
}

function _tSetActiveCat(cat, reload){
  window._tActiveCat={id:cat.id, internal_key:cat.internal_key,
    display_name:cat.display_name, features:(cat.features||[])};
  _applyTNavFeatures();
  if(reload){
    document.querySelectorAll('#teacher-app .nav-item').forEach(function(n){n.classList.remove('active');});
    var first=document.querySelector('#teacher-app .nav-item'); if(first) first.classList.add('active');
    try{ tPage('dashboard',null); }catch(e){}
  }
}

function _tFeatureOn(key){
  var a=window._tActiveCat; if(!a) return true;
  if(!key) return true;
  return (a.features||[]).indexOf(key)>=0;
}

function _applyTNavFeatures(){
  var app=document.getElementById('teacher-app'); if(!app) return;
  if(!document.getElementById('tnav-feat-css')){
    var st=document.createElement('style'); st.id='tnav-feat-css';
    st.textContent='#teacher-app .sidebar-nav .nav-item.nav-feat-off{display:none !important}#teacher-app .sidebar-nav .nav-section.nav-sec-off{display:none !important}';
    document.head.appendChild(st);
  }
  app.querySelectorAll('.sidebar-nav .nav-item').forEach(function(n){
    var oc=n.getAttribute('onclick')||'';
    var m=oc.match(/tPage\('([^']+)'/);
    var show=true;
    if(m){
      var page=m[1]; var feat=T_NAV_FEATURE[page];
      if(page==='students'){ show=_tFeatureOn('students')&&!!window._tCanSeeStudents; }
      else if(page==='attendance'){ show=!window._tAttOff; }        // attendance disabled -> hide
      else if(feat===undefined){ show=true; }                       // unmapped -> always show
      else { show=_tFeatureOn(feat); }
    } else if(oc.indexOf('openTeacherNotify')>=0){
      show=_tFeatureOn('students');                                 // notify students -> student feature
    } else {
      show=true;                                                    // Message Admin etc. stay
    }
    n.classList.toggle('nav-feat-off', !show);
  });
  _tHideEmptyNavSections(app);
}

function _tHideEmptyNavSections(app){
  var nav=app.querySelector('.sidebar-nav'); if(!nav) return;
  var kids=[].slice.call(nav.children);
  kids.forEach(function(el,idx){
    if(!el.classList.contains('nav-section')) return;
    var vis=false;
    for(var j=idx+1;j<kids.length;j++){
      if(kids[j].classList.contains('nav-section')) break;
      // a feature-off item never counts, regardless of accordion inline display
      if(kids[j].classList.contains('nav-item') && !kids[j].classList.contains('nav-feat-off')){ vis=true; break; }
    }
    el.classList.toggle('nav-sec-off', !vis);
  });
}

function _tRenderSwitcher(){
  var cats=window._tCats||[]; var a=window._tActiveCat||{};
  var app=document.getElementById('teacher-app'); if(!app) return;
  var actions=app.querySelector('.topbar .topbar-actions'); if(!actions) return;
  var host=document.getElementById('t-wsswitch');
  if(!host){
    host=document.createElement('div'); host.id='t-wsswitch';
    actions.insertBefore(host, actions.firstChild);
  }
  if(!document.getElementById('tws-css')){
    var s=document.createElement('style'); s.id='tws-css';
    s.textContent=[
      '#t-wsswitch{position:relative;margin-right:8px}',
      '.tws-pill{display:inline-flex;align-items:center;gap:8px;padding:7px 13px;border-radius:999px;border:1px solid var(--border);background:rgba(184,148,31,.08);font-weight:800;font-size:.82rem;color:#8a6d12;white-space:nowrap}',
      'body.dark .tws-pill{color:#e6c15a;border-color:var(--border)}',
      '.tws-pill.btn{cursor:pointer}.tws-pill.btn:hover{border-color:#b8941f}',
      '.tws-dot{width:8px;height:8px;border-radius:50%;background:#b8941f}',
      '.tws-menu{position:absolute;top:110%;right:0;min-width:190px;background:var(--card);border:1px solid var(--border);border-radius:12px;box-shadow:0 12px 30px rgba(15,23,42,.14);padding:6px;z-index:60;display:none}',
      'body.dark .tws-menu{background:var(--card);border-color:var(--border)}',
      '#t-wsswitch.open .tws-menu{display:block}',
      '.tws-item{display:flex;align-items:center;gap:9px;padding:9px 11px;border-radius:9px;cursor:pointer;font-size:.86rem;font-weight:600}',
      '.tws-item:hover{background:rgba(184,148,31,.1)}',
      '.tws-item.on{color:#8a6d12;font-weight:800}',
      '.tws-check{margin-left:auto;color:#059669;font-weight:800}'
    ].join('');
    document.head.appendChild(s);
  }
  if(cats.length<=1){
    // single-category teacher (e.g. a normal NIOS teacher) — show nothing,
    // so their header stays exactly as it was.
    host.className=''; host.innerHTML=''; return;
  }
  var items=cats.map(function(c){
    return '<div class="tws-item'+(c.id===a.id?' on':'')+'" onclick="tSwitchCat('+c.id+')"><span class="tws-dot"></span><span>'+esc(c.display_name)+'</span>'+(c.id===a.id?'<span class="tws-check">\u2713</span>':'')+'</div>';
  }).join('');
  host.innerHTML='<span class="tws-pill btn" onclick="twsToggle(event)"><span class="tws-dot"></span>'+esc(a.display_name||'Workspace')+' <span style="opacity:.6">\u25BE</span></span><div class="tws-menu">'+items+'</div>';
}

function twsToggle(e){ if(e){e.stopPropagation();} var h=document.getElementById('t-wsswitch'); if(h) h.classList.toggle('open'); }
document.addEventListener('click',function(){ var h=document.getElementById('t-wsswitch'); if(h&&h.classList.contains('open')) h.classList.remove('open'); });

function tSwitchCat(id){
  var cats=window._tCats||[]; var c=cats.filter(function(x){return x.id===id;})[0]; if(!c) return;
  var h=document.getElementById('t-wsswitch'); if(h) h.classList.remove('open');
  _tSetActiveCat(c, true);
  _tRenderSwitcher();
  toast(c.display_name+' workspace');
}

/* ============================================================
   PHASE 8 — Category subjects (admin) + Teacher "My Subjects"
   ============================================================ */
/* Inject category-only nav items into the teacher sidebar once. They are
   feature-gated by Phase 7, so they only appear for categories that enable them
   (NIOS has them OFF, so NIOS teachers never see them). */
function _tInjectCategoryNav(){
  var app=document.getElementById('teacher-app'); if(!app) return;
  var nav=app.querySelector('.sidebar-nav'); var main=app.querySelector('.main');
  if(!nav||!main) return;
  if(!nav.querySelector('[onclick*="mysubjects"]')){
    var anchor=[].slice.call(nav.querySelectorAll('.nav-item')).filter(function(n){
      return (n.getAttribute('onclick')||'').indexOf("'dashboard'")>=0;})[0];
    var d=document.createElement('div'); d.className='nav-item';
    d.setAttribute('onclick',"tPage('mysubjects',this)");
    d.innerHTML=(typeof ic==='function'?ic('book'):'')+'<span>My Subjects</span>'; d.style.display='none';
    if(anchor){ anchor.parentNode.insertBefore(d, anchor.nextSibling); } else { nav.appendChild(d); }
  }
  if(!document.getElementById('t-page-mysubjects')){
    var pg=document.createElement('div'); pg.className='page'; pg.id='t-page-mysubjects';
    pg.innerHTML='<div id="t-mysubjects-content"><div class="spinner"></div></div>';
    main.appendChild(pg);
  }
  if(!nav.querySelector('[onclick*="subjectmaterials"]')){
    var a2=[].slice.call(nav.querySelectorAll('.nav-item')).filter(function(n){
      return (n.getAttribute('onclick')||'').indexOf("'mysubjects'")>=0;})[0];
    var d2=document.createElement('div'); d2.className='nav-item';
    d2.setAttribute('onclick',"tPage('subjectmaterials',this)");
    d2.innerHTML=(typeof ic==='function'?ic('folder'):'')+'<span>Subject Materials</span>'; d2.style.display='none';
    if(a2){ a2.parentNode.insertBefore(d2, a2.nextSibling); } else { nav.appendChild(d2); }
  }
  if(!document.getElementById('t-page-subjectmaterials')){
    var pg2=document.createElement('div'); pg2.className='page'; pg2.id='t-page-subjectmaterials';
    pg2.innerHTML='<div id="t-subjectmaterials-content"><div class="spinner"></div></div>';
    main.appendChild(pg2);
  }
  if(!nav.querySelector('[onclick*="matchecker"]')){
    var a3=[].slice.call(nav.querySelectorAll('.nav-item')).filter(function(n){
      return (n.getAttribute('onclick')||'').indexOf("'subjectmaterials'")>=0;})[0];
    var d3=document.createElement('div'); d3.className='nav-item';
    d3.setAttribute('onclick',"tPage('matchecker',this)");
    d3.innerHTML=(typeof ic==='function'?ic('check'):'')+'<span>Material Checker</span>'; d3.style.display='none';
    if(a3){ a3.parentNode.insertBefore(d3, a3.nextSibling); } else { nav.appendChild(d3); }
  }
  if(!document.getElementById('t-page-matchecker')){
    var pg3=document.createElement('div'); pg3.className='page'; pg3.id='t-page-matchecker';
    pg3.innerHTML='<div id="t-matchecker-content"><div class="spinner"></div></div>';
    main.appendChild(pg3);
  }
}

function loadTMySubjects(){
  var el=document.getElementById('t-mysubjects-content'); if(!el) return;
  var a=window._tActiveCat; if(!a){ el.innerHTML='<div style="padding:22px;color:#9c8f6e">No workspace selected.</div>'; return; }
  try{ softSpin(el); }catch(e){ el.innerHTML='<div class="spinner"></div>'; }
  if(!document.getElementById('tmsub-css')){
    var s=document.createElement('style'); s.id='tmsub-css';
    s.textContent=[
      '.tmsub-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:14px}',
      '.tmsub-card{border:1px solid var(--border);border-radius:16px;padding:18px;background:var(--card);transition:.16s}',
      '.tmsub-card:hover{transform:translateY(-2px);box-shadow:0 10px 26px rgba(15,23,42,.08);border-color:#d9b978}',
      'body.dark .tmsub-card{background:var(--card);border-color:var(--border)}',
      '.tmsub-nm{font-weight:800;font-size:1.1rem}',
      '.tmsub-code{font-family:ui-monospace,monospace;font-size:.72rem;color:#8a7d5c;margin-top:2px}',
      '.tmsub-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:14px}',
      '.tmsub-stat{text-align:center;background:rgba(230,173,78,.08);border-radius:11px;padding:9px}',
      'body.dark .tmsub-stat{background:rgba(230,173,78,.06)}',
      '.tmsub-stat b{display:block;font-size:1.15rem;font-weight:800;color:#b8941f}',
      '.tmsub-stat.pend b{color:#d97706}.tmsub-stat.appr b{color:#059669}',
      '.tmsub-stat span{font-size:.66rem;color:#8a7d5c;text-transform:uppercase;letter-spacing:.03em}'
    ].join('');
    document.head.appendChild(s);
  }
  api('/api/teacher/subjects?category_id='+a.id).then(function(r){
    var subs=(r&&r.subjects)||[];
    if(!subs.length){ el.innerHTML='<div style="padding:26px;text-align:center;color:#9c8f6e"><div style="font-size:1.05rem;font-weight:700;margin-bottom:6px">No subjects assigned yet</div><div style="font-size:.86rem">Your admin will assign subjects for the '+esc(a.display_name)+' workspace.</div></div>'; return; }
    var cards=subs.map(function(s){
      return '<div class="tmsub-card"><div class="tmsub-nm">'+esc(s.name)+'</div>'
        +(s.code?'<div class="tmsub-code">'+esc(s.code)+'</div>':'')
        +(s.description?'<div style="font-size:.82rem;color:#8a7d5c;margin-top:8px">'+esc(s.description)+'</div>':'')
        +'<div class="tmsub-stats">'
          +'<div class="tmsub-stat"><b>'+(s.materials||0)+'</b><span>Materials</span></div>'
          +'<div class="tmsub-stat pend"><b>'+(s.pending||0)+'</b><span>Pending</span></div>'
          +'<div class="tmsub-stat appr"><b>'+(s.approved||0)+'</b><span>Approved</span></div>'
        +'</div></div>';
    }).join('');
    el.innerHTML='<div style="margin-bottom:14px"><div style="font-weight:800;font-size:1.05rem">My Subjects</div><div style="font-size:.84rem;color:#8a7d5c">'+esc(a.display_name)+' workspace</div></div><div class="tmsub-grid">'+cards+'</div>';
  }).catch(function(e){ el.innerHTML='<div style="padding:22px;color:#c1443a">'+esc((e&&e.message)||'Could not load subjects')+'</div>'; });
}

/* ---- Admin: manage a category's subjects ---- */
function catOpenSubjects(cid){
  var c=_catById(cid);
  showModal('Subjects · '+(c?c.display_name:''), '<div class="spinner"></div>', '');
  _catLoadSubjects(cid);
}
function _catLoadSubjects(cid){
  api('/api/admin/categories/'+cid+'/subjects').then(function(r){
    window._catSubState={cid:cid, subjects:(r.subjects||[])};
    _renderCatSubjects();
  }).catch(function(e){ document.getElementById('modal-body').innerHTML='<div style="color:#c1443a;padding:12px">'+esc((e&&e.message)||'Could not load')+'</div>'; });
}
function _renderCatSubjects(){
  var st=window._catSubState||{subjects:[]};
  var rows=st.subjects.map(function(s){
    var on=(s.status==='active');
    return '<div style="display:flex;align-items:center;gap:10px;padding:10px 12px;border:1px solid var(--border,#e5ddcb);border-radius:10px;margin-bottom:8px'+(on?'':';opacity:.55')+'">'
      +'<div style="flex:1"><div style="font-weight:700">'+esc(s.name)+(s.code?' <span style="font-family:ui-monospace,monospace;font-size:.72rem;color:#8a7d5c">'+esc(s.code)+'</span>':'')+'</div>'
        +(s.description?'<div style="font-size:.78rem;color:#8a7d5c">'+esc(s.description)+'</div>':'')+'</div>'
      +'<button class="btn btn-ghost btn-sm" onclick="catSubEdit('+s.id+')">Edit</button>'
      +'<button class="btn btn-ghost btn-sm" onclick="catSubToggle('+s.id+','+(on?'0':'1')+')">'+(on?'Disable':'Enable')+'</button>'
    +'</div>';
  }).join('') || '<div style="color:#9c8f6e;padding:8px 0">No subjects yet.</div>';
  var add='<div style="border-top:1px solid var(--border,#e5ddcb);margin-top:12px;padding-top:12px"><div style="font-weight:700;font-size:.86rem;margin-bottom:8px">Add subject</div>'
    +'<div style="display:flex;gap:8px;flex-wrap:wrap"><input id="csub-name" class="form-control" style="flex:2;min-width:150px" placeholder="Subject name">'
    +'<input id="csub-code" class="form-control" style="flex:1;min-width:90px" placeholder="Code (optional)">'
    +'<button class="btn btn-primary" onclick="catSubAdd()">Add</button></div></div>';
  document.getElementById('modal-body').innerHTML='<div class="catf-list" style="max-height:44vh">'+rows+'</div>'+add;
  document.getElementById('modal-footer').innerHTML='<button class="btn btn-ghost" onclick="closeModal()">Close</button>';
}
async function catSubAdd(){
  var st=window._catSubState; if(!st) return;
  var name=(document.getElementById('csub-name').value||'').trim();
  if(!name){ toast('Subject name required',true); return; }
  var code=(document.getElementById('csub-code').value||'').trim();
  try{ await api('/api/admin/categories/'+st.cid+'/subjects','POST',{name:name,code:code});
    _catLoadSubjects(st.cid); loadACategories();
  }catch(e){ toast((e&&e.message)||'Could not add',true); }
}
function catSubEdit(sid){
  var st=window._catSubState; var s=(st.subjects||[]).filter(function(x){return x.id===sid;})[0]; if(!s) return;
  var body='<div class="form-group"><label class="form-label">Name</label><input id="cse-name" class="form-control" value="'+esc(s.name)+'"></div>'
    +'<div class="form-group"><label class="form-label">Code</label><input id="cse-code" class="form-control" value="'+esc(s.code||'')+'"></div>'
    +'<div class="form-group"><label class="form-label">Description</label><textarea id="cse-desc" class="form-control" rows="2">'+esc(s.description||'')+'</textarea></div>';
  showModal('Edit Subject', body,
    '<button class="btn btn-ghost" onclick="catOpenSubjects('+st.cid+')">Back</button><button class="btn btn-primary" onclick="catSubSave('+sid+')">Save</button>');
}
async function catSubSave(sid){
  var st=window._catSubState;
  try{ await api('/api/admin/category-subjects/'+sid,'PATCH',{
      name:(document.getElementById('cse-name').value||'').trim(),
      code:(document.getElementById('cse-code').value||'').trim(),
      description:(document.getElementById('cse-desc').value||'').trim()});
    toast('Subject updated'); catOpenSubjects(st.cid); loadACategories();
  }catch(e){ toast((e&&e.message)||'Could not save',true); }
}
async function catSubToggle(sid,to){
  var st=window._catSubState;
  try{ await api('/api/admin/category-subjects/'+sid,'PATCH',{status:(to==1||to==='1')?'active':'inactive'});
    _catLoadSubjects(st.cid); loadACategories();
  }catch(e){ toast((e&&e.message)||'Could not update',true); }
}

/* ============================================================
   PHASE 10 — Non-NIOS workspace dashboard shell (feature-driven)
   NIOS dashboard is never touched: this only runs for non-NIOS categories.
   ============================================================ */
function _tIsCatWorkspace(){
  var a=window._tActiveCat;
  return !!(a && a.internal_key && a.internal_key!=='nios');
}

function _tGreet(){
  var h=new Date().getHours();
  return h<12?'Good Morning':h<17?'Good Afternoon':'Good Evening';
}

function loadTCatDashboard(){
  var el=document.getElementById('t-dashboard-content'); if(!el) return;
  var a=window._tActiveCat; if(!a){ if(typeof loadTDashboard==='function') loadTDashboard(); return; }
  try{ softSpin(el); }catch(e){ el.innerHTML='<div class="spinner"></div>'; }
  if(!document.getElementById('tcd-css')){
    var s=document.createElement('style'); s.id='tcd-css';
    s.textContent=[
      '.tcd-hero{border-radius:18px;padding:22px 24px;background:linear-gradient(135deg,rgba(230,173,78,.16),rgba(184,148,31,.05));border:1px solid var(--border);margin-bottom:18px}',
      'body.dark .tcd-hero{background:linear-gradient(135deg,rgba(230,173,78,.12),rgba(0,0,0,0));border-color:var(--border)}',
      '.tcd-hero h2{margin:0;font-size:1.4rem;font-weight:800}',
      '.tcd-hero p{margin:4px 0 0;color:#8a7d5c;font-size:.9rem;font-weight:600}',
      '.tcd-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:14px;margin-bottom:20px}',
      '.tcd-kpi{border:1px solid var(--border);border-radius:16px;padding:18px;background:var(--card);cursor:pointer;transition:.16s}',
      '.tcd-kpi:hover{transform:translateY(-2px);box-shadow:0 10px 26px rgba(15,23,42,.08);border-color:#d9b978}',
      'body.dark .tcd-kpi{background:var(--card);border-color:var(--border)}',
      '.tcd-kpi b{display:block;font-size:2rem;font-weight:800;line-height:1}',
      '.tcd-kpi span{font-size:.76rem;color:#8a7d5c;text-transform:uppercase;letter-spacing:.04em;font-weight:700}',
      '.tcd-kpi.tasks b{color:#b8941f}.tcd-kpi.mat b{color:#6d28d9}.tcd-kpi.pend b{color:#d97706}.tcd-kpi.appr b{color:#059669}',
      '.tcd-sec{font-weight:800;font-size:1.02rem;margin:22px 0 12px}',
      '.tcd-empty{border:1px dashed var(--border);border-radius:14px;padding:22px;text-align:center;color:#9c8f6e;font-size:.88rem}',
      '.tcd-tasks-wrap{border:1px solid var(--border);border-radius:18px;padding:18px 18px 20px;background:var(--card);box-shadow:0 1px 2px rgba(15,23,42,.04)}',
      '.tcd-tasks-head{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:14px}',
      '.tcd-filter{display:flex;gap:8px;align-items:center;flex-wrap:wrap}',
      '.tcd-filter select{padding:8px 12px;border:1px solid var(--border);border-radius:10px;background:var(--card);font-weight:700;font-size:.82rem;color:var(--text)}',
      '.tcd-tgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:10px}',
      '.tcd-tstat{border:1px solid var(--border);border-radius:14px;padding:16px 12px;text-align:center;background:linear-gradient(180deg,rgba(230,173,78,.05),transparent)}',
      '.tcd-tstat b{display:block;font-size:1.9rem;font-weight:800;line-height:1}',
      '.tcd-tstat span{font-size:.68rem;color:#8a7d5c;text-transform:uppercase;letter-spacing:.04em;font-weight:700;margin-top:4px;display:block}'
    ].join('');
    document.head.appendChild(s);
  }
  api('/api/teacher/category-dashboard?category_id='+a.id).then(function(d){
    var hero='<div class="tcd-hero"><h2>'+_tGreet()+', '+esc((NAME||'')+(typeof _tSuffix!=='undefined'?_tSuffix:''))+'</h2>'
      +'<p>'+esc(d.category&&d.category.display_name||a.display_name)+' Workspace</p></div>';
    var feats=(a.features||[]);
    var taskSec='';
    if(feats.indexOf('my_tasks')>=0){
      taskSec='<div class="tcd-tasks-wrap">'
        +'<div class="tcd-tasks-head"><div class="tcd-sec" style="margin:0">Task Overview</div>'
        +'<div class="tcd-filter"><select id="tcd-period" onchange="_catTaskPeriod(this.value)">'
          +'<option value="week">This Week</option><option value="month" selected>This Month</option>'
          +'<option value="lifetime">Lifetime</option><option value="custom">Custom range\u2026</option></select>'
        +'<span id="tcd-custom" style="display:none;gap:6px;align-items:center"><input type="date" id="tcd-from" class="form-control" style="padding:6px 8px;width:auto"><span style="color:var(--text-muted)">to</span><input type="date" id="tcd-to" class="form-control" style="padding:6px 8px;width:auto"><button class="btn btn-primary btn-sm" onclick="_catTaskLoad()">Go</button></span></div></div>'
        +'<div id="tcd-task-cards"><div class="spinner" style="margin:16px auto"></div></div>'
        +'<div style="text-align:center;margin-top:12px"><button class="btn btn-primary btn-sm" onclick="tPage(\'vtasks\',null)">Open My Tasks</button></div>'
        +'</div>';
    }
    var rec=d.recent||[];
    var recHtml='<div class="tcd-sec">Recent Activity</div>'+(rec.length
      ? '<div style="display:flex;flex-direction:column;gap:8px">'+rec.map(function(r){
          return '<div style="display:flex;gap:10px;align-items:center;padding:10px 12px;border:1px solid var(--border,#e5ddcb);border-radius:10px"><span style="color:#059669;font-weight:800">\u2713</span><div style="flex:1"><div style="font-weight:600;font-size:.86rem">'+esc(r.detail||r.action)+'</div><div style="font-size:.72rem;color:#8a7d5c">'+esc(r.at)+'</div></div></div>';
        }).join('')+'</div>'
      : '<div class="tcd-empty">You\u2019re all clear \u2014 no recent activity yet.</div>');
    el.innerHTML=hero+taskSec+recHtml;
    if(feats.indexOf('my_tasks')>=0) _catTaskLoad();
  }).catch(function(e){
    el.innerHTML='<div style="padding:22px;color:#c1443a">Could not load workspace. '+esc((e&&e.message)||'')+'</div>';
  });
}
function _catTaskPeriod(v){
  var c=document.getElementById('tcd-custom'); if(c) c.style.display=(v==='custom')?'inline-flex':'none';
  if(v!=='custom') _catTaskLoad();
}
function _catTaskLoad(){
  var box=document.getElementById('tcd-task-cards'); if(!box) return;
  var p=(document.getElementById('tcd-period')||{}).value||'month';
  var qs='period='+p;
  if(p==='custom'){ var f=(document.getElementById('tcd-from')||{}).value,t=(document.getElementById('tcd-to')||{}).value; if(!f||!t){ toast('Pick both dates',true); return; } qs+='&frm='+f+'&to='+t; }
  box.innerHTML='<div class="spinner" style="margin:16px auto"></div>';
  api('/api/teacher/task-stats?'+qs).then(function(s){
    var card=function(v,l,c){ return '<div class="tcd-tstat"><b style="color:'+c+'">'+v+'</b><span>'+l+'</span></div>'; };
    box.innerHTML='<div class="tcd-tgrid">'
      +card(s.assigned||0,'Total Tasks','#b8941f')
      +card(s.done||0,'Done','#059669')
      +card(s.pending||0,'Pending','#d97706')
      +card(s.on_time||0,'On-time','#0f7a44')
      +card(s.delayed||0,'Delayed','#dc2626')
      +card(s.rejected||0,'Rejected','#c0392b')
      +'</div>'
      +(s.projects?'<div style="text-align:center;margin-top:10px;font-size:.8rem;color:var(--text-muted)">Projects completed: <b>'+s.projects+'</b></div>':'');
  }).catch(function(e){ box.innerHTML='<div class="tcd-empty">Could not load task stats.</div>'; });
}

/* ============================================================
   PHASE 11 — Subject Materials (admin upload + teacher secure view)
   ============================================================ */
var MAT_TYPES=[['notes','Notes'],['book','Book'],['pdf','PDF'],['ppt','PPT'],
  ['qbank','Question Bank'],['reference','Reference'],['resource','Study Resource']];
function _matTypeLabel(k){ var f=MAT_TYPES.filter(function(x){return x[0]===k;})[0]; return f?f[1]:k; }
function _fmtSize(n){ n=n||0; return n>=1048576?(n/1048576).toFixed(1)+' MB':n>=1024?(n/1024).toFixed(0)+' KB':n+' B'; }

async function catDownloadMaterial(role, mid, name){
  var url=API+'/api/'+role+'/category-materials/'+mid+'/download';
  try{
    var r=await fetch(url,{headers:{Authorization:'Bearer '+TOKEN}});
    if(!r.ok) throw new Error('Download failed');
    var blob=await r.blob(); if(!blob||!blob.size) throw new Error('empty'); var u=URL.createObjectURL(blob);
    var a=document.createElement('a'); a.href=u; a.download=name||'file';
    document.body.appendChild(a); a.click(); a.remove(); setTimeout(function(){URL.revokeObjectURL(u);},4000);
  }catch(e){
    try{ window.open(url+'?t='+encodeURIComponent(TOKEN),'_blank','noopener'); }
    catch(e2){ toast('Could not download',true); }
  }
}

/* ---- Admin materials manager ---- */
function catOpenMaterials(cid){
  var c=_catById(cid);
  showModal('Subject Materials · '+(c?c.display_name:''), '<div class="spinner"></div>', '');
  Promise.all([
    api('/api/admin/categories/'+cid+'/subjects').catch(function(){return {subjects:[]};}),
    api('/api/admin/categories/'+cid+'/materials').catch(function(){return {materials:[]};})
  ]).then(function(res){
    window._catMatState={cid:cid, subjects:(res[0].subjects||[]), materials:(res[1].materials||[])};
    _renderCatMaterials();
  }).catch(function(e){ document.getElementById('modal-body').innerHTML='<div style="color:#c1443a;padding:12px">'+esc((e&&e.message)||'Could not load')+'</div>'; });
}
function _renderCatMaterials(){
  var st=window._catMatState||{subjects:[],materials:[]};
  var subOpts='<option value="">Whole category (no subject)</option>'+st.subjects.map(function(s){return '<option value="'+s.id+'">'+esc(s.name)+'</option>';}).join('');
  var typeOpts=MAT_TYPES.map(function(t){return '<option value="'+t[0]+'">'+t[1]+'</option>';}).join('');
  var up='<div style="border:1px solid var(--border,#e5ddcb);border-radius:12px;padding:14px;margin-bottom:14px">'
    +'<div style="font-weight:700;font-size:.88rem;margin-bottom:10px">Upload material</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">'
    +'<input id="cm-title" class="form-control" placeholder="Title">'
    +'<select id="cm-type" class="form-control">'+typeOpts+'</select>'
    +'<select id="cm-subject" class="form-control">'+subOpts+'</select>'
    +'<input id="cm-file" type="file" class="form-control">'
    +'</div>'
    +'<textarea id="cm-desc" class="form-control" rows="2" placeholder="Description (optional)" style="margin-top:8px"></textarea>'
    +'<div style="display:flex;justify-content:flex-end;margin-top:8px"><button class="btn btn-primary" id="cm-up-btn" onclick="catUploadMaterial()">Upload</button></div>'
    +'<div id="cm-up-status" style="font-size:.8rem;margin-top:6px"></div></div>';
  var rows=st.materials.length?st.materials.map(function(m){
    return '<div style="display:flex;align-items:center;gap:10px;padding:10px 12px;border:1px solid var(--border,#e5ddcb);border-radius:10px;margin-bottom:8px'+(m.is_active?'':';opacity:.55')+'">'
      +'<div style="flex:1"><div style="font-weight:700">'+esc(m.title)+' <span style="font-size:.68rem;color:#8a7d5c;background:rgba(230,173,78,.14);padding:2px 8px;border-radius:999px">'+esc(_matTypeLabel(m.material_type))+'</span></div>'
      +'<div style="font-size:.74rem;color:#8a7d5c">'+(m.subject?esc(m.subject)+' · ':'Whole category · ')+_fmtSize(m.file_size)+' · '+esc(m.created_at)+'</div></div>'
      +'<button class="btn btn-ghost btn-sm" onclick="catDownloadMaterial(\'admin\','+m.id+',\''+esc((m.filename||'file').replace(/'/g,''))+'\')">Download</button>'
      +'<button class="btn btn-ghost btn-sm" onclick="catMatToggle('+m.id+','+(m.is_active?0:1)+')">'+(m.is_active?'Disable':'Enable')+'</button>'
    +'</div>';
  }).join(''):'<div style="color:#9c8f6e;padding:8px 0">No materials uploaded yet.</div>';
  document.getElementById('modal-body').innerHTML=up+'<div style="font-weight:700;font-size:.86rem;margin-bottom:8px">Uploaded ('+st.materials.length+')</div>'+rows;
  document.getElementById('modal-footer').innerHTML='<button class="btn btn-ghost" onclick="closeModal()">Close</button>';
}
async function catUploadMaterial(){
  var st=window._catMatState; if(!st) return;
  var f=document.getElementById('cm-file'); var title=(document.getElementById('cm-title').value||'').trim();
  if(!f.files||!f.files[0]){ toast('Choose a file',true); return; }
  if(!title){ title=f.files[0].name; }
  var btn=document.getElementById('cm-up-btn'); btn.disabled=true; btn.textContent='Uploading...';
  try{
    var fd=new FormData();
    fd.append('file', f.files[0]); fd.append('title', title);
    fd.append('material_type', document.getElementById('cm-type').value);
    fd.append('subject_id', document.getElementById('cm-subject').value||'');
    fd.append('description', document.getElementById('cm-desc').value||'');
    var r=await fetch(API+'/api/admin/categories/'+st.cid+'/materials',{method:'POST',headers:{Authorization:'Bearer '+TOKEN},body:fd});
    if(!r.ok){ var d=null; try{d=await r.json();}catch(e){} throw new Error((d&&d.detail)||'Upload failed'); }
    toast('Material uploaded'); catOpenMaterials(st.cid); loadACategories();
  }catch(e){ document.getElementById('cm-up-status').innerHTML='<span style="color:#c1443a">'+esc(e.message)+'</span>'; btn.disabled=false; btn.textContent='Upload'; }
}
async function catMatToggle(mid,to){
  var st=window._catMatState;
  try{ await api('/api/admin/category-materials/'+mid,'PATCH',{is_active:(to==1||to==='1')}); catOpenMaterials(st.cid); }
  catch(e){ toast((e&&e.message)||'Could not update',true); }
}

/* ---- Teacher subject materials ---- */
function loadTSubjectMaterials(){
  var el=document.getElementById('t-subjectmaterials-content'); if(!el) return;
  var a=window._tActiveCat; if(!a){ el.innerHTML=''; return; }
  try{ softSpin(el); }catch(e){ el.innerHTML='<div class="spinner"></div>'; }
  api('/api/teacher/materials?category_id='+a.id).then(function(r){
    var mats=(r&&r.materials)||[];
    if(!mats.length){ el.innerHTML='<div style="margin-bottom:14px"><div style="font-weight:800;font-size:1.05rem">Subject Materials</div><div style="font-size:.84rem;color:#8a7d5c">'+esc(a.display_name)+' workspace</div></div><div class="tcd-empty">No materials available yet.</div>'; return; }
    // group by subject
    var groups={}; mats.forEach(function(m){ var k=m.subject||'General'; (groups[k]=groups[k]||[]).push(m); });
    var html='<div style="margin-bottom:14px"><div style="font-weight:800;font-size:1.05rem">Subject Materials</div><div style="font-size:.84rem;color:#8a7d5c">'+esc(a.display_name)+' workspace</div></div>';
    Object.keys(groups).forEach(function(g){
      html+='<div class="tcd-sec">'+esc(g)+'</div><div style="display:flex;flex-direction:column;gap:8px">';
      html+=groups[g].map(function(m){
        return '<div style="display:flex;align-items:center;gap:12px;padding:12px 14px;border:1px solid var(--border,#e5ddcb);border-radius:12px;background:var(--card,#fff)">'
          +'<div style="flex:1"><div style="font-weight:700">'+esc(m.title)+' <span style="font-size:.66rem;color:#8a7d5c;background:rgba(230,173,78,.14);padding:2px 8px;border-radius:999px">'+esc(_matTypeLabel(m.material_type))+'</span></div>'
          +(m.description?'<div style="font-size:.78rem;color:#8a7d5c;margin-top:2px">'+esc(m.description)+'</div>':'')
          +'<div style="font-size:.72rem;color:#8a7d5c;margin-top:2px">'+_fmtSize(m.file_size)+' · '+esc(m.created_at)+'</div></div>'
          +'<button class="btn btn-primary btn-sm" onclick="catDownloadMaterial(\'teacher\','+m.id+',\''+esc((m.filename||'file').replace(/'/g,''))+'\')">Download</button></div>';
      }).join('')+'</div>';
    });
    el.innerHTML=html;
  }).catch(function(e){ el.innerHTML='<div style="padding:22px;color:#c1443a">'+esc((e&&e.message)||'Could not load materials')+'</div>'; });
}

/* ============================================================
   PHASE 12A — Material Checker (teacher side)
   ============================================================ */
var MS_STATUS={submitted:['Submitted','#2563eb'],under_review:['Under Review','#7c3aed'],
  changes_required:['Changes Required','#d97706'],resubmitted:['Resubmitted','#0891b2'],
  approved:['Approved','#059669'],rejected:['Rejected','#dc2626'],draft:['Draft','#6b7280']};
function _msPill(st){ var m=MS_STATUS[st]||[st,'#6b7280']; return '<span style="font-size:.68rem;font-weight:800;padding:3px 10px;border-radius:999px;white-space:nowrap;color:#fff;background:'+m[1]+'">'+m[0]+'</span>'; }
function _mcStatusCls(s){
  s=String(s||'').toLowerCase();
  if(s==='approved') return 'ok';
  if(s==='rejected') return 'bad';
  if(s==='changes_required') return 'warn';
  if(s==='resubmitted') return 'info';
  return 'pend';
}
function _mcCss(){
  if(document.getElementById('mc-css')) return;
  var s=document.createElement('style'); s.id='mc-css';
  s.textContent=[
    '.mc-row{display:flex;align-items:center;gap:14px;padding:16px 18px;border:1px solid var(--border);border-radius:16px;background:var(--card);margin-bottom:11px;cursor:pointer;transition:.16s;box-shadow:0 1px 2px rgba(15,23,42,.04)}',
    '.mc-row:hover{border-color:#d9b978;transform:translateY(-2px);box-shadow:0 10px 26px rgba(15,23,42,.08)}',
    'body.dark .mc-row{background:var(--card);border-color:var(--border)}',
    '.mc-ic{width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,rgba(184,148,31,.18),rgba(184,148,31,.06));display:flex;align-items:center;justify-content:center;color:#b8941f;flex-shrink:0}',
    '.mc-ttl{font-weight:800;font-size:1rem}',
    '.mc-meta{font-size:.76rem;color:#8a7d5c;margin-top:3px;display:flex;align-items:center;gap:6px;flex-wrap:wrap}',
    '.mc-chip{background:var(--hover);border-radius:999px;padding:2px 9px;font-size:.68rem;font-weight:700;color:#7a6a3f}',
    '.mc-del{color:#c1443a;flex-shrink:0}',
    '.mc-row{position:relative;overflow:hidden}',
    '.mc-row::before{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;background:#cbb781}',
    '.mc-acc-ok::before{background:linear-gradient(#34d399,#059669)}',
    '.mc-acc-bad::before{background:linear-gradient(#f87171,#dc2626)}',
    '.mc-acc-warn::before{background:linear-gradient(#fbbf24,#d97706)}',
    '.mc-acc-info::before{background:linear-gradient(#60a5fa,#2563eb)}',
    '.mc-acc-pend::before{background:linear-gradient(#cbd5e1,#94a3b8)}',
    '.mc-ic-ok{background:linear-gradient(135deg,rgba(5,150,105,.18),rgba(5,150,105,.05));color:#059669}',
    '.mc-ic-bad{background:linear-gradient(135deg,rgba(220,38,38,.16),rgba(220,38,38,.04));color:#dc2626}',
    '.mc-ic-warn{background:linear-gradient(135deg,rgba(217,119,6,.18),rgba(217,119,6,.05));color:#d97706}',
    '.mc-ic-info{background:linear-gradient(135deg,rgba(37,99,235,.16),rgba(37,99,235,.04));color:#2563eb}',
    '.mc-right{display:flex;align-items:center;gap:9px;flex-shrink:0}',
    '.mc-chev{color:var(--text-muted);opacity:.5;display:flex;flex-shrink:0}',
    '.mc-chev svg{width:18px;height:18px}',
    '.mc-row:hover .mc-chev{opacity:.9;transform:translateX(2px);transition:.15s}',
    '.mc-rev-head{display:flex;align-items:center;gap:14px;padding:14px 16px;margin-bottom:14px;border-radius:14px;background:linear-gradient(135deg,rgba(184,148,31,.12),rgba(184,148,31,.03));border:1px solid var(--border)}',
    '.mc-v{display:flex;align-items:center;gap:12px;padding:13px 15px;border:1px solid var(--border);border-radius:14px;margin-bottom:9px;background:var(--card)}',
    '.mc-v-ic{width:40px;height:40px;border-radius:11px;background:linear-gradient(135deg,rgba(37,99,235,.14),rgba(37,99,235,.04));display:flex;align-items:center;justify-content:center;color:#2563eb;flex-shrink:0}',
    '.mc-ver{font-family:ui-monospace,monospace;font-size:.72rem;color:#8a7d5c}',
    '.mc-v{display:flex;align-items:center;gap:10px;padding:10px 12px;border:1px solid var(--border);border-radius:10px;margin-bottom:7px}',
    '.mc-due{font-size:.7rem;font-weight:800;padding:2px 9px;border-radius:999px}',
    '.mc-due.ok{background:rgba(5,150,105,.14);color:#059669}.mc-due.soon{background:rgba(217,119,6,.16);color:#d97706}.mc-due.over{background:rgba(220,38,38,.15);color:#dc2626}'
  ].join('');
  document.head.appendChild(s);
}
function _dueBadge(deadline){
  if(!deadline) return '';
  var d=new Date(deadline.replace(' ','T')); if(isNaN(d)) return '';
  var days=Math.ceil((d-new Date())/86400000);
  var cls=days<0?'over':days<=2?'soon':'ok';
  var txt=days<0?('Overdue '+(-days)+'d'):days===0?'Due today':days===1?'Due tomorrow':('Due in '+days+'d');
  return '<span class="mc-due '+cls+'">'+txt+'</span>';
}

function loadTMatChecker(){
  var el=document.getElementById('t-matchecker-content'); if(!el) return;
  var a=window._tActiveCat; if(!a){ el.innerHTML=''; return; }
  _mcCss(); try{ softSpin(el); }catch(e){ el.innerHTML='<div class="spinner"></div>'; }
  api('/api/teacher/material-submissions?category_id='+a.id).then(function(r){
    var subs=(r&&r.submissions)||[];
    var head='<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:16px">'
      +'<div><div style="font-weight:800;font-size:1.05rem">Material Checker</div><div style="font-size:.84rem;color:#8a7d5c">'+esc(a.display_name)+' workspace</div></div>'
      +'<button class="btn btn-primary" onclick="mcOpenSubmit()">+ New Submission</button></div>';
    if(!subs.length){ el.innerHTML=head+'<div class="tcd-empty">No submissions yet. Use \u201cNew Submission\u201d to send your first material for review.</div>'; return; }
    var rows=subs.map(function(m){
      var stCls=_mcStatusCls(m.status);
      return '<div class="mc-row mc-acc-'+stCls+'" onclick="mcOpenDetail('+m.id+')">'
        +'<div class="mc-ic mc-ic-'+stCls+'">'+(typeof ic==='function'?ic('folder'):'')+'</div>'
        +'<div style="flex:1;min-width:0"><div class="mc-ttl">'+esc(m.title)+'</div>'
        +'<div class="mc-meta">'+(m.subject?'<span class="mc-chip">'+esc(m.subject)+'</span>':'')+'<span class="mc-chip">'+esc(_matTypeLabel(m.material_type))+'</span><span class="mc-ver">v'+(m.current_version||1)+'</span></div></div>'
        +'<div class="mc-right">'+_dueBadge(m.deadline)+_msPill(m.status)+'<span class="mc-chev">'+(typeof ic==='function'?ic('chevron-right'):'\u203a')+'</span></div></div>';
    }).join('');
    el.innerHTML=head+rows;
  }).catch(function(e){ el.innerHTML='<div style="padding:22px;color:#c1443a">'+esc((e&&e.message)||'Could not load')+'</div>'; });
}

function mcOpenSubmit(){
  var a=window._tActiveCat; if(!a) return;
  api('/api/teacher/subjects?category_id='+a.id).then(function(r){
    var subs=(r&&r.subjects)||[];
    var subOpts='<option value="">No specific subject</option>'+subs.map(function(s){return '<option value="'+s.id+'">'+esc(s.name)+'</option>';}).join('');
    var typeOpts=MAT_TYPES.map(function(t){return '<option value="'+t[0]+'">'+t[1]+'</option>';}).join('');
    var body='<div class="form-group"><label class="form-label">Title</label><input id="mcs-title" class="form-control" placeholder="e.g. Economics Unit 2 PPT"></div>'
      +'<div style="display:flex;gap:10px"><div class="form-group" style="flex:1"><label class="form-label">Subject</label><select id="mcs-subject" class="form-control">'+subOpts+'</select></div>'
      +'<div class="form-group" style="flex:1"><label class="form-label">Type</label><select id="mcs-type" class="form-control">'+typeOpts+'</select></div></div>'
      +'<div class="form-group"><label class="form-label">Description</label><textarea id="mcs-desc" class="form-control" rows="2" placeholder="What is this material?"></textarea></div>'
      +'<div class="form-group"><label class="form-label">Reference link (optional)</label><input id="mcs-ref" class="form-control" placeholder="Drive/source link"></div>'
      +'<div class="form-group"><label class="form-label">File</label><input id="mcs-file" type="file" class="form-control"></div>'
      +'<div id="mcs-status" style="font-size:.8rem"></div>';
    showModal('New Submission · '+esc(a.display_name), body,
      '<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-primary" id="mcs-btn" onclick="mcSubmit()">Submit for Review</button>');
  });
}
async function mcSubmit(){
  var a=window._tActiveCat; var f=document.getElementById('mcs-file');
  var title=(document.getElementById('mcs-title').value||'').trim();
  if(!f.files||!f.files[0]){ toast('Choose a file',true); return; }
  var file=f.files[0], origName=file.name||'material';
  if(!title) title=origName;
  var btn=document.getElementById('mcs-btn'), st=document.getElementById('mcs-status');
  btn.disabled=true;
  try{
    // Compress PDFs before upload (PPT/other types are sent as-is)
    if(file.type==='application/pdf' && typeof compressPdf==='function'){
      btn.textContent='Compressing…';
      try{ file=await compressPdf(file,function(m){ if(st) st.textContent=m; }); }catch(e){}
    }
    btn.textContent='Preparing…';
    var b64=await _fileB64(file);
    var payload={category_id:a.id,title:title,subject_id:document.getElementById('mcs-subject').value||'',
      material_type:document.getElementById('mcs-type').value,description:document.getElementById('mcs-desc').value||'',
      reference:document.getElementById('mcs-ref').value||'',file_b64:b64,filename:origName,
      mime:file.type||'application/octet-stream'};
    await _xhrJson('/api/teacher/material-submissions-json',payload,function(pc){
      btn.textContent='Uploading… '+pc+'%'; if(st) st.textContent='Uploading… '+pc+'%'; });
    closeModal(); toast('Submitted for review'); loadTMatChecker();
  }catch(e){ if(st) st.innerHTML='<span style="color:#c1443a">'+esc(e.message)+'</span>'; btn.disabled=false; btn.textContent='Submit for Review'; }
}

function mcOpenDetail(sid){
  showModal('Submission', '<div class="spinner"></div>', '');
  api('/api/teacher/material-submissions/'+sid).then(function(r){
    var m=r.submission; window._mcCur=m;
    var vers=(m.versions||[]).map(function(v){
      return '<div class="mc-v"><div style="flex:1"><b>Version '+v.version_no+'</b> <span class="mc-ver">'+esc(v.filename)+' · '+_fmtSize(v.file_size)+'</span>'
        +(v.remarks?'<div style="font-size:.78rem;color:#8a7d5c;margin-top:3px">'+esc(v.remarks)+'</div>':'')
        +'<div style="font-size:.7rem;color:#8a7d5c">'+esc(v.created_at)+'</div></div>'
        +'<button class="btn btn-ghost btn-sm" onclick="catDownloadVersion(\'teacher\','+v.id+',\''+esc((v.filename||'file').replace(/'/g,''))+'\')">Download</button></div>';
    }).join('');
    var canResub=(m.status!=='approved'&&m.status!=='rejected');
    var body='<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:8px"><div><div style="font-weight:800;font-size:1.05rem">'+esc(m.title)+'</div>'
      +'<div style="font-size:.78rem;color:#8a7d5c">'+(m.subject?esc(m.subject)+' · ':'')+esc(_matTypeLabel(m.material_type))+'</div></div>'+_msPill(m.status)+'</div>'
      +(m.deadline?'<div style="margin-bottom:8px">'+_dueBadge(m.deadline)+'</div>':'')
      +(m.description?'<div style="font-size:.85rem;margin-bottom:10px">'+esc(m.description)+'</div>':'')
      +'<div style="font-weight:700;font-size:.86rem;margin:10px 0 8px">Version history</div>'+vers;
    var footer='<button class="btn btn-ghost" onclick="closeModal()">Close</button>'
      +(canResub?'<button class="btn btn-primary" onclick="mcResubmitPrompt('+m.id+')">Upload New Version</button>':'');
    showModal('Submission · v'+(m.current_version||1), body, footer);
    document.getElementById('modal-body').insertAdjacentHTML('beforeend','<div id="mc-chat-host" style="margin-top:16px;border-top:1px solid var(--border,#e5ddcb);padding-top:14px"></div>');
    _mcLoadChat('teacher', m.id);
  }).catch(function(e){ document.getElementById('modal-body').innerHTML='<div style="color:#c1443a;padding:12px">'+esc((e&&e.message)||'Could not load')+'</div>'; });
}
function mcResubmitPrompt(sid){
  var body='<div class="form-group"><label class="form-label">New version file</label><input id="mcr-file" type="file" class="form-control"></div>'
    +'<div class="form-group"><label class="form-label">Note (optional)</label><textarea id="mcr-note" class="form-control" rows="2" placeholder="What changed?"></textarea></div><div id="mcr-status" style="font-size:.8rem"></div>';
  showModal('Upload New Version', body,
    '<button class="btn btn-ghost" onclick="mcOpenDetail('+sid+')">Back</button><button class="btn btn-primary" id="mcr-btn" onclick="mcResubmit('+sid+')">Upload</button>');
}
async function mcResubmit(sid){
  var f=document.getElementById('mcr-file'); if(!f.files||!f.files[0]){ toast('Choose a file',true); return; }
  var file=f.files[0], origName=file.name||'file';
  var btn=document.getElementById('mcr-btn'), st=document.getElementById('mcr-status'); btn.disabled=true;
  try{
    if(file.type==='application/pdf' && typeof compressPdf==='function'){
      btn.textContent='Compressing…';
      try{ file=await compressPdf(file,function(m){ if(st) st.textContent=m; }); }catch(e){}
    }
    btn.textContent='Preparing…';
    var b64=await _fileB64(file);
    await _xhrJson('/api/teacher/material-submissions/'+sid+'/resubmit-json',
      {file_b64:b64,filename:origName,mime:file.type||'application/octet-stream',remarks:document.getElementById('mcr-note').value||''},
      function(pc){ btn.textContent='Uploading… '+pc+'%'; if(st) st.textContent='Uploading… '+pc+'%'; });
    toast('New version uploaded'); mcOpenDetail(sid); loadTMatChecker();
  }catch(e){ document.getElementById('mcr-status').innerHTML='<span style="color:#c1443a">'+esc(e.message)+'</span>'; btn.disabled=false; btn.textContent='Upload'; }
}
async function catDownloadVersion(role, vid, name){
  var url=API+'/api/'+role+'/material-versions/'+vid+'/download';
  try{
    var r=await fetch(url,{headers:{Authorization:'Bearer '+TOKEN}});
    if(!r.ok) throw new Error('fail'); var blob=await r.blob(); if(!blob||!blob.size) throw new Error('empty');
    var u=URL.createObjectURL(blob);
    var a=document.createElement('a'); a.href=u; a.download=name||'file'; document.body.appendChild(a); a.click(); a.remove(); setTimeout(function(){URL.revokeObjectURL(u);},4000);
  }catch(e){
    // Bulletproof: server R2 tak na pahunche to browser se seedha (top-level nav, no CORS)
    try{ window.open(url+'?t='+encodeURIComponent(TOKEN),'_blank','noopener'); }
    catch(e2){ toast('Could not download',true); }
  }
}

/* ============================================================
   PHASE 12A — Material Checker (admin side)
   ============================================================ */
function initAdminMatCheck(){
  var app=document.getElementById('admin-app'); if(!app) return;
  var nav=app.querySelector('.sidebar-nav'); var main=app.querySelector('.main');
  if(nav && !nav.querySelector('[onclick*="matcheck"]')){
    var anchor=[].slice.call(nav.querySelectorAll('.nav-item')).filter(function(n){
      return (n.getAttribute('onclick')||'').indexOf("'categories'")>=0;})[0];
    var d=document.createElement('div'); d.className='nav-item'; d.setAttribute('onclick',"aPage('matcheck',this)");
    d.innerHTML=(typeof ic==='function'?ic('check'):'')+'<span>Material Checker</span>';
    if(anchor){ anchor.parentNode.insertBefore(d, anchor.nextSibling); } else { nav.appendChild(d); }
  }
  if(main && !document.getElementById('a-page-matcheck')){
    var pg=document.createElement('div'); pg.className='page'; pg.id='a-page-matcheck';
    pg.innerHTML='<div id="a-matcheck-content"><div class="spinner"></div></div>';
    main.appendChild(pg);
  }
}
window._amcFilter={category_id:0,status:''};
function loadAMatCheck(){
  var el=document.getElementById('a-matcheck-content'); if(!el) return;
  _mcCss(); try{ softSpin(el); }catch(e){ el.innerHTML='<div class="spinner"></div>'; }
  Promise.all([
    api('/api/admin/categories').catch(function(){return {categories:[]};}),
    api('/api/admin/material-submissions?category_id='+(_amcFilter.category_id||0)+'&status='+(_amcFilter.status||''))
  ]).then(function(res){
    var cats=(res[0].categories||[]); var subs=(res[1].submissions||[]);
    var catOpts='<option value="0">All categories</option>'+cats.map(function(c){return '<option value="'+c.id+'"'+(_amcFilter.category_id==c.id?' selected':'')+'>'+esc(c.display_name)+'</option>';}).join('');
    var stList=[['','All statuses'],['submitted','Submitted'],['under_review','Under Review'],['changes_required','Changes Required'],['resubmitted','Resubmitted'],['approved','Approved'],['rejected','Rejected']];
    var stOpts=stList.map(function(x){return '<option value="'+x[0]+'"'+(_amcFilter.status===x[0]?' selected':'')+'>'+x[1]+'</option>';}).join('');
    var head='<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:16px">'
      +'<div style="font-weight:800;font-size:1.15rem">Material Checker</div>'
      +'<div style="display:flex;gap:8px"><button class="btn btn-ghost btn-sm" onclick="checkR2Health()" title="Test file storage (uploads/downloads)">'+(typeof ic==='function'?ic('shield'):'')+' Check Storage</button><select class="form-control" style="width:auto" onchange="amcSetCat(this.value)">'+catOpts+'</select>'
      +'<select class="form-control" style="width:auto" onchange="amcSetStatus(this.value)">'+stOpts+'</select></div></div>';
    if(!subs.length){ el.innerHTML=head+'<div class="tcd-empty">No submissions match this filter.</div>'; return; }
    var rows=subs.map(function(m){
      return '<div class="mc-row" onclick="amcOpenDetail('+m.id+')">'
        +'<div class="mc-ic">'+(typeof ic==='function'?ic('folder'):'')+'</div>'
        +'<div style="flex:1;min-width:0"><div class="mc-ttl">'+esc(m.title)+'</div>'
        +'<div class="mc-meta">'+(m.teacher?'<span class="mc-chip">'+esc(m.teacher)+'</span>':'')+(m.subject?'<span class="mc-chip">'+esc(m.subject)+'</span>':'')+'<span class="mc-chip">'+esc(_matTypeLabel(m.material_type))+'</span><span class="mc-ver">v'+(m.current_version||1)+'</span></div></div>'
        +_dueBadge(m.deadline)+(m.priority==='high'?'<span style="font-size:.66rem;font-weight:800;color:#dc2626">HIGH</span>':'')+_msPill(m.status)
        +'<button class="btn btn-ghost btn-sm mc-del" title="Delete this submission" onclick="event.stopPropagation();amcDeleteSubmission('+m.id+',\''+esc((m.title||'').replace(/\x27/g,"")) +'\')">'+(typeof ic==='function'?ic('trash'):'Delete')+'</button></div>';
    }).join('');
    el.innerHTML=head+rows;
  }).catch(function(e){ el.innerHTML='<div style="padding:22px;color:#c1443a">'+esc((e&&e.message)||'Could not load')+'</div>'; });
}
function amcSetCat(v){ _amcFilter.category_id=parseInt(v,10)||0; loadAMatCheck(); }
function amcSetStatus(v){ _amcFilter.status=v||''; loadAMatCheck(); }
async function checkR2Health(){
  showModal('Storage Health','<div style="text-align:center;padding:26px"><div class="spinner"></div><div style="margin-top:10px;color:var(--text-muted)">Testing file storage…</div></div>');
  try{
    var h=await api('/api/admin/r2-health');
    var ok=function(b){return b?'<span style="color:#059669;font-weight:800">✔ Working</span>':'<span style="color:#c1443a;font-weight:800">✘ Failing</span>';};
    var verdict='', color='#059669', title='All good';
    if(!h.configured){ verdict='R2 storage configured nahi hai (env vars missing).'; color='#c1443a'; title='Not configured'; }
    else if(!h.upload){ verdict='Upload hi fail ho raha hai — R2 credentials (Access Key / Secret) galat hain. Cloudflare mein sahi keys daalo.'; color='#c1443a'; title='Credentials issue'; }
    else if(!h.auth_read){ verdict='Upload chalta hai par READ fail hai — aapka R2 API token <b>write-only</b> hai. Cloudflare → R2 → Manage API Tokens → token ko <b>"Object Read & Write"</b> permission do. Bas yahi fix karna hai — downloads turant theek ho jayenge.'; color='#c1443a'; title='Token is write-only'; }
    else { verdict='Storage bilkul theek hai — authenticated read chal raha hai. Downloads ab kaam karenge.'; color='#059669'; title='Storage OK'; }
    var body='<div style="border:1px solid var(--border);border-radius:12px;overflow:hidden;margin-bottom:14px">'
      +'<div style="display:flex;justify-content:space-between;padding:11px 14px;border-bottom:1px solid var(--border)"><span>Configured</span>'+ok(h.configured)+'</div>'
      +'<div style="display:flex;justify-content:space-between;padding:11px 14px;border-bottom:1px solid var(--border)"><span>Upload (write)</span>'+ok(h.upload)+'</div>'
      +'<div style="display:flex;justify-content:space-between;padding:11px 14px;border-bottom:1px solid var(--border)"><span>Authenticated read <span style="font-size:.7rem;color:var(--text-muted)">(downloads use this)</span></span>'+ok(h.auth_read)+'</div>'
      +'<div style="display:flex;justify-content:space-between;padding:11px 14px"><span>Public read</span>'+ok(h.public_read)+'</div></div>'
      +'<div style="background:'+(color==='#059669'?'#e9f8ee':'#fdecea')+';border-radius:12px;padding:14px 16px"><div style="font-weight:800;color:'+color+';margin-bottom:5px">'+title+'</div><div style="font-size:.88rem;line-height:1.55">'+verdict+'</div></div>'
      +(h.detail?'<div style="font-size:.72rem;color:var(--text-muted);margin-top:8px">Debug: '+esc(h.detail)+'</div>':'');
    showModal('Storage Health',body,'<button class="btn btn-primary" onclick="closeModal()">OK</button>');
  }catch(e){ showModal('Storage Health','<div style="padding:16px;color:#c1443a">Could not run the check: '+esc(e.message||'')+'</div>','<button class="btn btn-ghost" onclick="closeModal()">Close</button>'); }
}
async function amcDeleteSubmission(sid, title){
  if(!confirm('Delete this submission'+(title?' "'+title+'"':'')+' permanently? This removes all its versions and messages.')) return;
  try{
    await api('/api/admin/material-submissions/'+sid+'/delete','POST',{});
    toast('Submission deleted.'); loadAMatCheck();
  }catch(e){ toast(e.message||'Could not delete',true); }
}

function amcOpenDetail(sid){
  showModal('Review', '<div class="spinner"></div>', '');
  api('/api/admin/material-submissions/'+sid).then(function(r){
    var m=r.submission; window._amcCur=m;
    var vers=(m.versions||[]).map(function(v){
      return '<div class="mc-v"><div class="mc-v-ic">'+(typeof ic==='function'?ic('clipboard'):'')+'</div><div style="flex:1;min-width:0"><b>Version '+v.version_no+'</b> <span class="mc-ver">'+esc(v.filename)+' · '+_fmtSize(v.file_size)+'</span>'
        +(v.remarks?'<div style="font-size:.78rem;color:#8a7d5c;margin-top:3px">'+esc(v.remarks)+'</div>':'')
        +'<div style="font-size:.7rem;color:#8a7d5c;margin-top:2px">'+esc(v.created_at)+'</div></div>'
        +'<button class="btn btn-primary btn-sm" onclick="catDownloadVersion(\'admin\','+v.id+',\''+esc((v.filename||'file').replace(/'/g,''))+'\')">'+(typeof ic==='function'?ic('download'):'')+' Download</button></div>';
    }).join('');
    var dl=m.deadline?m.deadline.replace(' ','T').slice(0,16):'';
    var body='<div class="mc-rev-head"><div class="mc-ic" style="width:48px;height:48px">'+(typeof ic==='function'?ic('folder'):'')+'</div>'
      +'<div style="flex:1;min-width:0"><div style="font-weight:800;font-size:1.15rem">'+esc(m.title)+'</div>'
      +'<div class="mc-meta" style="margin-top:4px">'+(m.teacher?'<span class="mc-chip">'+esc(m.teacher)+'</span>':'')+(m.subject?'<span class="mc-chip">'+esc(m.subject)+'</span>':'')+'<span class="mc-chip">'+esc(_matTypeLabel(m.material_type))+'</span></div></div>'+_msPill(m.status)+'</div>'
      +(m.description?'<div style="font-size:.85rem;margin:6px 0 10px">'+esc(m.description)+'</div>':'')
      +(m.reference?'<div style="font-size:.8rem;margin-bottom:10px">Reference: <a href="'+esc(m.reference)+'" target="_blank" rel="noopener" style="color:#2563eb">'+esc(m.reference)+'</a></div>':'')
      +'<div style="font-weight:700;font-size:.86rem;margin:10px 0 8px">Version history</div>'+vers
      +'<div style="border-top:1px solid var(--border,#e5ddcb);margin-top:12px;padding-top:12px"><div style="font-weight:700;font-size:.86rem;margin-bottom:8px">Review</div>'
      +'<textarea id="amc-remarks" class="form-control" rows="2" placeholder="Remarks to the teacher (optional)"></textarea>'
      +'<div style="display:flex;gap:10px;margin-top:8px;flex-wrap:wrap"><div style="flex:1"><label class="form-label">Deadline</label><input id="amc-deadline" type="datetime-local" class="form-control" value="'+dl+'"></div>'
      +'<div style="width:130px"><label class="form-label">Priority</label><select id="amc-priority" class="form-control"><option value="low"'+(m.priority==='low'?' selected':'')+'>Low</option><option value="normal"'+(m.priority==='normal'?' selected':'')+'>Normal</option><option value="high"'+(m.priority==='high'?' selected':'')+'>High</option></select></div></div></div>';
    var footer='<button class="btn btn-ghost" onclick="closeModal()">Close</button>'
      +'<button class="btn btn-ghost" style="color:#7c3aed" onclick="amcReview('+sid+',\'under_review\')">Under Review</button>'
      +'<button class="btn btn-ghost" style="color:#d97706" onclick="amcReview('+sid+',\'changes_required\')">Changes Required</button>'
      +'<button class="btn btn-danger" onclick="amcReview('+sid+',\'rejected\')">Reject</button>'
      +'<button class="btn btn-primary" onclick="amcReview('+sid+',\'approved\')">Approve</button>';
    showModal('Review · v'+(m.current_version||1), body, footer);
    document.getElementById('modal-body').insertAdjacentHTML('beforeend','<div id="mc-chat-host" style="margin-top:16px;border-top:1px solid var(--border,#e5ddcb);padding-top:14px"></div>');
    _mcLoadChat('admin', sid);
  }).catch(function(e){ document.getElementById('modal-body').innerHTML='<div style="color:#c1443a;padding:12px">'+esc((e&&e.message)||'Could not load')+'</div>'; });
}
async function amcReview(sid, decision){
  var payload={decision:decision,
    remarks:(document.getElementById('amc-remarks')||{}).value||'',
    deadline:(document.getElementById('amc-deadline')||{}).value||'',
    priority:(document.getElementById('amc-priority')||{}).value||'normal'};
  try{ await api('/api/admin/material-submissions/'+sid+'/review','POST',payload);
    closeModal(); toast('Review saved'); loadAMatCheck();
  }catch(e){ toast((e&&e.message)||'Could not save',true); }
}

/* ============================================================
   PHASE 12B — Material Checker review chat (teacher + admin)
   ============================================================ */
function _mcChatCss(){
  if(document.getElementById('mcchat-css')) return;
  var s=document.createElement('style'); s.id='mcchat-css';
  s.textContent=[
    '.mc-chat-msgs{max-height:34vh;overflow:auto;display:flex;flex-direction:column;gap:10px;padding:4px 2px;margin-bottom:10px}',
    '.mc-b{max-width:80%;padding:9px 12px;border-radius:14px;font-size:.86rem;line-height:1.35;word-break:break-word}',
    '.mc-b .who{font-size:.66rem;font-weight:800;text-transform:uppercase;letter-spacing:.04em;opacity:.7;margin-bottom:3px}',
    '.mc-b .at{font-size:.64rem;opacity:.6;margin-top:4px}',
    '.mc-b.them{align-self:flex-start;background:var(--card);border:1px solid var(--border)}',
    'body.dark .mc-b.them{background:var(--card);border-color:var(--border)}',
    '.mc-b.me{align-self:flex-end;background:linear-gradient(135deg,#e6ad4e,#c98a2e);color:#241a05}',
    '.mc-b img.att{max-width:210px;border-radius:10px;margin-top:6px;display:block;cursor:pointer}',
    '.mc-b a.att{display:inline-block;margin-top:6px;font-size:.78rem;font-weight:700;text-decoration:underline;cursor:pointer}',
    '.mc-comp{border:1px solid var(--border);border-radius:12px;padding:10px;background:var(--card)}',
    'body.dark .mc-comp{background:var(--card);border-color:var(--border)}',
    '.mc-comp.drag{border-color:#b8941f;background:rgba(184,148,31,.08)}',
    '.mc-pend{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:6px}',
    '.mc-chip{position:relative;border:1px solid var(--border);border-radius:8px;padding:5px 9px;font-size:.74rem;display:flex;align-items:center;gap:6px}',
    '.mc-chip img{width:34px;height:34px;object-fit:cover;border-radius:5px}',
    '.mc-chip .x{cursor:pointer;font-weight:800;color:#c1443a}'
  ].join('');
  document.head.appendChild(s);
}
function _mcChatHostHtml(role, sid){
  return '<div style="font-weight:700;font-size:.86rem;margin:6px 0 8px">Conversation</div>'
    +'<div id="mc-chat-msgs" class="mc-chat-msgs"><div class="spinner"></div></div>'
    +'<div class="mc-comp" id="mc-comp">'
      +'<div id="mc-pend" class="mc-pend"></div>'
      +'<textarea id="mc-input" class="form-control" rows="2" placeholder="Write a message\u2026 (paste or drop an image)"></textarea>'
      +'<div style="display:flex;justify-content:space-between;align-items:center;margin-top:6px">'
        +'<label class="btn btn-ghost btn-sm" style="cursor:pointer;margin:0">Attach<input id="mc-file" type="file" multiple accept="image/*,application/pdf" style="display:none" onchange="_mcPickFiles(this.files)"></label>'
        +'<button class="btn btn-primary btn-sm" id="mc-send" onclick="mcChatSend(\''+role+'\','+sid+')">Send</button>'
      +'</div></div>';
}
function _mcLoadChat(role, sid){
  _mcChatCss();
  var host=document.getElementById('mc-chat-host'); if(!host) return;
  host.innerHTML=_mcChatHostHtml(role, sid);
  window._mcChatPend=[];
  var comp=document.getElementById('mc-comp'), input=document.getElementById('mc-input');
  if(input){ input.addEventListener('paste', function(e){
    var items=((e.clipboardData||{}).items)||[]; var got=false;
    for(var i=0;i<items.length;i++){ if((items[i].type||'').indexOf('image')===0){ var f=items[i].getAsFile(); if(f){ _mcAddPend(f); got=true; } } }
    if(got) e.preventDefault();
  }); }
  if(comp){
    comp.addEventListener('dragover', function(e){ e.preventDefault(); comp.classList.add('drag'); });
    comp.addEventListener('dragleave', function(){ comp.classList.remove('drag'); });
    comp.addEventListener('drop', function(e){ e.preventDefault(); comp.classList.remove('drag'); var fs=((e.dataTransfer||{}).files)||[]; for(var i=0;i<fs.length;i++) _mcAddPend(fs[i]); });
  }
  api('/api/'+role+'/material-submissions/'+sid+'/messages').then(function(r){ _mcRenderMsgs(role,(r&&r.messages)||[]); })
    .catch(function(e){ var el=document.getElementById('mc-chat-msgs'); if(el) el.innerHTML='<div style="color:#c1443a;font-size:.82rem">'+esc((e&&e.message)||'Could not load chat')+'</div>'; });
}
function _mcRenderMsgs(role, msgs){
  var el=document.getElementById('mc-chat-msgs'); if(!el) return;
  if(!msgs.length){ el.innerHTML='<div style="color:#9c8f6e;font-size:.82rem;padding:6px">No messages yet. Start the conversation below.</div>'; return; }
  var imgJobs=[];
  el.innerHTML=msgs.map(function(m){
    var mine=(m.sender_role===role);
    var atts=(m.attachments||[]).map(function(a){
      if(a.is_image){ var id='mcimg-'+a.id; imgJobs.push([id, role, a.id]); return '<img id="'+id+'" class="att" alt="'+esc(a.filename)+'" onclick="_mcAttDownload(\''+role+'\','+a.id+',\''+esc((a.filename||'image').replace(/'/g,''))+'\')">'; }
      return '<a class="att" onclick="_mcAttDownload(\''+role+'\','+a.id+',\''+esc((a.filename||'file').replace(/'/g,''))+'\')">\u2193 '+esc(a.filename)+'</a>';
    }).join('');
    return '<div class="mc-b '+(mine?'me':'them')+'"><div class="who">'+esc(m.sender_role==='admin'?'Admin':'Teacher')+'</div>'
      +(m.message?esc(m.message).replace(/\n/g,'<br>'):'')+atts+'<div class="at">'+esc(m.at)+'</div></div>';
  }).join('');
  el.scrollTop=el.scrollHeight;
  imgJobs.forEach(function(j){ _mcLoadImg(j[0], '/api/'+j[1]+'/material-attachments/'+j[2]+'/view'); });
}
async function _mcLoadImg(imgId, url){
  try{ var r=await fetch(API+url,{headers:{Authorization:'Bearer '+TOKEN}}); if(!r.ok) return;
    var u=URL.createObjectURL(await r.blob()); var im=document.getElementById(imgId); if(im) im.src=u;
  }catch(e){}
}
function _mcPickFiles(files){ for(var i=0;i<files.length;i++) _mcAddPend(files[i]); }
function _mcAddPend(file){
  if(!file) return; window._mcChatPend=window._mcChatPend||[];
  var entry={file:file, url:''};
  if((file.type||'').indexOf('image')===0){ entry.url=URL.createObjectURL(file); }
  window._mcChatPend.push(entry); _mcRenderPend();
}
function _mcRenderPend(){
  var el=document.getElementById('mc-pend'); if(!el) return;
  el.innerHTML=(window._mcChatPend||[]).map(function(p,i){
    return '<span class="mc-chip">'+(p.url?'<img src="'+p.url+'">':'\uD83D\uDCCE ')+esc(p.file.name||'file')+' <span class="x" onclick="_mcRemovePend('+i+')">\u00d7</span></span>';
  }).join('');
}
function _mcRemovePend(i){ (window._mcChatPend||[]).splice(i,1); _mcRenderPend(); }
async function mcChatSend(role, sid){
  var input=document.getElementById('mc-input'); var txt=(input&&input.value||'').trim();
  var pend=window._mcChatPend||[];
  if(!txt && !pend.length){ toast('Type a message or attach a file',true); return; }
  var btn=document.getElementById('mc-send'); if(btn){ btn.disabled=true; btn.textContent='Sending...'; }
  try{
    var fd=new FormData(); fd.append('message', txt);
    pend.forEach(function(p){ fd.append('files', p.file, p.file.name||'file'); });
    var r=await fetch(API+'/api/'+role+'/material-submissions/'+sid+'/messages',{method:'POST',headers:{Authorization:'Bearer '+TOKEN},body:fd});
    if(!r.ok){ var d=null; try{d=await r.json();}catch(e){} throw new Error((d&&d.detail)||'Send failed'); }
    if(input) input.value=''; window._mcChatPend=[]; _mcRenderPend();
    api('/api/'+role+'/material-submissions/'+sid+'/messages').then(function(rr){ _mcRenderMsgs(role,(rr&&rr.messages)||[]); });
  }catch(e){ toast(e.message||'Could not send',true); }
  finally{ if(btn){ btn.disabled=false; btn.textContent='Send'; } }
}
async function _mcAttDownload(role, aid, name){
  try{ var r=await fetch(API+'/api/'+role+'/material-attachments/'+aid+'/download',{headers:{Authorization:'Bearer '+TOKEN}});
    if(!r.ok) throw new Error('fail'); var u=URL.createObjectURL(await r.blob());
    var a=document.createElement('a'); a.href=u; a.download=name||'file'; document.body.appendChild(a); a.click(); a.remove(); setTimeout(function(){URL.revokeObjectURL(u);},4000);
  }catch(e){ toast('Could not download',true); }
}

/* ============================================================
   PHASE 13 — Category performance (teacher). NIOS performance untouched:
   this only runs for non-NIOS workspaces.
   ============================================================ */
function loadTCatPerformance(){
  var el=document.getElementById('t-performance-content'); if(!el) return;
  var a=window._tActiveCat; if(!a){ if(typeof loadTPerformance==='function') loadTPerformance(); return; }
  try{ softSpin(el); }catch(e){ el.innerHTML='<div class="spinner"></div>'; }
  api('/api/teacher/category-performance?category_id='+a.id).then(function(d){
    var t=d.totals||{}; var rate=d.approval_rate||0;
    var ring='conic-gradient(#059669 '+(rate*3.6)+'deg,rgba(120,113,108,.18) 0)';
    var hero='<div class="tcd-hero" style="display:flex;align-items:center;gap:22px;flex-wrap:wrap">'
      +'<div style="width:104px;height:104px;border-radius:50%;background:'+ring+';display:flex;align-items:center;justify-content:center">'
        +'<div style="width:80px;height:80px;border-radius:50%;background:var(--bg,#fff);display:flex;flex-direction:column;align-items:center;justify-content:center"><b style="font-size:1.4rem;color:#059669">'+rate+'%</b><span style="font-size:.6rem;color:#8a7d5c;text-transform:uppercase">Approval</span></div></div>'
      +'<div><h2 style="margin:0;font-size:1.3rem;font-weight:800">'+esc(a.display_name)+' Performance</h2>'
        +'<p style="margin:4px 0 0;color:#8a7d5c;font-weight:600">'+(t.total||0)+' materials submitted \u00b7 '+(t.approved||0)+' approved</p></div></div>';
    var kpis='<div class="tcd-kpis">'
      +'<div class="tcd-kpi appr"><b>'+(t.approved||0)+'</b><span>Approved</span></div>'
      +'<div class="tcd-kpi pend"><b>'+(t.in_review||0)+'</b><span>In Review</span></div>'
      +'<div class="tcd-kpi mat"><b>'+(t.total||0)+'</b><span>Total</span></div>'
      +'<div class="tcd-kpi tasks"><b>'+(t.changes||0)+'</b><span>Changes Asked</span></div>'
      +'</div>';
    var subs=d.subjects||[];
    var subHtml='';
    if(subs.length){
      subHtml='<div class="tcd-sec">By Subject</div><div style="display:flex;flex-direction:column;gap:9px">'
        +subs.map(function(s){
          var pct=s.total?Math.round((s.approved||0)*100/s.total):0;
          return '<div style="border:1px solid var(--border,#e5ddcb);border-radius:12px;padding:12px 14px">'
            +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px"><div style="font-weight:700">'+esc(s.name)+'</div><div style="font-size:.78rem;color:#8a7d5c">'+(s.approved||0)+'/'+(s.total||0)+' approved</div></div>'
            +'<div style="height:8px;border-radius:999px;background:rgba(120,113,108,.16);overflow:hidden"><div style="height:100%;width:'+pct+'%;background:#059669"></div></div></div>';
        }).join('')+'</div>';
    }
    el.innerHTML=hero+kpis+subHtml;
  }).catch(function(e){ el.innerHTML='<div style="padding:22px;color:#c1443a">'+esc((e&&e.message)||'Could not load performance')+'</div>'; });
}

/* ============================================================
   PHASE 14 — Category-aware payout (additive; NIOS payroll untouched)
   ============================================================ */
var WT_UNITS=[['per_item','Per item'],['per_hour','Per hour'],['fixed','Fixed']];
function _wtUnit(u){ var f=WT_UNITS.filter(function(x){return x[0]===u;})[0]; return f?f[1]:u; }

/* ---- Admin: work types + effective-dated rates ---- */
function catOpenPayRates(cid){
  var c=_catById(cid);
  showModal('Pay Rates · '+(c?c.display_name:''), '<div class="spinner"></div>', '');
  _catLoadPayRates(cid);
}
function _catLoadPayRates(cid){
  api('/api/admin/categories/'+cid+'/work-types').then(function(r){
    window._catWtState={cid:cid, wts:(r.work_types||[])};
    _renderCatPayRates();
  }).catch(function(e){ document.getElementById('modal-body').innerHTML='<div style="color:#c1443a;padding:12px">'+esc((e&&e.message)||'Could not load')+'</div>'; });
}
function _renderCatPayRates(){
  var st=window._catWtState||{wts:[]};
  var rows=st.wts.map(function(w){
    var hist=(w.rates||[]).slice(0,4).map(function(r){return '<span style="font-size:.72rem;color:#8a7d5c">\u20b9'+r.amount+' from '+esc(r.effective_from)+'</span>';}).join(' · ');
    return '<div style="border:1px solid var(--border,#e5ddcb);border-radius:12px;padding:12px 14px;margin-bottom:9px'+(w.is_active?'':';opacity:.55')+'">'
      +'<div style="display:flex;align-items:center;gap:10px"><div style="flex:1"><div style="font-weight:700">'+esc(w.label)
        +' <span style="font-size:.66rem;color:#8a7d5c;background:rgba(230,173,78,.14);padding:2px 8px;border-radius:999px">'+esc(_wtUnit(w.unit))+'</span>'
        +(w.source==='auto_material'?' <span style="font-size:.62rem;font-weight:800;color:#059669">AUTO</span>':'')+'</div>'
        +'<div style="font-size:.78rem;color:#8a7d5c;margin-top:2px">Current: <b>\u20b9'+(w.current_rate||0)+'</b>'+(hist?' · '+hist:'')+'</div></div>'
      +'<button class="btn btn-ghost btn-sm" onclick="catRateAdd('+w.id+')">New Rate</button>'
      +'<button class="btn btn-ghost btn-sm" onclick="catWtToggle('+w.id+','+(w.is_active?0:1)+')">'+(w.is_active?'Disable':'Enable')+'</button></div></div>';
  }).join('') || '<div style="color:#9c8f6e;padding:8px 0">No work types yet.</div>';
  var typeUnit=WT_UNITS.map(function(u){return '<option value="'+u[0]+'">'+u[1]+'</option>';}).join('');
  var add='<div style="border-top:1px solid var(--border,#e5ddcb);margin-top:12px;padding-top:12px"><div style="font-weight:700;font-size:.86rem;margin-bottom:8px">Add work type</div>'
    +'<div style="display:flex;gap:8px;flex-wrap:wrap"><input id="cwt-label" class="form-control" style="flex:2;min-width:150px" placeholder="e.g. Approved Material">'
    +'<select id="cwt-unit" class="form-control" style="flex:1;min-width:110px">'+typeUnit+'</select>'
    +'<select id="cwt-source" class="form-control" style="flex:1;min-width:150px"><option value="manual">Manual count</option><option value="auto_material">Auto: approved materials</option></select>'
    +'<button class="btn btn-primary" onclick="catWtAdd()">Add</button></div>'
    +'<div style="font-size:.74rem;color:#8a7d5c;margin-top:6px">\u201cAuto: approved materials\u201d counts each approved Material Checker submission automatically. Set a rate after adding.</div></div>';
  document.getElementById('modal-body').innerHTML='<div class="catf-list" style="max-height:42vh">'+rows+'</div>'+add;
  document.getElementById('modal-footer').innerHTML='<button class="btn btn-ghost" onclick="closeModal()">Close</button>';
}
async function catWtAdd(){
  var st=window._catWtState; var label=(document.getElementById('cwt-label').value||'').trim();
  if(!label){ toast('Work type label required',true); return; }
  try{ await api('/api/admin/categories/'+st.cid+'/work-types','POST',{label:label,unit:document.getElementById('cwt-unit').value,source:document.getElementById('cwt-source').value});
    _catLoadPayRates(st.cid);
  }catch(e){ toast((e&&e.message)||'Could not add',true); }
}
async function catWtToggle(wid,to){
  var st=window._catWtState;
  try{ await api('/api/admin/work-types/'+wid,'PATCH',{is_active:(to==1||to==='1')}); _catLoadPayRates(st.cid); }
  catch(e){ toast((e&&e.message)||'Could not update',true); }
}
function catRateAdd(wid){
  var today=new Date().toISOString().slice(0,10);
  var body='<div class="form-group"><label class="form-label">Rate (\u20b9 per unit)</label><input id="cr-amt" type="number" class="form-control" placeholder="e.g. 150"></div>'
    +'<div class="form-group"><label class="form-label">Effective from</label><input id="cr-eff" type="date" class="form-control" value="'+today+'"></div>'
    +'<div class="form-group"><label class="form-label">Note (optional)</label><input id="cr-note" class="form-control" placeholder="e.g. revised rate"></div>'
    +'<div style="font-size:.76rem;color:#8a7d5c">Older months keep their old rate — this only applies from the effective date onward.</div>';
  showModal('New Rate', body, '<button class="btn btn-ghost" onclick="_catLoadPayRates('+(window._catWtState.cid)+');document.getElementById(\'modal-title\').textContent=\'Pay Rates\'">Back</button><button class="btn btn-primary" onclick="catRateSave('+wid+')">Save Rate</button>');
}
async function catRateSave(wid){
  var st=window._catWtState; var amt=document.getElementById('cr-amt').value;
  if(amt===''||isNaN(parseFloat(amt))){ toast('Enter a valid amount',true); return; }
  try{ await api('/api/admin/work-types/'+wid+'/rates','POST',{amount:parseFloat(amt),effective_from:document.getElementById('cr-eff').value,note:document.getElementById('cr-note').value||''});
    toast('Rate saved'); catOpenPayRates(st.cid);
  }catch(e){ toast((e&&e.message)||'Could not save',true); }
}

/* ---- Teacher: category earnings (read-only estimate) ---- */
function loadTCatEarnings(){
  var el=document.getElementById('t-payout-content'); if(!el) return;
  var a=window._tActiveCat; if(!a){ if(typeof payoutGate==='function') payoutGate(); return; }
  try{ softSpin(el); }catch(e){ el.innerHTML='<div class="spinner"></div>'; }
  api('/api/teacher/payout/status').then(function(st){
    if(st && st.payout_mode==='contract'){ if(typeof payoutGate==='function') payoutGate(); return; }
    _catEarningsEstimate(a, el);
  }).catch(function(){ _catEarningsEstimate(a, el); });
}
function _catEarningsEstimate(a, el){
  api('/api/teacher/category-earnings?category_id='+a.id).then(function(d){
    var lines=(d.lines||[]);
    var rowHtml=lines.length?lines.map(function(l){
      return '<div style="display:flex;align-items:center;gap:12px;padding:12px 14px;border:1px solid var(--border,#e5ddcb);border-radius:12px;margin-bottom:8px">'
        +'<div style="flex:1"><div style="font-weight:700">'+esc(l.work_type)+(l.auto?' <span style="font-size:.62rem;font-weight:800;color:#059669">AUTO</span>':'')+'</div>'
        +'<div style="font-size:.76rem;color:#8a7d5c">'+l.units+' \u00d7 \u20b9'+l.rate+' '+esc(_wtUnit(l.unit))+'</div></div>'
        +'<div style="font-weight:800;font-size:1.05rem">\u20b9'+l.amount+'</div></div>';
    }).join(''):'<div class="tcd-empty">No payable work types set for this workspace yet.</div>';
    el.innerHTML='<div class="tcd-hero" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px"><div><h2 style="margin:0;font-size:1.3rem;font-weight:800">'+esc(a.display_name)+' Earnings</h2>'
      +'<p style="margin:4px 0 0;color:#8a7d5c;font-weight:600">'+esc(d.month||'')+' \u00b7 estimated</p></div>'
      +'<div style="text-align:right"><div style="font-size:1.8rem;font-weight:800;color:#059669">\u20b9'+(d.total||0)+'</div><div style="font-size:.7rem;color:#8a7d5c;text-transform:uppercase">This Month (est.)</div></div></div>'
      +rowHtml
      +'<div style="font-size:.78rem;color:#8a7d5c;margin-top:12px;padding:12px;border:1px dashed var(--border,#cbb98f);border-radius:10px">'+esc(d.note||'')+'</div>';
  }).catch(function(e){ el.innerHTML='<div style="padding:22px;color:#c1443a">'+esc((e&&e.message)||'Could not load earnings')+'</div>'; });
}

/* ============================================================
   PHASE 15-16 — Category screens: responsive + theme polish
   ============================================================ */
(function _catInjectResponsive(){
  function inject(){
    if(document.getElementById('cat-responsive-css')) return;
    var s=document.createElement('style'); s.id='cat-responsive-css';
    s.textContent=[
      /* muted text + surfaces follow the app theme in both modes */
      '#a-page-categories,#a-page-matcheck{color:var(--text)}',
      /* smooth hover only on devices that support it */
      '@media (hover:none){.cat-card:hover,.tmsub-card:hover,.mc-row:hover{transform:none}}',
      /* narrow screens */
      '@media (max-width:640px){',
      '  .tcd-kpis{grid-template-columns:repeat(2,1fr)}',
      '  .cat-grid,.tmsub-grid{grid-template-columns:1fr}',
      '  .tcd-hero{padding:16px 16px}',
      '  .tcd-hero h2{font-size:1.2rem}',
      '  .mc-b{max-width:92%}',
      '  .mc-chat-msgs{max-height:42vh}',
      '  #t-wsswitch .tws-menu{min-width:170px}',
      '  #a-page-categories .cat-acts .cat-btn{min-width:calc(50% - 4px)}',
      '  .mc-row{flex-wrap:wrap}',
      '}',
      '@media (max-width:420px){',
      '  .tcd-kpis{grid-template-columns:1fr}',
      '  .cat-stats,.tmsub-stats{gap:6px}',
      '}'
    ].join('\n');
    document.head.appendChild(s);
  }
  if(document.head){ inject(); }
  else { document.addEventListener('DOMContentLoaded', inject); }
})();

/* ============================================================
   COMPLAINTS & FEEDBACK — Student UI (Phase 4)
   Injected into #student-app, same pattern as existing pages.
   ============================================================ */
function _supCss(){
  if(document.getElementById('sup-css')) return;
  var s=document.createElement('style'); s.id='sup-css';
  s.textContent=[
    '.sup-top{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:16px}',
    '.sup-list{display:flex;flex-direction:column;gap:10px;max-height:calc(100vh - 240px);overflow:auto;padding:2px}',
    '.sup-card{border:1px solid var(--border);border-radius:14px;padding:15px 16px;background:var(--card);cursor:pointer;transition:.14s}',
    '.sup-card:hover{border-color:#d9b978;transform:translateY(-1px);box-shadow:0 8px 22px rgba(15,23,42,.06)}',
    '.sup-num{font-family:ui-monospace,monospace;font-size:.72rem;color:var(--text-muted)}',
    '.sup-ttl{font-weight:700;margin-top:2px}',
    '.sup-meta{font-size:.75rem;color:var(--text-muted);margin-top:4px}',
    '.sup-pill{font-size:.66rem;font-weight:800;padding:4px 11px;border-radius:999px;color:#fff;white-space:nowrap;align-self:flex-start;flex-shrink:0;display:inline-block;line-height:1.35;height:fit-content}',
    '.af-new-pill{font-size:.6rem;font-weight:800;color:#fff;background:#dc2626;padding:2px 7px;border-radius:999px;letter-spacing:.05em;display:inline-block;animation:afNewBlink 1s ease-in-out infinite;box-shadow:0 0 0 0 rgba(220,38,38,.5)}',
    '@keyframes afNewBlink{0%,100%{opacity:1;box-shadow:0 0 0 0 rgba(220,38,38,.45)}50%{opacity:.35;box-shadow:0 0 0 5px rgba(220,38,38,0)}}',
    '.sup-dot{width:8px;height:8px;border-radius:50%;background:#dc2626;display:inline-block;margin-left:6px}',
    '.sup-empty{border:1px dashed var(--border);border-radius:14px;padding:28px;text-align:center;color:var(--text-muted)}',
    '.sup-thread{display:flex;flex-direction:column;gap:10px;max-height:44vh;overflow:auto;margin:6px 0 12px}',
    '.sup-b{max-width:82%;padding:10px 13px;border-radius:14px;font-size:.88rem;line-height:1.4;word-break:break-word}',
    '.sup-b .who{font-size:.64rem;font-weight:800;text-transform:uppercase;opacity:.7;margin-bottom:3px}',
    '.sup-b.them{align-self:flex-start;background:var(--card);border:1px solid var(--border)}',
    '.sup-b.me{align-self:flex-end;background:linear-gradient(135deg,#e6ad4e,#c98a2e);color:#241a05}',
    '.sup-b img.att{max-width:190px;border-radius:9px;margin-top:6px;display:block;cursor:pointer}',
    '.sup-att-row{display:flex;flex-wrap:wrap;gap:8px;margin:6px 0}',
    '.sup-att-chip{position:relative;border:1px solid var(--border);border-radius:8px;overflow:hidden;width:60px;height:60px}',
    '.sup-att-chip img{width:100%;height:100%;object-fit:cover}',
    '.sup-att-chip .x{position:absolute;top:2px;right:2px;background:rgba(0,0,0,.6);color:#fff;border-radius:50%;width:18px;height:18px;display:flex;align-items:center;justify-content:center;cursor:pointer;font-size:.8rem}',
    '.sup-stars{display:flex;gap:8px;font-size:2.2rem;cursor:pointer;justify-content:center;margin:10px 0}',
    '.sup-star{color:#d9c9a0;transition:.1s}.sup-star.on{color:#e6ad4e}',
    '.sup-star:focus{outline:2px solid #b8941f;border-radius:6px}'
  ].join('');
  document.head.appendChild(s);
  try{ _supPolishCss(); }catch(e){}
}
var SUP_ST={open:['Open','#2563eb'],assigned:['Assigned','#7c3aed'],in_progress:['In Progress','#0891b2'],waiting_student:['Waiting For You','#d97706'],resolved:['Resolved','#059669'],reopened:['Reopened','#dc2626']};
function _supPill(st){ var m=SUP_ST[st]||[st,'#6b7280']; return '<span class="sup-pill" style="background:'+m[1]+'">'+m[0]+'</span>'; }

function initStudentSupport(){
  var app=document.getElementById('student-app'); if(!app) return;
  var nav=app.querySelector('.sidebar-nav'); var main=app.querySelector('.main');
  if(nav && !nav.querySelector('[onclick*="complaints"]')){
    var sec=document.createElement('div'); sec.className='nav-section'; sec.textContent='Support';
    var c=document.createElement('div'); c.className='nav-item'; c.setAttribute('onclick',"sPage('complaints',this)");
    c.innerHTML=(typeof ic==='function'?ic('help'):'')+'<span>Complaints</span><span class="badge" id="s-cmp-badge" style="display:none">0</span>';
    var f=document.createElement('div'); f.className='nav-item'; f.setAttribute('onclick',"sPage('feedback',this)");
    f.innerHTML=(typeof ic==='function'?ic('star'):'')+'<span>Feedback</span>';
    nav.appendChild(sec); nav.appendChild(c); nav.appendChild(f);
  }
  if(main && !document.getElementById('s-page-complaints')){
    var p1=document.createElement('div'); p1.className='page'; p1.id='s-page-complaints';
    p1.innerHTML='<div id="s-complaints-content"><div class="spinner"></div></div>'; main.appendChild(p1);
    var p2=document.createElement('div'); p2.className='page'; p2.id='s-page-feedback';
    p2.innerHTML='<div id="s-feedback-content"><div class="spinner"></div></div>'; main.appendChild(p2);
  }
  _supLoadBadge();
}
function _supLoadBadge(){
  api('/api/student/support-badges').then(function(r){
    var b=document.getElementById('s-cmp-badge'); if(!b) return;
    var n=(r&&r.complaints)||0; b.textContent=n; b.style.display=n>0?'':'none';
  }).catch(function(){});
}

/* ---- My Complaints ---- */
function loadSComplaints(){
  var el=document.getElementById('s-complaints-content'); if(!el) return;
  _supCss(); el.innerHTML=_supSkelList(4);
  Promise.all([
    api('/api/student/complaint-categories').catch(function(){return {categories:[]};}),
    api('/api/student/complaints').catch(function(){return {complaints:[]};})
  ]).then(function(res){
    var cats=(res[0]&&res[0].categories)||[];
    var list=(res[1]&&res[1].complaints)||[];
    var opts='<option value="">Select a category</option>'+cats.map(function(c){return '<option value="'+c.id+'">'+esc(c.name)+'</option>';}).join('');
    var form='<div class="card"><div class="card-header"><h3>Raise a Complaint</h3></div><div class="card-body">'
      +'<div class="form-group"><label>Category</label><select id="sc-cat" class="form-control">'+opts+'</select></div>'
      +'<div class="form-group"><label>Short Title <span style="color:var(--text-muted);font-weight:400">(optional)</span></label><input id="sc-title" class="form-control" maxlength="200" placeholder="e.g. Portal login issue"></div>'
      +'<div class="form-group"><label>Your Complaint</label>'+composerHTML('sccmp','Write your complaint here\u2026 or record a voice note','scSubmit()','Submit Complaint')+'</div>'
      +'<div style="font-size:.78rem;color:var(--text-muted)">Non-academic issues \u2014 for subject doubts use Doubts.</div>'
      +'<div id="sc-status" style="font-size:.82rem;margin-top:8px"></div>'
      +'</div></div>';
    var body;
    if(!list.length){ body='<div class="sup-empty"><div style="font-weight:700;margin-bottom:4px">No complaints yet</div>You haven\u2019t raised any complaints.</div>'; }
    else {
      body='<div class="sup-list">'+list.map(function(c){
        return '<div class="sup-card" onclick="scOpenDetail('+c.id+')"><div style="display:flex;justify-content:space-between;gap:10px;align-items:flex-start">'
          +'<div><div class="sup-num">'+esc(c.complaint_number)+'</div><div class="sup-ttl">'+esc(c.title)+(c.read_by_student?'':'<span class="sup-dot" title="New reply"></span>')+'</div>'
          +'<div class="sup-meta">'+(c.category?esc(c.category)+' \u00b7 ':'')+esc(c.created_at)+(c.image_count?' \u00b7 \uD83D\uDCCE '+c.image_count:'')+(c.voice_count?' \u00b7 \uD83C\uDF99':'')+'</div></div>'
          +_supPill(c.status)+'</div></div>';
      }).join('')+'</div>';
    }
    var listCard='<div class="card"><div class="card-header"><h3>My Complaints</h3></div><div class="card-body hide-scroll">'+body+'</div></div>';
    el.innerHTML='<div class="grid-2">'+form+listCard+'</div>';
    _supLoadBadge();
  }).catch(function(e){ el.innerHTML='<div style="padding:20px;color:#c1443a">'+esc((e&&e.message)||'Could not load')+'</div>'; });
}

/* ---- Raise a Complaint (form) ---- */
window._scImgs=[];
function scOpenForm(){
  api('/api/student/complaint-categories').then(function(r){
    var cats=(r&&r.categories)||[];
    var opts='<option value="">Select a category</option>'+cats.map(function(c){return '<option value="'+c.id+'">'+esc(c.name)+'</option>';}).join('');
    var body='<div class="form-group"><label class="form-label">Category</label><select id="sc-cat" class="form-control">'+opts+'</select></div>'
      +'<div class="form-group"><label class="form-label">Short Title <span style="color:var(--text-muted);font-weight:400">(optional)</span></label><input id="sc-title" class="form-control" maxlength="200" placeholder="e.g. Portal login issue"></div>'
      +'<div class="form-group"><label class="form-label">Your Complaint</label>'+composerHTML('sccmp','Write your complaint here\u2026 or record a voice note','scSubmit()','Submit Complaint')+'</div>'
      +'<div id="sc-status" style="font-size:.82rem;margin-top:4px"></div>';
    showModal('Raise a Complaint', body, '');
  });
}
function scAddImgs(files){
  for(var i=0;i<files.length;i++){ if((files[i].type||'').indexOf('image')===0) window._scImgs.push(files[i]); }
  _scRenderPrev();
}
function _scRenderPrev(){
  var el=document.getElementById('sc-prev'); if(!el) return;
  el.innerHTML=window._scImgs.map(function(f,i){ return '<span class="sup-att-chip"><img src="'+URL.createObjectURL(f)+'"><span class="x" onclick="window._scImgs.splice('+i+',1);_scRenderPrev()">\u00d7</span></span>'; }).join('');
}
async function scSubmit(){
  var cat=(document.getElementById('sc-cat')||{}).value||'';
  var title=((document.getElementById('sc-title')||{}).value||'').trim();
  var descEl=document.getElementById('cmpt-sccmp');
  var desc=((descEl&&descEl.value)||'').trim();
  var st=(window._cmpState&&_cmpState['sccmp'])||{};
  if(!desc && !st.file && !st.voice){ toast('Please describe your complaint, attach a photo or record a voice note.',true); return; }
  if(!title){
    if(desc) title=desc.replace(/\s+/g,' ').slice(0,60);
    else if(cat){ var sel=document.getElementById('sc-cat'); title=sel.options[sel.selectedIndex].text; }
    else title='Complaint';
  }
  var btn=document.getElementById('cmps-sccmp'); if(btn){ btn.disabled=true; btn.textContent='Submitting...'; }
  try{
    var fd=new FormData();
    fd.append('title',title); fd.append('description',desc); fd.append('category_id',cat);
    if(st.file){
      var fl=st.file;
      if((fl.type||'').indexOf('image/')===0){
        try{ var _r=await Promise.race([smartCompress(fl,function(){}),new Promise(function(rs){setTimeout(function(){rs(null);},12000);})]); if(_r&&_r.ok&&_r.file) fl=_r.file; }catch(e){}
      }
      fd.append('images',fl,fl.name||'image');
    }
    if(st.voice){ fd.append('voice',st.voice,'voice.webm'); }
    var r=await fetch(API+'/api/student/complaints',{method:'POST',headers:{Authorization:'Bearer '+TOKEN},body:fd});
    if(!r.ok){ var d=null; try{d=await r.json();}catch(e){} throw new Error((d&&d.detail)||'Submit failed'); }
    var res=await r.json();
    closeModal();
    showModal('Complaint Submitted','<div style="text-align:center;padding:10px"><div style="font-size:2.4rem">\u2705</div>'
      +'<div style="font-weight:800;font-size:1.05rem;margin-top:8px">We\u2019ve received your complaint</div>'
      +'<div class="sup-num" style="margin-top:8px;font-size:.9rem">'+esc(res.complaint_number)+'</div>'
      +'<div style="margin-top:6px">'+_supPill('open')+'</div>'
      +'<div style="font-size:.84rem;color:var(--text-muted);margin-top:10px">We\u2019ll review it and respond here.</div></div>',
      '<button class="btn btn-primary" onclick="closeModal();loadSComplaints()">Done</button>');
  }catch(e){ var sx=document.getElementById('sc-status'); if(sx) sx.innerHTML='<span style="color:#c1443a">'+esc(e.message)+'</span>'; if(btn){ btn.disabled=false; btn.textContent='Submit Complaint'; } }
}

/* ---- Complaint detail / conversation ---- */
window._scReplyImgs=[];
function scOpenDetail(cid){
  showModal('Complaint','<div class="spinner"></div>','');
  api('/api/student/complaints/'+cid).then(function(r){
    var c=r.complaint; window._scReplyImgs=[]; _supRenderDetail('student', c);
    _supLoadBadge();
  }).catch(function(e){ document.getElementById('modal-body').innerHTML='<div style="color:#c1443a;padding:12px">'+esc((e&&e.message)||'Could not load')+'</div>'; });
}
function _supRenderDetail(role, c){
  _supCss();
  var imgJobs=[];
  var thread=(c.messages||[]).map(function(m){
    var mine=(m.sender_role===role);
    var atts=(m.attachments||[]).map(function(a){
      if(a.kind==='image'){ var id='sca-'+a.id; imgJobs.push([id,role,a.id]); return '<img id="'+id+'" class="att" onclick="_supViewImg(\''+role+'\','+a.id+')">'; }
      return '<div style="margin-top:6px"><audio controls id="scv-'+a.id+'" style="height:34px"></audio></div>';
    }).join('');
    (m.attachments||[]).forEach(function(a){ if(a.kind==='voice') imgJobs.push(['AUDIO:scv-'+a.id, role, a.id]); });
    return '<div class="sup-b '+(mine?'me':'them')+'"><div class="who">'+(m.sender_role==='admin'?'Support':'You')+'</div>'+(m.message?esc(m.message).replace(/\n/g,'<br>'):'')+atts+'</div>';
  }).join('') || '<div style="color:var(--text-muted);font-size:.84rem">No messages yet.</div>';
  var canReply=(c.status!=='resolved'||role==='student');
  var head='<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;margin-bottom:8px"><div>'
    +'<div class="sup-num">'+esc(c.complaint_number)+'</div><div style="font-weight:800;font-size:1.05rem">'+esc(c.title)+'</div>'
    +'<div class="sup-meta">'+(c.category?esc(c.category)+' \u00b7 ':'')+esc(c.created_at)+'</div></div>'+_supPill(c.status)+'</div>';
  window._scReplyCtx={role:role,cid:c.id,key:'screp'};
  var composer=canReply?('<div style="border-top:1px solid var(--border);padding-top:10px">'+composerHTML('screp',(role==='student'?'Reply to support\u2026':'Write a reply\u2026'),'scComposerReply()','Send')+'</div>'):'';
  document.getElementById('modal-body').innerHTML=head+'<div class="sup-thread">'+thread+'</div>'+composer;
  document.getElementById('modal-footer').innerHTML='<button class="btn btn-ghost" onclick="closeModal()">Close</button>';
  var title=document.getElementById('modal-title'); if(title) title.textContent='Complaint \u00b7 '+c.complaint_number;
  imgJobs.forEach(function(j){
    if((''+j[0]).indexOf('AUDIO:')===0){ _supLoadAudio(j[0].slice(6), '/api/'+j[1]+'/complaint-attachments/'+j[2]+'/view'); }
    else { _supLoadImg(j[0], '/api/'+j[1]+'/complaint-attachments/'+j[2]+'/view'); }
  });
}
async function _supLoadImg(id,url){ try{ var r=await fetch(API+url,{headers:{Authorization:'Bearer '+TOKEN}}); if(!r.ok)return; var u=URL.createObjectURL(await r.blob()); var im=document.getElementById(id); if(im) im.src=u; }catch(e){} }
async function _supLoadAudio(id,url){ try{ var r=await fetch(API+url,{headers:{Authorization:'Bearer '+TOKEN}}); if(!r.ok)return; var u=URL.createObjectURL(await r.blob()); var a=document.getElementById(id); if(a) a.src=u; }catch(e){} }
function _supViewImg(role,aid){ _supLoadImg('_lightbox', '/api/'+role+'/complaint-attachments/'+aid+'/view'); }
function scReplyAddImgs(files){ for(var i=0;i<files.length;i++){ if((files[i].type||'').indexOf('image')===0) window._scReplyImgs.push(files[i]); } _scReplyPrev(); }
function _scReplyPrev(){ var el=document.getElementById('sc-rprev'); if(!el)return; el.innerHTML=window._scReplyImgs.map(function(f,i){ return '<span class="sup-att-chip"><img src="'+URL.createObjectURL(f)+'"><span class="x" onclick="window._scReplyImgs.splice('+i+',1);_scReplyPrev()">\u00d7</span></span>'; }).join(''); }
async function scSendReply(role, cid){
  var txt=(document.getElementById('sc-reply').value||'').trim();
  if(!txt && !window._scReplyImgs.length){ toast('Type a message',true); return; }
  var btn=document.getElementById('sc-rbtn'); btn.disabled=true; btn.textContent='Sending...';
  try{
    var fd=new FormData(); fd.append('message',txt);
    window._scReplyImgs.forEach(function(f){ fd.append('images',f,f.name||'image'); });
    if(window._scReplyVoice&&window._scReplyVoice.blob){ fd.append('voice',window._scReplyVoice.blob,'voice.webm'); }
    var base=role==='student'?'/api/student/complaints/':'/api/admin/complaints/';
    var r=await fetch(API+base+cid+'/messages',{method:'POST',headers:{Authorization:'Bearer '+TOKEN},body:fd});
    if(!r.ok){ var d=null; try{d=await r.json();}catch(e){} throw new Error((d&&d.detail)||'Send failed'); }
    window._scReplyImgs=[];
    if(role==='student') scOpenDetail(cid); else amcCmpOpen(cid);
  }catch(e){ toast(e.message||'Could not send',true); }
  finally{ if(btn){ btn.disabled=false; btn.textContent='Send'; } }
}

/* ---- Feedback & Ratings ---- */
window._sfRating=0;
function loadSFeedback(){
  var el=document.getElementById('s-feedback-content'); if(!el) return;
  _supCss(); window._sfRating=0;
  var stars=[1,2,3,4,5].map(function(n){ return '<span class="sup-star" role="button" tabindex="0" aria-label="'+n+' star" data-n="'+n+'" onclick="sfSetRating('+n+')" onkeydown="if(event.key===\'Enter\'||event.key===\' \'){sfSetRating('+n+');event.preventDefault()}">\u2605</span>'; }).join('');
  el.innerHTML='<div style="max-width:560px;margin:0 auto"><div class="sup-card" style="cursor:default;text-align:center;padding:24px">'
    +'<div style="font-weight:800;font-size:1.15rem">How was your experience?</div>'
    +'<div style="font-size:.84rem;color:var(--text-muted);margin-top:4px">Your feedback helps us improve MVS Foundation.</div>'
    +'<div class="sup-stars" id="sf-stars">'+stars+'</div>'
    +'<div id="sf-label" style="font-size:.8rem;color:var(--text-muted);min-height:1em">Tap a star to rate</div>'
    +'<textarea id="sf-review" class="form-control" rows="3" maxlength="1000" placeholder="Tell us more (optional)" style="margin-top:12px"></textarea>'
    +'<div style="margin-top:12px"><button class="btn btn-primary" id="sf-submit" onclick="sfSubmit()" style="min-width:180px">Submit Feedback</button></div>'
    +'<div id="sf-status" style="font-size:.82rem;margin-top:8px"></div></div>'
    +'<div id="sf-mine" style="margin-top:16px"></div></div>';
  _sfLoadMine();
}
function sfSetRating(n){
  window._sfRating=n;
  document.querySelectorAll('#sf-stars .sup-star').forEach(function(s){ s.classList.toggle('on', parseInt(s.dataset.n,10)<=n); });
  var lbl=['','Poor','Fair','Good','Very Good','Excellent'][n];
  var el=document.getElementById('sf-label'); if(el) el.textContent=lbl;
}
async function sfSubmit(){
  if(!window._sfRating){ toast('Please choose a star rating',true); return; }
  var btn=document.getElementById('sf-submit'); btn.disabled=true; btn.textContent='Submitting...';
  try{
    await api('/api/student/feedback','POST',{rating:window._sfRating,review:document.getElementById('sf-review').value||''});
    document.getElementById('sf-status').innerHTML='<span style="color:#059669;font-weight:700">\u2705 Thank you for your feedback!</span>';
    document.getElementById('sf-review').value=''; sfSetRating(0); window._sfRating=0;
    _sfLoadMine();
    setTimeout(function(){ btn.disabled=false; btn.textContent='Submit Feedback'; },400);
  }catch(e){ document.getElementById('sf-status').innerHTML='<span style="color:#c1443a">'+esc((e&&e.message)||'Could not submit')+'</span>'; btn.disabled=false; btn.textContent='Submit Feedback'; }
}
function _sfLoadMine(){
  api('/api/student/feedback').then(function(r){
    var list=(r&&r.feedback)||[]; var el=document.getElementById('sf-mine'); if(!el)return;
    if(!list.length){ el.innerHTML=''; return; }
    el.innerHTML='<div style="font-weight:700;font-size:.9rem;margin-bottom:8px">Your Feedback</div>'+list.map(function(f){
      var st='<span style="color:#e6ad4e">'+'\u2605'.repeat(f.rating)+'</span><span style="color:#d9c9a0">'+'\u2605'.repeat(5-f.rating)+'</span>';
      return '<div class="sup-card" style="cursor:default;margin-bottom:8px">'+st+(f.review?'<div style="margin-top:6px;font-size:.88rem">'+esc(f.review)+'</div>':'')+'<div class="sup-meta">'+esc(f.created_at)+'</div></div>';
    }).join('');
  }).catch(function(){});
}

/* ============================================================
   COMPLAINTS & FEEDBACK — Admin UI (Phase 5)
   ============================================================ */
function _asupCss(){
  if(document.getElementById('asup-css')) return;
  var s=document.createElement('style'); s.id='asup-css';
  s.textContent=[
    '#a-page-complaints .ac-cards,#a-page-feedback .ac-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin-bottom:16px}',
    '.ac-kpi{border:1px solid var(--border);border-radius:14px;padding:15px;background:var(--card);cursor:pointer;transition:.14s}',
    '.ac-kpi:hover{border-color:#d9b978;transform:translateY(-2px)}',
    '.ac-kpi.static{cursor:default}.ac-kpi.static:hover{transform:none;border-color:var(--border)}',
    '.ac-kpi b{display:block;font-size:1.7rem;font-weight:800;line-height:1}',
    '.ac-kpi span{font-size:.72rem;color:var(--text-muted);text-transform:uppercase;letter-spacing:.03em;font-weight:700}',
    '.ac-kpi small{display:block;font-size:.72rem;color:var(--text-muted);margin-top:3px}',
    '.ac-filters{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:14px;align-items:center}',
    '.ac-filters select,.ac-filters input{padding:8px 11px;border-radius:9px;border:1px solid var(--border);background:var(--card);color:var(--text);font-size:.82rem}',
    '.ac-list{display:flex;flex-direction:column;gap:10px;max-height:calc(100vh - 380px);min-height:200px;overflow:auto;padding:2px}',
    '.ac-card{border:1px solid var(--border);border-radius:14px;padding:15px;background:var(--card);transition:.14s;flex:0 0 auto}',
    '.ac-card:hover{border-color:#d9b978}',
    '.ac-card2{border:1px solid var(--border);border-radius:16px;background:var(--card);overflow:hidden;transition:.15s;box-shadow:0 1px 2px rgba(15,23,42,.04);flex:0 0 auto}',
    '.ac-card2:hover{border-color:#d9b978;box-shadow:0 8px 24px rgba(15,23,42,.08)}',
    '.ac-card2.open{border-color:#d9b978;box-shadow:0 10px 30px rgba(15,23,42,.10)}',
    '.ac-chead{padding:16px 18px;cursor:pointer}',
    '.ac-crow{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}',
    '.ac-cdesc{color:var(--text-muted);font-size:.9rem;margin-top:6px;line-height:1.45;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}',
    '.ac-cright{display:flex;flex-direction:column;gap:6px;align-items:flex-end;flex-shrink:0}',
    '.ac-chev{font-size:1.35rem;color:#c9a86a;transition:.18s;line-height:1;margin-top:2px}',
    '.ac-cbody{border-top:1px solid var(--border);padding:14px 18px 16px;background:linear-gradient(180deg,rgba(230,173,78,.045),transparent)}',
    '.ac-cbody .att{max-width:200px;border-radius:10px;border:1px solid var(--border);margin-top:6px;cursor:pointer;display:block}',
    '.ac-name{font-weight:800;cursor:pointer}.ac-name:hover{color:#b8941f}',
    '.ac-prio{font-size:.64rem;font-weight:800;padding:2px 8px;border-radius:999px}',
    '.ac-prio.critical{background:rgba(220,38,38,.14);color:#dc2626}.ac-prio.emergency{background:#dc2626;color:#fff}',
    '.ac-trend{display:flex;align-items:flex-end;gap:2px;height:64px;padding:6px 2px 0;overflow:hidden}',
    '.ac-tday{flex:1;min-width:0;height:100%;display:flex;align-items:flex-end;justify-content:center;gap:2px}',
    '.ac-tday .r{width:4px;max-width:45%;background:#c98a2e;border-radius:3px 3px 0 0}',
    '.ac-tday .g{width:4px;max-width:45%;background:#059669;border-radius:3px 3px 0 0}',
    '.ac-dist-row{display:flex;align-items:center;gap:10px;margin-bottom:7px}',
    '.ac-dist-bar{flex:1;height:10px;border-radius:999px;background:rgba(120,113,108,.16);overflow:hidden}',
    '.ac-dist-fill{height:100%;background:#e6ad4e}',
    '.ac-star{color:#e6ad4e}'
  ].join('');
  document.head.appendChild(s);
  try{ _supPolishCss(); }catch(e){}
}
function _fmtDur(secs){ secs=secs||0; if(!secs) return '—'; var h=Math.floor(secs/3600),m=Math.floor((secs%3600)/60); return h?(h+'h '+m+'m'):(m+'m'); }
function _acPrio(p){ return (p==='critical'||p==='emergency')?'<span class="ac-prio '+p+'">'+p.toUpperCase()+'</span>':''; }

function initAdminSupport(){
  var app=document.getElementById('admin-app'); if(!app) return;
  var nav=app.querySelector('.sidebar-nav'); var main=app.querySelector('.main');
  if(nav && !nav.querySelector('[onclick*="complaints"]')){
    var anchor=[].slice.call(nav.querySelectorAll('.nav-item')).filter(function(n){return (n.getAttribute('onclick')||'').indexOf("'matcheck'")>=0;})[0];
    var sec=document.createElement('div'); sec.className='nav-section'; sec.textContent='Leads & Support';
    var c=document.createElement('div'); c.className='nav-item'; c.setAttribute('onclick',"aPage('complaints',this)");
    c.innerHTML=(typeof ic==='function'?ic('help'):'')+'<span>Complaints</span><span class="badge" id="a-cmp-badge" style="display:none">0</span>';
    var f=document.createElement('div'); f.className='nav-item'; f.setAttribute('onclick',"aPage('feedback',this)");
    f.innerHTML=(typeof ic==='function'?ic('star'):'')+'<span>Feedback</span><span class="badge" id="a-fb-badge" style="display:none">0</span>';
    if(anchor){ anchor.parentNode.insertBefore(f, anchor.nextSibling); anchor.parentNode.insertBefore(c, anchor.nextSibling); anchor.parentNode.insertBefore(sec, anchor.nextSibling); }
    else { nav.appendChild(sec); nav.appendChild(c); nav.appendChild(f); }
  }
  if(main){
    if(!document.getElementById('a-page-complaints')){ var p1=document.createElement('div'); p1.className='page'; p1.id='a-page-complaints'; p1.innerHTML='<div id="a-complaints-content"><div class="spinner"></div></div>'; main.appendChild(p1); }
    if(!document.getElementById('a-page-feedback')){ var p2=document.createElement('div'); p2.className='page'; p2.id='a-page-feedback'; p2.innerHTML='<div id="a-feedback-content"><div class="spinner"></div></div>'; main.appendChild(p2); }
  }
  _asupBadges();
}
function _asupBadges(){
  api('/api/admin/support-badges').then(function(r){
    var b=document.getElementById('a-cmp-badge'), f=document.getElementById('a-fb-badge');
    if(b){ var n=(r&&r.complaints)||0; b.textContent=n; b.style.display=n>0?'':'none'; }
    if(f){ var m=(r&&r.feedback)||0; f.textContent=m; f.style.display=m>0?'':'none'; }
  }).catch(function(){});
}

/* ---- Complaints console ---- */
window._acFilter={status:'',category_id:0,priority:'',resolver:0,date_range:'',q:'',page:1};
function loadAComplaints(){
  var el=document.getElementById('a-complaints-content'); if(!el) return;
  _asupCss(); _supCss();
  // paint instantly: KPI skeleton + filters (cached options) + list skeleton, then load the LIST first
  el.innerHTML='<div id="ac-kpis">'+_supSkelCards(6)+'</div>'+_acFiltersHTML()+'<div id="ac-listwrap">'+_supSkelList(4)+'</div>';
  _acLoadList();
  // analytics + filter options load in the background and fill in when ready
  Promise.all([
    api('/api/admin/complaint-analytics?rng=30').catch(function(){return {};}),
    api('/api/admin/complaint-categories').catch(function(){return {categories:[]};}),
    api('/api/admin/complaint-resolvers').catch(function(){return {resolvers:[]};})
  ]).then(function(res){
    window._acAnalytics=res[0]||{}; window._acCats=(res[1]&&res[1].categories)||[]; window._acResolvers=(res[2]&&res[2].resolvers)||[];
    var k=document.getElementById('ac-kpis'); if(k) k.innerHTML=_acKpisHTML();
    var fw=document.getElementById('ac-filters-wrap');
    if(fw){ var tmp=document.createElement('div'); tmp.innerHTML=_acFiltersHTML(); if(tmp.firstChild) fw.replaceWith(tmp.firstChild); }
  }).catch(function(){});
}
function _acKpisHTML(){
  var a=window._acAnalytics||{};
  var tr=(a.trend||[]).slice(-30);
  var mx=Math.max(1, Math.max.apply(null, tr.map(function(t){return Math.max(t.received,t.resolved);}).concat([1])));
  var H=54;
  var trend=tr.map(function(t){
    var rh=t.received?Math.max(3,Math.round(t.received/mx*H)):0;
    var gh=t.resolved?Math.max(3,Math.round(t.resolved/mx*H)):0;
    return '<div class="ac-tday" title="'+t.date+' \u00b7 '+t.received+' received, '+t.resolved+' resolved"><span class="r" style="height:'+rh+'px"></span><span class="g" style="height:'+gh+'px"></span></div>';
  }).join('');
  var cards='<div class="ac-cards">'
    +'<div class="ac-kpi" onclick="acQuick(\'status\',\'pending\')"><b style="color:#d97706">'+(a.pending||0)+'</b><span>Pending Now</span></div>'
    +'<div class="ac-kpi" onclick="acQuick(\'date_range\',\'today\')"><b>'+(a.created_today||0)+'</b><span>Today</span><small>'+(a.resolved_today||0)+' resolved</small></div>'
    +'<div class="ac-kpi" onclick="acQuick(\'date_range\',\'month\')"><b>'+(a.created_month||0)+'</b><span>This Month</span><small>'+(a.resolved_month||0)+' resolved</small></div>'
    +'<div class="ac-kpi" onclick="acQuick(\'status\',\'all\')"><b>'+(a.total||0)+'</b><span>Total</span></div>'
    +'<div class="ac-kpi static"><b style="color:#059669">'+(a.resolution_rate||0)+'%</b><span>Resolution Rate</span></div>'
    +'<div class="ac-kpi static"><b style="font-size:1.2rem">'+_fmtDur(a.avg_resolution_secs)+'</b><span>Avg Resolution</span></div>'
    +(a.top_resolver?'<div class="ac-kpi" onclick="acQuick(\'resolver\','+a.top_resolver.id+')"><b style="font-size:1.1rem">'+esc(a.top_resolver.name)+'</b><span>Top Resolver</span><small>'+a.top_resolver.count+' resolved</small></div>':'')
    +'</div>';
  var chart=tr.length?'<div class="ac-card static" style="margin-bottom:14px;cursor:default"><div style="display:flex;justify-content:space-between;font-size:.8rem;color:var(--text-muted)"><b style="color:var(--text)">Complaints Trend</b><span><span style="color:#c98a2e">\u25a0</span> Received <span style="color:#059669">\u25a0</span> Resolved</span></div><div class="ac-trend">'+trend+'</div></div>':'';
  return cards+chart;
}
function _acFiltersHTML(){
  var f=window._acFilter;
  var catOpts='<option value="0">All categories</option>'+(window._acCats||[]).map(function(c){return '<option value="'+c.id+'"'+(f.category_id==c.id?' selected':'')+'>'+esc(c.name)+'</option>';}).join('');
  var resOpts='<option value="0">All resolvers</option>'+(window._acResolvers||[]).map(function(x){return '<option value="'+x.id+'"'+(f.resolver==x.id?' selected':'')+'>'+esc(x.name)+'</option>';}).join('');
  var stOpts=[['','Status: All'],['pending','Pending'],['open','Open'],['in_progress','In Progress'],['waiting_student','Waiting'],['resolved','Resolved'],['reopened','Reopened']].map(function(x){return '<option value="'+x[0]+'"'+(f.status===x[0]?' selected':'')+'>'+x[1]+'</option>';}).join('');
  var prOpts=[['','Priority: All'],['normal','Normal'],['critical','Critical'],['emergency','Emergency']].map(function(x){return '<option value="'+x[0]+'"'+(f.priority===x[0]?' selected':'')+'>'+x[1]+'</option>';}).join('');
  var dtOpts=[['','Any date'],['today','Today'],['yesterday','Yesterday'],['week','This Week'],['month','This Month'],['last_month','Last Month']].map(function(x){return '<option value="'+x[0]+'"'+(f.date_range===x[0]?' selected':'')+'>'+x[1]+'</option>';}).join('');
  return '<div id="ac-filters-wrap"><button class="btn btn-ghost btn-sm ac-fbtn" onclick="var e=document.getElementById(\'ac-filterbar\');e&&e.classList.toggle(\'open\')">\u2699 Filters</button><div id="ac-filterbar" class="ac-filters">'
    +'<input id="ac-q" placeholder="Search name, ID, number or text\u2026" value="'+esc(f.q)+'" style="flex:1;min-width:180px" oninput="acDebounceSearch(this.value)">'
    +'<select onchange="acSetF(\'status\',this.value)">'+stOpts+'</select>'
    +'<select onchange="acSetF(\'category_id\',this.value)">'+catOpts+'</select>'
    +'<select onchange="acSetF(\'priority\',this.value)">'+prOpts+'</select>'
    +'<select onchange="acSetF(\'resolver\',this.value)">'+resOpts+'</select>'
    +'<select onchange="acSetF(\'date_range\',this.value)">'+dtOpts+'</select></div></div>';
}
function _renderAComplaints(){
  var el=document.getElementById('a-complaints-content'); if(!el) return;
  el.innerHTML='<div id="ac-kpis">'+_acKpisHTML()+'</div>'+_acFiltersHTML()+'<div id="ac-listwrap">'+_supSkelList(3)+'</div>';
  _acLoadList();
}
function _acLoadList(){
  var f=window._acFilter;
  var qs='?status='+f.status+'&category_id='+f.category_id+'&priority='+f.priority+'&resolver='+f.resolver+'&date_range='+f.date_range+'&q='+encodeURIComponent(f.q)+'&page='+f.page+'&page_size=20';
  api('/api/admin/complaints'+qs).then(function(r){
    var list=r.complaints||[]; var wrap=document.getElementById('ac-listwrap'); if(!wrap)return;
    if(!list.length && f.page===1){ wrap.innerHTML='<div class="sup-empty"><div style="font-weight:700;margin-bottom:4px">No complaints found</div>Try changing your filters or search term.</div>'; return; }
    var cards=list.map(function(c){
      var sid=(c.student&&c.student.id)||0;
      var atts=(c.image_count?'\uD83D\uDCCE '+c.image_count+' ':'')+(c.voice_count?'\uD83C\uDF99 '+c.voice_count:'');
      var desc=(c.description||'').trim();
      return '<div class="ac-card2" id="acc-'+c.id+'"><div class="ac-chead" onclick="amcToggle('+c.id+')"><div class="ac-crow">'
        +'<div style="min-width:0"><span class="ac-name" onclick="event.stopPropagation();_supDrawer('+sid+')">'+esc(c.student&&c.student.name||'Student')+'</span> <span class="sup-num">'+esc(c.student&&c.student.student_id||'')+' \u00b7 '+esc(c.complaint_number)+'</span>'
        +'<div class="sup-ttl" style="margin-top:4px;font-size:1.02rem">'+esc(c.title)+(c.read_by_admin?'':'<span class="sup-dot"></span>')+'</div>'
        +(desc?'<div class="ac-cdesc">'+esc(desc)+'</div>':'')
        +'<div class="sup-meta" style="margin-top:6px">'+(c.category?esc(c.category)+' \u00b7 ':'')+esc(c.created_at)+(atts?' \u00b7 '+atts:'')+'</div></div>'
        +'<div class="ac-cright"><span id="achs-'+c.id+'">'+_supPill(c.status)+_acPrio(c.priority)+'</span><span class="ac-chev" id="acv-'+c.id+'">\u203a</span></div>'
        +'</div></div><div class="ac-cbody" id="accb-'+c.id+'" style="display:none"></div></div>';
    }).join('');
    var more=r.has_more?'<div style="text-align:center;margin-top:12px"><button class="btn btn-ghost btn-sm" onclick="acMore()">Load more</button></div>':'';
    if(f.page===1){ wrap.innerHTML='<div class="ac-list">'+cards+'</div>'+more; }
    else { var lw=wrap.querySelector('.ac-list'); if(lw) lw.insertAdjacentHTML('beforeend',cards); }
  }).catch(function(e){ var wrap=document.getElementById('ac-listwrap'); if(wrap) wrap.innerHTML='<div style="padding:14px;color:#c1443a">'+esc((e&&e.message)||'Could not load')+'</div>'; });
}
function amcToggle(cid){
  var card=document.getElementById('acc-'+cid); var body=document.getElementById('accb-'+cid); var chev=document.getElementById('acv-'+cid);
  if(!body) return;
  if(body.style.display!=='none'){ body.style.display='none'; body.innerHTML=''; if(chev) chev.style.transform=''; if(card) card.classList.remove('open'); return; }
  if(chev) chev.style.transform='rotate(90deg)'; if(card) card.classList.add('open');
  body.style.display=''; body.innerHTML='<div class="spinner" style="margin:16px auto"></div>';
  api('/api/admin/complaints/'+cid).then(function(r){ _amcRenderInline(r.complaint, body); _asupBadges();
    var hs=document.getElementById('achs-'+cid); if(hs) hs.innerHTML=_supPill(r.complaint.status)+_acPrio(r.complaint.priority);
  }).catch(function(e){ body.innerHTML='<div style="color:#c1443a;padding:12px">'+esc((e&&e.message)||'Could not load')+'</div>'; });
}
function _amcRenderInline(c, body){
  _supCss(); _asupCss();
  var imgJobs=[];
  var thread=(c.messages||[]).map(function(m){
    var mine=(m.sender_role==='admin');
    var atts=(m.attachments||[]).map(function(a){
      if(a.kind==='image'){ var id='aci-'+a.id; imgJobs.push(['IMG:'+id,a.id]); return '<img id="'+id+'" class="att" onclick="_supLightbox(\'/api/admin/complaint-attachments/'+a.id+'/view\')">'; }
      var vid='acu-'+a.id; imgJobs.push(['AUD:'+vid,a.id]); return '<div style="margin-top:6px"><audio controls id="'+vid+'" style="height:34px"></audio></div>';
    }).join('');
    return '<div class="sup-b '+(mine?'me':'them')+'"><div class="who">'+(mine?'Support':(c.student&&c.student.name||'Student'))+'</div>'+(m.message?esc(m.message).replace(/\n/g,'<br>'):'')+atts+'</div>';
  }).join('')||'<div style="color:var(--text-muted)">No messages.</div>';
  var key='ac'+c.id;
  var prio='<select class="form-control" style="max-width:180px;height:38px;padding:6px 10px" onchange="acActionInline('+c.id+',\'priority\',{priority:this.value})"><option value="">Priority: '+(c.priority||'normal')+'</option><option value="normal">Normal</option><option value="critical">Critical</option><option value="emergency">Emergency</option></select>';
  var resBtn=(c.status==='resolved')
    ?'<button class="btn btn-ghost btn-sm" onclick="acActionInline('+c.id+',\'reopen\')">Reopen</button>'
    :'<button class="btn btn-primary btn-sm" style="background:#059669" onclick="acActionInline('+c.id+',\'resolve\')">Mark Resolved</button>';
  var actions='<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:4px 0 12px">'+prio
    +'<button class="btn btn-ghost btn-sm" onclick="_supDrawer('+((c.student&&c.student.id)||0)+')">View Student</button>'
    +'<button class="btn btn-ghost btn-sm" id="acwa-'+c.id+'" style="color:#25D366;display:none" onclick="acWhatsApp2('+c.id+')">Send on WhatsApp</button>'
    +resBtn+'</div>';
  var composer='<div style="border-top:1px solid var(--border);padding-top:12px;margin-top:4px">'+composerHTML(key,'Write a reply to the student\u2026','amcInlineReply('+c.id+')','Reply')+'</div>';
  body.innerHTML='<div class="sup-thread" style="max-height:40vh">'+thread+'</div>'+actions+composer;
  imgJobs.forEach(function(j){ var t=j[0].slice(0,4), id=j[0].slice(4); if(t==='IMG:') _supLoadImg(id,'/api/admin/complaint-attachments/'+j[1]+'/view'); else _supLoadAudio(id,'/api/admin/complaint-attachments/'+j[1]+'/view'); });
  api('/api/admin/complaints/'+c.id+'/whatsapp').then(function(w){ if(w&&w.available){ var b=document.getElementById('acwa-'+c.id); if(b){ b.style.display=''; b.dataset.url=w.url; } } }).catch(function(){});
}
function amcRefresh(cid){
  var body=document.getElementById('accb-'+cid); if(!body||body.style.display==='none') return;
  body.innerHTML='<div class="spinner" style="margin:16px auto"></div>';
  api('/api/admin/complaints/'+cid).then(function(r){ _amcRenderInline(r.complaint, body);
    var hs=document.getElementById('achs-'+cid); if(hs) hs.innerHTML=_supPill(r.complaint.status)+_acPrio(r.complaint.priority);
    _asupBadges();
  });
}
async function amcInlineReply(cid){
  var key='ac'+cid;
  var txt=((document.getElementById('cmpt-'+key)||{}).value||'').trim();
  var st=(window._cmpState&&_cmpState[key])||{};
  if(!txt&&!st.file&&!st.voice){ toast('Type a message',true); return; }
  var btn=document.getElementById('cmps-'+key); if(btn){ btn.disabled=true; btn.textContent='Sending...'; }
  try{
    var fd=new FormData(); fd.append('message',txt);
    if(st.file){ var fl=st.file; if((fl.type||'').indexOf('image/')===0){ try{ var _r=await Promise.race([smartCompress(fl,function(){}),new Promise(function(rs){setTimeout(function(){rs(null);},12000);})]); if(_r&&_r.ok&&_r.file) fl=_r.file; }catch(e){} } fd.append('images',fl,fl.name||'image'); }
    if(st.voice){ fd.append('voice',st.voice,'voice.webm'); }
    var r=await fetch(API+'/api/admin/complaints/'+cid+'/messages',{method:'POST',headers:{Authorization:'Bearer '+TOKEN},body:fd});
    if(!r.ok){ var d=null; try{d=await r.json();}catch(e){} throw new Error((d&&d.detail)||'Send failed'); }
    amcRefresh(cid);
  }catch(e){ toast(e.message||'Could not send',true); if(btn){ btn.disabled=false; btn.textContent='Reply'; } }
}
async function acActionInline(cid, action, extra){
  try{ var r=await api('/api/admin/complaints/'+cid+'/action','POST',Object.assign({action:action},extra||{}));
    var hs=document.getElementById('achs-'+cid); if(hs) hs.innerHTML=_supPill(r.status)+_acPrio(r.priority);
    amcRefresh(cid); _asupBadges();
    if(action==='resolve') toast('Marked resolved'); else if(action==='reopen') toast('Reopened');
  }catch(e){ toast((e&&e.message)||'Failed',true); }
}
function acWhatsApp2(cid){ var b=document.getElementById('acwa-'+cid); if(b&&b.dataset.url) window.open(b.dataset.url,'_blank'); }
var _acSearchT=null;
function acDebounceSearch(v){ window._acFilter.q=v; window._acFilter.page=1; clearTimeout(_acSearchT); _acSearchT=setTimeout(function(){ document.getElementById('ac-listwrap').innerHTML='<div class="spinner"></div>'; _acLoadList(); }, 350); }
function acSetF(k,v){ window._acFilter[k]=(k==='category_id'||k==='resolver')?(parseInt(v,10)||0):v; window._acFilter.page=1; _renderAComplaints(); }
function acQuick(k,v){ window._acFilter={status:'',category_id:0,priority:'',resolver:0,date_range:'',q:'',page:1}; window._acFilter[k]=(k==='resolver'||k==='category_id')?v:v; _renderAComplaints(); }
function acMore(){ window._acFilter.page++; _acLoadList(); }
async function acAction(cid, action, extra){
  try{ await api('/api/admin/complaints/'+cid+'/action','POST',Object.assign({action:action},extra||{})); toast('Done'); loadAComplaints(); _asupBadges(); }
  catch(e){ toast((e&&e.message)||'Failed',true); }
}

/* ---- admin complaint detail ---- */
function amcCmpOpen(cid){
  showModal('Complaint','<div class="spinner"></div>','');
  api('/api/admin/complaints/'+cid).then(function(r){
    var c=r.complaint; window._scReplyImgs=[]; _amcRenderDetail(c); _asupBadges();
  }).catch(function(e){ document.getElementById('modal-body').innerHTML='<div style="color:#c1443a;padding:12px">'+esc((e&&e.message)||'Could not load')+'</div>'; });
}
function _amcRenderDetail(c){
  _supCss(); _asupCss();
  var imgJobs=[];
  var thread=(c.messages||[]).map(function(m){
    var mine=(m.sender_role==='admin');
    var atts=(m.attachments||[]).map(function(a){
      if(a.kind==='image'){ var id='aca-'+a.id; imgJobs.push(['IMG:'+id,a.id]); return '<img id="'+id+'" class="att" onclick="_supLightbox(\'/api/admin/complaint-attachments/'+a.id+'/view\')">'; }
      var vid='acv-'+a.id; imgJobs.push(['AUD:'+vid,a.id]); return '<div style="margin-top:6px"><audio controls id="'+vid+'" style="height:34px"></audio></div>';
    }).join('');
    return '<div class="sup-b '+(mine?'me':'them')+'"><div class="who">'+(mine?'Support':(c.student&&c.student.name||'Student'))+'</div>'+(m.message?esc(m.message).replace(/\n/g,'<br>'):'')+atts+'</div>';
  }).join('')||'<div style="color:var(--text-muted)">No messages.</div>';
  var st=c.student||{};
  var head='<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;margin-bottom:8px"><div>'
    +'<span class="ac-name" onclick="_supDrawer('+st.id+')">'+esc(st.name||'Student')+'</span> <span class="sup-num">'+esc(st.student_id||'')+'</span>'
    +'<div class="sup-num">'+esc(c.complaint_number)+'</div><div style="font-weight:800;font-size:1.05rem;margin-top:2px">'+esc(c.title)+'</div>'
    +'<div class="sup-meta">'+(c.category?esc(c.category)+' \u00b7 ':'')+esc(c.created_at)+'</div></div><div style="text-align:right;display:flex;flex-direction:column;gap:5px;align-items:flex-end">'+_supPill(c.status)+_acPrio(c.priority)+'</div></div>';
  var ctrl='<div class="ac-filters" style="margin:0 0 10px">'
    +'<select onchange="acAction('+c.id+',\'priority\',{priority:this.value})"><option value="">Set priority\u2026</option><option value="normal"'+(c.priority==='normal'?' selected':'')+'>Normal</option><option value="critical"'+(c.priority==='critical'?' selected':'')+'>Critical</option><option value="emergency"'+(c.priority==='emergency'?' selected':'')+'>Emergency</option></select>'
    +'<button class="btn btn-ghost btn-sm" onclick="_supDrawer('+st.id+')">View Student</button>'
    +'<button class="btn btn-ghost btn-sm" id="ac-wa" style="color:#25D366;display:none" onclick="acWhatsApp('+c.id+')">Send on WhatsApp</button></div>';
  window._scReplyCtx={role:'admin',cid:c.id,key:'screp'};
  var composer='<div style="border-top:1px solid var(--border);padding-top:10px">'+composerHTML('screp','Write a reply\u2026','scComposerReply()','Reply')+'</div>';
  document.getElementById('modal-body').innerHTML=head+ctrl+'<div class="sup-thread">'+thread+'</div>'+composer;
  document.getElementById('modal-footer').innerHTML='<button class="btn btn-ghost" onclick="closeModal()">Close</button>'
    +(c.status==='resolved'?'<button class="btn btn-ghost" onclick="acAction('+c.id+',\'reopen\');closeModal()">Reopen</button>':'<button class="btn btn-primary" style="background:#059669" onclick="acAction('+c.id+',\'resolve\');closeModal()">Mark Resolved</button>');
  var title=document.getElementById('modal-title'); if(title) title.textContent='Complaint \u00b7 '+c.complaint_number;
  imgJobs.forEach(function(j){ var t=j[0].slice(0,4), id=j[0].slice(4); if(t==='IMG:') _supLoadImg(id,'/api/admin/complaint-attachments/'+j[1]+'/view'); else _supLoadAudio(id,'/api/admin/complaint-attachments/'+j[1]+'/view'); });
  api('/api/admin/complaints/'+c.id+'/whatsapp').then(function(w){ if(w&&w.available){ var b=document.getElementById('ac-wa'); if(b){ b.style.display=''; b.dataset.url=w.url; } } }).catch(function(){});
}
function acWhatsApp(cid){ var b=document.getElementById('ac-wa'); if(b&&b.dataset.url) window.open(b.dataset.url,'_blank'); }

/* ---- shared student profile drawer ---- */
function _supDrawer(sid){
  if(!sid) return;
  showModal('Student','<div class="spinner"></div>','');
  api('/api/admin/students/'+sid+'/support').then(function(r){
    var s=r.student||{}, sm=r.summary||{};
    var info='<div style="display:flex;gap:14px;align-items:center;margin-bottom:12px"><div class="avatar" style="width:52px;height:52px;font-size:1.2rem;background:#b8941f;color:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:800">'+esc((s.name||'S').slice(0,1))+'</div>'
      +'<div><div style="font-weight:800;font-size:1.1rem">'+esc(s.name||'Student')+'</div><div class="sup-num">'+esc(s.student_id||'')+(s.batch?' \u00b7 '+esc(s.batch):'')+'</div>'+(s.phone?'<div class="sup-meta">'+esc(s.phone)+'</div>':'')+'</div></div>';
    var summ='<div class="ac-cards" style="grid-template-columns:repeat(auto-fit,minmax(90px,1fr))">'
      +'<div class="ac-kpi static"><b>'+(sm.total||0)+'</b><span>Complaints</span></div>'
      +'<div class="ac-kpi static"><b style="color:#d97706">'+(sm.open||0)+'</b><span>Open</span></div>'
      +'<div class="ac-kpi static"><b style="color:#059669">'+(sm.resolved||0)+'</b><span>Resolved</span></div>'
      +'<div class="ac-kpi static"><b style="color:#dc2626">'+(sm.critical||0)+'</b><span>Critical</span></div>'
      +'<div class="ac-kpi static"><b style="font-size:1rem">'+_fmtDur(sm.avg_resolution_secs)+'</b><span>Avg Time</span></div></div>';
    var hist=(r.complaints||[]).map(function(c){ return '<div class="ac-card" style="padding:11px 13px;cursor:pointer" onclick="amcCmpOpen('+c.id+')"><div style="display:flex;justify-content:space-between;gap:8px;align-items:flex-start"><div style="min-width:0"><div class="sup-num">'+esc(c.complaint_number)+'</div><div style="font-weight:600;font-size:.9rem">'+esc(c.title)+'</div><div class="sup-meta">'+(c.category?esc(c.category)+' \u00b7 ':'')+esc(c.created_at)+'</div></div>'+_supPill(c.status)+'</div></div>'; }).join('')||'<div style="color:var(--text-muted);font-size:.85rem">No complaints.</div>';
    var fbs=(r.feedback||[]).map(function(f){ return '<div class="ac-card" style="padding:10px 13px;cursor:default;margin-bottom:6px"><span class="ac-star">'+'\u2605'.repeat(f.rating)+'</span><span style="color:#d9c9a0">'+'\u2605'.repeat(5-f.rating)+'</span>'+(f.review?'<div style="font-size:.86rem;margin-top:4px">'+esc(f.review)+'</div>':'')+'<div class="sup-meta">'+esc(f.created_at)+'</div></div>'; }).join('');
    var body=info+summ+'<div style="font-weight:700;font-size:.9rem;margin:8px 0 8px">Complaint History</div><div class="sup-list" style="max-height:34vh">'+hist+'</div>'
      +(fbs?'<div style="font-weight:700;font-size:.9rem;margin:14px 0 8px">Feedback</div>'+fbs:'');
    document.getElementById('modal-body').innerHTML=body;
    document.getElementById('modal-footer').innerHTML='<button class="btn btn-ghost" onclick="closeModal()">Close</button>';
    var t=document.getElementById('modal-title'); if(t) t.textContent='Student \u00b7 '+(s.name||'');
  }).catch(function(e){ document.getElementById('modal-body').innerHTML='<div style="color:#c1443a;padding:12px">'+esc((e&&e.message)||'Could not load')+'</div>'; });
}

/* ---- Feedback dashboard ---- */
window._afRating=0;
function loadAFeedback(){
  var el=document.getElementById('a-feedback-content'); if(!el) return;
  _asupCss(); _supCss();
  el.innerHTML='<div id="af-kpis">'+_supSkelCards(3)+'</div>'+_afFilterHTML()+'<div id="af-listwrap">'+_supSkelList(4)+'</div>';
  // list first
  api('/api/admin/feedback?rating='+(window._afRating||0)+'&page=1&page_size=30').catch(function(){return {feedback:[]};})
    .then(function(l){ var w=document.getElementById('af-listwrap'); if(w) w.innerHTML=_afListHTML(l);
      // Admin ne feedback dekh liya — NEW ones ko background me seen mark karo (blink is baar dikha,
      // agli baar NEW nahi aayega). List abhi blink karti rahegi is session me.
      var news=(l&&l.feedback||[]).filter(function(f){return f.new;});
      if(news.length){ setTimeout(function(){ news.forEach(function(f){ api('/api/admin/feedback/'+f.id+'/read','POST').catch(function(){}); }); },2500); }
    });
  // analytics in background
  api('/api/admin/feedback-analytics').catch(function(){return {};})
    .then(function(a){ var k=document.getElementById('af-kpis'); if(k) k.innerHTML=_afKpisHTML(a); _asupBadges(); });
}
function _afKpisHTML(a){
  a=a||{};
  var cards='<div class="ac-cards"><div class="ac-kpi static"><b>'+(a.total||0)+'</b><span>Total Feedback</span></div>'
    +'<div class="ac-kpi static"><b style="color:#e6ad4e">'+(a.average||0)+' <span style="font-size:1rem">/5</span></b><span>Average Rating</span></div>'
    +'<div class="ac-kpi static"><b style="color:#dc2626">'+(a.new||0)+'</b><span>New</span></div></div>';
  var dist=(a.distribution||[]).map(function(d){ return '<div class="ac-dist-row"><span style="width:64px;font-size:.8rem" class="ac-star">'+'\u2605'.repeat(d.star)+'</span><div class="ac-dist-bar"><div class="ac-dist-fill" style="width:'+d.pct+'%"></div></div><span style="width:80px;text-align:right;font-size:.8rem;color:var(--text-muted)">'+d.count+' \u00b7 '+d.pct+'%</span></div>'; }).join('');
  var distBlock=dist?'<div class="ac-card static" style="margin-bottom:14px;cursor:default"><b style="font-size:.9rem">Rating Distribution</b><div style="margin-top:10px">'+dist+'</div></div>':'';
  return cards+distBlock;
}
function _afFilterHTML(){
  return '<div class="ac-filters"><select onchange="window._afRating=parseInt(this.value,10)||0;loadAFeedback()"><option value="0">All ratings</option>'+[5,4,3,2,1].map(function(n){return '<option value="'+n+'"'+(window._afRating===n?' selected':'')+'>'+n+' star</option>';}).join('')+'</select></div>';
}
function _afListHTML(l){
  var list=(l&&l.feedback)||[];
  var rows=list.length?list.map(function(f){
    return '<div class="ac-card"><div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-start"><div style="min-width:0;flex:1">'
      +'<span class="ac-name" onclick="_supDrawer('+(f.student&&f.student.id)+')">'+esc(f.student&&f.student.name||'Student')+'</span> <span class="sup-num">'+esc(f.student&&f.student.student_id||'')+'</span>'+(f.new?' <span class="af-new-pill">NEW</span>':'')
      +'<div style="margin-top:4px"><span class="ac-star">'+'\u2605'.repeat(f.rating)+'</span><span style="color:#d9c9a0">'+'\u2605'.repeat(5-f.rating)+'</span></div>'
      +(f.review?'<div style="font-size:.9rem;margin-top:6px;word-break:break-word;line-height:1.5">'+esc(f.review)+'</div>':'')
      +'<div class="sup-meta">'+esc(f.created_at)+'</div></div>'
      +'<button class="btn btn-ghost btn-sm af-del" onclick="afDelete('+f.id+')">Delete</button></div></div>';
  }).join(''):'<div class="sup-empty">No feedback received yet.</div>';
  return '<div class="ac-list">'+rows+'</div>';
}
function _renderAFeedback(a, l){
  var el=document.getElementById('a-feedback-content'); if(!el) return;
  var cards='<div class="ac-cards"><div class="ac-kpi static"><b>'+(a.total||0)+'</b><span>Total Feedback</span></div>'
    +'<div class="ac-kpi static"><b style="color:#e6ad4e">'+(a.average||0)+' <span style="font-size:1rem">/5</span></b><span>Average Rating</span></div>'
    +'<div class="ac-kpi static"><b style="color:#dc2626">'+(a.new||0)+'</b><span>New</span></div></div>';
  var dist=(a.distribution||[]).map(function(d){ return '<div class="ac-dist-row"><span style="width:64px;font-size:.8rem" class="ac-star">'+'\u2605'.repeat(d.star)+'</span><div class="ac-dist-bar"><div class="ac-dist-fill" style="width:'+d.pct+'%"></div></div><span style="width:80px;text-align:right;font-size:.8rem;color:var(--text-muted)">'+d.count+' \u00b7 '+d.pct+'%</span></div>'; }).join('');
  var distBlock=dist?'<div class="ac-card static" style="margin-bottom:14px;cursor:default"><b style="font-size:.9rem">Rating Distribution</b><div style="margin-top:10px">'+dist+'</div></div>':'';
  var filt='<div class="ac-filters"><select onchange="window._afRating=parseInt(this.value,10)||0;loadAFeedback()"><option value="0">All ratings</option>'+[5,4,3,2,1].map(function(n){return '<option value="'+n+'"'+(window._afRating===n?' selected':'')+'>'+n+' star</option>';}).join('')+'</select></div>';
  var list=(l.feedback||[]);
  var rows=list.length?list.map(function(f){
    return '<div class="ac-card"><div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-start"><div style="min-width:0;flex:1">'
      +'<span class="ac-name" onclick="_supDrawer('+(f.student&&f.student.id)+')">'+esc(f.student&&f.student.name||'Student')+'</span> <span class="sup-num">'+esc(f.student&&f.student.student_id||'')+'</span>'+(f.new?' <span class="af-new-pill">NEW</span>':'')
      +'<div style="margin-top:4px"><span class="ac-star">'+'\u2605'.repeat(f.rating)+'</span><span style="color:#d9c9a0">'+'\u2605'.repeat(5-f.rating)+'</span></div>'
      +(f.review?'<div style="font-size:.9rem;margin-top:6px;word-break:break-word;line-height:1.5">'+esc(f.review)+'</div>':'')
      +'<div class="sup-meta">'+esc(f.created_at)+'</div></div>'
      +'<button class="btn btn-ghost btn-sm af-del" onclick="afDelete('+f.id+')">Delete</button></div></div>';
  }).join(''):'<div class="sup-empty">No feedback received yet.</div>';
  el.innerHTML=cards+distBlock+filt+'<div class="ac-list">'+rows+'</div>';
}
function afDelete(fid){
  showModal('Delete this feedback?','<div style="padding:6px 2px;color:var(--text-muted)">This action cannot be undone. The review will be removed and excluded from the average rating.</div>',
    '<button class="btn btn-ghost" onclick="closeModal()">Cancel</button><button class="btn btn-danger" onclick="afDoDelete('+fid+')">Delete</button>');
}
async function afDoDelete(fid){
  try{ await api('/api/admin/feedback/'+fid+'/delete','POST',{}); closeModal(); toast('Feedback removed'); loadAFeedback(); }
  catch(e){ toast((e&&e.message)||'Could not delete',true); }
}

/* ============================================================
   COMPLAINTS — Media: clipboard paste + voice (Phase 6)
   Reusable, composer-scoped. No global clipboard hijack.
   ============================================================ */
function _supWireClipboard(taId, imgs, renderFn){
  var ta=document.getElementById(taId); if(!ta||ta._supPasteWired) return; ta._supPasteWired=true;
  ta.addEventListener('paste', function(e){
    var items=(e.clipboardData&&e.clipboardData.items)||[]; var added=false;
    for(var i=0;i<items.length;i++){
      var it=items[i];
      if(it.type&&it.type.indexOf('image')===0){ var f=it.getAsFile(); if(f){ imgs.push(new File([f],'pasted-'+Date.now()+'.png',{type:f.type||'image/png'})); added=true; } }
    }
    if(added){ e.preventDefault(); try{ renderFn(); }catch(_){} try{ toast('Image pasted'); }catch(_){} }
  });
}
function _supFmtT(s){ s=s||0; var m=Math.floor(s/60), r=s%60; return (m<10?'0':'')+m+':'+(r<10?'0':'')+r; }
function _supVoiceUI(containerId, refName){
  try{ window[refName]=null; }catch(_){}
  var el=document.getElementById(containerId); if(!el) return;
  el.innerHTML='<button type="button" class="btn btn-ghost btn-sm" style="margin:0" onclick="_supVoiceStart(\''+containerId+'\',\''+refName+'\')">\uD83C\uDF99 Record Voice</button>';
}
async function _supVoiceStart(containerId, refName){
  var el=document.getElementById(containerId); if(!el) return;
  if(!navigator.mediaDevices||!window.MediaRecorder){ el.innerHTML='<span style="font-size:.78rem;color:#c1443a">Recording isn\u2019t supported on this device.</span>'; return; }
  var stream;
  try{ stream=await navigator.mediaDevices.getUserMedia({audio:true}); }
  catch(e){ el.innerHTML='<span style="font-size:.78rem;color:#c1443a">Microphone permission denied.</span> <button type="button" class="btn btn-ghost btn-sm" onclick="_supVoiceUI(\''+containerId+'\',\''+refName+'\')">Try again</button>'; return; }
  var chunks=[]; var mime=(window.MediaRecorder&&MediaRecorder.isTypeSupported&&MediaRecorder.isTypeSupported('audio/webm'))?'audio/webm':'';
  var mr; try{ mr=mime?new MediaRecorder(stream,{mimeType:mime}):new MediaRecorder(stream); }catch(e){ mr=new MediaRecorder(stream); }
  el._mr=mr; el._sec=0; el._paused=false;
  mr.ondataavailable=function(ev){ if(ev.data&&ev.data.size) chunks.push(ev.data); };
  mr.onstop=function(){
    try{ stream.getTracks().forEach(function(t){t.stop();}); }catch(_){}
    var blob=new Blob(chunks,{type:mime||'audio/webm'});
    try{ window[refName]={blob:blob,dur:el._sec}; }catch(_){}
    var url=URL.createObjectURL(blob);
    el.innerHTML='<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap"><audio controls src="'+url+'" style="height:34px"></audio>'
      +'<span style="font-size:.74rem;color:var(--text-muted)">'+_supFmtT(el._sec)+'</span>'
      +'<button type="button" class="btn btn-ghost btn-sm" style="color:#c1443a;margin:0" onclick="_supVoiceUI(\''+containerId+'\',\''+refName+'\')">Delete / Re-record</button></div>';
  };
  try{ mr.start(); }catch(e){ el.innerHTML='<span style="font-size:.78rem;color:#c1443a">Could not start recording.</span>'; return; }
  el._tick=setInterval(function(){ if(!el._paused){ el._sec++; var t=document.getElementById(containerId+'-t'); if(t) t.textContent=_supFmtT(el._sec); } },1000);
  el.innerHTML='<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap"><span style="color:#dc2626">\u25cf</span> Recording <span id="'+containerId+'-t" style="font-family:ui-monospace,monospace">00:00</span>'
    +'<button type="button" class="btn btn-ghost btn-sm" onclick="_supVoicePause(\''+containerId+'\',this)">Pause</button>'
    +'<button type="button" class="btn btn-primary btn-sm" onclick="_supVoiceStop(\''+containerId+'\')">Stop</button></div>';
}
function _supVoicePause(containerId, btn){
  var el=document.getElementById(containerId); if(!el||!el._mr) return;
  try{
    if(el._paused){ el._mr.resume&&el._mr.resume(); el._paused=false; if(btn) btn.textContent='Pause'; }
    else { el._mr.pause&&el._mr.pause(); el._paused=true; if(btn) btn.textContent='Resume'; }
  }catch(_){}
}
function _supVoiceStop(containerId){ var el=document.getElementById(containerId); if(!el||!el._mr)return; try{ clearInterval(el._tick); }catch(_){} try{ el._mr.stop(); }catch(_){} }

/* Support (Phase 7): activate the nav item after a deep-link jump */
function _supActivateNav(appId, page){
  try{
    document.querySelectorAll('#'+appId+' .nav-item').forEach(function(el){
      el.classList.remove('active');
      if((el.getAttribute('onclick')||'').indexOf("'"+page+"'")>=0) el.classList.add('active');
    });
  }catch(e){}
}

/* ============================================================
   COMPLAINTS & FEEDBACK — Premium polish + responsive (Phase 8)
   ============================================================ */
function _supPolishCss(){
  if(document.getElementById('sup-polish-css')) return;
  var s=document.createElement('style'); s.id='sup-polish-css';
  s.textContent=[
    /* premium scrollbar */
    '.sup-list::-webkit-scrollbar,.ac-list::-webkit-scrollbar,.sup-thread::-webkit-scrollbar{width:8px}',
    '.sup-list::-webkit-scrollbar-thumb,.ac-list::-webkit-scrollbar-thumb,.sup-thread::-webkit-scrollbar-thumb{background:rgba(120,113,108,.32);border-radius:99px}',
    '.sup-list::-webkit-scrollbar-thumb:hover,.ac-list::-webkit-scrollbar-thumb:hover{background:rgba(120,113,108,.5)}',
    '.sup-list,.ac-list,.sup-thread{scrollbar-width:thin;scrollbar-color:rgba(120,113,108,.32) transparent}',
    /* skeleton shimmer */
    '@keyframes supShim{0%{background-position:-320px 0}100%{background-position:320px 0}}',
    '.sup-sk{background:linear-gradient(90deg,rgba(120,113,108,.10) 25%,rgba(120,113,108,.20) 37%,rgba(120,113,108,.10) 63%);background-size:640px 100%;animation:supShim 1.2s infinite;border-radius:8px}',
    '.sup-sk-card{border:1px solid var(--border);border-radius:14px;padding:15px;background:var(--card);margin-bottom:10px}',
    /* card hover micro-interaction already set; focus rings for a11y */
    '.ac-card:focus-within{border-color:#d9b978}',
    /* mobile filter toggle (hidden on desktop) */
    '.ac-fbtn{display:none}',
    '.af-del{color:#c1443a;flex-shrink:0;white-space:nowrap}',
    '@media(max-width:680px){',
    '  #a-page-complaints .ac-cards,#a-page-feedback .ac-cards{grid-template-columns:1fr 1fr;gap:9px}',
    '  .ac-kpi b{font-size:1.4rem}',
    '  .ac-fbtn{display:inline-flex;margin-bottom:10px}',
    '  #ac-filterbar{display:none !important}#ac-filterbar.open{display:flex !important}',
    '  #ac-filterbar select,#ac-filterbar input{flex:1 1 100% !important;min-width:0 !important}',
    '  .ac-list,.sup-list{max-height:none}',
    '  .sup-b{max-width:92%}',
    '  .sup-top{gap:8px}.sup-top .btn{width:100%}',
    '  .ac-chead{padding:13px 14px}.ac-cbody{padding:12px 14px 14px}',
    '  .ac-crow{gap:8px}.ac-cright{gap:4px}',
    '  .ac-card .af-del{padding:6px 10px;font-size:.8rem}',
    '  .sup-thread{max-height:52vh !important}',
    '  .ac-name{font-size:.96rem}',
    '}',
    '@media(max-width:420px){',
    '  #a-page-feedback .ac-cards{grid-template-columns:1fr}',
    '  .ac-kpi{padding:12px}.ac-kpi b{font-size:1.25rem}',
    '  .af-del{padding:5px 9px !important;font-size:.78rem !important}',
    '}',
  ].join('');
  document.head.appendChild(s);
}
function _supSkelList(n){
  var one='<div class="sup-sk-card"><div class="sup-sk" style="height:11px;width:38%;margin-bottom:9px"></div><div class="sup-sk" style="height:16px;width:68%;margin-bottom:7px"></div><div class="sup-sk" style="height:10px;width:48%"></div></div>';
  var out=''; for(var i=0;i<(n||4);i++) out+=one; return out;
}
function _supSkelCards(n){
  var one='<div class="sup-sk-card" style="margin:0"><div class="sup-sk" style="height:26px;width:52%;margin-bottom:9px"></div><div class="sup-sk" style="height:10px;width:72%"></div></div>';
  var out='<div class="ac-cards">'; for(var i=0;i<(n||6);i++) out+=one; out+='</div>'; return out;
}

/* Complaint reply via the premium composer (student + admin) — Phase: composer reply */
async function scComposerReply(){
  var ctx=window._scReplyCtx||{}; var role=ctx.role||'student', cid=ctx.cid, key=ctx.key||'screp';
  if(!cid) return;
  var txtEl=document.getElementById('cmpt-'+key);
  var txt=((txtEl&&txtEl.value)||'').trim();
  var st=(window._cmpState&&_cmpState[key])||{};
  if(!txt && !st.file && !st.voice){ toast('Type a message',true); return; }
  var btn=document.getElementById('cmps-'+key); if(btn){ btn.disabled=true; btn.textContent='Sending...'; }
  try{
    var fd=new FormData(); fd.append('message',txt);
    if(st.file){
      var fl=st.file;
      if((fl.type||'').indexOf('image/')===0){
        try{ var _r=await Promise.race([smartCompress(fl,function(){}),new Promise(function(rs){setTimeout(function(){rs(null);},12000);})]); if(_r&&_r.ok&&_r.file) fl=_r.file; }catch(e){}
      }
      fd.append('images',fl,fl.name||'image');
    }
    if(st.voice){ fd.append('voice',st.voice,'voice.webm'); }
    var base=role==='student'?'/api/student/complaints/':'/api/admin/complaints/';
    var r=await fetch(API+base+cid+'/messages',{method:'POST',headers:{Authorization:'Bearer '+TOKEN},body:fd});
    if(!r.ok){ var d=null; try{d=await r.json();}catch(e){} throw new Error((d&&d.detail)||'Send failed'); }
    if(role==='student') scOpenDetail(cid); else amcCmpOpen(cid);
  }catch(e){ toast(e.message||'Could not send',true); if(btn){ btn.disabled=false; btn.textContent=(role==='student'?'Send':'Reply'); } }
}

/* Fullscreen image lightbox for complaint attachments */
function _supLightbox(url){
  var ov=document.getElementById('_sup-lb');
  if(!ov){ ov=document.createElement('div'); ov.id='_sup-lb'; ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.86);display:flex;align-items:center;justify-content:center;z-index:99999;cursor:zoom-out'; ov.onclick=function(){ ov.style.display='none'; ov.innerHTML=''; }; document.body.appendChild(ov); }
  ov.style.display='flex'; ov.innerHTML='<div style="color:#fff;font-size:.9rem">Loading\u2026</div>';
  fetch(API+url,{headers:{Authorization:'Bearer '+TOKEN}}).then(function(r){ if(!r.ok) throw 0; return r.blob(); })
    .then(function(b){ ov.innerHTML='<img src="'+URL.createObjectURL(b)+'" style="max-width:92vw;max-height:92vh;border-radius:10px;box-shadow:0 10px 40px rgba(0,0,0,.5)">'; })
    .catch(function(){ ov.innerHTML='<div style="color:#fff">Could not load image</div>'; });
}

/* Modal footer buttons: never wrap char-by-char; on mobile go 2-per-row.
   Injected here so it ships with mvs_app.js (independent of the HTML file). */
(function(){
  try{
    if(document.getElementById('mvs-footer-fix')) return;
    var s=document.createElement('style'); s.id='mvs-footer-fix';
    s.textContent='.modal-footer{flex-wrap:wrap}'
      +'.modal-footer .btn{white-space:nowrap !important;overflow:hidden;text-overflow:ellipsis}'
      +'@media(max-width:640px){.modal-footer .btn{flex:1 1 calc(50% - 6px) !important;min-width:0 !important;font-size:.84rem !important;padding:11px 8px !important}}';
    (document.head||document.documentElement).appendChild(s);
  }catch(e){}
})();
